--
-- Name: assessment_paper_release_issues(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.assessment_paper_release_issues(p_paper_id uuid) RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_paper public.assessment_papers%rowtype;
  v_issues text[];
  v_invalid_count integer;
  v_question record;
begin
  v_issues := private.assessment_paper_release_issues_with_temporary_notice(
    p_paper_id
  );
  select * into v_paper
  from public.assessment_papers
  where id = p_paper_id;

  if v_paper.paper_code = 'EX-K1-MID-V1' then
    select coalesce(array_agg(issue order by position), array[]::text[])
    into v_issues
    from unnest(v_issues) with ordinality as quality_issue(issue, position)
    where issue <> '有 5 道听力题仍使用 temporary 临时音频，正式发布前须完成听校并复制为新版本';
  end if;

  if v_paper.paper_type = 'exam'
    and v_paper.paper_code like 'EX-K1-FIN-%' then
    if v_paper.paper_code !~ '^EX-K1-FIN-V[0-9]+$' then
      v_issues := array_append(v_issues, '期末母卷代码必须符合 EX-K1-FIN-V{版本号}');
    end if;
    if v_paper.question_count <> 41 then
      v_issues := array_append(v_issues, '期末考试必须包含41题');
    end if;
    if v_paper.total_points <> 100 then
      v_issues := array_append(v_issues, '期末考试母卷总分必须等于100分');
    end if;
    if v_paper.duration_minutes <> 90 then
      v_issues := array_append(v_issues, '期末考试时长必须为90分钟');
    end if;
    if v_paper.passing_score <> 60 then
      v_issues := array_append(v_issues, '期末考试及格分必须为60分');
    end if;
    if v_paper.allow_resubmission then
      v_issues := array_append(v_issues, '期末考试不得允许重复提交');
    end if;
    if (
      select count(distinct question.skill)
      from public.assessment_paper_questions as question
      where question.paper_id = p_paper_id
        and question.skill in (
          'vocabulary', 'grammar', 'listening', 'speaking', 'reading', 'writing'
        )
    ) <> 6 then
      v_issues := array_append(v_issues, '期末考试的单词、语法、听力、口语、阅读、写作六项不齐全');
    end if;
    if exists (
      select required.skill
      from (values
        ('vocabulary', 15::numeric), ('grammar', 20::numeric),
        ('listening', 15::numeric), ('speaking', 15::numeric),
        ('reading', 20::numeric), ('writing', 15::numeric)
      ) as required(skill, points)
      left join (
        select question.skill, sum(question.points) as points
        from public.assessment_paper_questions as question
        where question.paper_id = p_paper_id
        group by question.skill
      ) as actual using (skill)
      where coalesce(actual.points, 0) <> required.points
    ) then
      v_issues := array_append(v_issues,
        '期末考试六项分值必须为单词15、语法20、听力15、口语15、阅读20、写作15');
    end if;

    for v_question in
      select question.question_code, question.points,
        case
          when question.question_code ~ '^V' then 1.25::numeric
          when question.question_code ~ '^G' then 2::numeric
          when question.question_code ~ '^L0[1-7]$' then 2::numeric
          when question.question_code = 'L08' then 1::numeric
          when question.question_code = 'S01' then 7::numeric
          when question.question_code = 'S02' then 8::numeric
          when question.question_code ~ '^R' then 2.5::numeric
          when question.question_code = 'W01' then 15::numeric
        end as expected_points
      from public.assessment_paper_questions as question
      where question.paper_id = p_paper_id
        and question.points <> case
          when question.question_code ~ '^V' then 1.25::numeric
          when question.question_code ~ '^G' then 2::numeric
          when question.question_code ~ '^L0[1-7]$' then 2::numeric
          when question.question_code = 'L08' then 1::numeric
          when question.question_code = 'S01' then 7::numeric
          when question.question_code = 'S02' then 8::numeric
          when question.question_code ~ '^R' then 2.5::numeric
          when question.question_code = 'W01' then 15::numeric
          else -1::numeric
        end
      order by question.sort_order
    loop
      v_issues := array_append(v_issues, format(
        '期末题 %s 分值应为 %s 分，当前为 %s 分',
        coalesce(v_question.question_code, '未编号题目'),
        v_question.expected_points, v_question.points
      ));
    end loop;

    select count(*) into v_invalid_count
    from public.assessment_paper_questions as question
    where question.paper_id = p_paper_id
      and (
        question.question_code is null
        or cardinality(question.source_chapters) = 0
        or nullif(btrim(question.source_knowledge), '') is null
      );
    if v_invalid_count > 0 then
      v_issues := array_append(v_issues, format(
        '有 %s 道期末题缺少稳定题号、章节来源或知识点快照', v_invalid_count
      ));
    end if;
    if (
      select count(distinct question.question_code)
      from public.assessment_paper_questions as question
      where question.paper_id = p_paper_id
        and question.question_code ~ '^(V(0[1-9]|1[0-2])|G(0[1-9]|10)|L0[1-8]|S0[1-2]|R0[1-8]|W01)$'
    ) <> 41 then
      v_issues := array_append(v_issues, '期末考试稳定题号集合不完整或重复');
    end if;
    if (
      select count(distinct chapter_key)
      from public.assessment_paper_questions as question
      cross join unnest(question.source_chapters) as chapter_key
      where question.paper_id = p_paper_id
        and chapter_key ~ '^K1-(0[1-9]|1[0-6])$'
    ) <> 16 then
      v_issues := array_append(v_issues, '期末考试必须覆盖第1—16章');
    end if;
    if exists (
      select required.chapter_key
      from (
        select format('K1-%s', lpad(chapter_number::text, 2, '0')) as chapter_key
        from generate_series(1, 16) as chapter_number
      ) as required
      where not exists (
        select 1
        from public.assessment_paper_questions as question
        where question.paper_id = p_paper_id
          and required.chapter_key = any(question.source_chapters)
      )
    ) then
      v_issues := array_append(v_issues, '期末考试前后册章节覆盖不平衡');
    end if;

    select count(*) into v_invalid_count
    from public.assessment_paper_questions as question
    join public.assessment_paper_question_keys as answer_key
      on answer_key.question_id = question.id
    where question.paper_id = p_paper_id
      and question.skill in ('vocabulary', 'grammar', 'listening', 'reading')
      and (
        not question.auto_graded
        or question.question_type <> 'single_choice'
        or jsonb_array_length(question.options) <> 4
        or (select count(distinct lower(btrim(option_value.value)))
            from jsonb_array_elements_text(question.options) as option_value(value)) <> 4
        or (select count(*) from jsonb_array_elements_text(question.options) as option_value(value)
            where option_value.value = answer_key.correct_answer) <> 1
      );
    if v_invalid_count > 0 then
      v_issues := array_append(v_issues, format(
        '有 %s 道期末客观题未满足四个唯一选项、唯一答案或自动判分合同', v_invalid_count
      ));
    end if;

    select count(*) into v_invalid_count
    from public.assessment_paper_questions as question
    join public.assessment_paper_question_keys as answer_key
      on answer_key.question_id = question.id
    where question.paper_id = p_paper_id
      and question.skill in ('speaking', 'writing')
      and (
        question.auto_graded
        or (question.skill = 'speaking' and question.question_type <> 'audio_recording')
        or (question.skill = 'writing' and question.question_type <> 'long_text')
        or jsonb_typeof(answer_key.rubric_snapshot -> 'criteria') <> 'array'
        or coalesce((
          select sum((criterion ->> 'maxPoints')::numeric)
          from jsonb_array_elements(answer_key.rubric_snapshot -> 'criteria') as criterion
        ), 0) <> question.points
      );
    if v_invalid_count > 0 then
      v_issues := array_append(v_issues, format(
        '有 %s 道期末主观题的作答方式或量规满分与题目分值不一致', v_invalid_count
      ));
    end if;

    select count(*) into v_invalid_count
    from public.assessment_paper_questions as question
    where question.paper_id = p_paper_id
      and question.skill = 'listening'
      and (nullif(btrim(question.stimulus_text), '') is null
        or question.audio_status <> 'temporary');
    if v_invalid_count > 0 then
      v_issues := array_append(v_issues, format(
        '有 %s 道期末听力题缺少材料快照或未保持 temporary 状态', v_invalid_count
      ));
    end if;
    select count(*) into v_invalid_count
    from public.assessment_paper_questions as question
    where question.paper_id = p_paper_id
      and question.skill = 'reading'
      and nullif(btrim(question.stimulus_text), '') is null;
    if v_invalid_count > 0 then
      v_issues := array_append(v_issues, format(
        '有 %s 道期末阅读题缺少材料快照', v_invalid_count
      ));
    end if;
    if exists (
      select 1 from public.assessment_paper_questions as question
      where question.paper_id = p_paper_id
        and question.skill <> 'listening'
        and question.audio_status <> 'not_applicable'
    ) then
      v_issues := array_append(v_issues, '期末非听力题的题干音频状态必须为 not_applicable');
    end if;
  end if;

  return v_issues;
end;
$_$;


ALTER FUNCTION private.assessment_paper_release_issues(p_paper_id uuid) OWNER TO postgres;

--
-- Name: assessment_paper_release_issues_with_temporary_notice(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.assessment_paper_release_issues_with_temporary_notice(p_paper_id uuid) RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_paper public.assessment_papers%rowtype;
  v_issues text[] := array[]::text[];
  v_is_chapter_exam boolean;
  v_is_midterm boolean;
  v_invalid_count integer;
  v_question record;
begin
  select * into v_paper
  from public.assessment_papers
  where id = p_paper_id;
  if not found then
    return array['标准试卷不存在'];
  end if;

  v_is_chapter_exam := v_paper.paper_type = 'exam'
    and v_paper.paper_code ~ '^EX-K1-(0[1-9]|1[0-6])-V[0-9]+$';
  v_is_midterm := v_paper.paper_type = 'exam'
    and v_paper.paper_code like 'EX-K1-MID-%';

  if v_paper.question_count < 1 then
    v_issues := array_append(v_issues, '试卷没有题目');
  end if;
  if v_paper.duration_minutes is null then
    v_issues := array_append(v_issues, '未设置考试时长');
  end if;
  if v_paper.passing_score is null then
    v_issues := array_append(v_issues, '未设置及格分');
  end if;
  if not v_paper.resubmission_policy_configured then
    v_issues := array_append(v_issues, '重复提交规则尚未由内容负责人确认');
  end if;

  select count(*) into v_invalid_count
  from (
    select lower(btrim(question.prompt))
    from public.assessment_paper_questions as question
    where question.paper_id = p_paper_id
    group by lower(btrim(question.prompt))
    having count(*) > 1
  ) as duplicates;
  if v_invalid_count > 0 then
    v_issues := array_append(v_issues,
      format('存在 %s 组重复题干', v_invalid_count));
  end if;

  select count(*) into v_invalid_count
  from public.assessment_paper_questions as question
  left join public.assessment_paper_question_keys as answer_key
    on answer_key.question_id = question.id
  where question.paper_id = p_paper_id
    and (
      nullif(btrim(question.prompt), '') is null
      or question.points <= 0
      or answer_key.question_id is null
      or nullif(btrim(answer_key.explanation), '') is null
      or question.skill not in (
        'vocabulary', 'grammar', 'listening', 'speaking', 'reading', 'writing'
      )
    );
  if v_invalid_count > 0 then
    v_issues := array_append(v_issues,
      format('有 %s 道题的题干、解析、分值或能力分类未完成', v_invalid_count));
  end if;

  select count(*) into v_invalid_count
  from public.assessment_paper_questions as question
  left join public.assessment_paper_question_keys as answer_key
    on answer_key.question_id = question.id
  where question.paper_id = p_paper_id
    and question.auto_graded
    and (
      nullif(btrim(answer_key.correct_answer), '') is null
      or nullif(btrim(answer_key.explanation), '') is null
    );
  if v_invalid_count > 0 then
    v_issues := array_append(v_issues,
      format('有 %s 道客观题缺少正确答案或解析', v_invalid_count));
  end if;

  select count(*) into v_invalid_count
  from public.assessment_paper_questions as question
  join public.assessment_paper_question_keys as answer_key
    on answer_key.question_id = question.id
  where question.paper_id = p_paper_id
    and question.auto_graded
    and (
      jsonb_array_length(question.options) < 2
      or not question.options @> jsonb_build_array(answer_key.correct_answer)
    );
  if v_invalid_count > 0 then
    v_issues := array_append(v_issues,
      format('有 %s 道客观题的可选项未完整冻结或不包含正确答案', v_invalid_count));
  end if;

  select count(*) into v_invalid_count
  from public.assessment_paper_questions as question
  where question.paper_id = p_paper_id
    and exists (
      select 1
      from jsonb_array_elements_text(question.options) as option_value(value)
      group by lower(btrim(option_value.value))
      having count(*) > 1
    );
  if v_invalid_count > 0 then
    v_issues := array_append(v_issues,
      format('有 %s 道题包含完全重复的选项', v_invalid_count));
  end if;

  if (
    select count(*) from public.assessment_paper_questions as question
    where question.paper_id = p_paper_id
  ) <> v_paper.question_count then
    v_issues := array_append(v_issues, '试卷题量与题目快照不一致');
  end if;
  if (
    select coalesce(sum(question.points), 0)
    from public.assessment_paper_questions as question
    where question.paper_id = p_paper_id
  ) <> v_paper.total_points then
    v_issues := array_append(v_issues, '试卷总分与题目快照不一致');
  end if;

  if v_is_midterm then
    if v_paper.paper_code !~ '^EX-K1-MID-V[0-9]+$' then
      v_issues := array_append(v_issues, '期中母卷代码必须符合 EX-K1-MID-V{版本号}');
    end if;
    if v_paper.total_points <> 100 then
      v_issues := array_append(v_issues, '期中考试母卷总分必须等于100分');
    end if;
    if (
      select count(distinct question.skill)
      from public.assessment_paper_questions as question
      where question.paper_id = p_paper_id
        and question.skill in (
          'vocabulary', 'grammar', 'listening', 'speaking', 'reading', 'writing'
        )
    ) <> 6 then
      v_issues := array_append(v_issues, '期中考试的单词、语法、听力、口语、阅读、写作六项不齐全');
    end if;
    if exists (
      select required.skill
      from (values
        ('vocabulary', 15::numeric), ('grammar', 20::numeric),
        ('listening', 15::numeric), ('speaking', 15::numeric),
        ('reading', 20::numeric), ('writing', 15::numeric)
      ) as required(skill, points)
      left join (
        select question.skill, sum(question.points) as points
        from public.assessment_paper_questions as question
        where question.paper_id = p_paper_id
        group by question.skill
      ) as actual using (skill)
      where coalesce(actual.points, 0) <> required.points
    ) then
      v_issues := array_append(v_issues,
        '期中考试六项分值必须为单词15、语法20、听力15、口语15、阅读20、写作15');
    end if;
    for v_question in
      select
        coalesce(question.question_code, '未编号题目') as question_code,
        question.points,
        case question.skill
          when 'vocabulary' then 1.5::numeric
          when 'grammar' then 2::numeric
          when 'listening' then 3::numeric
          when 'speaking' then 15::numeric
          when 'reading' then 2.5::numeric
          when 'writing' then 15::numeric
        end as expected_points
      from public.assessment_paper_questions as question
      where question.paper_id = p_paper_id
        and question.skill in (
          'vocabulary', 'grammar', 'listening', 'speaking', 'reading', 'writing'
        )
        and question.points <> case question.skill
          when 'vocabulary' then 1.5::numeric
          when 'grammar' then 2::numeric
          when 'listening' then 3::numeric
          when 'speaking' then 15::numeric
          when 'reading' then 2.5::numeric
          when 'writing' then 15::numeric
        end
      order by question.sort_order
    loop
      v_issues := array_append(
        v_issues,
        format(
          '期中题 %s 分值应为 %s 分，当前为 %s 分',
          v_question.question_code,
          v_question.expected_points,
          v_question.points
        )
      );
    end loop;
    if (
      select count(distinct chapter_key)
      from public.assessment_paper_questions as question
      cross join unnest(question.source_chapters) as chapter_key
      where question.paper_id = p_paper_id
        and chapter_key ~ '^K1-(0[1-9]|1[0-6])$'
    ) < 6 then
      v_issues := array_append(v_issues, '期中考试必须至少覆盖6个不同章节');
    end if;
    select count(*) into v_invalid_count
    from public.assessment_paper_questions as question
    where question.paper_id = p_paper_id
      and (
        question.question_code is null
        or cardinality(question.source_chapters) = 0
        or nullif(btrim(question.source_knowledge), '') is null
      );
    if v_invalid_count > 0 then
      v_issues := array_append(v_issues,
        format('有 %s 道期中题缺少稳定题号、章节来源或知识点快照', v_invalid_count));
    end if;
    if exists (
      select 1 from public.assessment_paper_questions as question
      where question.paper_id = p_paper_id
        and question.skill in ('vocabulary', 'grammar', 'listening', 'reading')
        and not question.auto_graded
    ) then
      v_issues := array_append(v_issues, '期中考试的单词、语法、听力或阅读客观题未配置自动判分');
    end if;
    if exists (
      select 1 from public.assessment_paper_questions as question
      where question.paper_id = p_paper_id
        and question.skill in ('speaking', 'writing')
        and question.auto_graded
    ) then
      v_issues := array_append(v_issues, '期中考试的口语和写作必须配置为人工批改');
    end if;
    select count(*) into v_invalid_count
    from public.assessment_paper_questions as question
    join public.assessment_paper_question_keys as answer_key
      on answer_key.question_id = question.id
    where question.paper_id = p_paper_id
      and question.skill in ('speaking', 'writing')
      and (
        (question.skill = 'speaking' and question.question_type <> 'audio_recording')
        or (question.skill = 'writing' and question.question_type <> 'long_text')
        or case
          when jsonb_typeof(answer_key.rubric_snapshot -> 'criteria') = 'array'
          then
            exists (
              select 1
              from jsonb_array_elements(
                answer_key.rubric_snapshot -> 'criteria'
              ) as criterion
              where jsonb_typeof(criterion -> 'maxPoints') <> 'number'
            )
            or coalesce((
              select sum((criterion ->> 'maxPoints')::numeric)
              from jsonb_array_elements(
                answer_key.rubric_snapshot -> 'criteria'
              ) as criterion
            ), 0) <> question.points
          else true
        end
      );
    if v_invalid_count > 0 then
      v_issues := array_append(v_issues,
        format('有 %s 道主观题的作答方式或量规满分与题目分值不一致', v_invalid_count));
    end if;
    select count(*) into v_invalid_count
    from public.assessment_paper_questions as question
    where question.paper_id = p_paper_id
      and question.skill = 'listening'
      and (
        nullif(btrim(question.stimulus_text), '') is null
        or question.audio_status not in ('temporary', 'formal')
      );
    if v_invalid_count > 0 then
      v_issues := array_append(v_issues,
        format('有 %s 道听力题缺少材料文本或有效音频状态', v_invalid_count));
    end if;
    select count(*) into v_invalid_count
    from public.assessment_paper_questions as question
    where question.paper_id = p_paper_id
      and question.skill = 'listening'
      and question.audio_status = 'temporary';
    if v_invalid_count > 0 then
      v_issues := array_append(v_issues,
        format('有 %s 道听力题仍使用 temporary 临时音频，正式发布前须完成听校并复制为新版本', v_invalid_count));
    end if;
    if exists (
      select 1 from public.assessment_paper_questions as question
      where question.paper_id = p_paper_id
        and question.skill = 'listening'
        and question.audio_status = 'formal'
    ) and v_paper.paper_code = 'EX-K1-MID-V1' then
      v_issues := array_append(v_issues, 'EX-K1-MID-V1 合同规定听力状态不得标记为 formal');
    end if;
  elsif v_is_chapter_exam then
    if v_paper.total_points <> 100 then
      v_issues := array_append(v_issues, '正式章节考试总分必须等于100分');
    end if;
    if (
      select count(distinct question.skill)
      from public.assessment_paper_questions as question
      where question.paper_id = p_paper_id
        and question.skill in (
          'vocabulary', 'grammar', 'listening', 'speaking', 'reading', 'writing'
        )
    ) <> 6 then
      v_issues := array_append(v_issues, '单词、语法、听力、口语、阅读、写作六项不齐全');
    end if;
    if exists (
      select required.skill
      from (values
        ('vocabulary', 15::numeric), ('grammar', 20::numeric),
        ('listening', 15::numeric), ('speaking', 15::numeric),
        ('reading', 20::numeric), ('writing', 15::numeric)
      ) as required(skill, points)
      left join (
        select question.skill, sum(question.points) as points
        from public.assessment_paper_questions as question
        where question.paper_id = p_paper_id
        group by question.skill
      ) as actual using (skill)
      where coalesce(actual.points, 0) <> required.points
    ) then
      v_issues := array_append(v_issues,
        '六项分值必须为单词15、语法20、听力15、口语15、阅读20、写作15');
    end if;
  elsif v_paper.paper_type = 'homework' then
    if (
      select count(distinct question.skill)
      from public.assessment_paper_questions as question
      where question.paper_id = p_paper_id
        and question.skill in (
          'vocabulary', 'grammar', 'listening', 'speaking', 'reading', 'writing'
        )
    ) <> 6 then
      v_issues := array_append(v_issues, '章节作业的词汇、语法、听说读写六项内容不完整');
    end if;
    if exists (
      select 1 from public.assessment_paper_questions as question
      where question.paper_id = p_paper_id
        and question.skill = 'listening'
        and nullif(btrim(question.stimulus_text), '') is null
    ) then
      v_issues := array_append(v_issues, '章节作业的听力题缺少韩语听力材料');
    end if;
  end if;

  return v_issues;
end;
$_$;


ALTER FUNCTION private.assessment_paper_release_issues_with_temporary_notice(p_paper_id uuid) OWNER TO postgres;

--
-- Name: assignment_delivery_paper_id(uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.assignment_delivery_paper_id(p_tenant_id uuid, p_assignment_id uuid, p_student_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when exists (
      select 1
      from public.learning_assignment_retake_students as retake
      where retake.tenant_id = assignment.tenant_id
        and retake.assignment_id = assignment.id
        and retake.student_id = p_student_id
    ) then assignment.retake_paper_id
    else assignment.source_paper_id
  end
  from public.learning_assignments as assignment
  where assignment.tenant_id = p_tenant_id
    and assignment.id = p_assignment_id;
$$;


ALTER FUNCTION private.assignment_delivery_paper_id(p_tenant_id uuid, p_assignment_id uuid, p_student_id uuid) OWNER TO postgres;

