--
-- Name: audit_application_access_change(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.audit_application_access_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_row jsonb := case
    when tg_op = 'DELETE' then to_jsonb(old)
    else to_jsonb(new)
  end;
  v_tenant_id uuid;
  v_app_id uuid;
  v_subject_type text;
  v_subject_user_id uuid;
begin
  v_tenant_id := nullif(v_row ->> 'tenant_id', '')::uuid;

  if tg_table_name = 'tenant_student_assignments' then
    v_app_id := nullif(v_row ->> 'student_app_id', '')::uuid;
    v_subject_type := 'teacher_assignment';
    v_subject_user_id := nullif(v_row ->> 'student_id', '')::uuid;
  elsif tg_table_name = 'student_app_enrollments' then
    v_app_id := nullif(v_row ->> 'app_id', '')::uuid;
    v_subject_type := 'student';
    v_subject_user_id := nullif(v_row ->> 'student_id', '')::uuid;
  elsif tg_table_name = 'staff_app_assignments' then
    v_app_id := nullif(v_row ->> 'app_id', '')::uuid;
    v_subject_type := 'staff';
    v_subject_user_id := nullif(v_row ->> 'staff_id', '')::uuid;
  elsif tg_table_name = 'tenant_student_apps' then
    v_app_id := nullif(v_row ->> 'app_id', '')::uuid;
    v_subject_type := 'tenant_app';
    v_subject_user_id := null;
  else
    raise exception '不支持的应用授权审计表：%', tg_table_name;
  end if;

  insert into public.application_access_audit_logs (
    tenant_id, app_id, actor_id, subject_type, subject_user_id,
    operation, before_data, after_data
  ) values (
    v_tenant_id,
    v_app_id,
    auth.uid(),
    v_subject_type,
    v_subject_user_id,
    lower(tg_op),
    case when tg_op = 'INSERT' then null else to_jsonb(old) end,
    case when tg_op = 'DELETE' then null else to_jsonb(new) end
  );

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.audit_application_access_change() OWNER TO postgres;

--
-- Name: audit_tenant_membership_change(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.audit_tenant_membership_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  insert into public.tenant_membership_audit_logs (
    tenant_id,
    actor_id,
    target_user_id,
    operation,
    before_data,
    after_data
  ) values (
    case when tg_op = 'DELETE' then old.tenant_id else new.tenant_id end,
    auth.uid(),
    case when tg_op = 'DELETE' then old.user_id else new.user_id end,
    lower(tg_op),
    case when tg_op = 'INSERT' then null else to_jsonb(old) end,
    case when tg_op = 'DELETE' then null else to_jsonb(new) end
  );

  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


ALTER FUNCTION private.audit_tenant_membership_change() OWNER TO postgres;

--
-- Name: build_completion_gap(text, text, text, text, text, text, numeric, numeric, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.build_completion_gap(p_key text, p_category text, p_title text, p_status text, p_reason text, p_href text, p_current_value numeric DEFAULT NULL::numeric, p_required_value numeric DEFAULT NULL::numeric, p_source_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select jsonb_strip_nulls(jsonb_build_object(
    'key', p_key,
    'category', p_category,
    'title', p_title,
    'status', p_status,
    'currentValue', p_current_value,
    'requiredValue', p_required_value,
    'sourceId', p_source_id,
    'href', p_href,
    'reason', p_reason
  ));
$$;


