--
-- Name: can_manage_curriculum_plan(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.can_manage_curriculum_plan(p_plan_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.institution_curriculum_plans as plan
    where plan.id = p_plan_id
      and plan.tenant_id = (select private.current_tenant_id())
      and (
        (select public.current_profile_role()) in ('ceo', 'tenant_super_admin')
        or (
          (select public.current_profile_role()) = 'admin'
          and exists (
            select 1 from public.staff_app_assignments as access
            where access.tenant_id = plan.tenant_id
              and access.app_id = plan.student_app_id
              and access.staff_id = (select auth.uid())
              and access.status = 'active'
              and access.can_manage_assessments
          )
        )
        or (
          (select public.current_profile_role()) = 'teacher'
          and plan.created_by = (select auth.uid())
          and exists (
            select 1 from public.staff_app_assignments as access
            where access.tenant_id = plan.tenant_id
              and access.app_id = plan.student_app_id
              and access.staff_id = (select auth.uid())
              and access.status = 'active'
              and access.can_manage_assessments
          )
        )
      )
  );
$$;


ALTER FUNCTION private.can_manage_curriculum_plan(p_plan_id uuid) OWNER TO postgres;

--
-- Name: can_manage_standard_question_bank(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.can_manage_standard_question_bank() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.is_platform_owner()
    or exists (
      select 1
      from public.profiles as profile
      where profile.id = (select auth.uid())
        and profile.global_role = 'platform_admin'
        and coalesce(profile.status, 'active') = 'active'
    )
    or private.current_user_has_explicit_permission(
      'standard_question_bank.manage', null
    );
$$;


ALTER FUNCTION private.can_manage_standard_question_bank() OWNER TO postgres;

--
-- Name: capture_assignment_activity_event(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.capture_assignment_activity_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_student_app_id uuid;
  v_assignment_title text;
  v_event_type text;
  v_occurred_at timestamptz;
begin
  if tg_op = 'INSERT' then
    v_event_type := 'assignment_submitted';
    v_occurred_at := new.submitted_at;
  elsif new.status is not distinct from old.status
    or new.status not in ('graded', 'revision_required') then
    return new;
  else
    v_event_type := case new.status
      when 'graded' then 'assignment_graded'
      else 'assignment_revision_required'
    end;
    v_occurred_at := coalesce(new.graded_at, new.updated_at, now());
  end if;

  select assignment.student_app_id, assignment.title
  into v_student_app_id, v_assignment_title
  from public.learning_assignments as assignment
  where assignment.tenant_id = new.tenant_id
    and assignment.id = new.assignment_id;

  if v_student_app_id is null then
    raise exception '作业学习事件缺少有效的学生应用归属';
  end if;

  insert into public.student_learning_activity_events (
    tenant_id, student_id, student_app_id, category, event_type,
    source_kind, source_id, dedupe_key, occurred_at, metadata
  ) values (
    new.tenant_id,
    new.student_id,
    v_student_app_id,
    'task',
    v_event_type,
    'learning_submission',
    new.id::text,
    'submission:' || new.id::text || ':' || v_event_type,
    v_occurred_at,
    jsonb_build_object(
      'assignment_id', new.assignment_id,
      'attempt_number', new.attempt_number,
      'status', new.status,
      'score', new.score,
      'title', v_assignment_title
    )
  )
  on conflict (tenant_id, student_id, student_app_id, dedupe_key) do nothing;
  return new;
end;
$$;


ALTER FUNCTION private.capture_assignment_activity_event() OWNER TO postgres;

--
-- Name: capture_chapter_test_activity_event(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.capture_chapter_test_activity_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_student_app_id uuid;
  v_test_title text;
begin
  select test.student_app_id, test.title
  into v_student_app_id, v_test_title
  from public.chapter_tests as test
  where (new.test_id is not null and test.id = new.test_id)
     or (new.test_id is null and test.slug = new.test_slug)
  order by case when test.id = new.test_id then 0 else 1 end
  limit 1;

  if v_student_app_id is null then
    raise exception '章节测试事件缺少有效的学生应用归属';
  end if;

  insert into public.student_learning_activity_events (
    tenant_id, student_id, student_app_id, category, event_type,
    source_kind, source_id, dedupe_key, occurred_at, metadata
  ) values (
    new.tenant_id,
    new.student_id,
    v_student_app_id,
    'task',
    'chapter_test_completed',
    'chapter_test_attempt',
    new.id::text,
    'chapter-test-attempt:' || new.id::text,
    new.attempted_at,
    jsonb_build_object(
      'test_id', new.test_id,
      'test_slug', new.test_slug,
      'score', new.score,
      'passed', new.passed,
      'correct_count', new.correct_count,
      'total_questions', new.total_questions,
      'title', v_test_title
    )
  )
  on conflict (tenant_id, student_id, student_app_id, dedupe_key) do nothing;
  return new;
end;
$$;


ALTER FUNCTION private.capture_chapter_test_activity_event() OWNER TO postgres;

--
-- Name: capture_chapter_test_review_items(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.capture_chapter_test_review_items() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_test public.chapter_tests%rowtype;
  v_question public.chapter_test_questions%rowtype;
  v_selected integer;
  v_course_id uuid;
  v_course_chapter_id uuid;
begin
  begin
    select * into v_test
    from public.chapter_tests
    where id = new.test_id;
    if v_test.id is null then return new; end if;

    select chapter.id, lesson.course_id
    into v_course_chapter_id, v_course_id
    from public.course_chapters as chapter
    join public.lessons as lesson on lesson.id = chapter.lesson_id
    where chapter.chapter_test_id = v_test.id
    order by chapter.created_at
    limit 1;

    for v_question in
      select question.*
      from public.chapter_test_questions as question
      where question.test_id = v_test.id
        and question.question_type = 'single_choice'
        and question.is_chapter_test_item
    loop
      if not (new.answers ? v_question.question_key) then continue; end if;
      begin
        v_selected := (new.answers ->> v_question.question_key)::integer;
      exception when others then
        continue;
      end;
      if v_selected = v_question.correct_option then continue; end if;

      perform private.merge_student_review_item(
        new.tenant_id, new.student_id, v_test.student_app_id,
        'chapter_quiz', v_test.id, v_question.id,
        v_course_id, v_course_chapter_id, v_question.skill,
        jsonb_build_object(
          'sourceVersion', v_test.version,
          'sourceAttemptId', new.id,
          'sourceTitle', v_test.title,
          'questionKey', v_question.question_key,
          'prompt', v_question.prompt,
          'options', v_question.options,
          'questionType', v_question.question_type,
          'originalSkill', v_question.skill
        ),
        jsonb_build_object(
          'selectedOption', v_selected,
          'selectedValue', v_question.options -> v_selected
        ),
        jsonb_build_object(
          'correctOption', v_question.correct_option,
          'correctAnswer', v_question.options -> v_question.correct_option,
          'explanation', v_question.explanation
        ),
        new.attempted_at, 1, new.attempted_at
      );
    end loop;
  exception when others then
    raise warning 'chapter test review capture skipped for attempt %: %',
      new.id, sqlerrm;
  end;
  return new;
end;
$$;


ALTER FUNCTION private.capture_chapter_test_review_items() OWNER TO postgres;

--
-- Name: capture_conversation_activity_event(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.capture_conversation_activity_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_student_app_id uuid;
  v_scenario_title text;
begin
  if tg_op = 'UPDATE' and new.practice_count <= old.practice_count then
    return new;
  end if;

  select scenario.student_app_id, scenario.title
  into v_student_app_id, v_scenario_title
  from public.conversation_practice_scenarios as scenario
  where scenario.id = new.scenario_id
    and (
      scenario.tenant_id is null
      or scenario.tenant_id = new.tenant_id
    );

  if v_student_app_id is null then
    raise exception '会话练习事件缺少有效的学生应用归属';
  end if;

  insert into public.student_learning_activity_events (
    tenant_id, student_id, student_app_id, category, event_type,
    source_kind, source_id, dedupe_key, occurred_at, metadata
  ) values (
    new.tenant_id,
    new.user_id,
    v_student_app_id,
    'practice',
    'conversation_practiced',
    'conversation_practice_progress',
    new.scenario_id::text,
    'conversation:' || new.scenario_id::text || ':' || new.practice_count::text,
    new.last_practiced_at,
    jsonb_build_object(
      'practice_count', new.practice_count,
      'status', new.status,
      'confidence', new.confidence,
      'title', v_scenario_title
    )
  )
  on conflict (tenant_id, student_id, student_app_id, dedupe_key) do nothing;
  return new;
end;
$$;


ALTER FUNCTION private.capture_conversation_activity_event() OWNER TO postgres;

--
-- Name: capture_learning_submission_review_items(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.capture_learning_submission_review_items() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_assignment public.learning_assignments%rowtype;
  v_paper public.assessment_papers%rowtype;
  v_answer record;
  v_source_type text;
  v_course_chapter_id uuid;
  v_is_feedback boolean;
  v_should_capture boolean;
  v_improvement_task text;
begin
  if new.submission_state not in (
    'grading_completed', 'grade_released', 'revision_required'
  ) then return new; end if;
  if new.submission_state = old.submission_state then return new; end if;
  if new.submission_state = 'grade_released'
    and old.submission_state = 'grading_completed' then return new; end if;

  begin
    select * into v_assignment
    from public.learning_assignments where id = new.assignment_id;
    if v_assignment.id is null or v_assignment.student_app_id is null then
      return new;
    end if;
    if v_assignment.source_paper_id is not null then
      select * into v_paper
      from public.assessment_papers where id = v_assignment.source_paper_id;
    end if;

    select chapter.id into v_course_chapter_id
    from public.course_chapters as chapter
    where chapter.chapter_test_id = v_paper.source_test_id
    order by chapter.created_at
    limit 1;

    if v_assignment.assignment_type = 'homework' then
      v_source_type := 'teacher_homework';
    elsif coalesce(v_assignment.source_paper_code, v_paper.paper_code, '')
        ~* '(^|[-_])ST[0-9]'
      or coalesce(v_assignment.title, '') ~ '阶段考试' then
      v_source_type := 'stage_exam';
    elsif coalesce(v_assignment.source_paper_code, v_paper.paper_code, '')
        ~* '(MID|MIDTERM)'
      or coalesce(v_assignment.title, '') ~ '期中' then
      v_source_type := 'midterm_exam';
    elsif coalesce(v_assignment.source_paper_code, v_paper.paper_code, '')
        ~* '(FIN|FINAL)'
      or coalesce(v_assignment.title, '') ~ '期末' then
      v_source_type := 'final_exam';
    else
      v_source_type := 'formal_chapter_exam';
    end if;

    for v_answer in
      select
        answer.id, answer.question_id, answer.answer_text,
        answer.awarded_points, answer.rubric_scores, answer.grader_feedback,
        question.prompt, question.options, question.points,
        question.question_type, question.language_skill,
        question.stimulus_text, question.source_bank_question_id,
        question.source_bank_version, question.auto_graded,
        answer_key.correct_answer, answer_key.explanation
      from public.learning_submission_answers as answer
      join public.learning_assignment_questions as question
        on question.tenant_id = answer.tenant_id
       and question.id = answer.question_id
      left join public.learning_assignment_question_keys as answer_key
        on answer_key.question_id = question.id
      where answer.tenant_id = new.tenant_id
        and answer.submission_id = new.id
    loop
      v_is_feedback := v_answer.language_skill in ('speaking', 'writing');
      v_should_capture := coalesce(v_answer.awarded_points, 0) < v_answer.points
        or (v_is_feedback and (
          nullif(btrim(coalesce(v_answer.grader_feedback, '')), '') is not null
          or v_answer.rubric_scores is not null
          or nullif(btrim(coalesce(new.overall_feedback, '')), '') is not null
        ));
      if not v_should_capture then continue; end if;

      v_improvement_task := coalesce(
        nullif(btrim(coalesce(v_answer.grader_feedback, '')), ''),
        nullif(btrim(coalesce(new.overall_feedback, '')), ''),
        case when v_is_feedback
          then '按评分标准修改表达后重新提交练习。'
          else '复习正确答案与解析后重新作答。' end
      );

      perform private.merge_student_review_item(
        new.tenant_id, new.student_id, v_assignment.student_app_id,
        case when v_is_feedback
          then 'teacher_speaking_writing_feedback' else v_source_type end,
        v_assignment.id, v_answer.question_id,
        v_assignment.course_id, v_course_chapter_id, v_answer.language_skill,
        jsonb_build_object(
          'sourceVersion', coalesce(
            v_assignment.source_paper_version, v_paper.version, 1
          ),
          'sourcePaperId', v_assignment.source_paper_id,
          'sourcePaperCode', coalesce(
            v_assignment.source_paper_code, v_paper.paper_code
          ),
          'sourceSubmissionId', new.id,
          'sourceAttemptNumber', new.attempt_number,
          'sourceTitle', v_assignment.title,
          'prompt', v_answer.prompt,
          'stimulus', v_answer.stimulus_text,
          'options', v_answer.options,
          'questionType', v_answer.question_type,
          'points', v_answer.points,
          'sourceBankQuestionId', v_answer.source_bank_question_id,
          'sourceBankVersion', v_answer.source_bank_version
        ),
        jsonb_build_object('answer', v_answer.answer_text),
        jsonb_build_object(
          'correctAnswer', v_answer.correct_answer,
          'explanation', v_answer.explanation,
          'awardedPoints', v_answer.awarded_points,
          'maxPoints', v_answer.points,
          'rubric', v_answer.rubric_scores,
          'teacherComment', v_answer.grader_feedback,
          'overallComment', new.overall_feedback,
          'improvementTask', v_improvement_task,
          'gradingDecision', new.submission_state
        ),
        coalesce(new.graded_at, new.updated_at), 1,
        coalesce(new.graded_at, new.updated_at)
      );
    end loop;
  exception when others then
    raise warning 'assignment review capture skipped for submission %: %',
      new.id, sqlerrm;
  end;
  return new;
end;
$$;


