--
-- Name: capture_lesson_completion_activity_event(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.capture_lesson_completion_activity_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_student_app_id uuid;
  v_lesson_title text;
begin
  if new.status <> 'completed'
    or (tg_op = 'UPDATE' and old.status = 'completed') then
    return new;
  end if;

  select course.student_app_id, lesson.title
  into v_student_app_id, v_lesson_title
  from public.lessons as lesson
  join public.courses as course
    on course.id = lesson.course_id
   and (
     course.tenant_id is null
     or course.tenant_id = new.tenant_id
   )
  where lesson.id = new.lesson_id
    and (
      lesson.tenant_id is null
      or lesson.tenant_id = new.tenant_id
    );

  if v_student_app_id is null then
    raise exception '课时学习事件缺少有效的学生应用归属';
  end if;

  insert into public.student_learning_activity_events (
    tenant_id, student_id, student_app_id, category, event_type,
    source_kind, source_id, dedupe_key, occurred_at, metadata
  ) values (
    new.tenant_id,
    new.user_id,
    v_student_app_id,
    'course',
    'lesson_completed',
    'lesson_progress',
    new.id::text,
    'lesson-completed:' || new.id::text,
    coalesce(new.completed_at, new.last_viewed_at, new.updated_at, now()),
    jsonb_build_object(
      'course_id', new.course_id,
      'lesson_id', new.lesson_id,
      'title', v_lesson_title
    )
  )
  on conflict (tenant_id, student_id, student_app_id, dedupe_key) do nothing;
  return new;
end;
$$;


ALTER FUNCTION private.capture_lesson_completion_activity_event() OWNER TO postgres;

--
-- Name: capture_toolbox_review_item(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.capture_toolbox_review_item() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_question public.growth_toolbox_questions%rowtype;
  v_key public.growth_toolbox_question_keys%rowtype;
  v_exercise public.growth_toolbox_exercises%rowtype;
  v_student_app_id uuid;
begin
  if new.is_correct is distinct from false or new.question_id is null then
    return new;
  end if;
  begin
    select * into v_question
    from public.growth_toolbox_questions where id = new.question_id;
    select * into v_key
    from public.growth_toolbox_question_keys where question_id = new.question_id;
    select * into v_exercise
    from public.growth_toolbox_exercises where id = v_question.exercise_id;
    v_student_app_id := coalesce(
      v_exercise.student_app_id,
      '10000000-0000-4000-8000-000000000001'::uuid
    );

    perform private.merge_student_review_item(
      new.tenant_id, new.student_id, v_student_app_id,
      'specialized_practice', v_exercise.id, v_question.id,
      v_exercise.course_id, v_exercise.course_chapter_id,
      coalesce(v_question.primary_skill, new.skill),
      jsonb_build_object(
        'sourceVersion', 1,
        'sourceSessionId', new.session_id,
        'sourceAttemptId', new.id,
        'sourceTitle', v_exercise.title,
        'prompt', v_question.prompt,
        'questionType', v_question.question_type,
        'content', v_question.content_payload,
        'maxScore', v_question.max_score
      ),
      new.response_payload,
      jsonb_build_object(
        'acceptedAnswers', v_key.accepted_answers,
        'rubric', v_key.rubric,
        'explanation', v_key.explanation,
        'earnedScore', new.earned_score,
        'maxScore', new.max_score
      ),
      new.answered_at, 1, new.answered_at
    );
  exception when others then
    raise warning 'toolbox review capture skipped for attempt %: %', new.id, sqlerrm;
  end;
  return new;
end;
$$;


