-- Name: chapter_test_attempts_validate_slug(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.chapter_test_attempts_validate_slug() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.test_id is not null then
    if not exists (
      select 1 from public.chapter_tests
      where id = new.test_id and slug = new.test_slug
    ) then
      raise exception '章节测试标识不匹配（test_id 与 test_slug 不一致）';
    end if;
  elsif not exists (
    select 1 from public.chapter_tests where slug = new.test_slug
  ) then
    raise exception '没有找到对应的章节测试：%', new.test_slug;
  end if;
  return new;
end;
$$;


