--
-- Name: clamp_ebook_reading_increment(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.clamp_ebook_reading_increment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    new.reading_seconds := least(greatest(new.reading_seconds, 0), 35);
  elsif old.reading_seconds > 86400 and new.reading_seconds = 0 then
    new.progress_percent := 0;
    return new;
  else
    new.reading_seconds := least(
      greatest(new.reading_seconds, old.reading_seconds),
      old.reading_seconds + 35
    );
  end if;
  new.progress_percent := least(
    100,
    round(new.reading_seconds::numeric / 600 * 100)
  );
  return new;
end;
$$;


ALTER FUNCTION private.clamp_ebook_reading_increment() OWNER TO postgres;

--
-- Name: FUNCTION clamp_ebook_reading_increment(); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.clamp_ebook_reading_increment() IS '学生电子书阅读时长单次最多增加 35 秒，阻止休眠恢复和异常请求污染累计值。';

