--
-- Name: completion_assignment_evidence(uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.completion_assignment_evidence(p_assignment_id uuid, p_student_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_assignment public.learning_assignments%rowtype;
  v_retake_enabled boolean := false;
  v_original public.learning_submissions%rowtype;
  v_retake public.learning_submissions%rowtype;
  v_selected public.learning_submissions%rowtype;
  v_original_score numeric;
  v_retake_score numeric;
  v_score numeric;
  v_pending boolean := false;
  v_has_submission boolean := false;
  v_manual_count integer := 0;
begin
  select * into strict v_assignment
  from public.learning_assignments
  where id = p_assignment_id;

  v_retake_enabled := v_assignment.retake_paper_id is not null and exists (
    select 1
    from public.learning_assignment_retake_students as retake_student
    where retake_student.assignment_id = v_assignment.id
      and retake_student.student_id = p_student_id
  );

  select exists (
    select 1 from public.learning_submissions as submission
    where submission.assignment_id = v_assignment.id
      and submission.student_id = p_student_id
  ) into v_has_submission;

  select exists (
    select 1 from public.learning_submissions as submission
    where submission.assignment_id = v_assignment.id
      and submission.student_id = p_student_id
      and submission.submission_state in (
        'submitted_pending_grading',
        'objective_graded_pending_manual',
        'grading_completed'
      )
  ) into v_pending;

  select count(*) into v_manual_count
  from public.learning_assignment_questions as question
  where question.assignment_id = v_assignment.id
    and not question.auto_graded;

  select submission.* into v_original
  from public.learning_submissions as submission
  where submission.assignment_id = v_assignment.id
    and submission.student_id = p_student_id
    and submission.submission_state = 'grade_released'
    and submission.grade_released_at is not null
    and submission.score is not null
    and (
      not v_retake_enabled
      or submission.submitted_at < v_assignment.retake_starts_at
    )
  order by submission.submitted_at desc, submission.attempt_number desc
  limit 1;

  if v_original.id is not null then
    v_original_score := round(
      least(100, greatest(0,
        v_original.score * 100 / nullif(v_assignment.total_points, 0)
      )), 3
    );
  end if;

  if v_retake_enabled then
    select submission.* into v_retake
    from public.learning_submissions as submission
    where submission.assignment_id = v_assignment.id
      and submission.student_id = p_student_id
      and submission.submission_state = 'grade_released'
      and submission.grade_released_at is not null
      and submission.score is not null
      and submission.submitted_at >= v_assignment.retake_starts_at
    order by submission.submitted_at desc, submission.attempt_number desc
    limit 1;

    if v_retake.id is not null then
      v_retake_score := round(
        least(100, greatest(0,
          v_retake.score * 100 / nullif(v_assignment.total_points, 0)
        )), 3
      );
    end if;
  end if;

  if v_retake_score is null then
    v_score := v_original_score;
    v_selected := v_original;
  elsif v_original_score is null then
    v_score := v_retake_score;
    v_selected := v_retake;
  elsif v_assignment.retake_score_policy = 'highest' then
    if v_retake_score >= v_original_score then
      v_score := v_retake_score;
      v_selected := v_retake;
    else
      v_score := v_original_score;
      v_selected := v_original;
    end if;
  elsif v_assignment.retake_score_policy = 'latest' then
    v_score := v_retake_score;
    v_selected := v_retake;
  elsif v_assignment.retake_score_policy = 'weighted' then
    v_score := round(
      v_original_score * v_assignment.retake_original_weight_percent / 100
      + v_retake_score * (100 - v_assignment.retake_original_weight_percent) / 100,
      3
    );
    v_selected := v_retake;
  else
    raise exception '任务 % 的补考计分策略无效', v_assignment.id;
  end if;

  return jsonb_strip_nulls(jsonb_build_object(
    'assignmentId', v_assignment.id,
    'sourcePaperId', v_assignment.source_paper_id,
    'sourcePaperCode', v_assignment.source_paper_code,
    'href', '/dashboard/assignments/' || v_assignment.id,
    'hasSubmission', v_has_submission,
    'pendingGrading', v_pending and v_score is null,
    'manualQuestionCount', v_manual_count,
    'manualGradingComplete', not (v_manual_count > 0 and v_pending and v_score is null),
    'gradeReleased', v_score is not null,
    'score', v_score,
    'releasedSubmissionId', v_selected.id,
    'releasedAt', v_selected.grade_released_at,
    'retake', jsonb_strip_nulls(jsonb_build_object(
      'enabled', v_retake_enabled,
      'policy', case when v_retake_enabled then v_assignment.retake_score_policy end,
      'originalWeightPercent', case when v_retake_enabled
        then v_assignment.retake_original_weight_percent end,
      'originalGradeReleased', v_original_score is not null,
      'retakeGradeReleased', v_retake_score is not null,
      'originalScore', v_original_score,
      'retakeScore', v_retake_score
    ))
  ));
end;
$$;


ALTER FUNCTION private.completion_assignment_evidence(p_assignment_id uuid, p_student_id uuid) OWNER TO postgres;

--
-- Name: completion_evidence_uses_released_scores(jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.completion_evidence_uses_released_scores(p_evidence jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  v_key text;
  v_value jsonb;
begin
  if jsonb_typeof(p_evidence) = 'object' then
    if p_evidence ?| array['computedScore', 'tentativeScore', 'unreleasedScore'] then
      return false;
    end if;
    if p_evidence ? 'score'
      and jsonb_typeof(p_evidence -> 'score') = 'number'
      and coalesce((p_evidence ->> 'gradeReleased')::boolean, false) is false
      and coalesce((p_evidence ->> 'published')::boolean, false) is false then
      return false;
    end if;
    if p_evidence ? 'originalScore'
      and jsonb_typeof(p_evidence -> 'originalScore') = 'number'
      and coalesce((p_evidence ->> 'originalGradeReleased')::boolean, false) is false then
      return false;
    end if;
    if p_evidence ? 'retakeScore'
      and jsonb_typeof(p_evidence -> 'retakeScore') = 'number'
      and coalesce((p_evidence ->> 'retakeGradeReleased')::boolean, false) is false then
      return false;
    end if;
    for v_key, v_value in select key, value from jsonb_each(p_evidence) loop
      if v_key ~* 'score$'
        and jsonb_typeof(v_value) = 'number'
        and v_key not in ('score', 'originalScore', 'retakeScore') then
        return false;
      end if;
      if not private.completion_evidence_uses_released_scores(v_value) then
        return false;
      end if;
    end loop;
  elsif jsonb_typeof(p_evidence) = 'array' then
    for v_value in select value from jsonb_array_elements(p_evidence) loop
      if not private.completion_evidence_uses_released_scores(v_value) then
        return false;
      end if;
    end loop;
  end if;
  return true;
exception when invalid_text_representation then
  return false;
end;
$_$;


ALTER FUNCTION private.completion_evidence_uses_released_scores(p_evidence jsonb) OWNER TO postgres;

--
-- Name: completion_gap_is_valid(jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.completion_gap_is_valid(p_gap jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
begin
  return jsonb_typeof(p_gap) = 'object'
    and p_gap ?& array['key', 'category', 'title', 'status', 'reason']
    and p_gap ->> 'category' in (
      'course', 'assignment', 'chapter_exam', 'stage_exam',
      'midterm_exam', 'final_exam', 'manual_grading', 'overall_score',
      'chapter_practice', 'specialized_practice', 'review'
    )
    and p_gap ->> 'status' in (
      'missing', 'in_progress', 'failed', 'pending_grading'
    )
    and char_length(btrim(p_gap ->> 'key')) between 1 and 160
    and char_length(btrim(p_gap ->> 'title')) between 1 and 200
    and char_length(btrim(p_gap ->> 'reason')) between 2 and 500
    and (
      not (p_gap ? 'href')
      or p_gap ->> 'href' is null
      or (p_gap ->> 'href') ~ '^/dashboard(?:/|$)'
    )
    and not (p_gap ?| array[
      'color', 'icon', 'class', 'className', 'cssClass', 'backgroundColor'
    ])
    and (
      not (p_gap ? 'currentValue')
      or jsonb_typeof(p_gap -> 'currentValue') = 'number'
    )
    and (
      not (p_gap ? 'requiredValue')
      or jsonb_typeof(p_gap -> 'requiredValue') = 'number'
    );
exception when others then
  return false;
end;
$_$;


ALTER FUNCTION private.completion_gap_is_valid(p_gap jsonb) OWNER TO postgres;

--
-- Name: completion_gaps_are_valid(jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.completion_gaps_are_valid(p_gaps jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select jsonb_typeof(p_gaps) = 'array'
    and not exists (
      select 1
      from jsonb_array_elements(p_gaps) as gap
      where not private.completion_gap_is_valid(gap)
    );
$$;


ALTER FUNCTION private.completion_gaps_are_valid(p_gaps jsonb) OWNER TO postgres;

--
-- Name: completion_policy_requirements_are_valid(jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.completion_policy_requirements_are_valid(p_requirements jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_required_sections constant text[] := array[
    'textbook',
    'required_assignments',
    'formal_chapter_exams',
    'stage_exams',
    'midterm_exam',
    'final_exam',
    'subjective_grading',
    'overall_score',
    'blocking_gaps'
  ];
  v_section text;
  v_number numeric;
begin
  if jsonb_typeof(p_requirements) <> 'object'
    or not (p_requirements ?& v_required_sections) then
    return false;
  end if;

  foreach v_section in array v_required_sections loop
    if jsonb_typeof(p_requirements -> v_section) <> 'object' then
      return false;
    end if;
  end loop;

  if jsonb_typeof(p_requirements #> '{textbook,required_chapter_count}') <> 'number'
    or jsonb_typeof(p_requirements #> '{textbook,require_all_mandatory_chapters}') <> 'boolean'
    or jsonb_typeof(p_requirements #> '{required_assignments,require_all_assigned}') <> 'boolean'
    or jsonb_typeof(p_requirements #> '{required_assignments,require_submitted}') <> 'boolean'
    or jsonb_typeof(p_requirements #> '{required_assignments,require_graded}') <> 'boolean'
    or jsonb_typeof(p_requirements #> '{formal_chapter_exams,minimum_completed_count}') <> 'number'
    or jsonb_typeof(p_requirements #> '{formal_chapter_exams,minimum_passed_count}') <> 'number'
    or jsonb_typeof(p_requirements #> '{formal_chapter_exams,passing_score}') <> 'number'
    or jsonb_typeof(p_requirements #> '{stage_exams,required_count}') <> 'number'
    or jsonb_typeof(p_requirements #> '{stage_exams,require_published_grades}') <> 'boolean'
    or jsonb_typeof(p_requirements #> '{midterm_exam,require_published_grade}') <> 'boolean'
    or jsonb_typeof(p_requirements #> '{midterm_exam,passing_score}') <> 'number'
    or jsonb_typeof(p_requirements #> '{final_exam,require_published_grade}') <> 'boolean'
    or jsonb_typeof(p_requirements #> '{final_exam,passing_score}') <> 'number'
    or jsonb_typeof(p_requirements #> '{subjective_grading,require_all_certification_items_graded}') <> 'boolean'
    or jsonb_typeof(p_requirements #> '{overall_score,minimum_score}') <> 'number'
    or jsonb_typeof(p_requirements #> '{blocking_gaps,maximum_allowed_count}') <> 'number' then
    return false;
  end if;

  foreach v_section in array array[
    'textbook.required_chapter_count',
    'formal_chapter_exams.minimum_completed_count',
    'formal_chapter_exams.minimum_passed_count',
    'stage_exams.required_count',
    'blocking_gaps.maximum_allowed_count'
  ] loop
    v_number := p_requirements #>> string_to_array(v_section, '.');
    if v_number < 0 or v_number <> trunc(v_number) then
      return false;
    end if;
  end loop;

  if ((p_requirements #>> '{textbook,required_chapter_count}')::numeric) < 1
    or ((p_requirements #>> '{formal_chapter_exams,minimum_passed_count}')::numeric)
      > ((p_requirements #>> '{formal_chapter_exams,minimum_completed_count}')::numeric) then
    return false;
  end if;

  foreach v_section in array array[
    'formal_chapter_exams.passing_score',
    'midterm_exam.passing_score',
    'final_exam.passing_score',
    'overall_score.minimum_score'
  ] loop
    v_number := p_requirements #>> string_to_array(v_section, '.');
    if v_number < 0 or v_number > 100 then
      return false;
    end if;
  end loop;

  return true;
exception
  when invalid_text_representation or numeric_value_out_of_range then
    return false;
end;
$$;


ALTER FUNCTION private.completion_policy_requirements_are_valid(p_requirements jsonb) OWNER TO postgres;

