--
-- Name: current_staff_has_app_capability(uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.current_staff_has_app_capability(p_tenant_id uuid, p_app_id uuid, p_capability text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    p_tenant_id = private.current_tenant_id()
    and p_capability in (
      'manage_availability', 'manage_students', 'manage_content',
      'manage_assessments', 'view_analytics'
    )
    and exists (
      select 1
      from public.profiles as profile
      join public.tenant_memberships as membership
        on membership.user_id = profile.id
       and membership.tenant_id = p_tenant_id
      join public.tenant_student_apps as tenant_app
        on tenant_app.tenant_id = membership.tenant_id
       and tenant_app.app_id = p_app_id
      left join public.staff_app_assignments as staff_access
        on staff_access.tenant_id = membership.tenant_id
       and staff_access.staff_id = membership.user_id
       and staff_access.app_id = tenant_app.app_id
       and staff_access.status = 'active'
      where profile.id = (select auth.uid())
        and coalesce(profile.status, 'active') = 'active'
        and membership.status = 'active'
        and membership.role in ('teacher', 'admin', 'ceo', 'tenant_super_admin')
        and (
          (
            membership.role in ('ceo', 'tenant_super_admin')
            and p_capability in (
              'manage_availability', 'manage_students', 'manage_content',
              'manage_assessments', 'view_analytics'
            )
          )
          or (
            tenant_app.is_enabled
            and tenant_app.status <> 'hidden'
            and staff_access.staff_id is not null
            and case p_capability
              when 'manage_students' then staff_access.can_manage_students
              when 'manage_content' then staff_access.can_manage_content
              when 'manage_assessments' then staff_access.can_manage_assessments
              when 'view_analytics' then staff_access.can_view_analytics
              else false
            end
          )
        )
    );
$$;


ALTER FUNCTION private.current_staff_has_app_capability(p_tenant_id uuid, p_app_id uuid, p_capability text) OWNER TO postgres;

--
-- Name: current_student_can_read_learning_recommendation(uuid, uuid, text, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.current_student_can_read_learning_recommendation(p_tenant_id uuid, p_student_app_id uuid, p_target_scope text, p_class_id uuid, p_student_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    private.current_student_has_app_access(
      p_tenant_id, (select auth.uid()), p_student_app_id
    )
    and (
      (
        p_target_scope = 'student'
        and p_class_id is null
        and p_student_id = (select auth.uid())
      )
      or (
        p_target_scope = 'class'
        and p_student_id is null
        and exists (
          select 1
          from public.live_class_sessions as class
          join public.live_class_members as member on member.session_id = class.id
          join public.courses as course on course.id = class.course_id
          where class.id = p_class_id
            and class.tenant_id = p_tenant_id
            and class.mode = 'group'
            and member.student_id = (select auth.uid())
            and course.student_app_id = p_student_app_id
        )
      )
    );
$$;


ALTER FUNCTION private.current_student_can_read_learning_recommendation(p_tenant_id uuid, p_student_app_id uuid, p_target_scope text, p_class_id uuid, p_student_id uuid) OWNER TO postgres;

--
-- Name: current_student_can_use_textbook_activity(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.current_student_can_use_textbook_activity(p_tenant_id uuid, p_student_id uuid, p_activity_id uuid, p_version_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.digital_textbook_activities as activity
    join public.digital_textbook_nodes as node on node.id = activity.node_id
    join public.digital_textbook_modules as module on module.id = node.module_id
    join public.digital_textbook_chapters as chapter on chapter.id = module.chapter_id
    join public.digital_textbook_versions as chapter_version
      on chapter_version.id = chapter.version_id
    join public.digital_textbooks as textbook
      on textbook.id = chapter_version.textbook_id
    join public.digital_textbook_versions as requested_version
      on requested_version.id = p_version_id
     and requested_version.id = chapter_version.id
    where activity.id = p_activity_id
      and chapter.status = 'published'
      and requested_version.status = 'published'
      and textbook.status = 'published'
      and private.current_student_has_app_access(
        p_tenant_id, p_student_id, textbook.student_app_id
      )
  );
$$;


ALTER FUNCTION private.current_student_can_use_textbook_activity(p_tenant_id uuid, p_student_id uuid, p_activity_id uuid, p_version_id uuid) OWNER TO postgres;

