-- Name: current_student_can_use_textbook_node(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.current_student_can_use_textbook_node(p_tenant_id uuid, p_student_id uuid, p_node_id uuid, p_version_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
