ALTER FUNCTION private.current_student_can_use_textbook_node(p_tenant_id uuid, p_student_id uuid, p_node_id uuid, p_version_id uuid) OWNER TO postgres;

--
-- Name: current_student_has_app_access(uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.current_student_has_app_access(p_tenant_id uuid, p_student_id uuid, p_app_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    p_student_id = (select auth.uid())
    and p_tenant_id = private.current_tenant_id()
    and exists (
      select 1
      from public.profiles as profile
      join public.tenant_memberships as membership
        on membership.user_id = profile.id
       and membership.tenant_id = p_tenant_id
      join public.tenant_student_apps as tenant_app
        on tenant_app.tenant_id = membership.tenant_id
       and tenant_app.app_id = p_app_id
      join public.student_app_enrollments as enrollment
        on enrollment.tenant_id = membership.tenant_id
       and enrollment.student_id = membership.user_id
       and enrollment.app_id = tenant_app.app_id
      where profile.id = p_student_id
        and coalesce(profile.status, 'active') = 'active'
        and membership.role = 'student'
        and membership.status = 'active'
        and tenant_app.is_enabled
        and tenant_app.status = 'active'
        and enrollment.status = 'active'
        and enrollment.starts_at <= now()
        and (enrollment.ends_at is null or enrollment.ends_at > now())
    );
$$;


ALTER FUNCTION private.current_student_has_app_access(p_tenant_id uuid, p_student_id uuid, p_app_id uuid) OWNER TO postgres;

--
-- Name: current_teacher_can_manage_learning_recommendation(uuid, uuid, uuid, text, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.current_teacher_can_manage_learning_recommendation(p_tenant_id uuid, p_teacher_id uuid, p_student_app_id uuid, p_target_scope text, p_class_id uuid, p_student_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    p_teacher_id = (select auth.uid())
    and p_tenant_id = private.current_tenant_id()
    and private.current_staff_has_app_capability(
      p_tenant_id, p_student_app_id, 'view_analytics'
    )
    and (
      (
        p_target_scope = 'student'
        and p_class_id is null
        and private.current_teacher_has_student_app_access(
          p_tenant_id, p_student_id, p_student_app_id
        )
      )
      or (
        p_target_scope = 'class'
        and p_student_id is null
        and exists (
          select 1
          from public.live_class_sessions as class
          join public.courses as course on course.id = class.course_id
          where class.id = p_class_id
            and class.tenant_id = p_tenant_id
            and class.teacher_id = (select auth.uid())
            and class.mode = 'group'
            and course.student_app_id = p_student_app_id
        )
      )
    );
$$;


ALTER FUNCTION private.current_teacher_can_manage_learning_recommendation(p_tenant_id uuid, p_teacher_id uuid, p_student_app_id uuid, p_target_scope text, p_class_id uuid, p_student_id uuid) OWNER TO postgres;

