--
-- Name: default_tenant_of(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.default_tenant_of(target_user_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select membership.tenant_id
  from public.tenant_memberships as membership
  where membership.user_id = target_user_id
  order by
    (membership.status = 'active') desc,
    membership.is_default desc,
    membership.created_at,
    membership.tenant_id
  limit 1;
$$;


ALTER FUNCTION private.default_tenant_of(target_user_id uuid) OWNER TO postgres;

--
-- Name: enforce_announcement_scope(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enforce_announcement_scope() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  resolved_tenant_id uuid;
begin
  if tg_op = 'UPDATE' then
    if new.scope is distinct from old.scope
      or new.tenant_id is distinct from old.tenant_id then
      raise exception '不能修改公告的发布范围';
    end if;
    return new;
  end if;

  if new.scope = 'platform' then
    if new.tenant_id is not null then
      raise exception '平台公告不能归属某个机构';
    end if;
    return new;
  end if;

  if new.tenant_id is null then
    resolved_tenant_id := private.current_tenant_id();
    if resolved_tenant_id is null and new.created_by is not null then
      resolved_tenant_id := private.default_tenant_of(new.created_by);
    end if;
    new.tenant_id := resolved_tenant_id;
  end if;

  if new.tenant_id is null then
    raise exception '机构公告缺少机构上下文';
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.enforce_announcement_scope() OWNER TO postgres;

--
-- Name: enforce_assessment_paper_release_owner(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enforce_assessment_paper_release_owner() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if (
    (tg_op = 'INSERT' and new.status <> 'draft')
    or (tg_op = 'UPDATE' and new.status is distinct from old.status)
  ) and not public.current_user_can_release_assessment_papers() then
    raise exception '只有平台负责人可以发布、撤回、停止提供或归档试卷';
  end if;

  if tg_op = 'UPDATE' and old.status <> 'draft' and (
    new.paper_type is distinct from old.paper_type
    or new.title is distinct from old.title
    or new.description is distinct from old.description
    or new.source_test_id is distinct from old.source_test_id
    or new.student_app_id is distinct from old.student_app_id
    or new.duration_minutes is distinct from old.duration_minutes
    or new.passing_score is distinct from old.passing_score
    or new.allow_resubmission is distinct from old.allow_resubmission
    or new.total_points is distinct from old.total_points
    or new.question_count is distinct from old.question_count
    or new.version is distinct from old.version
  ) then
    raise exception '已发布或已停止提供的试卷内容不可直接修改，请复制为新草稿';
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.enforce_assessment_paper_release_owner() OWNER TO postgres;

--
-- Name: enforce_chapter_test_learning_prerequisites(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enforce_chapter_test_learning_prerequisites() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_test public.chapter_tests%rowtype;
  v_tenant_id uuid := private.current_tenant_id();
begin
  if auth.uid() is null or auth.role() = 'service_role' then
    return new;
  end if;

  if new.student_id is distinct from auth.uid()
    or new.tenant_id is distinct from v_tenant_id then
    raise exception '不能为其他学生或租户提交章节测试';
  end if;

  select * into v_test
  from public.chapter_tests
  where id = new.test_id
    and slug = new.test_slug
    and status = 'published';

  if not found then
    raise exception '没有找到这份章节测试';
  end if;

  if v_test.student_app_id is distinct from
    '10000000-0000-4000-8000-000000000001'::uuid then
    raise exception '这份测试不属于韩语学习应用';
  end if;

  if not public.student_feature_allowed('korean_course') then
    raise exception '当前会员档位没有权限提交这项测试';
  end if;

  if not exists (
    select 1
    from public.course_ebook_progress as progress
    where progress.tenant_id = new.tenant_id
      and progress.student_id = new.student_id
      and progress.student_app_id = v_test.student_app_id
      and progress.test_slug = v_test.slug
      and (
        progress.completion_source in ('smart_textbook', 'both')
        or (
          progress.progress_percent >= 100
          and progress.reading_seconds >= 600
        )
      )
  ) then
    raise exception '请先完成本章电子书或八个智能教材节点，再开始章节测试';
  end if;

  if exists (
    select 1
    from public.chapter_tests as prior_test
    where prior_test.student_app_id = v_test.student_app_id
      and prior_test.course_key = v_test.course_key
      and prior_test.status = 'published'
      and prior_test.chapter_number < v_test.chapter_number
      and not exists (
        select 1
        from public.chapter_test_attempts as prior_attempt
        where prior_attempt.tenant_id = new.tenant_id
          and prior_attempt.student_id = new.student_id
          and prior_attempt.test_id = prior_test.id
          and prior_attempt.passed
      )
  ) then
    raise exception '请先通过前面章节的测试，再开始本章测试';
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.enforce_chapter_test_learning_prerequisites() OWNER TO postgres;

--
-- Name: FUNCTION enforce_chapter_test_learning_prerequisites(); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.enforce_chapter_test_learning_prerequisites() IS 'Korean chapter-test guard: current tenant/student/app/tier, prior tests, and either verified ebook time or all eight smart-textbook nodes.';

