--
-- Name: enforce_course_completion_certificate_state(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enforce_course_completion_certificate_state() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception '结课证书不可删除，只能通过 RPC 撤销或重新颁发';
  end if;

  if tg_op = 'INSERT' then
    -- Always overwrite the value. No insert path, including a future trusted
    -- server path, can smuggle in a caller-selected certificate number.
    new.certificate_number := private.generate_course_completion_certificate_number();
    if new.status <> 'issued'
      or new.revoked_by is not null
      or new.revoked_at is not null
      or new.revocation_reason is not null then
      raise exception '新证书必须以 issued 状态创建且不得预填撤销信息';
    end if;

    if new.reissued_from_id is not null and not exists (
      select 1
      from public.course_completion_certificates as previous
      where previous.id = new.reissued_from_id
        and previous.tenant_id = new.tenant_id
        and previous.student_id = new.student_id
        and previous.student_app_id = new.student_app_id
        and previous.course_id = new.course_id
        and previous.status = 'revoked'
    ) then
      raise exception '重新颁发来源必须是同一学生、机构和课程下已撤销的证书';
    end if;
    return new;
  end if;

  if (
    to_jsonb(new) - array[
      'status', 'revoked_by', 'revoked_at', 'revocation_reason'
    ]
  ) is distinct from (
    to_jsonb(old) - array[
      'status', 'revoked_by', 'revoked_at', 'revocation_reason'
    ]
  ) then
    raise exception '证书编号、身份、来源和颁发时快照均不可修改';
  end if;

  if old.status = 'issued' and new.status = 'revoked' then
    if new.revoked_by is null
      or new.revoked_at is null
      or new.revocation_reason is null
      or char_length(btrim(new.revocation_reason)) not between 2 and 1000 then
      raise exception '撤销证书必须保存操作者、时间和明确原因';
    end if;
  elsif old.status = 'revoked' and new.status = 'reissued' then
    if new.revoked_by is distinct from old.revoked_by
      or new.revoked_at is distinct from old.revoked_at
      or new.revocation_reason is distinct from old.revocation_reason then
      raise exception '重新颁发不能改写原证书的撤销记录';
    end if;
  else
    raise exception '无效的证书状态转换：% -> %', old.status, new.status;
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.enforce_course_completion_certificate_state() OWNER TO postgres;

--
-- Name: enforce_course_completion_policy_lifecycle(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enforce_course_completion_policy_lifecycle() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
begin
  if v_actor_id is null or not private.is_platform_owner() then
    raise exception '只有平台负责人可以创建、发布、停用或修改结课政策';
  end if;

  if tg_op = 'DELETE' then
    if old.status <> 'draft' then
      raise exception '已发布的结课政策不可删除，请发布新版本或停用当前版本';
    end if;
    return old;
  end if;

  if tg_op = 'INSERT' then
    if new.status = 'retired' then
      raise exception '新建结课政策只能是草稿或直接发布';
    end if;
    if new.created_by is not null and new.created_by <> v_actor_id then
      raise exception '结课政策创建人必须是当前平台负责人';
    end if;
    new.created_by := v_actor_id;
  else
    if new.created_by is distinct from old.created_by then
      raise exception '结课政策创建人不可修改';
    end if;

    if old.status = 'published' then
      if new.status not in ('published', 'retired')
        or (to_jsonb(new) - array['status', 'updated_at'])
          is distinct from (to_jsonb(old) - array['status', 'updated_at']) then
        raise exception '已发布的结课政策内容不可直接修改，请复制为新版本';
      end if;
    elsif old.status = 'retired' then
      raise exception '已发布并停用的结课政策不可修改，请复制为新版本';
    elsif new.status = 'retired' then
      raise exception '草稿不能直接停用';
    end if;
  end if;

  if not exists (
    select 1
    from public.courses as course
    where course.id = new.course_id
      and course.student_app_id = new.student_app_id
  ) then
    raise exception '结课政策的 course_id 与 student_app_id 不属于同一学习应用';
  end if;

  if new.status = 'published'
    and (tg_op = 'INSERT' or old.status is distinct from 'published') then
    if new.effective_from is null then
      raise exception '发布结课政策必须设置生效时间';
    end if;
    if not private.completion_policy_requirements_are_valid(new.requirements) then
      raise exception '结课政策 requirements 缺少必修项、阈值或字段类型无效';
    end if;
    new.published_by := v_actor_id;
    new.published_at := now();
  elsif new.status = 'draft' then
    new.published_by := null;
    new.published_at := null;
  end if;

  new.updated_at := now();
  return new;
end;
$$;


ALTER FUNCTION private.enforce_course_completion_policy_lifecycle() OWNER TO postgres;

--
-- Name: enforce_explicit_student_app_ownership(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enforce_explicit_student_app_ownership() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_row jsonb := to_jsonb(new);
  v_old_row jsonb := case
    when tg_op = 'UPDATE' then to_jsonb(old)
    else null
  end;
  v_student_app_id uuid := nullif(v_row ->> 'student_app_id', '')::uuid;
  v_parent_app_id uuid;
  v_related_id uuid;
begin
  if v_student_app_id is null then
    raise exception '缺少学生应用归属，拒绝写入';
  end if;

  if tg_table_name = 'growth_toolbox_items' then
    v_related_id := nullif(v_row ->> 'related_course_id', '')::uuid;
    if v_related_id is not null then
      select course.student_app_id into v_parent_app_id
      from public.courses as course
      where course.id = v_related_id;
      if v_parent_app_id is null
        or v_parent_app_id is distinct from v_student_app_id then
        raise exception '工具入口关联课程与入口不属于同一个应用';
      end if;
    end if;
  elsif tg_table_name = 'growth_toolbox_vocabulary' then
    v_related_id := nullif(v_row ->> 'source_chapter_id', '')::uuid;
    if v_related_id is not null then
      select textbook.student_app_id into v_parent_app_id
      from public.digital_textbook_chapters as chapter
      join public.digital_textbook_versions as version
        on version.id = chapter.version_id
      join public.digital_textbooks as textbook
        on textbook.id = version.textbook_id
      where chapter.id = v_related_id;
      if v_parent_app_id is null
        or v_parent_app_id is distinct from v_student_app_id then
        raise exception '工具箱词汇来源章节与词汇不属于同一个应用';
      end if;
    end if;
  end if;

  if tg_op = 'UPDATE'
    and nullif(v_old_row ->> 'student_app_id', '')::uuid
      is distinct from v_student_app_id then
    raise exception '应用归属创建后不可修改；请在目标应用重新创建数据';
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.enforce_explicit_student_app_ownership() OWNER TO postgres;

