--
-- Name: enforce_tenant_membership_integrity(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enforce_tenant_membership_integrity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := auth.uid();
  affected_tenant_id uuid;
  removes_owner boolean := false;
  is_hard_delete boolean := coalesce(current_setting('app.tenant_hard_delete', true), '') = 'on';
begin
  affected_tenant_id := case when tg_op = 'DELETE' then old.tenant_id else new.tenant_id end;

  if is_hard_delete
     and tg_op = 'DELETE'
     and private.is_platform_tenant_manager() then
    return old;
  end if;

  if tg_op <> 'DELETE' and new.is_default and new.status <> 'active' then
    raise exception '默认租户成员关系必须处于活跃状态';
  end if;

  if tg_op = 'DELETE' then
    removes_owner := old.role = 'tenant_super_admin' and old.status = 'active';
  elsif tg_op = 'UPDATE' then
    removes_owner := old.role = 'tenant_super_admin' and old.status = 'active'
      and (new.role <> 'tenant_super_admin' or new.status <> 'active');
  end if;

  if removes_owner and not exists (
    select 1
    from public.tenant_memberships as membership
    where membership.tenant_id = affected_tenant_id
      and membership.user_id <> old.user_id
      and membership.role = 'tenant_super_admin'
      and membership.status = 'active'
  ) then
    raise exception '租户必须保留至少一个活跃的超级管理员';
  end if;

  if tg_op = 'UPDATE'
     and actor_id = old.user_id
     and new.tenant_id = old.tenant_id
     and new.user_id = old.user_id
     and new.role = old.role
     and new.status = old.status
     and new.membership_tier = old.membership_tier
     and new.invited_by is not distinct from old.invited_by
     and new.joined_at is not distinct from old.joined_at
     and new.created_at = old.created_at then
    return new;
  end if;

  if tg_op = 'INSERT'
     and actor_id = new.user_id
     and new.role = 'tenant_super_admin'
     and new.status = 'active'
     and exists (
       select 1
       from public.tenants as tenant
       where tenant.id = new.tenant_id
         and tenant.created_by = actor_id
     )
     and not exists (
       select 1
       from public.tenant_memberships as membership
       where membership.tenant_id = new.tenant_id
     ) then
    return new;
  end if;

  if tg_op = 'INSERT'
     and new.tenant_id = '00000000-0000-4000-8000-000000000001'::uuid
     and (actor_id is null or actor_id = new.user_id)
     and new.role = 'student'
     and not exists (
       select 1
       from public.tenant_memberships as membership
       where membership.user_id = new.user_id
     ) then
    return new;
  end if;

  if actor_id is not null
     and auth.role() <> 'service_role'
     and not private.has_tenant_role(
       affected_tenant_id,
       array['tenant_super_admin']::text[]
     ) then
    if not private.has_tenant_role(
      affected_tenant_id,
      array['ceo']::text[]
    ) then
      raise exception '只有租户超级管理员或 CEO 可以管理成员';
    end if;

    if (tg_op <> 'INSERT' and old.role = 'tenant_super_admin')
       or (tg_op <> 'DELETE' and new.role = 'tenant_super_admin') then
      raise exception '只有租户超级管理员可以管理超级管理员角色';
    end if;
  end if;

  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


ALTER FUNCTION private.enforce_tenant_membership_integrity() OWNER TO postgres;

--
-- Name: FUNCTION enforce_tenant_membership_integrity(); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.enforce_tenant_membership_integrity() IS '保护租户成员完整性；仅在平台生命周期管理员执行永久删除租户时放行成员清理';

--
-- Name: enforce_tenant_scope(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enforce_tenant_scope() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  resolved uuid;
  row_json jsonb;
  owner_id uuid;
begin
  if tg_op = 'UPDATE' then
    if coalesce(current_setting('app.platform_content_migration', true), '') = 'on' then return new; end if;
    if new.tenant_id is distinct from old.tenant_id then raise exception '不能把数据移动到其他租户'; end if;
    return new;
  end if;

  row_json := to_jsonb(new);
  if private.is_platform_course_manager()
     and tg_table_name in ('course_categories', 'courses', 'lessons', 'lesson_resources', 'course_chapters', 'course_content_audit_logs') then
    new := jsonb_populate_record(new, row_json || jsonb_build_object('tenant_id', null, 'content_scope', 'platform'));
    return new;
  end if;

  if new.tenant_id is null then
    resolved := private.current_tenant_id();
    if resolved is null then
      owner_id := coalesce(
        nullif(row_json->>'user_id', '')::uuid,
        nullif(row_json->>'student_id', '')::uuid,
        nullif(row_json->>'target_user_id', '')::uuid,
        nullif(row_json->>'admin_id', '')::uuid,
        nullif(row_json->>'actor_id', '')::uuid,
        nullif(row_json->>'created_by', '')::uuid
      );
      if owner_id is not null then resolved := private.default_tenant_of(owner_id); end if;
    end if;
    new.tenant_id := resolved;
  end if;
  if new.tenant_id is null then raise exception '缺少租户上下文，拒绝写入'; end if;
  return new;
end;
$$;


ALTER FUNCTION private.enforce_tenant_scope() OWNER TO postgres;

--
-- Name: FUNCTION enforce_tenant_scope(); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.enforce_tenant_scope() IS '业务表统一租户约束：插入自动落当前租户（服务端按归属用户推导），禁止跨租户改行';

--
-- Name: enqueue_completion_after_grade_item_publish(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enqueue_completion_after_grade_item_publish() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_course_id uuid;
  v_student_app_id uuid;
begin
  if new.status <> 'published' or new.published_at is null
    or (tg_op = 'UPDATE' and old.status = 'published') then
    return new;
  end if;

  select coalesce(new.course_id, assignment.course_id),
    coalesce(course.student_app_id, assignment.student_app_id)
  into v_course_id, v_student_app_id
  from (select 1) as singleton
  left join public.learning_assignments as assignment
    on assignment.id = new.source_assignment_id
   and assignment.tenant_id = new.tenant_id
  left join public.courses as course
    on course.id = coalesce(new.course_id, assignment.course_id);

  if v_course_id is null or v_student_app_id is null then return new; end if;
  begin
    perform private.enqueue_completion_refresh_task(
      'grade_item_publish', new.tenant_id, null, v_student_app_id,
      v_course_id, null, 'grade_item', new.id::text,
      '成绩项目发布后的机构批量刷新',
      'grade-item-publish:' || new.id::text || ':' || new.published_at::text,
      auth.uid(), now()
    );
  exception when others then
    null;
  end;
  return new;
end;
$$;


ALTER FUNCTION private.enqueue_completion_after_grade_item_publish() OWNER TO postgres;

--
-- Name: enqueue_completion_after_policy_publish(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enqueue_completion_after_policy_publish() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.status <> 'published'
    or (tg_op = 'UPDATE' and old.status = 'published') then
    return new;
  end if;

  perform private.enqueue_completion_refresh_task(
    'policy_publish', null, null, new.student_app_id, new.course_id,
    new.id, 'course_completion_policy', new.id::text,
    '新结课政策发布后的适用学生批量刷新',
    'policy-publish:' || new.id::text, new.published_by,
    greatest(now(), new.effective_from)
  );
  return new;
end;
$$;


ALTER FUNCTION private.enqueue_completion_after_policy_publish() OWNER TO postgres;

--
-- Name: enqueue_completion_refresh_task(text, uuid, uuid, uuid, uuid, uuid, text, text, text, text, uuid, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enqueue_completion_refresh_task(p_task_kind text, p_tenant_id uuid, p_student_id uuid, p_student_app_id uuid, p_course_id uuid, p_policy_id uuid, p_source_kind text, p_source_id text, p_reason text, p_dedupe_key text, p_requested_by uuid DEFAULT NULL::uuid, p_available_at timestamp with time zone DEFAULT now()) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_task_id uuid;
begin
  insert into public.course_completion_refresh_tasks (
    task_kind, tenant_id, student_id, student_app_id, course_id, policy_id,
    source_kind, source_id, reason, dedupe_key, requested_by, available_at
  ) values (
    p_task_kind, p_tenant_id, p_student_id, p_student_app_id, p_course_id,
    p_policy_id, nullif(btrim(p_source_kind), ''), nullif(btrim(p_source_id), ''),
    btrim(p_reason), p_dedupe_key, p_requested_by,
    coalesce(p_available_at, now())
  )
  on conflict do nothing
  returning id into v_task_id;

  if v_task_id is null then
    select task.id into v_task_id
    from public.course_completion_refresh_tasks as task
    where task.dedupe_key = p_dedupe_key
      and task.status in ('pending', 'processing')
    order by task.created_at desc
    limit 1;
  end if;
  return v_task_id;
end;
$$;


ALTER FUNCTION private.enqueue_completion_refresh_task(p_task_kind text, p_tenant_id uuid, p_student_id uuid, p_student_app_id uuid, p_course_id uuid, p_policy_id uuid, p_source_kind text, p_source_id text, p_reason text, p_dedupe_key text, p_requested_by uuid, p_available_at timestamp with time zone) OWNER TO postgres;

--
-- Name: ensure_chapter_homework_plan(uuid, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.ensure_chapter_homework_plan(p_test_id uuid, p_test_title text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_plan_id uuid;
  v_course_key text;
  v_topic text;
  v_learning_goal text;
begin
  select
    test.course_key,
    concat(
      '《',
      test.title,
      case
        when nullif(btrim(test.korean_title), '') is null then ''
        else ' · ' || btrim(test.korean_title)
      end,
      '》'
    ),
    nullif(btrim(test.description), '')
  into v_course_key, v_topic, v_learning_goal
  from public.course_tests as test
  where test.id = p_test_id;

  insert into public.chapter_homework_plans (
    test_id,
    title,
    duration_minutes
  )
  values (
    p_test_id,
    left(coalesce(nullif(btrim(p_test_title), ''), '章节') || '作业', 120),
    35
  )
  on conflict (test_id) do nothing;

  select plan.id
  into v_plan_id
  from public.chapter_homework_plans as plan
  where plan.test_id = p_test_id;

  insert into public.chapter_homework_skill_settings (
    plan_id,
    language_skill,
    response_mode,
    target_question_count,
    target_points,
    duration_minutes,
    instructions,
    sort_order
  )
  values
    (
      v_plan_id,
      'listening',
      'mixed',
      5,
      25,
      8,
      case
        when v_course_key = 'hangul-introduction' then
          '听辨' || v_topic || '中的核心字母、音节与发音规则；先听后选或听写，并能区分相近音。'
        else
          '听懂围绕' || v_topic || '展开的短对话，捕捉人物、场景、关键信息和本课重点表达。'
      end ||
      case when v_learning_goal is null then '' else ' 学习重点：' || v_learning_goal end,
      1
    ),
    (
      v_plan_id,
      'speaking',
      'audio_recording',
      1,
      25,
      5,
      case
        when v_course_key = 'hangul-introduction' then
          '准确朗读' || v_topic || '中的字母、音节和例词；按提示录音，注意口型、收音和音变。'
        else
          '围绕' || v_topic || '完成情景口语录音，使用本课词汇与语法作答，保证发音清楚、表达完整。'
      end ||
      case when v_learning_goal is null then '' else ' 学习重点：' || v_learning_goal end,
      2
    ),
    (
      v_plan_id,
      'reading',
      'mixed',
      5,
      25,
      10,
      case
        when v_course_key = 'hangul-introduction' then
          '阅读并拆分' || v_topic || '中的音节和例词，判断字母组成、收音位置及适用的拼读或音变规则。'
        else
          '阅读与' || v_topic || '相关的短对话或短文，理解主旨、细节、词汇含义和语法功能。'
      end ||
      case when v_learning_goal is null then '' else ' 学习重点：' || v_learning_goal end,
      3
    ),
    (
      v_plan_id,
      'writing',
      'long_text',
      1,
      25,
      12,
      case
        when v_course_key = 'hangul-introduction' then
          '根据' || v_topic || '完成字母、音节和例词的规范书写或听写，并写出关键拼读规则。'
        else
          '围绕' || v_topic || '使用本课重点词汇和语法写 4—6 句连贯短文；内容切题、格式完整。'
      end ||
      case when v_learning_goal is null then '' else ' 学习重点：' || v_learning_goal end,
      4
    )
  on conflict (plan_id, language_skill) do nothing;

  return v_plan_id;
end;
$$;


