--
-- Name: generate_course_completion_certificate_number(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.generate_course_completion_certificate_number() RETURNS text
    LANGUAGE sql
    SET search_path TO ''
    AS $$
  select 'CERT-' || to_char(clock_timestamp(), 'YYYY') || '-'
    || upper(substr(encoded.value, 1, 8)) || '-'
    || upper(substr(encoded.value, 9, 8)) || '-'
    || upper(substr(encoded.value, 17, 8)) || '-'
    || upper(substr(encoded.value, 25, 8))
  from (
    select encode(extensions.gen_random_bytes(16), 'hex') as value
  ) as encoded;
$$;


ALTER FUNCTION private.generate_course_completion_certificate_number() OWNER TO postgres;

--
-- Name: FUNCTION generate_course_completion_certificate_number(); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.generate_course_completion_certificate_number() IS '使用 pgcrypto 加密安全随机源生成含 128 位随机熵的不可预测证书编号；不包含学生或数据库标识。';

--
-- Name: grade_review_student_app_id(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.grade_review_student_app_id(p_review_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case review.source_type
    when 'assignment_submission' then (
      select assignment.student_app_id
      from public.learning_submissions as submission
      join public.learning_assignments as assignment
        on assignment.tenant_id = submission.tenant_id
       and assignment.id = submission.assignment_id
      where submission.id = review.source_result_id
    )
    when 'chapter_test_attempt' then (
      select test.student_app_id
      from public.chapter_test_attempts as attempt
      join public.chapter_tests as test on test.id = attempt.test_id
      where attempt.id = review.source_result_id
    )
    when 'manual_grade_record' then (
      select coalesce(course.student_app_id, assignment.student_app_id)
      from public.grade_records as grade_record
      join public.grade_items as grade_item
        on grade_item.tenant_id = grade_record.tenant_id
       and grade_item.id = grade_record.item_id
      left join public.courses as course on course.id = grade_item.course_id
      left join public.learning_assignments as assignment
        on assignment.id = grade_item.source_assignment_id
      where grade_record.id = review.record_id
    )
    else null
  end
  from public.grade_review_requests as review
  where review.id = p_review_id;
$$;


ALTER FUNCTION private.grade_review_student_app_id(p_review_id uuid) OWNER TO postgres;

--
-- Name: guard_curriculum_plan_template(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_curriculum_plan_template() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_course_app_id uuid;
  v_course_scope text;
begin
  if tg_op = 'DELETE' then
    if old.status <> 'draft' then
      raise exception '已发布或停用的标准计划不能删除';
    end if;
    return old;
  end if;

  if tg_op = 'UPDATE' and old.status <> 'draft' then
    if not (
      old.status = 'published'
      and new.status = 'retired'
      and new.student_app_id = old.student_app_id
      and new.course_id is not distinct from old.course_id
      and new.title = old.title
      and new.description is not distinct from old.description
      and new.duration_days = old.duration_days
      and new.version = old.version
      and new.created_by = old.created_by
      and new.published_by is not distinct from old.published_by
      and new.published_at is not distinct from old.published_at
    ) then
      raise exception '已发布的标准计划不可修改，请建立新版本';
    end if;
  end if;

  if new.course_id is not null then
    select course.student_app_id, course.content_scope
    into v_course_app_id, v_course_scope
    from public.courses as course
    where course.id = new.course_id;

    if v_course_app_id is null
      or v_course_app_id <> new.student_app_id
      or v_course_scope <> 'platform'
    then
      raise exception '标准计划只能绑定当前应用的平台课程';
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.guard_curriculum_plan_template() OWNER TO postgres;

--
-- Name: guard_curriculum_plan_template_item(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_curriculum_plan_template_item() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_status text;
  v_duration_days integer;
  v_course_id uuid;
begin
  select template.status, template.duration_days, template.course_id
  into v_status, v_duration_days, v_course_id
  from public.curriculum_plan_templates as template
  where template.id = coalesce(new.template_id, old.template_id);

  if v_status is distinct from 'draft' then
    raise exception '已发布或停用的标准计划不能修改明细，请复制为新版本';
  end if;
  if tg_op <> 'DELETE' and new.day_offset >= v_duration_days then
    raise exception '计划项目超出模板总天数';
  end if;
  if tg_op <> 'DELETE' and new.activity_type = 'course' then
    if new.source_type not in ('lesson', 'chapter') or new.source_id is null then
      raise exception '课程学习必须绑定真实课时或章节';
    end if;
    if new.source_type = 'lesson' and (
      v_course_id is null or not exists (
        select 1 from public.lessons as lesson
        where lesson.id = new.source_id
          and lesson.course_id = v_course_id
          and lesson.is_published
      )
    ) then
      raise exception '绑定课时未发布或不属于模板课程';
    end if;
    if new.source_type = 'chapter' and (
      v_course_id is null or not exists (
        select 1
        from public.course_chapters as chapter
        join public.lessons as lesson on lesson.id = chapter.lesson_id
        where chapter.id = new.source_id
          and chapter.is_published
          and lesson.course_id = v_course_id
          and lesson.is_published
      )
    ) then
      raise exception '绑定章节未发布或不属于模板课程';
    end if;
  end if;
  if tg_op <> 'DELETE' and new.activity_type = 'chapter_test' then
    if new.source_type <> 'chapter_test' or new.source_id is null then
      raise exception '章节测试必须绑定真实测试';
    end if;
    if v_course_id is null or not exists (
      select 1
      from public.chapter_tests as test
      join public.lessons as lesson on lesson.id = test.lesson_id
      where test.id = new.source_id
        and test.status = 'published'
        and lesson.course_id = v_course_id
        and lesson.is_published
    ) then
      raise exception '绑定测试未发布或不属于模板课程';
    end if;
  end if;
  if tg_op <> 'DELETE' and new.source_type in ('lesson', 'chapter') and new.activity_type <> 'course' then
    raise exception '只有课程学习活动可以绑定课时或章节';
  end if;
  if tg_op <> 'DELETE' and new.source_type = 'chapter_test' and new.activity_type <> 'chapter_test' then
    raise exception '只有章节测试活动可以绑定测试';
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.guard_curriculum_plan_template_item() OWNER TO postgres;

--
-- Name: guard_curriculum_plan_template_publish(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_curriculum_plan_template_publish() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.status = 'draft' and new.status = 'published' then
    if not exists (
      select 1 from public.curriculum_plan_template_items as item
      where item.template_id = new.id
    ) then
      raise exception '至少添加一个计划项目后才能发布';
    end if;
    if exists (
      select 1 from public.curriculum_plan_template_items as item
      where item.template_id = new.id
        and item.activity_type = 'course'
        and (item.source_type not in ('lesson', 'chapter') or item.source_id is null)
    ) then
      raise exception '课程学习项目必须全部绑定真实课时或章节';
    end if;
    if exists (
      select 1 from public.curriculum_plan_template_items as item
      where item.template_id = new.id
        and item.activity_type = 'chapter_test'
        and (item.source_type <> 'chapter_test' or item.source_id is null)
    ) then
      raise exception '章节测试项目必须全部绑定真实测试';
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.guard_curriculum_plan_template_publish() OWNER TO postgres;

