--
-- Name: has_tenant_role(uuid, text[]); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.has_tenant_role(requested_tenant_id uuid, allowed_roles text[]) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.tenant_memberships as membership
    join public.tenants as tenant on tenant.id = membership.tenant_id
    where membership.tenant_id = requested_tenant_id
      and membership.user_id = (select auth.uid())
      and membership.status = 'active'
      and tenant.status = 'active'
      and membership.role = any(allowed_roles)
  );
$$;


