--
-- Name: korean_bank_json_strings_are_valid(jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.korean_bank_json_strings_are_valid(p_value jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_child jsonb;
begin
  if p_value is null then
    return true;
  end if;

  case jsonb_typeof(p_value)
    when 'string' then
      return private.korean_bank_text_is_valid(p_value #>> '{}');
    when 'array' then
      for v_child in select value from jsonb_array_elements(p_value)
      loop
        if not private.korean_bank_json_strings_are_valid(v_child) then
          return false;
        end if;
      end loop;
    when 'object' then
      for v_child in select value from jsonb_each(p_value)
      loop
        if not private.korean_bank_json_strings_are_valid(v_child) then
          return false;
        end if;
      end loop;
  end case;

  return true;
end;
$$;


ALTER FUNCTION private.korean_bank_json_strings_are_valid(p_value jsonb) OWNER TO postgres;

--
-- Name: korean_bank_optional_text_is_valid(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.korean_bank_optional_text_is_valid(p_value text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select
    char_length(trim(coalesce(p_value, ''))) = 0
    or private.korean_bank_text_is_valid(p_value);
$$;


ALTER FUNCTION private.korean_bank_optional_text_is_valid(p_value text) OWNER TO postgres;

--
-- Name: korean_bank_options_are_valid(jsonb, integer); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.korean_bank_options_are_valid(p_options jsonb, p_expected_count integer DEFAULT 4) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_option jsonb;
begin
  if jsonb_typeof(p_options) <> 'array'
    or jsonb_array_length(p_options) <> p_expected_count then
    return false;
  end if;

  for v_option in select value from jsonb_array_elements(p_options)
  loop
    if jsonb_typeof(v_option) <> 'string'
      or not private.korean_bank_text_is_valid(v_option #>> '{}') then
      return false;
    end if;
  end loop;

  return (
    select count(distinct value #>> '{}') = p_expected_count
    from jsonb_array_elements(p_options)
  );
end;
$$;


ALTER FUNCTION private.korean_bank_options_are_valid(p_options jsonb, p_expected_count integer) OWNER TO postgres;

--
-- Name: korean_bank_text_is_valid(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.korean_bank_text_is_valid(p_value text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select
    char_length(trim(coalesce(p_value, ''))) > 0
    and coalesce(p_value, '') ~ '[가-힣]'
    and coalesce(p_value, '') !~ '[㐀-䶿一-鿿]';
$$;


ALTER FUNCTION private.korean_bank_text_is_valid(p_value text) OWNER TO postgres;

--
-- Name: merge_student_review_item(uuid, uuid, uuid, text, uuid, uuid, uuid, uuid, text, jsonb, jsonb, jsonb, timestamp with time zone, integer, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.merge_student_review_item(p_tenant_id uuid, p_student_id uuid, p_student_app_id uuid, p_source_type text, p_source_id uuid, p_source_question_id uuid, p_course_id uuid, p_course_chapter_id uuid, p_skill text, p_content_snapshot jsonb, p_student_answer_snapshot jsonb, p_feedback_snapshot jsonb, p_occurred_at timestamp with time zone DEFAULT now(), p_error_count_delta integer DEFAULT 1, p_created_at timestamp with time zone DEFAULT now()) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_id uuid;
  v_occurred_at timestamptz := coalesce(p_occurred_at, now());
  v_feedback jsonb := coalesce(p_feedback_snapshot, '{}'::jsonb)
    || jsonb_build_object('lastErrorAt', to_jsonb(v_occurred_at));
begin
  if p_tenant_id is null or p_student_id is null or p_student_app_id is null
    or p_source_id is null then
    raise exception '复习项目缺少归属或来源';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      p_tenant_id::text || ':' || p_student_id::text || ':'
        || p_source_type || ':' || p_source_id::text || ':'
        || coalesce(p_source_question_id::text, 'none'),
      0
    )
  );

  select item.id into v_id
  from public.student_review_items as item
  where item.tenant_id = p_tenant_id
    and item.student_id = p_student_id
    and item.student_app_id = p_student_app_id
    and item.source_type = p_source_type
    and item.source_id = p_source_id
    and item.source_question_id is not distinct from p_source_question_id
  order by item.created_at, item.id
  limit 1
  for update;

  if v_id is null then
    insert into public.student_review_items (
      tenant_id, student_id, student_app_id, source_type, source_id,
      source_question_id, course_id, course_chapter_id, skill,
      content_snapshot, student_answer_snapshot, feedback_snapshot,
      error_count, status, created_at, updated_at
    ) values (
      p_tenant_id, p_student_id, p_student_app_id, p_source_type, p_source_id,
      p_source_question_id, p_course_id, p_course_chapter_id,
      private.normalize_student_review_skill(p_skill),
      coalesce(p_content_snapshot, '{}'::jsonb),
      coalesce(p_student_answer_snapshot, '{}'::jsonb),
      v_feedback, greatest(0, coalesce(p_error_count_delta, 0)), 'pending',
      coalesce(p_created_at, v_occurred_at), v_occurred_at
    ) returning id into v_id;
  else
    update public.student_review_items
    set course_id = coalesce(p_course_id, course_id),
        course_chapter_id = coalesce(p_course_chapter_id, course_chapter_id),
        skill = private.normalize_student_review_skill(p_skill),
        content_snapshot = coalesce(p_content_snapshot, content_snapshot),
        student_answer_snapshot = coalesce(
          p_student_answer_snapshot, student_answer_snapshot
        ),
        feedback_snapshot = v_feedback,
        error_count = error_count + greatest(0, coalesce(p_error_count_delta, 0)),
        status = 'pending',
        mastered_at = null,
        updated_at = v_occurred_at
    where id = v_id;
  end if;

  return v_id;
end;
$$;


ALTER FUNCTION private.merge_student_review_item(p_tenant_id uuid, p_student_id uuid, p_student_app_id uuid, p_source_type text, p_source_id uuid, p_source_question_id uuid, p_course_id uuid, p_course_chapter_id uuid, p_skill text, p_content_snapshot jsonb, p_student_answer_snapshot jsonb, p_feedback_snapshot jsonb, p_occurred_at timestamp with time zone, p_error_count_delta integer, p_created_at timestamp with time zone) OWNER TO postgres;

--
-- Name: normalize_assignment_answer(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.normalize_assignment_answer(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select lower(
    regexp_replace(
      btrim(coalesce(p_value, '')),
      '[[:space:]。．.!！?？,，;；:''"“”‘’()（）\[\]{}]+',
      '',
      'g'
    )
  );
$$;


ALTER FUNCTION private.normalize_assignment_answer(p_value text) OWNER TO postgres;

--
-- Name: normalize_completion_evaluation_gaps(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.normalize_completion_evaluation_gaps() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  new.missing_requirements := private.normalize_completion_gaps(
    new.missing_requirements
  );
  return new;
end;
$$;


ALTER FUNCTION private.normalize_completion_evaluation_gaps() OWNER TO postgres;

--
-- Name: normalize_completion_gaps(jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.normalize_completion_gaps(p_gaps jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(
    case
      when gap ->> 'status' = 'pending_grading' then gap - 'href'
      when gap ->> 'category' in (
        'stage_exam', 'midterm_exam', 'final_exam'
      ) and (
        gap ->> 'status' = 'failed'
        or gap ->> 'reason' like '%尚未布置%'
      ) then (gap - 'href') || case
        when gap ->> 'status' = 'failed'
          and gap ->> 'reason' not like '%老师%补考%'
        then jsonb_build_object(
          'reason', rtrim(gap ->> 'reason', '。') || '，老师将根据本次成绩布置补考。'
        )
        else '{}'::jsonb
      end
      else gap
    end
    order by ordinal
  ), '[]'::jsonb)
  from jsonb_array_elements(coalesce(p_gaps, '[]'::jsonb))
    with ordinality as item(gap, ordinal);
$$;


ALTER FUNCTION private.normalize_completion_gaps(p_gaps jsonb) OWNER TO postgres;

--
-- Name: normalize_student_review_skill(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.normalize_student_review_skill(p_skill text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when lower(coalesce(p_skill, '')) in (
      'listening', 'speaking', 'reading', 'writing', 'grammar', 'vocabulary'
    ) then lower(p_skill)
    when lower(coalesce(p_skill, '')) ~ '(listen|audio|听力|听音)' then 'listening'
    when lower(coalesce(p_skill, '')) ~ '(speak|pronunciation|口语|发音)' then 'speaking'
    when lower(coalesce(p_skill, '')) ~ '(read|阅读|理解)' then 'reading'
    when lower(coalesce(p_skill, '')) ~ '(writ|作文|写作|书写)' then 'writing'
    when lower(coalesce(p_skill, '')) ~ '(vocab|word|词汇|单词)' then 'vocabulary'
    else 'grammar'
  end;
$$;


ALTER FUNCTION private.normalize_student_review_skill(p_skill text) OWNER TO postgres;

--
-- Name: overwrite_previous_course_test_attempt(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.overwrite_previous_course_test_attempt() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  -- 串行化同一学生、同一测试的并发提交，避免产生重复成绩。
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      new.tenant_id::text || ':' || new.student_id::text || ':' || new.test_slug,
      0
    )
  );

  delete from public.course_test_attempts
  where tenant_id = new.tenant_id
    and student_id = new.student_id
    and test_slug = new.test_slug;

  return new;
end;
$$;


ALTER FUNCTION private.overwrite_previous_course_test_attempt() OWNER TO postgres;

