    where paper.id = v_paper_id and paper.status <> 'draft'
  ) then
    raise exception '已发布或已停止提供的试卷题目不可直接修改，请复制为新草稿';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


