--
-- Name: protect_published_chapter_practice(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.protect_published_chapter_practice() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_published_at timestamptz;
begin
  if tg_table_name = 'chapter_practice_units' then
    if old.published_at is null then
      if tg_op = 'DELETE' then
        return old;
      end if;
      return new;
    end if;

    if tg_op = 'DELETE' then
      raise exception '已发布巩固包不可删除，请停用旧版本并创建新版本';
    end if;

    if new.student_app_id is distinct from old.student_app_id
      or new.course_chapter_id is distinct from old.course_chapter_id
      or new.source_textbook_chapter_id is distinct from old.source_textbook_chapter_id
      or new.version is distinct from old.version
      or new.title is distinct from old.title
      or new.completion_rule is distinct from old.completion_rule
      or new.source_snapshot is distinct from old.source_snapshot
      or new.published_at is distinct from old.published_at then
      raise exception '已发布巩固包内容不可覆盖，请创建新版本';
    end if;

    return new;
  end if;

  if tg_op = 'INSERT' then
    select practice_unit.published_at
    into v_published_at
    from public.chapter_practice_units as practice_unit
    where practice_unit.id = new.practice_unit_id;

    if v_published_at is not null then
      raise exception '已发布巩固包的内容块不可变更，请创建新版本';
    end if;

    return new;
  end if;

  select practice_unit.published_at
  into v_published_at
  from public.chapter_practice_units as practice_unit
  where practice_unit.id = old.practice_unit_id;

  if v_published_at is not null then
    raise exception '已发布巩固包的内容块不可变更，请创建新版本';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;

  if new.practice_unit_id is distinct from old.practice_unit_id then
    select practice_unit.published_at
    into v_published_at
    from public.chapter_practice_units as practice_unit
    where practice_unit.id = new.practice_unit_id;

    if v_published_at is not null then
      raise exception '已发布巩固包的内容块不可变更，请创建新版本';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.protect_published_chapter_practice() OWNER TO postgres;

--
-- Name: FUNCTION protect_published_chapter_practice(); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.protect_published_chapter_practice() IS '保护已发布巩固版本及内容块不可覆盖或删除，同时允许将巩固包标记为需更新或已停用';

--
-- Name: refresh_completion_after_ebook_progress(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.refresh_completion_after_ebook_progress() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_course_id uuid;
begin
  if new.completed_at is null
    or (tg_op = 'UPDATE' and old.completed_at is not null) then
    return new;
  end if;

  select lesson.course_id into v_course_id
  from public.course_tests as test
  join public.lessons as lesson on lesson.id = test.lesson_id
  join public.courses as course on course.id = lesson.course_id
  where test.slug = new.test_slug
    and course.student_app_id = new.student_app_id
  limit 1;

  perform private.safe_refresh_student_course_completion(
    new.tenant_id, new.student_id, new.student_app_id, v_course_id,
    'course_ebook_progress', new.id::text, '教材章节完成'
  );
  return new;
end;
$$;


ALTER FUNCTION private.refresh_completion_after_ebook_progress() OWNER TO postgres;

--
-- Name: refresh_completion_after_grade_record(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.refresh_completion_after_grade_record() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_item public.grade_items%rowtype;
  v_course_id uuid;
  v_student_app_id uuid;
begin
  select * into v_item
  from public.grade_items
  where id = new.item_id and tenant_id = new.tenant_id
    and status = 'published' and published_at is not null;
  if v_item.id is null then return new; end if;

  select coalesce(v_item.course_id, assignment.course_id),
    coalesce(course.student_app_id, assignment.student_app_id)
  into v_course_id, v_student_app_id
  from (select 1) as singleton
  left join public.learning_assignments as assignment
    on assignment.id = v_item.source_assignment_id
   and assignment.tenant_id = v_item.tenant_id
  left join public.courses as course
    on course.id = coalesce(v_item.course_id, assignment.course_id);

  perform private.safe_refresh_student_course_completion(
    new.tenant_id, new.student_id, v_student_app_id, v_course_id,
    'grade_record', new.id::text, '已发布成绩记录变更'
  );
  return new;
end;
$$;


ALTER FUNCTION private.refresh_completion_after_grade_record() OWNER TO postgres;

--
-- Name: refresh_completion_after_grade_release(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.refresh_completion_after_grade_release() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_assignment public.learning_assignments%rowtype;
begin
  if new.submission_state <> 'grade_released'
    or (tg_op = 'UPDATE' and old.submission_state = 'grade_released') then
    return new;
  end if;

  select * into v_assignment
  from public.learning_assignments
  where id = new.assignment_id and tenant_id = new.tenant_id;

  perform private.safe_refresh_student_course_completion(
    new.tenant_id, new.student_id, v_assignment.student_app_id,
    v_assignment.course_id, 'learning_submission', new.id::text,
    case
      when v_assignment.retake_paper_id is not null
        and v_assignment.retake_starts_at is not null
        and new.submitted_at >= v_assignment.retake_starts_at
        then '补考最终成绩发布'
      when v_assignment.source_paper_code = 'EX-K1-MID-V1'
        then '期中成绩发布'
      when v_assignment.source_paper_code = 'EX-K1-FIN-V1'
        then '期末成绩发布'
      when v_assignment.source_paper_code like 'EX-K1-ST%-V1'
        then '阶段成绩发布'
      when v_assignment.source_paper_code like 'EX-K1-%-V1'
        then '章节成绩发布'
      else '必修作业成绩发布'
    end
  );
  return new;
end;
$$;


ALTER FUNCTION private.refresh_completion_after_grade_release() OWNER TO postgres;

