--
-- Name: replace_chapter_homework_listening(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.replace_chapter_homework_listening(p_test_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_question_count integer;
begin
  select count(*) into v_question_count
  from public.digital_textbook_activities as activity
  join public.digital_textbook_nodes as node on node.id = activity.node_id
  join public.digital_textbook_modules as module on module.id = node.module_id
  join public.digital_textbook_chapters as chapter on chapter.id = module.chapter_id
  join public.digital_textbook_versions as version
    on version.id = chapter.version_id and version.status = 'published'
  join public.digital_textbooks as textbook
    on textbook.id = version.textbook_id and textbook.status = 'published'
  join public.digital_textbook_activity_secrets as secret
    on secret.activity_id = activity.id
  where chapter.chapter_test_id = p_test_id
    and chapter.status = 'published'
    and activity.activity_type = 'listening'
    and secret.answer_key ->> 'kind' = 'index'
    and nullif(btrim(coalesce(secret.transcript_ko, '')), '') is not null;

  if v_question_count < 1 then
    raise exception '本章缺少可用的真实听力活动';
  end if;

  -- 此更新会触发整章题目同步；必须放在最终替换之前。
  update public.chapter_homework_skill_settings as setting
  set target_question_count = v_question_count,
      target_points = 15,
      response_mode = 'single_choice',
      instructions = '播放本章真实听力材料后完成理解题；界面不直接展示听力原文。'
  from public.chapter_homework_plans as plan
  where setting.plan_id = plan.id
    and plan.test_id = p_test_id
    and setting.language_skill = 'listening';

  delete from public.chapter_homework_questions as question
  using public.chapter_homework_plans as plan
  where question.plan_id = plan.id
    and plan.test_id = p_test_id
    and question.language_skill = 'listening';

  insert into public.chapter_homework_questions (
    plan_id, language_skill, question_type, stimulus_text, prompt, options,
    correct_answer, explanation, difficulty, source_skill, points, sort_order
  )
  select
    plan.id,
    'listening',
    'single_choice',
    secret.transcript_ko,
    coalesce(activity.prompt ->> 'zh-CN', activity.prompt ->> 'ko-KR'),
    activity.options,
    activity.options ->> ((secret.answer_key ->> 'value')::integer),
    coalesce(secret.explanation #>> '{correct,zh-CN}', '根据听力原文判断。'),
    'medium',
    'listening',
    15,
    row_number() over (order by activity.sort_order, activity.id)::integer
  from public.chapter_homework_plans as plan
  join public.digital_textbook_chapters as chapter
    on chapter.chapter_test_id = plan.test_id and chapter.status = 'published'
  join public.digital_textbook_versions as version
    on version.id = chapter.version_id and version.status = 'published'
  join public.digital_textbooks as textbook
    on textbook.id = version.textbook_id and textbook.status = 'published'
  join public.digital_textbook_modules as module on module.chapter_id = chapter.id
  join public.digital_textbook_nodes as node on node.module_id = module.id
  join public.digital_textbook_activities as activity on activity.node_id = node.id
  join public.digital_textbook_activity_secrets as secret
    on secret.activity_id = activity.id
  where plan.test_id = p_test_id
    and activity.activity_type = 'listening'
    and secret.answer_key ->> 'kind' = 'index'
    and nullif(btrim(coalesce(secret.transcript_ko, '')), '') is not null;
end;
$$;


ALTER FUNCTION private.replace_chapter_homework_listening(p_test_id uuid) OWNER TO postgres;

--
-- Name: require_teaching_script_source_review(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.require_teaching_script_source_review() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.status = 'published' and old.status is distinct from 'published' then
    lock table public.digital_textbook_modules, public.digital_textbook_nodes, public.digital_textbook_activities, public.digital_textbook_activity_secrets in share mode;
    if not exists (select 1 from public.teaching_script_source_reviews r where r.script_version_id = old.id
      and r.source_snapshot = private.teaching_script_source_snapshot(old.id)
      and r.script_token = private.teaching_script_review_token(old.id)) then
      raise exception '教材或脚本尚未复核，或复核后已变化，请先完成教材与脚本复核';
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.require_teaching_script_source_review() OWNER TO postgres;

--
-- Name: safe_refresh_student_course_completion(uuid, uuid, uuid, uuid, text, text, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.safe_refresh_student_course_completion(p_tenant_id uuid, p_student_id uuid, p_student_app_id uuid, p_course_id uuid, p_source_kind text, p_source_id text, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_result record;
  v_task_id uuid;
begin
  if p_tenant_id is null or p_student_id is null or p_student_app_id is null
    or p_course_id is null then
    return;
  end if;

  -- A later policy-publication batch covers events that occur before any
  -- active default policy exists; do not create permanently failing noise.
  if not exists (
    select 1
    from public.course_completion_policies as policy
    where policy.student_app_id = p_student_app_id
      and policy.course_id = p_course_id
      and policy.status = 'published'
      and policy.is_default
      and policy.effective_from <= now()
      and (policy.effective_until is null or policy.effective_until > now())
  ) then
    return;
  end if;

  select * into v_result
  from private.try_evaluate_student_course_completion(
    p_student_id, p_course_id, null
  );

  if not v_result.succeeded then
    begin
      v_task_id := private.enqueue_completion_refresh_task(
        'event_retry', p_tenant_id, p_student_id, p_student_app_id,
        p_course_id, null, p_source_kind, p_source_id,
        p_reason || '（自动刷新失败，等待重试）',
        concat_ws(':', 'event-retry', p_tenant_id, p_student_id, p_course_id),
        null, now()
      );
      update public.course_completion_refresh_tasks
      set last_error = left(v_result.error_code || ': ' || v_result.error_message, 2000),
          updated_at = now()
      where id = v_task_id;
    exception when others then
      -- Queue observability must not become a new reason to reject the
      -- authoritative completion or grade publication.
      null;
    end;
  end if;
exception when others then
  -- This final boundary deliberately isolates all refresh infrastructure from
  -- the business transaction that fired it.
  null;
end;
$$;


ALTER FUNCTION private.safe_refresh_student_course_completion(p_tenant_id uuid, p_student_id uuid, p_student_app_id uuid, p_course_id uuid, p_source_kind text, p_source_id text, p_reason text) OWNER TO postgres;

