-- Name: student_review_item_grade_is_released(uuid, uuid, text, uuid, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.student_review_item_grade_is_released(p_tenant_id uuid, p_student_id uuid, p_source_type text, p_source_id uuid, p_content_snapshot jsonb) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    not (p_source_type = any(array[
      'teacher_homework',
      'formal_chapter_exam',
      'stage_exam',
      'midterm_exam',
      'final_exam',
      'makeup_exam',
      'teacher_speaking_writing_feedback'
    ]::text[]))
    or exists (
      select 1
      from public.learning_submissions as submission
      where submission.tenant_id = p_tenant_id
        and submission.student_id = p_student_id
        and submission.assignment_id = p_source_id
        and submission.id::text = p_content_snapshot ->> 'sourceSubmissionId'
        and submission.submission_state = 'grade_released'
    );
$$;


