--
-- Name: sync_learning_assignment_draft_progress(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.sync_learning_assignment_draft_progress() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_attempts integer;
begin
  select coalesce(max(submission.attempt_number), 0) into v_attempts
  from public.learning_submissions as submission
  where submission.tenant_id = new.tenant_id
    and submission.assignment_id = new.assignment_id
    and submission.student_id = new.student_id;

  insert into public.learning_assignment_progress (
    tenant_id, assignment_id, student_id, progress_state,
    latest_submission_id, attempts_used, updated_at
  ) values (
    new.tenant_id, new.assignment_id, new.student_id, 'in_progress',
    null, v_attempts, new.updated_at
  )
  on conflict (tenant_id, assignment_id, student_id) do update
  set progress_state = 'in_progress',
      latest_submission_id = null,
      attempts_used = excluded.attempts_used,
      updated_at = excluded.updated_at;
  return new;
end;
$$;


ALTER FUNCTION private.sync_learning_assignment_draft_progress() OWNER TO postgres;

--
-- Name: sync_learning_assignment_submission_progress(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.sync_learning_assignment_submission_progress() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_latest public.learning_submissions%rowtype;
  v_attempts integer;
begin
  select submission.* into v_latest
  from public.learning_submissions as submission
  where submission.tenant_id = new.tenant_id
    and submission.assignment_id = new.assignment_id
    and submission.student_id = new.student_id
  order by submission.attempt_number desc, submission.submitted_at desc,
    submission.id desc
  limit 1;

  select coalesce(max(submission.attempt_number), 0) into v_attempts
  from public.learning_submissions as submission
  where submission.tenant_id = new.tenant_id
    and submission.assignment_id = new.assignment_id
    and submission.student_id = new.student_id;

  insert into public.learning_assignment_progress (
    tenant_id, assignment_id, student_id, progress_state,
    latest_submission_id, attempts_used, updated_at
  ) values (
    new.tenant_id, new.assignment_id, new.student_id,
    v_latest.submission_state, v_latest.id, v_attempts, now()
  )
  on conflict (tenant_id, assignment_id, student_id) do update
  set progress_state = excluded.progress_state,
      latest_submission_id = excluded.latest_submission_id,
      attempts_used = excluded.attempts_used,
      updated_at = now();
  return new;
end;
$$;


ALTER FUNCTION private.sync_learning_assignment_submission_progress() OWNER TO postgres;

--
-- Name: sync_profile_to_bootstrap_membership(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.sync_profile_to_bootstrap_membership() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  target_tenant_id uuid;
begin
  if old.role is not distinct from new.role
     and old.global_role is not distinct from new.global_role
     and old.status is not distinct from new.status
     and old.membership_tier is not distinct from new.membership_tier then
    return new;
  end if;

  if new.global_role in ('platform_owner', 'platform_deputy', 'platform_admin') then
    perform set_config('app.tenant_hard_delete', 'on', true);
    delete from public.tenant_memberships where user_id = new.id;
    return new;
  end if;

  select provisioned.tenant_id into target_tenant_id
  from public.tenant_provisioned_accounts as provisioned
  where provisioned.user_id = new.id
  order by provisioned.created_at, provisioned.tenant_id
  limit 1;
  target_tenant_id := coalesce(target_tenant_id, private.default_tenant_of(new.id));
  if target_tenant_id is null then return new; end if;

  update public.tenant_memberships as membership
  set role = case
        when new.role in ('student', 'teacher', 'admin', 'ceo', 'tenant_super_admin')
          then new.role
        else 'student'
      end,
      status = case
        when coalesce(new.status, 'active') = 'active' then 'active'
        else 'suspended'
      end,
      membership_tier = case
        when new.membership_tier in ('normal', 'vip1', 'vip2', 'vip3')
          then new.membership_tier
        else 'normal'
      end,
      is_default = case
        when coalesce(new.status, 'active') <> 'active' then false
        when membership.is_default then true
        else not exists (
          select 1
          from public.tenant_memberships as other
          where other.user_id = new.id
            and other.tenant_id <> membership.tenant_id
            and other.status = 'active'
            and other.is_default
        )
      end,
      updated_at = now()
  where membership.tenant_id = target_tenant_id
    and membership.user_id = new.id;

  return new;
end;
$$;


ALTER FUNCTION private.sync_profile_to_bootstrap_membership() OWNER TO postgres;

--
-- Name: sync_smart_textbook_chapter_completion(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.sync_smart_textbook_chapter_completion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_chapter_id uuid;
  v_test_slug text;
  v_student_app_id uuid;
  v_total_nodes integer;
  v_completed_nodes integer;
  v_total_activities integer;
  v_completed_activities integer;
begin
  if new.status <> 'completed' or new.completion_percent < 100 then
    return new;
  end if;

  select chapter.id, test.slug, test.student_app_id
  into v_chapter_id, v_test_slug, v_student_app_id
  from public.digital_textbook_nodes as node
  join public.digital_textbook_modules as module on module.id = node.module_id
  join public.digital_textbook_chapters as chapter on chapter.id = module.chapter_id
  join public.chapter_tests as test on test.id = chapter.chapter_test_id
  where node.id = new.node_id
    and chapter.version_id = new.version_id
    and test.status = 'published';

  if v_chapter_id is null then return new; end if;

  select count(*) into v_total_nodes
  from public.digital_textbook_nodes as node
  join public.digital_textbook_modules as module on module.id = node.module_id
  where module.chapter_id = v_chapter_id;

  select count(*) into v_completed_nodes
  from public.digital_textbook_node_progress as progress
  join public.digital_textbook_nodes as node on node.id = progress.node_id
  join public.digital_textbook_modules as module on module.id = node.module_id
  where module.chapter_id = v_chapter_id
    and progress.tenant_id = new.tenant_id
    and progress.student_id = new.student_id
    and progress.version_id = new.version_id
    and progress.status = 'completed'
    and progress.completion_percent = 100;

  if v_total_nodes <> 8 or v_completed_nodes <> v_total_nodes then
    return new;
  end if;

  select count(*) into v_total_activities
  from public.digital_textbook_activities as activity
  join public.digital_textbook_nodes as node on node.id = activity.node_id
  join public.digital_textbook_modules as module on module.id = node.module_id
  where module.chapter_id = v_chapter_id
    and activity.counts_toward_completion;

  select count(distinct activity.id) into v_completed_activities
  from public.digital_textbook_activities as activity
  join public.digital_textbook_nodes as node on node.id = activity.node_id
  join public.digital_textbook_modules as module on module.id = node.module_id
  join public.digital_textbook_attempts as attempt
    on attempt.activity_id = activity.id
   and attempt.tenant_id = new.tenant_id
   and attempt.student_id = new.student_id
   and attempt.version_id = new.version_id
   and (
     attempt.is_correct is true
     or (
       activity.activity_type in ('speaking', 'writing', 'self_check')
       and attempt.is_correct is null
     )
   )
  where module.chapter_id = v_chapter_id
    and activity.counts_toward_completion;

  if v_total_activities = 0 or v_completed_activities <> v_total_activities then
    return new;
  end if;

  insert into public.course_ebook_progress (
    tenant_id, student_id, student_app_id, test_slug,
    current_page, total_pages, progress_percent, read_pages,
    reading_seconds, completion_source, last_read_at, updated_at
  ) values (
    new.tenant_id, new.student_id, v_student_app_id, v_test_slug,
    0, 32, 0, '{}'::integer[], 0, 'smart_textbook', now(), now()
  )
  on conflict (tenant_id, student_id, test_slug) do nothing;

  update public.course_ebook_progress as progress
  set
    progress_percent = 100,
    completion_source = case
      when progress.completion_source = 'both' then 'both'
      when progress.completion_source = 'ebook'
        and progress.progress_percent >= 100
        and progress.reading_seconds >= 600 then 'both'
      else 'smart_textbook'
    end,
    updated_at = now()
  where progress.tenant_id = new.tenant_id
    and progress.student_id = new.student_id
    and progress.test_slug = v_test_slug;

  return new;
end;
$$;


ALTER FUNCTION private.sync_smart_textbook_chapter_completion() OWNER TO postgres;

--
-- Name: FUNCTION sync_smart_textbook_chapter_completion(); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.sync_smart_textbook_chapter_completion() IS 'When and only when all eight smart-textbook nodes and every required activity are complete, records a smart_textbook compatibility completion without fabricating ebook reading time.';

--
-- Name: sync_student_app_ownership(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.sync_student_app_ownership() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_derived_app_id uuid;
  v_secondary_app_id uuid;
begin
  if tg_table_name = 'course_categories' then
    if new.parent_id is not null then
      select parent.student_app_id into v_derived_app_id
      from public.course_categories as parent
      where parent.id = new.parent_id;
      if v_derived_app_id is null then
        raise exception '父级课程分类不存在或缺少应用归属';
      end if;
    elsif new.student_app_id is null then
      raise exception '一级课程分类必须显式选择学生应用';
    end if;

  elsif tg_table_name = 'courses' then
    select category.student_app_id into v_derived_app_id
    from public.course_categories as category
    where category.id = new.category_id;
    if v_derived_app_id is null then
      raise exception '课程分类不存在或缺少应用归属';
    end if;

  elsif tg_table_name = 'learning_assignments' then
    if new.course_id is not null then
      select course.student_app_id into v_derived_app_id
      from public.courses as course
      where course.id = new.course_id;
      if v_derived_app_id is null then
        raise exception '作业课程不存在或缺少应用归属';
      end if;
    end if;
    if new.source_paper_id is not null then
      select paper.student_app_id into v_secondary_app_id
      from public.assessment_papers as paper
      where paper.id = new.source_paper_id;
      if v_secondary_app_id is null then
        raise exception '来源试卷不存在或缺少应用归属';
      end if;
      if v_derived_app_id is not null
        and v_derived_app_id is distinct from v_secondary_app_id then
        raise exception '作业课程与来源试卷不属于同一个应用';
      end if;
      v_derived_app_id := v_secondary_app_id;
    end if;

  elsif tg_table_name = 'chapter_tests' then
    if new.lesson_id is not null then
      select course.student_app_id into v_derived_app_id
      from public.lessons as lesson
      join public.courses as course on course.id = lesson.course_id
      where lesson.id = new.lesson_id;
      if v_derived_app_id is null then
        raise exception '章节测试课时不存在或缺少应用归属';
      end if;
    end if;

  elsif tg_table_name = 'assessment_papers' then
    select test.student_app_id into v_derived_app_id
    from public.chapter_tests as test
    where test.id = new.source_test_id;
    if v_derived_app_id is null then
      raise exception '标准试卷来源测试不存在或缺少应用归属';
    end if;

  elsif tg_table_name = 'digital_textbooks' then
    select course.student_app_id into v_derived_app_id
    from public.lessons as lesson
    join public.courses as course on course.id = lesson.course_id
    where lesson.id = new.lesson_id;
    if v_derived_app_id is null then
      raise exception '互动教材课时不存在或缺少应用归属';
    end if;

  elsif tg_table_name = 'growth_toolbox_exercises' then
    if new.course_id is not null then
      select course.student_app_id into v_derived_app_id
      from public.courses as course
      where course.id = new.course_id;
      if v_derived_app_id is null then
        raise exception '练习课程不存在或缺少应用归属';
      end if;
    end if;

  elsif tg_table_name = 'toolbox_practice_sessions' then
    select exercise.student_app_id into v_derived_app_id
    from public.growth_toolbox_exercises as exercise
    where exercise.id = new.exercise_id;
    if v_derived_app_id is null then
      raise exception '练习项目不存在或缺少应用归属';
    end if;

  elsif tg_table_name in ('course_ebook_progress', 'learning_time_log') then
    if new.test_slug is not null then
      select test.student_app_id into v_derived_app_id
      from public.chapter_tests as test
      where test.slug = new.test_slug;
      if v_derived_app_id is null then
        raise exception '学习测试不存在或缺少应用归属';
      end if;
    end if;
  end if;

  if v_derived_app_id is not null then
    if new.student_app_id is not null
      and new.student_app_id is distinct from v_derived_app_id then
      raise exception '写入的应用与父级内容归属不一致';
    end if;
    new.student_app_id := v_derived_app_id;
  end if;

  if new.student_app_id is null then
    raise exception '缺少学生应用归属，拒绝写入';
  end if;

  if tg_op = 'UPDATE'
    and old.student_app_id is distinct from new.student_app_id then
    raise exception '应用归属创建后不可修改；请在目标应用重新创建内容';
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.sync_student_app_ownership() OWNER TO postgres;

--
-- Name: teaching_script_review_token(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.teaching_script_review_token(p_version_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select md5(jsonb_build_object('id', v.id, 'lessonId', v.lesson_id, 'title', v.title,
    'nodes', (select jsonb_agg(to_jsonb(n) order by n.id) from public.learning_agent_script_nodes n where n.script_version_id = v.id),
    'answers', (select jsonb_agg(to_jsonb(s) order by s.node_id) from public.learning_agent_node_interaction_secrets s
      join public.learning_agent_script_nodes n on n.id = s.node_id where n.script_version_id = v.id))::text)
  from public.learning_agent_script_versions v where v.id = p_version_id;
$$;


ALTER FUNCTION private.teaching_script_review_token(p_version_id uuid) OWNER TO postgres;

--
-- Name: teaching_script_source_snapshot(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.teaching_script_source_snapshot(p_version_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'textbookVersionId', c.version_id, 'chapterId', c.id,
    'module', to_jsonb(m) - 'created_at' - 'updated_at',
    'nodes', coalesce((select jsonb_agg(to_jsonb(n) - 'created_at' - 'updated_at' order by n.id)
      from public.digital_textbook_nodes n where n.module_id = m.id), '[]'::jsonb),
    'activities', coalesce((select jsonb_agg(to_jsonb(a) - 'created_at' - 'updated_at' order by a.id)
      from public.digital_textbook_activities a join public.digital_textbook_nodes n on n.id = a.node_id
      where n.module_id = m.id), '[]'::jsonb),
    'activityAnswers', coalesce((select jsonb_agg(to_jsonb(s) - 'created_at' - 'updated_at' order by s.activity_id)
      from public.digital_textbook_activity_secrets s join public.digital_textbook_activities a on a.id = s.activity_id
      join public.digital_textbook_nodes n on n.id = a.node_id where n.module_id = m.id), '[]'::jsonb)
  ) from public.learning_agent_script_versions v
  join public.learning_agent_lessons l on l.id = v.lesson_id
  join public.digital_textbook_modules m on m.id = l.module_id
  join public.digital_textbook_chapters c on c.id = m.chapter_id where v.id = p_version_id;
$$;


ALTER FUNCTION private.teaching_script_source_snapshot(p_version_id uuid) OWNER TO postgres;

