--
-- Name: valid_textbook_grammar_card(jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.valid_textbook_grammar_card(p jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare key text; row jsonb;
begin
 if p is null or jsonb_typeof(p) is distinct from 'object' or
 (p-'form'-'function'-'rules'-'examples'-'caution'-'source'-'comparison')<>'{}'::jsonb or
 not (p ?& array['form','function','rules','examples','caution','source']) or
 jsonb_typeof(p->'form') is distinct from 'string' or length(p->>'form') not between 1 and 12000 then return false; end if;
 foreach key in array array['function','caution','source','comparison'] loop
  if key='comparison' and not (p ? key) then continue; end if;
  row:=p->key;
  if jsonb_typeof(row) is distinct from 'object' or (row-'zh-CN'-'ko-KR')<>'{}'::jsonb or
   jsonb_typeof(row->'zh-CN') is distinct from 'string' or jsonb_typeof(row->'ko-KR') is distinct from 'string' or
   length(row->>'zh-CN')>12000 or length(row->>'ko-KR')>12000 then return false; end if;
 end loop;
 if jsonb_typeof(p->'rules') is distinct from 'array' or jsonb_typeof(p->'examples') is distinct from 'array' then return false; end if;
 for row in select value from jsonb_array_elements(p->'rules') loop
  if jsonb_typeof(row) is distinct from 'string' or length(row#>>'{}')>12000 then return false; end if;
 end loop;
 for row in select value from jsonb_array_elements(p->'examples') loop
  if jsonb_typeof(row) is distinct from 'object' or (row-'ko'-'zh'-'audioId'-'audioStatus')<>'{}'::jsonb then return false; end if;
  foreach key in array array['ko','zh','audioId','audioStatus'] loop
   if jsonb_typeof(row->key) is distinct from 'string' or length(row->>key)>12000 then return false; end if;
  end loop;
 end loop;
 return true;
end $$;


ALTER FUNCTION private.valid_textbook_grammar_card(p jsonb) OWNER TO postgres;

--
-- Name: validate_application_access_row(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.validate_application_access_row() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_row jsonb := to_jsonb(new);
  v_user_id uuid;
  v_expected_role text;
  v_membership_tier text;
begin
  if tg_table_name = 'student_app_enrollments' then
    v_user_id := nullif(v_row ->> 'student_id', '')::uuid;
    v_expected_role := 'student';
  elsif tg_table_name = 'staff_app_assignments' then
    v_user_id := nullif(v_row ->> 'staff_id', '')::uuid;
    v_expected_role := null;
  else
    raise exception '不支持的应用授权表：%', tg_table_name;
  end if;

  select membership.membership_tier
  into v_membership_tier
  from public.tenant_memberships as membership
  where membership.tenant_id = new.tenant_id
    and membership.user_id = v_user_id
    and membership.status = 'active'
    and (
      (v_expected_role = 'student' and membership.role = 'student')
      or (v_expected_role is null and membership.role in (
        'teacher', 'admin', 'ceo', 'tenant_super_admin'
      ))
    );

  if not found then
    raise exception '应用授权目标不属于当前机构或账号角色不正确';
  end if;

  if tg_table_name = 'student_app_enrollments'
    and (v_row ->> 'access_tier') is distinct from v_membership_tier then
    raise exception '学生应用等级必须与当前机构会员等级一致';
  end if;

  if not exists (
    select 1
    from public.tenant_student_apps as tenant_app
    where tenant_app.tenant_id = new.tenant_id
      and tenant_app.app_id = new.app_id
  ) then
    raise exception '当前机构没有注册该应用';
  end if;

  if new.status = 'active' and not exists (
    select 1
    from public.tenant_student_apps as tenant_app
    where tenant_app.tenant_id = new.tenant_id
      and tenant_app.app_id = new.app_id
      and tenant_app.is_enabled
      and tenant_app.status <> 'hidden'
  ) then
    raise exception '当前机构尚未开放该应用';
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.validate_application_access_row() OWNER TO postgres;

--
-- Name: validate_assessment_paper_release(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.validate_assessment_paper_release(p_paper_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_paper public.assessment_papers%rowtype;
  v_question_count integer;
  v_total_points numeric;
begin
  select * into v_paper from public.assessment_papers where id = p_paper_id;
  if v_paper.id is null or v_paper.status <> 'published' then
    raise exception '所选标准试卷当前不可发布';
  end if;
  select count(*), coalesce(sum(question.points), 0)
  into v_question_count, v_total_points
  from public.assessment_paper_questions as question
  where question.paper_id = p_paper_id;
  if v_question_count <> v_paper.question_count
    or v_total_points <> v_paper.total_points then
    raise exception '标准试卷题量或总分与题目快照不一致';
  end if;
  if exists (
    select 1
    from public.assessment_paper_questions as question
    left join public.assessment_paper_question_keys as answer_key
      on answer_key.question_id = question.id
    where question.paper_id = p_paper_id
      and question.auto_graded
      and nullif(btrim(coalesce(answer_key.correct_answer, '')), '') is null
  ) then
    raise exception '标准试卷中有客观题缺少正确答案';
  end if;

  if v_paper.paper_type = 'homework' then
    if (
      select count(distinct question.skill)
      from public.assessment_paper_questions as question
      where question.paper_id = p_paper_id
        and question.skill in (
          'vocabulary', 'grammar', 'listening', 'speaking', 'reading', 'writing'
        )
    ) <> 6 then
      raise exception '章节作业的词汇、语法、听说读写六项内容不完整';
    end if;
    if exists (
      select 1
      from public.assessment_paper_questions as question
      where question.paper_id = p_paper_id
        and question.skill = 'listening'
        and nullif(btrim(question.stimulus_text), '') is null
    ) then
      raise exception '章节作业的听力题缺少韩语听力材料';
    end if;
    if v_paper.source_homework_plan_id is not null and exists (
      select 1
      from (
        select source.language_skill, count(*) as expected_count
        from public.chapter_homework_questions as source
        where source.plan_id = v_paper.source_homework_plan_id
        group by source.language_skill
      ) as expected
      left join (
        select question.skill as language_skill, count(*) as actual_count
        from public.assessment_paper_questions as question
        where question.paper_id = p_paper_id
        group by question.skill
      ) as actual using (language_skill)
      where expected.expected_count <> coalesce(actual.actual_count, 0)
    ) then
      raise exception '章节作业与平台发布的词汇、语法或六项题目数量不一致';
    end if;
  end if;
end;
$$;


ALTER FUNCTION private.validate_assessment_paper_release(p_paper_id uuid) OWNER TO postgres;

