--
-- Name: validate_student_app_activity(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.validate_student_app_activity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tenant_id uuid;
  v_student_id uuid;
  v_app_id uuid;
begin
  if auth.uid() is null or auth.role() = 'service_role' then
    return new;
  end if;

  if tg_table_name = 'conversation_practice_progress' then
    v_tenant_id := coalesce(new.tenant_id, private.current_tenant_id());
    v_student_id := new.user_id;
    select scenario.student_app_id into v_app_id
    from public.conversation_practice_scenarios as scenario
    where scenario.id = new.scenario_id
      and (
        scenario.tenant_id is null
        or scenario.tenant_id = v_tenant_id
      );

  elsif tg_table_name = 'toolbox_practice_sessions' then
    v_tenant_id := coalesce(new.tenant_id, private.current_tenant_id());
    v_student_id := new.student_id;
    select exercise.student_app_id into v_app_id
    from public.growth_toolbox_exercises as exercise
    where exercise.id = new.exercise_id
      and (exercise.tenant_id is null or exercise.tenant_id = v_tenant_id);

  elsif tg_table_name = 'course_ebook_progress' then
    v_tenant_id := coalesce(new.tenant_id, private.current_tenant_id());
    v_student_id := new.student_id;
    select test.student_app_id into v_app_id
    from public.chapter_tests as test
    where test.slug = new.test_slug;

  elsif tg_table_name = 'chapter_test_attempts' then
    v_tenant_id := coalesce(new.tenant_id, private.current_tenant_id());
    v_student_id := new.student_id;
    select test.student_app_id into v_app_id
    from public.chapter_tests as test
    where test.id = new.test_id
      and test.slug = new.test_slug;

  elsif tg_table_name = 'lesson_progress' then
    v_tenant_id := coalesce(new.tenant_id, private.current_tenant_id());
    v_student_id := new.user_id;
    select course.student_app_id into v_app_id
    from public.courses as course
    where course.id = new.course_id
      and (course.tenant_id is null or course.tenant_id = v_tenant_id);

  elsif tg_table_name = 'learning_time_log' then
    v_tenant_id := coalesce(new.tenant_id, private.current_tenant_id());
    v_student_id := new.student_id;
    v_app_id := new.student_app_id;
  end if;

  if v_student_id is distinct from auth.uid() then
    return new;
  end if;
  if v_app_id is null then
    raise exception '学习内容不存在或缺少应用归属';
  end if;
  if not private.current_student_has_app_access(
    v_tenant_id,
    v_student_id,
    v_app_id
  ) then
    raise exception '当前学生没有该应用的有效访问权限';
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.validate_student_app_activity() OWNER TO postgres;

--
-- Name: validate_student_learning_task_preference(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.validate_student_learning_task_preference() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_prefix text;
  v_remainder text;
  v_source_type text;
  v_source_id text;
  v_source_uuid uuid;
  v_assignment_type text;
  v_recommendation_required boolean;
begin
  if tg_op = 'UPDATE' and (
    new.tenant_id is distinct from old.tenant_id
    or new.student_id is distinct from old.student_id
    or new.student_app_id is distinct from old.student_app_id
    or new.task_key is distinct from old.task_key
  ) then
    raise exception '暂缓记录的机构、学生、应用和任务标识不可改写';
  end if;

  v_prefix := new.student_app_id::text || ':';
  if left(new.task_key, char_length(v_prefix)) <> v_prefix then
    raise exception 'task_key 与 student_app_id 不匹配';
  end if;

  v_remainder := substr(new.task_key, char_length(v_prefix) + 1);
  v_source_type := split_part(v_remainder, ':', 1);
  v_source_id := substr(v_remainder, char_length(v_source_type) + 2);
  if v_source_type not in (
    'assignment', 'exam', 'course', 'chapter_practice',
    'specialized_practice', 'review', 'teacher_recommendation', 'student_plan'
  ) or v_source_id = '' then
    raise exception 'task_key 格式或来源类型无效';
  end if;

  if v_source_type in ('assignment', 'exam') then
    begin
      v_source_uuid := v_source_id::uuid;
    exception when invalid_text_representation then
      raise exception '作业或考试 task_key 的 sourceId 必须是 UUID';
    end;

    select assignment.assignment_type
    into v_assignment_type
    from public.learning_assignments as assignment
    where assignment.id = v_source_uuid
      and assignment.tenant_id = new.tenant_id
      and assignment.student_app_id = new.student_app_id
      and assignment.status = 'published'
      and (
        assignment.target_scope = 'all_students'
        or exists (
          select 1
          from public.learning_assignment_targets as target
          where target.assignment_id = assignment.id
            and target.student_id = new.student_id
        )
      );

    if v_assignment_type is null
      or (v_source_type = 'assignment' and v_assignment_type <> 'homework')
      or (v_source_type = 'exam' and v_assignment_type <> 'exam') then
      raise exception 'task_key 对应的学生作业或考试不存在';
    end if;

    raise exception using
      errcode = 'P0001',
      message = '必做任务不可暂缓：作业、考试和截止提醒必须始终显示';
  elsif v_source_type = 'teacher_recommendation' then
    begin
      v_source_uuid := v_source_id::uuid;
    exception when invalid_text_representation then
      raise exception '老师推荐 task_key 的 sourceId 必须是 UUID';
    end;

    select recommendation.is_required
    into v_recommendation_required
    from public.teacher_learning_recommendations as recommendation
    where recommendation.id = v_source_uuid
      and recommendation.tenant_id = new.tenant_id
      and recommendation.student_app_id = new.student_app_id
      and recommendation.status = 'active'
      and (
        (
          recommendation.target_scope = 'student'
          and recommendation.student_id = new.student_id
        )
        or (
          recommendation.target_scope = 'class'
          and exists (
            select 1
            from public.live_class_members as member
            where member.session_id = recommendation.class_id
              and member.student_id = new.student_id
          )
        )
      );

    if v_recommendation_required is null then
      raise exception 'task_key 对应的老师推荐不存在或未面向当前学生';
    end if;
    if v_recommendation_required then
      raise exception using
        errcode = 'P0001',
        message = '必做任务不可暂缓：老师必做推荐必须始终显示';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.validate_student_learning_task_preference() OWNER TO postgres;

--
-- Name: validate_teacher_learning_recommendation(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.validate_teacher_learning_recommendation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_source_app_id uuid;
  v_source_tenant_id uuid;
  v_source_student_id uuid;
begin
  if tg_op = 'UPDATE' then
    if new.tenant_id is distinct from old.tenant_id
      or new.student_app_id is distinct from old.student_app_id
      or new.teacher_id is distinct from old.teacher_id
      or new.target_scope is distinct from old.target_scope
      or new.class_id is distinct from old.class_id
      or new.student_id is distinct from old.student_id
      or new.source_type is distinct from old.source_type
      or new.source_id is distinct from old.source_id
      or new.title is distinct from old.title
      or new.reason is distinct from old.reason
      or new.is_required is distinct from old.is_required
      or new.starts_at is distinct from old.starts_at
      or new.due_at is distinct from old.due_at
      or old.status <> 'active'
      or new.status <> 'withdrawn' then
      raise exception '推荐创建后只能撤回，不能改写推荐内容或目标';
    end if;
    if old.starts_at <= statement_timestamp() then
      raise exception '已经开始的推荐不能撤回';
    end if;
  elsif new.status <> 'active' then
    raise exception '新推荐必须处于 active 状态';
  end if;

  if not exists (
    select 1
    from public.profiles as profile
    join public.tenant_memberships as membership
      on membership.user_id = profile.id
     and membership.tenant_id = new.tenant_id
    join public.staff_app_assignments as staff_access
      on staff_access.tenant_id = membership.tenant_id
     and staff_access.staff_id = membership.user_id
     and staff_access.app_id = new.student_app_id
    join public.tenant_student_apps as tenant_app
      on tenant_app.tenant_id = membership.tenant_id
     and tenant_app.app_id = staff_access.app_id
    where profile.id = new.teacher_id
      and coalesce(profile.status, 'active') = 'active'
      and membership.role = 'teacher'
      and membership.status = 'active'
      and staff_access.status = 'active'
      and staff_access.access_role in ('teacher', 'operator', 'administrator')
      and tenant_app.is_enabled
      and tenant_app.status = 'active'
  ) then
    raise exception '推荐老师没有当前机构应用的有效教学权限';
  end if;

  if new.target_scope = 'student' then
    if not exists (
      select 1
      from public.tenant_student_assignments as assignment
      join public.student_app_enrollments as enrollment
        on enrollment.tenant_id = assignment.tenant_id
       and enrollment.student_id = assignment.student_id
       and enrollment.app_id = assignment.student_app_id
      where assignment.tenant_id = new.tenant_id
        and assignment.teacher_id = new.teacher_id
        and assignment.student_id = new.student_id
        and assignment.student_app_id = new.student_app_id
        and enrollment.status = 'active'
        and enrollment.starts_at <= statement_timestamp()
        and (
          enrollment.ends_at is null
          or enrollment.ends_at > statement_timestamp()
        )
    ) then
      raise exception '目标学生不在老师当前应用的负责范围内';
    end if;
  elsif not exists (
    select 1
    from public.live_class_sessions as class
    join public.courses as course on course.id = class.course_id
    where class.id = new.class_id
      and class.tenant_id = new.tenant_id
      and class.teacher_id = new.teacher_id
      and class.mode = 'group'
      and course.student_app_id = new.student_app_id
  ) then
    raise exception '目标班级不属于老师或不属于当前应用';
  end if;

  if new.source_type = 'course' then
    select course.student_app_id, course.tenant_id
    into v_source_app_id, v_source_tenant_id
    from public.course_chapters as chapter
    join public.lessons as lesson on lesson.id = chapter.lesson_id
    join public.courses as course on course.id = lesson.course_id
    where chapter.id = new.source_id
      and chapter.is_published
      and lesson.is_published
      and course.is_published;
  elsif new.source_type = 'chapter_practice' then
    select unit.student_app_id, course.tenant_id
    into v_source_app_id, v_source_tenant_id
    from public.chapter_practice_units as unit
    join public.course_chapters as chapter on chapter.id = unit.course_chapter_id
    join public.lessons as lesson on lesson.id = chapter.lesson_id
    join public.courses as course on course.id = lesson.course_id
    where unit.id = new.source_id
      and unit.status = 'published';
  elsif new.source_type = 'specialized_practice' then
    select exercise.student_app_id, exercise.tenant_id
    into v_source_app_id, v_source_tenant_id
    from public.growth_toolbox_exercises as exercise
    where exercise.id = new.source_id
      and exercise.status = 'published';
  else
    select review.student_app_id, review.tenant_id, review.student_id
    into v_source_app_id, v_source_tenant_id, v_source_student_id
    from public.student_review_items as review
    where review.id = new.source_id;

    if new.target_scope <> 'student'
      or v_source_student_id is distinct from new.student_id then
      raise exception '错题推荐只能指向该错题所属学生';
    end if;
  end if;

  if v_source_app_id is null then
    raise exception '推荐来源不存在、未发布或缺少应用归属';
  end if;
  if v_source_app_id is distinct from new.student_app_id then
    raise exception '推荐来源与 student_app_id 不属于同一应用';
  end if;
  if v_source_tenant_id is not null
    and v_source_tenant_id is distinct from new.tenant_id then
    raise exception '推荐来源不属于当前机构';
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.validate_teacher_learning_recommendation() OWNER TO postgres;

--
-- Name: add_help_ticket_message(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.add_help_ticket_message(p_ticket_id uuid, p_body text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  ticket_owner uuid;
  ticket_status text;
  message_id uuid;
  is_handler boolean;
  current_tenant uuid;
begin
  current_tenant := private.current_tenant_id();
  is_handler := public.current_user_can_handle_help_tickets();

  select user_id, status
  into ticket_owner, ticket_status
  from public.help_tickets
  where id = p_ticket_id and tenant_id = current_tenant;

  if ticket_owner is null then raise exception '求助记录不存在'; end if;
  if not is_handler and ticket_owner <> auth.uid() then raise exception '无权回复该求助'; end if;
  if not is_handler and ticket_status = 'closed' then raise exception '该求助已经关闭'; end if;
  if char_length(trim(coalesce(p_body, ''))) not between 1 and 5000 then
    raise exception '回复内容需要填写 1 至 5000 个字';
  end if;

  insert into public.help_ticket_messages (
    tenant_id, ticket_id, sender_id, sender_kind, body
  ) values (
    current_tenant,
    p_ticket_id,
    auth.uid(),
    case when is_handler then 'staff' else 'student' end,
    trim(p_body)
  ) returning id into message_id;

  update public.help_tickets
  set status = case
        when is_handler and status = 'open' then 'in_progress'
        when not is_handler and status = 'waiting_student' then 'in_progress'
        else status
      end,
      assigned_to = case
        when is_handler then coalesce(assigned_to, auth.uid())
        else assigned_to
      end,
      updated_at = now()
  where id = p_ticket_id and tenant_id = current_tenant;

  return message_id;
end;
$$;


ALTER FUNCTION public.add_help_ticket_message(p_ticket_id uuid, p_body text) OWNER TO postgres;

--
-- Name: append_institution_learning_followup(uuid, uuid, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.append_institution_learning_followup(p_tenant_id uuid, p_app_id uuid, p_topic text, p_status text, p_note text, p_expected_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_latest uuid; v_id uuid;
begin
  if auth.uid() is null or not coalesce(private.is_platform_tenant_manager(),false) or private.current_tenant_id() is not null then
    raise exception '当前账号没有机构跟进权限' using errcode='42501';
  end if;
  if p_topic is null or p_topic not in ('grades','records','conversation') or p_status is null or p_status not in ('pending','in_progress','resolved') or p_note is null or char_length(btrim(p_note)) not between 1 and 2000 then
    raise exception '请选择有效状态并填写 1–2000 字处理说明' using errcode='22023';
  end if;
  -- Serialize writes even when there is no previous event; never overwrite history.
  perform 1 from public.tenant_student_apps where tenant_id=p_tenant_id and app_id=p_app_id for update;
  if not found then raise exception '机构未注册当前应用' using errcode='22023'; end if;
  select id into v_latest from public.institution_learning_followups where tenant_id=p_tenant_id and app_id=p_app_id and topic=p_topic order by sequence desc limit 1;
  if v_latest is distinct from p_expected_id then
    raise exception '跟进记录已更新，请刷新后核对最新记录再保存' using errcode='40001';
  end if;
  insert into public.institution_learning_followups(tenant_id,app_id,topic,status,note,actor_id)
  values(p_tenant_id,p_app_id,p_topic,p_status,btrim(p_note),auth.uid()) returning id into v_id;
  return v_id;
end;
$$;


ALTER FUNCTION public.append_institution_learning_followup(p_tenant_id uuid, p_app_id uuid, p_topic text, p_status text, p_note text, p_expected_id uuid) OWNER TO postgres;

--
-- Name: assert_runtime_dependency_fence_v1(text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.assert_runtime_dependency_fence_v1(p_snapshot text, p_capture jsonb) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select exists(select 1 from runtime_publish_private.dependency_fences d
  where d.snapshot_id=p_snapshot and d.capture=p_capture
  and not exists(select 1 from runtime_publish_private.retired_snapshots r where r.snapshot_id=d.snapshot_id)
  and not exists(select 1 from runtime_publish_private.authoring_control c where c.textbook_id=(d.scope->>'textbookId')::uuid and c.state<>'open'));
$$;


ALTER FUNCTION public.assert_runtime_dependency_fence_v1(p_snapshot text, p_capture jsonb) OWNER TO postgres;

--
-- Name: assign_help_ticket(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.assign_help_ticket(p_ticket_id uuid, p_teacher_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  current_tenant uuid;
begin
  current_tenant := private.current_tenant_id();
  if not (
    public.is_active_account()
    and current_tenant is not null
    and public.current_profile_role() in ('ceo', 'tenant_super_admin')
  ) then
    raise exception '只有机构负责人可以分配工单';
  end if;

  if p_teacher_id is not null and not exists (
    select 1
    from public.tenant_memberships as membership
    where membership.tenant_id = current_tenant
      and membership.user_id = p_teacher_id
      and membership.role = 'teacher'
      and membership.status = 'active'
  ) then
    raise exception '只能分配给本机构正常状态的教师';
  end if;

  update public.help_tickets
  set assigned_to = p_teacher_id,
      updated_at = now()
  where id = p_ticket_id and tenant_id = current_tenant;

  if not found then raise exception '求助记录不存在'; end if;
end;
$$;


ALTER FUNCTION public.assign_help_ticket(p_ticket_id uuid, p_teacher_id uuid) OWNER TO postgres;

--
-- Name: audit_course_content_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.audit_course_content_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  row_id uuid;
  resolved_tenant uuid;
begin
  row_id := case when tg_op = 'DELETE' then old.id else new.id end;

  -- 优先当前租户上下文；平台管理员（无租户）尝试从操作者推断；
  -- 仍为空（平台内容操作）则跳过审计，不阻塞课程/课时修改。
  resolved_tenant := private.current_tenant_id();
  if resolved_tenant is null then
    resolved_tenant := private.default_tenant_of(auth.uid());
  end if;
  if resolved_tenant is null then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  insert into public.course_content_audit_logs (
    tenant_id,
    actor_id,
    entity_type,
    entity_id,
    operation,
    before_data,
    after_data
  )
  values (
    resolved_tenant,
    auth.uid(),
    tg_argv[0],
    row_id,
    lower(tg_op),
    case when tg_op = 'INSERT' then null else to_jsonb(old) end,
    case when tg_op = 'DELETE' then null else to_jsonb(new) end
  );

  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


ALTER FUNCTION public.audit_course_content_change() OWNER TO postgres;

--
-- Name: audit_profile_management_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.audit_profile_management_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  audit_action text;
  fields text[] := '{}';
begin
  if tg_op = 'INSERT' then
    audit_action := 'account_created';
    fields := array['created_at'];
  else
    if old.role is distinct from new.role then
      fields := array_append(fields, 'role');
    end if;

    if old.global_role is distinct from new.global_role then
      fields := array_append(fields, 'global_role');
    end if;

    if old.status is distinct from new.status then
      fields := array_append(fields, 'status');
    end if;

    if old.membership_tier is distinct from new.membership_tier then
      fields := array_append(fields, 'membership_tier');
    end if;

    if old.full_name is distinct from new.full_name then fields := array_append(fields, 'full_name'); end if;
    if old.email is distinct from new.email then fields := array_append(fields, 'email'); end if;
    if old.gender is distinct from new.gender then fields := array_append(fields, 'gender'); end if;
    if old.birth_date is distinct from new.birth_date then fields := array_append(fields, 'birth_date'); end if;
    if old.avatar_path is distinct from new.avatar_path then fields := array_append(fields, 'avatar_path'); end if;
    if old.address_province is distinct from new.address_province then fields := array_append(fields, 'address_province'); end if;
    if old.address_city is distinct from new.address_city then fields := array_append(fields, 'address_city'); end if;
    if old.education_level is distinct from new.education_level then fields := array_append(fields, 'education_level'); end if;
    if old.education_status is distinct from new.education_status then fields := array_append(fields, 'education_status'); end if;
    if old.education_completion_month is distinct from new.education_completion_month then fields := array_append(fields, 'education_completion_month'); end if;
    if old.academic_average is distinct from new.academic_average then fields := array_append(fields, 'academic_average'); end if;
    if old.gaokao_has_score is distinct from new.gaokao_has_score then fields := array_append(fields, 'gaokao_has_score'); end if;
    if old.gaokao_score is distinct from new.gaokao_score then fields := array_append(fields, 'gaokao_score'); end if;
    if old.english_level is distinct from new.english_level then fields := array_append(fields, 'english_level'); end if;
    if old.math_level is distinct from new.math_level then fields := array_append(fields, 'math_level'); end if;
    if old.has_korean is distinct from new.has_korean then fields := array_append(fields, 'has_korean'); end if;
    if old.topik_level is distinct from new.topik_level then fields := array_append(fields, 'topik_level'); end if;
    if old.has_work_experience is distinct from new.has_work_experience then fields := array_append(fields, 'has_work_experience'); end if;

    if coalesce(array_length(fields, 1), 0) = 0 then
      return new;
    end if;

    if 'role' = any(fields) or 'global_role' = any(fields) then
      audit_action := 'role_changed';
    elsif 'status' = any(fields) then
      audit_action := 'status_changed';
    elsif 'membership_tier' = any(fields) then
      audit_action := 'membership_changed';
    else
      audit_action := 'profile_updated';
    end if;
  end if;

  insert into public.account_management_audit_logs (
    actor_id,
    target_user_id,
    action,
    changed_fields,
    before_data,
    after_data
  )
  values (
    auth.uid(),
    new.id,
    audit_action,
    fields,
    case when tg_op = 'INSERT' then null else jsonb_build_object(
      'full_name', old.full_name,
      'email', old.email,
      'role', old.role,
      'global_role', old.global_role,
      'status', old.status,
      'membership_tier', old.membership_tier
    ) end,
    jsonb_build_object(
      'full_name', new.full_name,
      'email', new.email,
      'role', new.role,
      'global_role', new.global_role,
      'status', new.status,
      'membership_tier', new.membership_tier
    )
  );

  return new;
end;
$$;


ALTER FUNCTION public.audit_profile_management_change() OWNER TO postgres;

--
-- Name: FUNCTION audit_profile_management_change(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.audit_profile_management_change() IS '自动记录账号角色、状态、会员档位和学生资料的重要变更';

--
-- Name: begin_runtime_textbook_edit_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.begin_runtime_textbook_edit_v1(p_actor uuid, p_textbook uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare count_inflight bigint; rev bigint;
begin
 perform runtime_publish_private.owner_guard(p_actor);
 perform runtime_publish_private.authoring_lock();
 if not exists(select 1 from public.digital_textbooks where id=p_textbook) then raise exception 'TEXTBOOK_NOT_FOUND'; end if;
 insert into runtime_publish_private.authoring_control values(p_textbook,'draining',1)
  on conflict(textbook_id) do update set state=case when runtime_publish_private.authoring_control.state='editing' then 'editing' else 'draining' end,
   revision=runtime_publish_private.authoring_control.revision+1 returning revision into rev;
 select count(*) into count_inflight from runtime_publish_private.runtime_requests where textbook_id=p_textbook and finished_at is null;
 if count_inflight>0 then return jsonb_build_object('state','draining','inflight',count_inflight,'revision',rev); end if;
 -- Revocation is explicitly authorized; records remain intact. This affects
 -- only locators of this textbook, never attempts/progress/evidence/Agent rows.
 update runtime_publish_private.sessions set revoked=true where snapshot_id in(select id from runtime_publish_private.snapshots where textbook_id=p_textbook) and not revoked;
 insert into runtime_publish_private.retired_snapshots(snapshot_id,retired_by)
  select id,p_actor from runtime_publish_private.snapshots where textbook_id=p_textbook on conflict do nothing;
 update runtime_publish_private.authoring_control set state='editing' where textbook_id=p_textbook;
 return jsonb_build_object('state','editing','inflight',0,'revision',rev);
end $$;


ALTER FUNCTION public.begin_runtime_textbook_edit_v1(p_actor uuid, p_textbook uuid) OWNER TO postgres;

