--
-- Name: change_assessment_paper_status(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.change_assessment_paper_status(p_paper_id uuid, p_status text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not public.current_user_can_manage_assessment_papers() then
    raise exception '只有平台负责人或指定管理员可以变更试卷状态';
  end if;
  if p_status not in ('draft', 'published', 'retired', 'archived') then
    raise exception '试卷状态不正确';
  end if;
  if p_status = 'published' and not exists (
    select 1
    from public.assessment_paper_questions
    where paper_id = p_paper_id
  ) then
    raise exception '空试卷不能发布';
  end if;

  update public.assessment_papers
  set status = p_status,
      published_at = case
        when p_status = 'published' and status <> 'published' then now()
        when p_status = 'draft' then null
        else published_at
      end,
      updated_by = auth.uid(),
      updated_at = now()
  where id = p_paper_id;

  if not found then
    raise exception '试卷不存在';
  end if;
end;
$$;


ALTER FUNCTION public.change_assessment_paper_status(p_paper_id uuid, p_status text) OWNER TO postgres;

