ALTER FUNCTION public.change_help_article_status(p_article_id uuid, p_status text) OWNER TO postgres;

--
-- Name: change_learning_assignment_status(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.change_learning_assignment_status(p_assignment_id uuid, p_status text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not exists (
    select 1
    from public.learning_assignments as assignment
    where assignment.id = p_assignment_id
      and assignment.tenant_id = private.current_tenant_id()
      and private.current_staff_has_app_capability(
        assignment.tenant_id,
        assignment.student_app_id,
        'manage_assessments'
      )
  ) then
    raise exception '任务不存在或当前账号没有该应用的教学管理权限';
  end if;
  if p_status not in ('draft', 'published', 'closed') then
    raise exception '任务状态不正确';
  end if;
  if p_status = 'published' and exists (
    select 1
    from public.learning_assignments
    where id = p_assignment_id
      and tenant_id = private.current_tenant_id()
      and due_at <= now()
  ) then
    raise exception '截止时间已过，不能发布';
  end if;

  update public.learning_assignments
  set status = p_status,
      published_at = case
        when p_status = 'published' and status <> 'published' then now()
        when p_status = 'draft' then null
        else published_at
      end,
      updated_by = auth.uid(),
      updated_at = now()
  where id = p_assignment_id
    and tenant_id = private.current_tenant_id();
end;
$$;


ALTER FUNCTION public.change_learning_assignment_status(p_assignment_id uuid, p_status text) OWNER TO postgres;

--
-- Name: change_learning_record_note_status(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.change_learning_record_note_status(p_note_id uuid, p_status text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_note public.learning_record_notes%rowtype;
begin
  select * into v_note
  from public.learning_record_notes
  where id = p_note_id
    and tenant_id = private.current_tenant_id();
  if not found
    or not private.current_staff_has_app_capability(
      v_note.tenant_id, v_note.student_app_id, 'manage_assessments'
    )
    or (
      public.current_profile_role() = 'teacher'
      and not private.current_teacher_has_student_app_access(
        v_note.tenant_id, v_note.student_id, v_note.student_app_id
      )
    ) then
    raise exception '学习记录不存在或当前账号没有该应用的管理权限';
  end if;
  if p_status not in ('active', 'archived') then
    raise exception '学习记录状态不正确';
  end if;

  update public.learning_record_notes
  set status = p_status,
      updated_by = auth.uid(),
      updated_at = now()
  where id = p_note_id
    and tenant_id = v_note.tenant_id;
end;
$$;


ALTER FUNCTION public.change_learning_record_note_status(p_note_id uuid, p_status text) OWNER TO postgres;

--
-- Name: change_library_resource_status(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.change_library_resource_status(p_resource_id uuid, p_status text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not private.is_platform_owner() then
    raise exception '只有平台负责人可以修改资料状态';
  end if;
  if p_status not in ('draft', 'published', 'archived') then
    raise exception '资料状态不正确';
  end if;

  update public.library_resources
  set status = p_status,
      published_at = case
        when p_status = 'published' and status <> 'published' then now()
        when p_status = 'draft' then null
        else published_at
      end,
      updated_by = auth.uid(),
      updated_at = now()
  where id = p_resource_id;

  if not found then
    raise exception '资料不存在';
  end if;
end;
$$;


ALTER FUNCTION public.change_library_resource_status(p_resource_id uuid, p_status text) OWNER TO postgres;

--
-- Name: claim_smart_textbook_recording_delete_v2(uuid, uuid, uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_smart_textbook_recording_delete_v2(p_tenant_id uuid, p_student_id uuid, p_activity_id uuid, p_version_id uuid, p_evidence_id uuid, p_runtime_binding jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare e public.digital_textbook_speaking_evidence; identity jsonb;
begin
  perform recording_private.require_service();
  perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':'||p_student_id::text||':'||p_activity_id::text,0));
  select * into e from public.digital_textbook_speaking_evidence where id=p_evidence_id for update;
  perform recording_private.check_scope(e,p_tenant_id,p_student_id,p_activity_id,p_version_id,p_runtime_binding);
  identity := recording_private.identity(e);
  if e.consumed_at is not null or coalesce(e.metadata->>'lifecycle','active') not in ('active','delete-pending') then
    raise exception 'RECORDING_DELETE_CONFLICT';
  end if;
  update public.digital_textbook_speaking_evidence set metadata=jsonb_set(metadata,'{lifecycle}','"delete-pending"') where id=e.id;
  -- Server-private DTO; never return this object identity to the browser.
  return jsonb_build_object('evidenceId',e.id,'backend',identity->>'backend','objectKey',e.object_key,'state','delete-pending');
end $$;


ALTER FUNCTION public.claim_smart_textbook_recording_delete_v2(p_tenant_id uuid, p_student_id uuid, p_activity_id uuid, p_version_id uuid, p_evidence_id uuid, p_runtime_binding jsonb) OWNER TO postgres;

--
-- Name: complete_smart_textbook_roleplay_v2(uuid, uuid, uuid, uuid, text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_smart_textbook_roleplay_v2(p_tenant_id uuid, p_student_id uuid, p_activity_id uuid, p_version_id uuid, p_scene_id text, p_role_side text, p_evidence_proofs jsonb, p_runtime_binding jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare scene jsonb; turns integer[]; seen integer[] := '{}'; ids uuid[]; item jsonb;
  e public.digital_textbook_speaking_evidence; result jsonb; response jsonb;
begin
  perform recording_private.require_service();
  perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':'||p_student_id::text||':'||p_activity_id::text,0));
  if p_role_side is null or p_role_side not in ('left','right') then raise exception 'RECORDING_ROLE_INVALID'; end if;
  select s into scene from public.digital_textbook_activities a
    join public.digital_textbook_nodes n on n.id=a.node_id
    join public.digital_textbook_modules m on m.id=n.module_id
    join public.digital_textbook_chapters c on c.id=m.chapter_id
    cross join lateral jsonb_array_elements(n.content->'dialogueScenes') s
    where a.id=p_activity_id and a.activity_type='speaking' and a.public_config->>'practiceKind'='dialogue_roleplay'
      and c.version_id=p_version_id and s->>'id'=p_scene_id;
  if scene is null or jsonb_typeof(scene->'lines') <> 'array' then raise exception 'RECORDING_SCENE_INVALID'; end if;
  select array_agg(i order by i) into turns from generate_series(0,jsonb_array_length(scene->'lines')-1) i
    where i%2=case p_role_side when 'left' then 0 else 1 end;
  if coalesce(cardinality(turns),0)=0 then raise exception 'RECORDING_TURNS_EMPTY'; end if;
  -- Deliberate conflict, not success: stale/new-snapshot callers cannot use an
  -- old completed attempt as proof of their own submitted evidence.
  if exists(select 1 from public.digital_textbook_attempts where tenant_id=p_tenant_id and student_id=p_student_id
    and activity_id=p_activity_id and version_id=p_version_id and meets_completion_requirements) then
    raise exception 'RECORDING_ROLEPLAY_ALREADY_COMPLETED' using errcode='23505';
  end if;
  if jsonb_typeof(p_evidence_proofs) is distinct from 'array' or jsonb_array_length(p_evidence_proofs) <> cardinality(turns)
    or exists(select 1 from jsonb_array_elements(p_evidence_proofs) x where jsonb_typeof(x)<>'object' or (x-array['evidenceId','proof'])<>'{}') then
    raise exception 'RECORDING_COVERAGE_INVALID';
  end if;
  select array_agg((x->>'evidenceId')::uuid order by (x->>'evidenceId')::uuid) into ids from jsonb_array_elements(p_evidence_proofs) x;
  if (select count(distinct id) from unnest(ids) id) <> cardinality(turns) then raise exception 'RECORDING_DUPLICATE_EVIDENCE'; end if;
  response := jsonb_build_object('sceneId',p_scene_id,'roleSide',p_role_side,'recordedTurns',to_jsonb(turns));
  -- Activity lock first, UUID row order second, node lock inside the old RPC last.
  for e in select * from public.digital_textbook_speaking_evidence where id=any(ids) order by id for update loop
    perform recording_private.check_scope(e,p_tenant_id,p_student_id,p_activity_id,p_version_id,p_runtime_binding);
    if recording_private.identity(e)->>'kind'<>'roleplay-turn' or e.metadata->>'sceneId' is distinct from p_scene_id
      or e.metadata->>'roleSide' is distinct from p_role_side or not ((e.metadata->>'turnIndex')::integer=any(turns)) then
      raise exception 'RECORDING_ROLE_BINDING_MISMATCH';
    end if;
    select x->'proof' into item from jsonb_array_elements(p_evidence_proofs) x where x->>'evidenceId'=e.id::text;
    perform recording_private.verify(e,p_version_id,p_runtime_binding,'roleplay-completion',response,item);
    seen := array_append(seen,(e.metadata->>'turnIndex')::integer);
  end loop;
  if cardinality(seen) <> cardinality(turns) or (select count(distinct t) from unnest(seen) t) <> cardinality(turns) then
    raise exception 'RECORDING_COVERAGE_INVALID';
  end if;
  select to_jsonb(r) into result from public.record_smart_textbook_attempt(
    p_tenant_id,p_student_id,p_activity_id,p_version_id,response,null,null,true) r;
  update public.digital_textbook_speaking_evidence set consumed_at=clock_timestamp(),
    consumed_attempt_number=(result->>'attempt_number')::integer,
    metadata=jsonb_set(metadata,'{lifecycle}','"consumed"') where id=any(ids);
  return result;
end $$;


ALTER FUNCTION public.complete_smart_textbook_roleplay_v2(p_tenant_id uuid, p_student_id uuid, p_activity_id uuid, p_version_id uuid, p_scene_id text, p_role_side text, p_evidence_proofs jsonb, p_runtime_binding jsonb) OWNER TO postgres;

--
-- Name: configure_assignment_chapter_unlock(uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.configure_assignment_chapter_unlock(p_assignment_id uuid, p_enabled boolean) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select public.configure_assignment_chapter_unlock(
    p_assignment_id, p_enabled, case when p_enabled then 3 else null end
  );
$$;


ALTER FUNCTION public.configure_assignment_chapter_unlock(p_assignment_id uuid, p_enabled boolean) OWNER TO postgres;

--
-- Name: configure_assignment_chapter_unlock(uuid, boolean, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.configure_assignment_chapter_unlock(p_assignment_id uuid, p_enabled boolean, p_due_days_after_unlock integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_assignment public.learning_assignments%rowtype;
  v_test_slug text;
begin
  select * into v_assignment
  from public.learning_assignments
  where id = p_assignment_id and tenant_id = private.current_tenant_id()
  for update;
  if not found or not private.current_staff_has_app_capability(
    v_assignment.tenant_id, v_assignment.student_app_id, 'manage_assessments'
  ) then
    raise exception '当前账号没有配置该作业的权限';
  end if;
  if p_enabled then
    select test.slug into v_test_slug
    from public.assessment_papers as paper
    join public.course_tests as test on test.id = paper.source_test_id
    where paper.id = v_assignment.source_paper_id;
    if v_test_slug is null then
      raise exception '该作业缺少对应章节，不能按章节完成状态开放';
    end if;
    if coalesce(p_due_days_after_unlock, 0) not between 1 and 30 then
      raise exception '完成章节后的提交期限需要设置为 1 至 30 天';
    end if;
  end if;

  update public.learning_assignments
  set unlock_after_chapter_completion = coalesce(p_enabled, false),
      unlock_test_slug = case when p_enabled then v_test_slug else null end,
      due_days_after_unlock = case when p_enabled
        then p_due_days_after_unlock else null end,
      updated_at = now()
  where id = p_assignment_id;
end;
$$;


ALTER FUNCTION public.configure_assignment_chapter_unlock(p_assignment_id uuid, p_enabled boolean, p_due_days_after_unlock integer) OWNER TO postgres;

--
-- Name: configure_learning_assignment_retake(uuid, uuid, uuid, timestamp with time zone, timestamp with time zone, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.configure_learning_assignment_retake(p_evaluation_id uuid, p_assignment_id uuid, p_retake_paper_id uuid, p_retake_starts_at timestamp with time zone, p_retake_due_at timestamp with time zone, p_retake_score_policy text, p_retake_original_weight_percent integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tenant_id uuid := private.current_tenant_id();
  v_evaluation public.student_course_completion_evaluations%rowtype;
  v_assignment public.learning_assignments%rowtype;
  v_paper public.assessment_papers%rowtype;
  v_next_attempt integer;
  v_paper_question public.assessment_paper_questions%rowtype;
  v_paper_key public.assessment_paper_question_keys%rowtype;
  v_question_id uuid;
begin
  select * into v_evaluation
  from public.student_course_completion_evaluations
  where id = p_evaluation_id
    and tenant_id = v_tenant_id
    and status <> 'superseded'
  for key share;
  if v_evaluation.id is null then
    raise exception '结课资格记录不存在或已经失效';
  end if;

  select * into v_assignment
  from public.learning_assignments
  where id = p_assignment_id
    and tenant_id = v_tenant_id
    and student_app_id = v_evaluation.student_app_id
    and course_id = v_evaluation.course_id
    and assignment_type = 'exam'
    and status in ('published', 'closed')
  for update;
  if v_assignment.id is null
    or not private.current_staff_has_app_capability(
      v_tenant_id, v_evaluation.student_app_id, 'manage_assessments'
    )
    or not (
      private.has_current_tenant_role(
        array['tenant_super_admin', 'ceo']::text[]
      )
      or private.current_teacher_has_student_app_access(
        v_tenant_id, v_evaluation.student_id, v_evaluation.student_app_id
      )
    ) then
    raise exception '当前账号没有为该考试发起补考的权限';
  end if;
  if not exists (
    select 1
    from jsonb_array_elements(v_evaluation.missing_requirements) as gap
    where gap ->> 'sourceId' = p_assignment_id::text
      and gap ->> 'status' = 'failed'
      and gap ->> 'category' in (
        'chapter_exam', 'stage_exam', 'midterm_exam', 'final_exam'
      )
  ) then
    raise exception '该考试不在当前资格快照的未通过项目中';
  end if;

  select * into v_paper
  from public.assessment_papers
  where id = p_retake_paper_id and status = 'published';
  if v_paper.id is null
    or v_paper.student_app_id is distinct from v_assignment.student_app_id
    or v_paper.paper_type <> 'exam'
    or v_paper.total_points is distinct from v_assignment.total_points then
    raise exception '补考卷必须是同应用、同类型、同满分值的已发布试卷';
  end if;
  if p_retake_starts_at <= now()
    or p_retake_starts_at < v_assignment.due_at
    or p_retake_due_at <= p_retake_starts_at then
    raise exception '补考开始时间必须晚于当前时间和首次截止时间，截止时间必须晚于开始时间';
  end if;
  if p_retake_score_policy not in ('highest', 'latest', 'weighted') then
    raise exception '补考成绩采用规则不正确';
  end if;
  if (p_retake_score_policy = 'weighted' and
      coalesce(p_retake_original_weight_percent, 0) not between 1 and 99)
    or (p_retake_score_policy <> 'weighted' and
      p_retake_original_weight_percent is not null) then
    raise exception '补考加权比例不正确';
  end if;
  if v_assignment.retake_paper_id is not null and (
    v_assignment.retake_paper_id is distinct from p_retake_paper_id
    or v_assignment.retake_starts_at is distinct from p_retake_starts_at
    or v_assignment.retake_due_at is distinct from p_retake_due_at
    or v_assignment.retake_score_policy is distinct from p_retake_score_policy
    or v_assignment.retake_original_weight_percent is distinct from
      p_retake_original_weight_percent
  ) then
    raise exception '该考试已经有补考安排；新增学生须沿用同一试卷、时间和计分规则';
  end if;

  select coalesce(max(attempt_number), 0) + 1 into v_next_attempt
  from public.learning_submissions
  where tenant_id = v_tenant_id
    and assignment_id = v_assignment.id
    and student_id = v_evaluation.student_id;

  update public.learning_assignments
  set status = 'published',
      retake_paper_id = p_retake_paper_id,
      retake_starts_at = p_retake_starts_at,
      retake_due_at = p_retake_due_at,
      retake_score_policy = p_retake_score_policy,
      retake_original_weight_percent = p_retake_original_weight_percent,
      allow_resubmission = true,
      max_attempts = greatest(max_attempts, v_next_attempt),
      updated_by = auth.uid(),
      updated_at = now()
  where id = v_assignment.id;

  -- Snapshot the selected retake mother paper exactly once.  The original
  -- snapshot remains available for historical submissions and audit.
  if not exists (
    select 1
    from public.learning_assignment_questions as question
    where question.tenant_id = v_tenant_id
      and question.assignment_id = v_assignment.id
      and question.delivery_paper_id = v_paper.id
  ) then
    for v_paper_question in
      select *
      from public.assessment_paper_questions
      where paper_id = v_paper.id
      order by sort_order
    loop
      insert into public.learning_assignment_questions (
        tenant_id, assignment_id, delivery_paper_id,
        source_paper_question_id, question_type,
        language_skill, stimulus_text, prompt, options, points, sort_order,
        source_bank_question_id, source_bank_version, auto_graded
      ) values (
        v_tenant_id, v_assignment.id, v_paper.id, v_paper_question.id,
        v_paper_question.question_type, v_paper_question.skill,
        v_paper_question.stimulus_text, v_paper_question.prompt,
        v_paper_question.options, v_paper_question.points,
        v_paper_question.sort_order, v_paper_question.source_bank_question_id,
        v_paper_question.source_bank_version, v_paper_question.auto_graded
      ) returning id into v_question_id;

      select * into v_paper_key
      from public.assessment_paper_question_keys
      where question_id = v_paper_question.id;
      if found then
        insert into public.learning_assignment_question_keys (
          tenant_id, question_id, correct_answer, explanation, updated_by
        ) values (
          v_tenant_id, v_question_id, v_paper_key.correct_answer,
          v_paper_key.explanation, auth.uid()
        );
      end if;
    end loop;
  end if;

  insert into public.learning_assignment_retake_students (
    tenant_id, assignment_id, student_id, assigned_at
  ) values (
    v_tenant_id, v_assignment.id, v_evaluation.student_id, now()
  ) on conflict (assignment_id, student_id) do update
    set assigned_at = excluded.assigned_at;
end;
$$;


ALTER FUNCTION public.configure_learning_assignment_retake(p_evaluation_id uuid, p_assignment_id uuid, p_retake_paper_id uuid, p_retake_starts_at timestamp with time zone, p_retake_due_at timestamp with time zone, p_retake_score_policy text, p_retake_original_weight_percent integer) OWNER TO postgres;

--
-- Name: confirm_help_ticket_resolved(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.confirm_help_ticket_resolved(p_ticket_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update public.help_tickets
  set status = 'closed',
      resolved_at = coalesce(resolved_at, now()),
      updated_at = now()
  where id = p_ticket_id
    and tenant_id = private.current_tenant_id()
    and user_id = auth.uid()
    and status in ('waiting_student', 'resolved');

  if not found then raise exception '当前求助不能确认完成'; end if;
end;
$$;


ALTER FUNCTION public.confirm_help_ticket_resolved(p_ticket_id uuid) OWNER TO postgres;

--
-- Name: confirm_teaching_script_source_review(uuid, integer, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.confirm_teaching_script_source_review(p_version_id uuid, p_revision integer, p_source jsonb, p_script_token text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare current_source jsonb; current_token text; saved uuid;
begin
  if auth.uid() is null or not coalesce(private.is_platform_owner(), false) then raise exception '只有平台负责人可以复核教学脚本'; end if;
  if p_revision is null or p_revision < 0 then raise exception '无效的复核版本'; end if;
  lock table public.learning_agent_script_nodes, public.learning_agent_node_interaction_secrets in share row exclusive mode;
  lock table public.digital_textbook_modules, public.digital_textbook_nodes, public.digital_textbook_activities, public.digital_textbook_activity_secrets in share mode;
  perform 1 from public.learning_agent_script_versions where id = p_version_id and status in ('draft', 'published') for update;
  if not found then raise exception '只能复核草稿或已发布脚本'; end if;
  current_source := private.teaching_script_source_snapshot(p_version_id);
  current_token := private.teaching_script_review_token(p_version_id);
  if current_source is null or p_source is distinct from current_source or p_script_token is distinct from current_token then
    raise exception '核对期间教材或脚本已变化，请刷新后重新复核';
  end if;
  if p_revision = 0 then
    insert into public.teaching_script_source_reviews(script_version_id, source_snapshot, script_token, revision, reviewed_by)
    values(p_version_id, current_source, current_token, 1, auth.uid())
    on conflict do nothing returning script_version_id into saved;
  else
    update public.teaching_script_source_reviews set source_snapshot = current_source, script_token = current_token,
      revision = revision + 1, reviewed_by = auth.uid(), reviewed_at = now()
    where script_version_id = p_version_id and revision = p_revision returning script_version_id into saved;
  end if;
  if saved is null then raise exception '复核记录已被更新，请刷新后重试'; end if;
end;
$$;


ALTER FUNCTION public.confirm_teaching_script_source_review(p_version_id uuid, p_revision integer, p_source jsonb, p_script_token text) OWNER TO postgres;

--
-- Name: create_assessment_paper_from_bank(text, text, text, uuid, integer, numeric, boolean, boolean, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_assessment_paper_from_bank(p_title text, p_description text, p_paper_type text, p_source_test_id uuid, p_duration_minutes integer, p_passing_score numeric, p_allow_resubmission boolean, p_publish boolean, p_questions jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_paper_id uuid;
  v_paper_code text;
  v_selection jsonb;
  v_bank_question public.course_test_questions%rowtype;
  v_paper_question_id uuid;
  v_bank_question_id uuid;
  v_points numeric(8,2);
  v_total_points numeric(8,2) := 0;
  v_sort_order integer := 0;
  v_correct_answer text;
  v_seen_ids uuid[] := array[]::uuid[];
begin
  if not public.current_user_can_manage_assessment_papers() then
    raise exception '只有平台负责人或指定管理员可以创建标准试卷';
  end if;

  p_title := btrim(coalesce(p_title, ''));
  p_description := btrim(coalesce(p_description, ''));
  if char_length(p_title) not between 2 and 120 then
    raise exception '试卷名称需要填写 2 至 120 个字';
  end if;
  if char_length(p_description) > 5000 then
    raise exception '试卷说明不能超过 5000 个字';
  end if;
  if p_paper_type not in ('homework', 'exam') then
    raise exception '试卷类型只能是作业或考试';
  end if;
  if p_duration_minutes is not null
    and p_duration_minutes not between 1 and 600 then
    raise exception '建议用时需要在 1 至 600 分钟之间';
  end if;
  if p_passing_score is not null
    and p_passing_score not between 0 and 100 then
    raise exception '及格线需要在 0 至 100 之间';
  end if;
  if not exists (
    select 1
    from public.course_tests
    where id = p_source_test_id
      and status = 'published'
  ) then
    raise exception '所选题库章节不存在或尚未发布';
  end if;
  if p_questions is null
    or jsonb_typeof(p_questions) <> 'array'
    or jsonb_array_length(p_questions) not between 1 and 100 then
    raise exception '每套试卷需要选择 1 至 100 道题目';
  end if;

  v_paper_code :=
    case when p_paper_type = 'homework' then 'HW-' else 'EX-' end
    || lpad(nextval('public.assessment_paper_code_seq')::text, 6, '0');

  insert into public.assessment_papers (
    paper_code,
    paper_type,
    title,
    description,
    source_test_id,
    duration_minutes,
    passing_score,
    allow_resubmission,
    status,
    published_at,
    created_by,
    updated_by
  )
  values (
    v_paper_code,
    p_paper_type,
    p_title,
    p_description,
    p_source_test_id,
    p_duration_minutes,
    p_passing_score,
    coalesce(p_allow_resubmission, p_paper_type = 'homework'),
    case when p_publish then 'published' else 'draft' end,
    case when p_publish then now() else null end,
    auth.uid(),
    auth.uid()
  )
  returning id into v_paper_id;

  for v_selection in
    select value from jsonb_array_elements(p_questions)
  loop
    begin
      v_bank_question_id := (v_selection ->> 'questionId')::uuid;
      v_points := (v_selection ->> 'points')::numeric;
    exception when others then
      raise exception '试卷选题数据格式不正确';
    end;

    if v_bank_question_id = any(v_seen_ids) then
      raise exception '同一套试卷不能重复使用同一道题';
    end if;
    v_seen_ids := array_append(v_seen_ids, v_bank_question_id);

    if v_points <= 0 or v_points > 1000 then
      raise exception '第 % 题分值需要大于 0 且不超过 1000', v_sort_order + 1;
    end if;

    select question.*
    into v_bank_question
    from public.course_test_questions as question
    where question.id = v_bank_question_id
      and question.test_id = p_source_test_id
      and question.status = 'published';

    if not found then
      raise exception '第 % 道标准题不存在、不属于所选章节或尚未发布', v_sort_order + 1;
    end if;

    insert into public.assessment_paper_questions (
      paper_id,
      source_bank_question_id,
      source_bank_version,
      question_type,
      prompt,
      options,
      points,
      sort_order,
      difficulty,
      skill
    )
    values (
      v_paper_id,
      v_bank_question.id,
      v_bank_question.version,
      v_bank_question.question_type,
      v_bank_question.prompt,
      v_bank_question.options,
      v_points,
      v_sort_order,
      v_bank_question.difficulty,
      v_bank_question.skill
    )
    returning id into v_paper_question_id;

    v_correct_answer := case
      when v_bank_question.question_type = 'single_choice'
        then v_bank_question.options ->> v_bank_question.correct_option
      else v_bank_question.correct_answer
    end;

    insert into public.assessment_paper_question_keys (
      question_id,
      correct_answer,
      explanation
    )
    values (
      v_paper_question_id,
      v_correct_answer,
      nullif(v_bank_question.explanation, '')
    );

    v_total_points := v_total_points + v_points;
    v_sort_order := v_sort_order + 1;
  end loop;

  update public.assessment_papers
  set total_points = v_total_points,
      question_count = v_sort_order,
      updated_at = now()
  where id = v_paper_id;

  return v_paper_id;
end;
$$;


ALTER FUNCTION public.create_assessment_paper_from_bank(p_title text, p_description text, p_paper_type text, p_source_test_id uuid, p_duration_minutes integer, p_passing_score numeric, p_allow_resubmission boolean, p_publish boolean, p_questions jsonb) OWNER TO postgres;

--
-- Name: create_help_ticket(text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_help_ticket(p_subject text, p_description text, p_category text, p_priority text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_ticket_id uuid;
begin
  if not (public.is_active_account() and public.current_profile_role() = 'student') then
    raise exception '只有正常状态的学生账号可以提交求助';
  end if;
  if char_length(trim(coalesce(p_subject, ''))) not between 2 and 120
     or char_length(trim(coalesce(p_description, ''))) not between 2 and 5000 then
    raise exception '求助标题或问题描述长度不正确';
  end if;
  if p_category not in ('technical', 'account', 'course', 'service', 'other')
     or p_priority not in ('normal', 'urgent') then
    raise exception '求助分类或紧急程度不正确';
  end if;

  insert into public.help_tickets (user_id, subject, description, category, priority)
  values (auth.uid(), trim(p_subject), trim(p_description), p_category, p_priority)
  returning id into v_ticket_id;
  return v_ticket_id;
end;
$$;


ALTER FUNCTION public.create_help_ticket(p_subject text, p_description text, p_category text, p_priority text) OWNER TO postgres;

--
-- Name: create_learning_agent_script_draft(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_learning_agent_script_draft(p_lesson_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'auth'
    AS $$
declare
  v_existing uuid;
  v_published uuid;
  v_created uuid;
  v_next_version integer;
begin
  if auth.uid() is null or not private.is_platform_owner() then
    raise exception '只有平台负责人可以编辑教学脚本';
  end if;

  perform 1 from public.learning_agent_lessons where id = p_lesson_id for update;
  if not found then raise exception '没有找到对应的教学模块'; end if;

  select id into v_existing
  from public.learning_agent_script_versions
  where lesson_id = p_lesson_id and status = 'draft'
  limit 1;
  if v_existing is not null then return v_existing; end if;

  select coalesce(max(version_number), 0) + 1 into v_next_version
  from public.learning_agent_script_versions
  where lesson_id = p_lesson_id;

  select id into v_published
  from public.learning_agent_script_versions
  where lesson_id = p_lesson_id and status = 'published'
  limit 1;

  insert into public.learning_agent_script_versions (
    lesson_id, version_number, status, title, created_by
  )
  select p_lesson_id, v_next_version, 'draft',
    coalesce((select title from public.learning_agent_script_versions where id = v_published), '{}'::jsonb),
    auth.uid()
  returning id into v_created;

  if v_published is not null then
    insert into public.learning_agent_script_nodes (
      script_version_id, node_key, node_type, sort_order, title, teacher_script,
      configuration, reference_activity_id, action_type, next_node_key,
      remediation_node_key, is_required
    )
    select v_created, node_key, node_type, sort_order, title, teacher_script,
      configuration, reference_activity_id, action_type, next_node_key,
      remediation_node_key, is_required
    from public.learning_agent_script_nodes
    where script_version_id = v_published
    order by sort_order;

    insert into public.learning_agent_script_audio_assets (
      script_node_id,
      locale,
      segment_index,
      content_hash,
      object_key,
      duration_ms,
      cue_timeline,
      voice_manifest,
      production_status
    )
    select
      draft_node.id,
      source_asset.locale,
      source_asset.segment_index,
      source_asset.content_hash,
      source_asset.object_key,
      source_asset.duration_ms,
      source_asset.cue_timeline,
      source_asset.voice_manifest,
      source_asset.production_status
    from public.learning_agent_script_nodes source_node
    join public.learning_agent_script_nodes draft_node
      on draft_node.script_version_id = v_created
     and draft_node.node_key = source_node.node_key
    join public.learning_agent_script_audio_assets source_asset
      on source_asset.script_node_id = source_node.id
    where source_node.script_version_id = v_published
    on conflict (script_node_id, locale, segment_index) do nothing;
  end if;

  insert into public.learning_agent_publish_logs (
    lesson_id, script_version_id, action, actor_id, details
  ) values (
    p_lesson_id, v_created, 'create_draft', auth.uid(),
    jsonb_build_object('sourceVersionId', v_published)
  );

  return v_created;
end;
$$;


ALTER FUNCTION public.create_learning_agent_script_draft(p_lesson_id uuid) OWNER TO postgres;

--
-- Name: create_learning_assignment(text, text, text, uuid, text, uuid[], timestamp with time zone, integer, boolean, boolean, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_learning_assignment(p_title text, p_description text, p_assignment_type text, p_course_id uuid, p_target_scope text, p_target_ids uuid[], p_due_at timestamp with time zone, p_duration_minutes integer, p_allow_resubmission boolean, p_publish boolean, p_questions jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_assignment_id uuid;
  v_question jsonb;
  v_question_id uuid;
  v_question_type text;
  v_prompt text;
  v_options jsonb;
  v_points numeric(8,2);
  v_total_points numeric(8,2) := 0;
  v_sort_order integer := 0;
  v_correct_answer text;
  v_explanation text;
  v_target_count integer;
  v_expected_target_count integer;
begin
  if not public.current_user_is_assignment_manager() then
    raise exception '当前账号没有教学管理权限';
  end if;

  p_title := btrim(coalesce(p_title, ''));
  p_description := btrim(coalesce(p_description, ''));
  if char_length(p_title) not between 2 and 120 then
    raise exception '标题需要填写 2 至 120 个字';
  end if;
  if char_length(p_description) > 5000 then
    raise exception '任务说明不能超过 5000 个字';
  end if;
  if p_assignment_type not in ('homework', 'quiz', 'exam') then
    raise exception '任务类型不正确';
  end if;
  if p_target_scope not in ('all_students', 'selected_students') then
    raise exception '分配范围不正确';
  end if;
  if p_due_at is null or p_due_at <= now() then
    raise exception '截止时间必须晚于当前时间';
  end if;
  if p_duration_minutes is not null and p_duration_minutes not between 1 and 600 then
    raise exception '建议用时需要在 1 至 600 分钟之间';
  end if;
  if p_course_id is not null and not exists (
    select 1 from public.courses
    where id = p_course_id and tenant_id = private.current_tenant_id()
  ) then
    raise exception '所选课程不存在';
  end if;
  if p_questions is null or jsonb_typeof(p_questions) <> 'array'
     or jsonb_array_length(p_questions) not between 1 and 50 then
    raise exception '请设置 1 至 50 道题目';
  end if;

  if p_target_scope = 'selected_students' then
    select count(distinct value::uuid)
      into v_expected_target_count
    from unnest(coalesce(p_target_ids, array[]::uuid[])) as value;
    if v_expected_target_count = 0 then
      raise exception '请至少选择一名学生';
    end if;
    select count(*)
      into v_target_count
    from public.tenant_memberships as membership
    where membership.user_id = any(p_target_ids)
      and membership.tenant_id = private.current_tenant_id()
      and membership.role = 'student'
      and membership.status = 'active';
    if v_target_count <> v_expected_target_count then
      raise exception '分配名单中包含无效学生账号';
    end if;
  end if;

  insert into public.learning_assignments (
    title, description, assignment_type, course_id, target_scope,
    due_at, duration_minutes, allow_resubmission, status, published_at,
    created_by, updated_by
  ) values (
    p_title, p_description, p_assignment_type, p_course_id, p_target_scope,
    p_due_at, p_duration_minutes, coalesce(p_allow_resubmission, false),
    case when p_publish then 'published' else 'draft' end,
    case when p_publish then now() else null end,
    auth.uid(), auth.uid()
  ) returning id into v_assignment_id;

  for v_question in select value from jsonb_array_elements(p_questions)
  loop
    v_question_type := coalesce(v_question->>'type', '');
    v_prompt := btrim(coalesce(v_question->>'prompt', ''));
    v_options := coalesce(v_question->'options', '[]'::jsonb);
    v_correct_answer := nullif(btrim(coalesce(v_question->>'correctAnswer', '')), '');
    v_explanation := nullif(btrim(coalesce(v_question->>'explanation', '')), '');
    begin
      v_points := (v_question->>'points')::numeric;
    exception when others then
      raise exception '第 % 题分值不正确', v_sort_order + 1;
    end;

    if v_question_type not in ('short_text', 'long_text', 'single_choice', 'file_link') then
      raise exception '第 % 题类型不正确', v_sort_order + 1;
    end if;
    if char_length(v_prompt) not between 1 and 3000 then
      raise exception '第 % 题题目不能为空且不能超过 3000 个字', v_sort_order + 1;
    end if;
    if v_points <= 0 or v_points > 1000 then
      raise exception '第 % 题分值需要在 0 至 1000 分之间', v_sort_order + 1;
    end if;
    if jsonb_typeof(v_options) <> 'array' then
      raise exception '第 % 题选项格式不正确', v_sort_order + 1;
    end if;
    if v_question_type = 'single_choice' and jsonb_array_length(v_options) < 2 then
      raise exception '第 % 道选择题至少需要两个选项', v_sort_order + 1;
    end if;
    if v_explanation is not null and char_length(v_explanation) > 3000 then
      raise exception '第 % 题解析不能超过 3000 个字', v_sort_order + 1;
    end if;

    insert into public.learning_assignment_questions (
      assignment_id, question_type, prompt, options, points, sort_order
    ) values (
      v_assignment_id, v_question_type, v_prompt, v_options, v_points, v_sort_order
    ) returning id into v_question_id;

    if v_correct_answer is not null or v_explanation is not null then
      insert into public.learning_assignment_question_keys (
        question_id, correct_answer, explanation, updated_by
      ) values (
        v_question_id, v_correct_answer, v_explanation, auth.uid()
      );
    end if;

    v_total_points := v_total_points + v_points;
    v_sort_order := v_sort_order + 1;
  end loop;

  update public.learning_assignments
  set total_points = v_total_points
  where id = v_assignment_id;

  if p_target_scope = 'selected_students' then
    insert into public.learning_assignment_targets (assignment_id, student_id)
    select v_assignment_id, value::uuid
    from unnest(p_target_ids) as value
    on conflict do nothing;
  end if;

  return v_assignment_id;
end;
$$;


ALTER FUNCTION public.create_learning_assignment(p_title text, p_description text, p_assignment_type text, p_course_id uuid, p_target_scope text, p_target_ids uuid[], p_due_at timestamp with time zone, p_duration_minutes integer, p_allow_resubmission boolean, p_publish boolean, p_questions jsonb) OWNER TO postgres;

--
-- Name: create_learning_assignment_from_bank(text, text, text, uuid, text, uuid[], timestamp with time zone, integer, boolean, boolean, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_learning_assignment_from_bank(p_title text, p_description text, p_assignment_type text, p_course_id uuid, p_target_scope text, p_target_ids uuid[], p_due_at timestamp with time zone, p_duration_minutes integer, p_allow_resubmission boolean, p_publish boolean, p_questions jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tenant_id uuid := private.current_tenant_id();
  v_assignment_id uuid;
  v_selection jsonb;
  v_bank_question public.course_test_questions%rowtype;
  v_question_id uuid;
  v_bank_question_id uuid;
  v_points numeric(8,2);
  v_total_points numeric(8,2) := 0;
  v_sort_order integer := 0;
  v_correct_answer text;
  v_target_count integer;
  v_expected_target_count integer;
  v_seen_ids uuid[] := array[]::uuid[];
begin
  if v_tenant_id is null
    or not public.current_user_can_use_standard_question_bank() then
    raise exception '当前账号没有使用标准题库布置任务的权限';
  end if;

  p_title := btrim(coalesce(p_title, ''));
  p_description := btrim(coalesce(p_description, ''));
  if char_length(p_title) not between 2 and 120 then
    raise exception '标题需要填写 2 至 120 个字';
  end if;
  if char_length(p_description) > 5000 then
    raise exception '任务说明不能超过 5000 个字';
  end if;
  if p_assignment_type not in ('homework', 'exam') then
    raise exception '任务类型只能是作业或考试';
  end if;
  if p_target_scope not in ('all_students', 'selected_students') then
    raise exception '分配范围不正确';
  end if;
  if p_due_at is null or p_due_at <= now() then
    raise exception '截止时间必须晚于当前时间';
  end if;
  if p_duration_minutes is not null
    and p_duration_minutes not between 1 and 600 then
    raise exception '建议用时需要在 1 至 600 分钟之间';
  end if;
  if p_course_id is not null and not exists (
    select 1
    from public.courses
    where id = p_course_id
      and tenant_id = v_tenant_id
  ) then
    raise exception '所选课程不存在';
  end if;
  if p_questions is null
    or jsonb_typeof(p_questions) <> 'array'
    or jsonb_array_length(p_questions) not between 1 and 50 then
    raise exception '请从标准题库选择 1 至 50 道题目';
  end if;

  if p_target_scope = 'selected_students' then
    select count(distinct value::uuid)
    into v_expected_target_count
    from unnest(coalesce(p_target_ids, array[]::uuid[])) as value;

    if v_expected_target_count = 0 then
      raise exception '请至少选择一名学生';
    end if;

    select count(*)
    into v_target_count
    from public.tenant_memberships as membership
    where membership.user_id = any(p_target_ids)
      and membership.tenant_id = v_tenant_id
      and membership.role = 'student'
      and membership.status = 'active';

    if v_target_count <> v_expected_target_count then
      raise exception '分配名单中包含无效学生账号';
    end if;
  end if;

  insert into public.learning_assignments (
    tenant_id,
    title,
    description,
    assignment_type,
    course_id,
    target_scope,
    due_at,
    duration_minutes,
    allow_resubmission,
    status,
    published_at,
    created_by,
    updated_by
  )
  values (
    v_tenant_id,
    p_title,
    p_description,
    p_assignment_type,
    p_course_id,
    p_target_scope,
    p_due_at,
    p_duration_minutes,
    coalesce(p_allow_resubmission, false),
    case when p_publish then 'published' else 'draft' end,
    case when p_publish then now() else null end,
    auth.uid(),
    auth.uid()
  )
  returning id into v_assignment_id;

  for v_selection in
    select value from jsonb_array_elements(p_questions)
  loop
    begin
      v_bank_question_id := (v_selection ->> 'questionId')::uuid;
      v_points := (v_selection ->> 'points')::numeric;
    exception
      when others then
        raise exception '选题数据格式不正确';
    end;

    if v_bank_question_id = any(v_seen_ids) then
      raise exception '不能重复选择同一道题';
    end if;
    v_seen_ids := array_append(v_seen_ids, v_bank_question_id);

    if v_points <= 0 or v_points > 1000 then
      raise exception '第 % 题分值需要大于 0 且不超过 1000', v_sort_order + 1;
    end if;

    select question.*
    into v_bank_question
    from public.course_test_questions as question
    join public.course_tests as test on test.id = question.test_id
    where question.id = v_bank_question_id
      and question.status = 'published'
      and test.status = 'published';

    if not found then
      raise exception '第 % 道标准题不存在或尚未发布', v_sort_order + 1;
    end if;

    insert into public.learning_assignment_questions (
      tenant_id,
      assignment_id,
      question_type,
      prompt,
      options,
      points,
      sort_order,
      source_bank_question_id,
      source_bank_version
    )
    values (
      v_tenant_id,
      v_assignment_id,
      v_bank_question.question_type,
      v_bank_question.prompt,
      v_bank_question.options,
      v_points,
      v_sort_order,
      v_bank_question.id,
      v_bank_question.version
    )
    returning id into v_question_id;

    v_correct_answer := case
      when v_bank_question.question_type = 'single_choice'
        then v_bank_question.options ->> v_bank_question.correct_option
      else v_bank_question.correct_answer
    end;

    if v_correct_answer is not null or v_bank_question.explanation <> '' then
      insert into public.learning_assignment_question_keys (
        tenant_id,
        question_id,
        correct_answer,
        explanation,
        updated_by
      )
      values (
        v_tenant_id,
        v_question_id,
        v_correct_answer,
        nullif(v_bank_question.explanation, ''),
        auth.uid()
      );
    end if;

    v_total_points := v_total_points + v_points;
    v_sort_order := v_sort_order + 1;
  end loop;

  update public.learning_assignments
  set total_points = v_total_points
  where id = v_assignment_id
    and tenant_id = v_tenant_id;

  if p_target_scope = 'selected_students' then
    insert into public.learning_assignment_targets (
      tenant_id,
      assignment_id,
      student_id
    )
    select v_tenant_id, v_assignment_id, value::uuid
    from unnest(p_target_ids) as value
    on conflict do nothing;
  end if;

  return v_assignment_id;
end;
$$;


