-- Name: create_learning_assignment_from_paper_with_unlock(uuid, uuid, text, uuid[], timestamp with time zone, timestamp with time zone, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_learning_assignment_from_paper_with_unlock(p_paper_id uuid, p_course_id uuid, p_target_scope text, p_target_ids uuid[], p_starts_at timestamp with time zone, p_due_at timestamp with time zone, p_institution_note text, p_unlock_after_chapter_completion boolean) RETURNS uuid
    LANGUAGE sql
    SET search_path TO ''
    AS $$
  select public.create_learning_assignment_from_paper_with_unlock(
    p_paper_id, p_course_id, p_target_scope, p_target_ids,
    p_starts_at, p_due_at, p_institution_note,
    p_unlock_after_chapter_completion,
    case when p_unlock_after_chapter_completion then 3 else null end
  );
$$;


ALTER FUNCTION public.create_learning_assignment_from_paper_with_unlock(p_paper_id uuid, p_course_id uuid, p_target_scope text, p_target_ids uuid[], p_starts_at timestamp with time zone, p_due_at timestamp with time zone, p_institution_note text, p_unlock_after_chapter_completion boolean) OWNER TO postgres;

--
-- Name: FUNCTION create_learning_assignment_from_paper_with_unlock(p_paper_id uuid, p_course_id uuid, p_target_scope text, p_target_ids uuid[], p_starts_at timestamp with time zone, p_due_at timestamp with time zone, p_institution_note text, p_unlock_after_chapter_completion boolean); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.create_learning_assignment_from_paper_with_unlock(p_paper_id uuid, p_course_id uuid, p_target_scope text, p_target_ids uuid[], p_starts_at timestamp with time zone, p_due_at timestamp with time zone, p_institution_note text, p_unlock_after_chapter_completion boolean) IS '原子创建标准卷任务并配置章节完成后开放规则。';

--
-- Name: create_learning_assignment_from_paper_with_unlock(uuid, uuid, text, uuid[], timestamp with time zone, timestamp with time zone, text, boolean, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_learning_assignment_from_paper_with_unlock(p_paper_id uuid, p_course_id uuid, p_target_scope text, p_target_ids uuid[], p_starts_at timestamp with time zone, p_due_at timestamp with time zone, p_institution_note text, p_unlock_after_chapter_completion boolean, p_due_days_after_unlock integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_assignment_id uuid;
  v_paper public.assessment_papers%rowtype;
begin
  select * into v_paper
  from public.assessment_papers
  where id = p_paper_id and status = 'published';
  if v_paper.id is null then raise exception '所选标准试卷当前不可用'; end if;

  if public.current_profile_role() = 'teacher' then
    if p_target_scope <> 'selected_students' then
      raise exception '老师只能把任务布置给自己负责的学生';
    end if;
    if exists (
      select 1 from unnest(coalesce(p_target_ids, array[]::uuid[])) as target(student_id)
      where not private.current_teacher_has_student_app_access(
        private.current_tenant_id(), target.student_id, v_paper.student_app_id
      )
    ) then
      raise exception '分配名单中包含当前老师未负责的学生';
    end if;
  end if;

  perform private.validate_assessment_paper_release(p_paper_id);
  v_assignment_id := public.create_learning_assignment_from_paper(
    p_paper_id, p_course_id, p_target_scope, p_target_ids,
    p_starts_at, p_due_at, p_institution_note
  );
  perform public.configure_assignment_chapter_unlock(
    v_assignment_id,
    coalesce(p_unlock_after_chapter_completion, false),
    case when p_unlock_after_chapter_completion
      then p_due_days_after_unlock else null end
  );
  return v_assignment_id;
end;
$$;


ALTER FUNCTION public.create_learning_assignment_from_paper_with_unlock(p_paper_id uuid, p_course_id uuid, p_target_scope text, p_target_ids uuid[], p_starts_at timestamp with time zone, p_due_at timestamp with time zone, p_institution_note text, p_unlock_after_chapter_completion boolean, p_due_days_after_unlock integer) OWNER TO postgres;

--
-- Name: create_learning_assignment_from_paper_with_unlock(uuid, uuid, text, uuid[], timestamp with time zone, timestamp with time zone, text, boolean, integer, boolean, integer, boolean, boolean, timestamp with time zone, uuid, uuid[], timestamp with time zone, timestamp with time zone, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_learning_assignment_from_paper_with_unlock(p_paper_id uuid, p_course_id uuid, p_target_scope text, p_target_ids uuid[], p_starts_at timestamp with time zone, p_due_at timestamp with time zone, p_institution_note text, p_unlock_after_chapter_completion boolean, p_due_days_after_unlock integer, p_allow_late_submission boolean, p_max_attempts integer, p_shuffle_questions boolean, p_shuffle_options boolean, p_grade_release_at timestamp with time zone, p_retake_paper_id uuid, p_retake_student_ids uuid[], p_retake_starts_at timestamp with time zone, p_retake_due_at timestamp with time zone, p_retake_score_policy text, p_retake_original_weight_percent integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_assignment_id uuid;
  v_assignment public.learning_assignments%rowtype;
  v_retake_paper public.assessment_papers%rowtype;
  v_retake_student_count integer;
  v_valid_retake_student_count integer;
begin
  if p_max_attempts is not null and p_max_attempts not between 1 and 10 then
    raise exception '允许提交次数需要设置为 1 至 10 次';
  end if;
  if p_grade_release_at is not null and p_grade_release_at < p_due_at then
    raise exception '成绩公开时间不能早于提交截止时间';
  end if;

  select count(distinct student_id)
  into v_retake_student_count
  from unnest(coalesce(p_retake_student_ids, array[]::uuid[])) as student_id;

  if p_retake_paper_id is null then
    if v_retake_student_count > 0
      or p_retake_starts_at is not null
      or p_retake_due_at is not null
      or p_retake_score_policy is not null
      or p_retake_original_weight_percent is not null then
      raise exception '未启用补考时不能设置补考名单、时间或成绩规则';
    end if;
  else
    perform private.validate_assessment_paper_release(p_retake_paper_id);
    select * into v_retake_paper
    from public.assessment_papers
    where id = p_retake_paper_id and status = 'published';
    if not found then
      raise exception '所选补考卷不存在或已经停止提供';
    end if;
    if v_retake_student_count = 0 then
      raise exception '启用补考时请至少选择一名补考学生';
    end if;
    if p_retake_starts_at is null
      or p_retake_due_at is null
      or p_retake_starts_at < p_due_at
      or p_retake_due_at <= p_retake_starts_at then
      raise exception '补考开始时间不能早于首次截止时间，且补考截止时间必须晚于开始时间';
    end if;
    if p_retake_score_policy not in ('highest', 'latest', 'weighted') then
      raise exception '补考成绩采用规则不正确';
    end if;
    if p_retake_score_policy = 'weighted' then
      if coalesce(p_retake_original_weight_percent, 0) not between 1 and 99 then
        raise exception '加权分需要设置 1 至 99 的首次成绩占比';
      end if;
    elsif p_retake_original_weight_percent is not null then
      raise exception '只有加权分规则可以设置首次成绩占比';
    end if;
  end if;

  v_assignment_id := public.create_learning_assignment_from_paper_with_unlock(
    p_paper_id, p_course_id, p_target_scope, p_target_ids,
    p_starts_at, p_due_at, p_institution_note,
    p_unlock_after_chapter_completion, p_due_days_after_unlock
  );

  select * into v_assignment
  from public.learning_assignments
  where id = v_assignment_id
  for update;

  if p_retake_paper_id is not null then
    if v_retake_paper.student_app_id is distinct from v_assignment.student_app_id
      or v_retake_paper.paper_type is distinct from v_assignment.assignment_type then
      raise exception '补考卷必须与首次考试属于同一应用和同一任务类型';
    end if;

    if p_target_scope = 'selected_students' and exists (
      select 1
      from unnest(p_retake_student_ids) as retake_student_id
      where not (retake_student_id = any(coalesce(p_target_ids, array[]::uuid[])))
    ) then
      raise exception '补考学生必须属于本次考试的指定学生名单';
    end if;

    select count(*) into v_valid_retake_student_count
    from (
      select distinct requested.student_id
      from unnest(p_retake_student_ids) as requested(student_id)
      join public.tenant_memberships as membership
        on membership.tenant_id = v_assignment.tenant_id
       and membership.user_id = requested.student_id
       and membership.role = 'student'
       and membership.status = 'active'
      join public.student_app_enrollments as enrollment
        on enrollment.tenant_id = membership.tenant_id
       and enrollment.student_id = membership.user_id
       and enrollment.app_id = v_assignment.student_app_id
       and enrollment.status = 'active'
       and enrollment.starts_at <= now()
       and (enrollment.ends_at is null or enrollment.ends_at > now())
    ) as valid_retake_student;
    if v_valid_retake_student_count <> v_retake_student_count then
      raise exception '补考名单中包含未开通该应用的学生';
    end if;
  end if;

  update public.learning_assignments
  set allow_late_submission = coalesce(p_allow_late_submission, false),
      max_attempts = coalesce(
        p_max_attempts,
        case when allow_resubmission then 100 else 1 end
      ),
      allow_resubmission = coalesce(
        p_max_attempts > 1,
        allow_resubmission
      ),
      shuffle_questions = coalesce(p_shuffle_questions, false),
      shuffle_options = coalesce(p_shuffle_options, false),
      grade_release_at = p_grade_release_at,
      retake_paper_id = p_retake_paper_id,
      retake_starts_at = p_retake_starts_at,
      retake_due_at = p_retake_due_at,
      retake_score_policy = p_retake_score_policy,
      retake_original_weight_percent = p_retake_original_weight_percent,
      updated_by = auth.uid(),
      updated_at = now()
  where id = v_assignment_id;

  if p_retake_paper_id is not null then
    insert into public.learning_assignment_retake_students (
      tenant_id, assignment_id, student_id
    )
    select v_assignment.tenant_id, v_assignment_id, student_id
    from unnest(p_retake_student_ids) as student_id
    on conflict do nothing;
  end if;

  return v_assignment_id;
end;
$$;


ALTER FUNCTION public.create_learning_assignment_from_paper_with_unlock(p_paper_id uuid, p_course_id uuid, p_target_scope text, p_target_ids uuid[], p_starts_at timestamp with time zone, p_due_at timestamp with time zone, p_institution_note text, p_unlock_after_chapter_completion boolean, p_due_days_after_unlock integer, p_allow_late_submission boolean, p_max_attempts integer, p_shuffle_questions boolean, p_shuffle_options boolean, p_grade_release_at timestamp with time zone, p_retake_paper_id uuid, p_retake_student_ids uuid[], p_retake_starts_at timestamp with time zone, p_retake_due_at timestamp with time zone, p_retake_score_policy text, p_retake_original_weight_percent integer) OWNER TO postgres;

--
-- Name: create_learning_grading_comment(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_learning_grading_comment(p_content text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tenant_id uuid := private.current_tenant_id();
  v_id uuid;
  v_content text := btrim(coalesce(p_content, ''));
  v_sort_order integer;
begin
  if v_tenant_id is null or not public.current_user_is_assignment_manager() then
    raise exception '当前账号没有维护常用评语的权限';
  end if;
  if char_length(v_content) not between 1 and 500 then
    raise exception '常用评语必须为 1 到 500 个字';
  end if;
  select coalesce(max(comment.sort_order), 0) + 10 into v_sort_order
  from public.learning_grading_comments as comment
  where comment.tenant_id = v_tenant_id;
  insert into public.learning_grading_comments (
    tenant_id, content, sort_order, created_by, updated_by
  ) values (
    v_tenant_id, v_content, v_sort_order, auth.uid(), auth.uid()
  ) returning id into v_id;
  return v_id;
exception when unique_violation then
  raise exception '这条常用评语已经存在';
end;
$$;


ALTER FUNCTION public.create_learning_grading_comment(p_content text) OWNER TO postgres;

--
-- Name: create_tenant(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_tenant(requested_name text, requested_slug text, requested_plan_key text DEFAULT 'starter'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  created_tenant_id uuid;
  normalized_slug text := lower(btrim(requested_slug));
begin
  if not private.is_platform_tenant_manager() then
    raise exception '只有负责人或副负责人可以创建租户';
  end if;

  if normalized_slug = any(array[
    'platform', 'dashboard', 'login', 'register', 'api',
    'access-denied', 'account-disabled', 'dev-preview'
  ]) then
    raise exception 'Tenant slug "%" is reserved', normalized_slug using errcode = 'P0001';
  end if;

  insert into public.tenants (slug, name, plan_key, created_by)
  values (normalized_slug, btrim(requested_name), requested_plan_key, auth.uid())
  returning id into created_tenant_id;

  return created_tenant_id;
end;
$$;


ALTER FUNCTION public.create_tenant(requested_name text, requested_slug text, requested_plan_key text) OWNER TO postgres;

--
-- Name: current_profile_role(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.current_profile_role() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select membership.role
  from public.tenant_memberships as membership
  where membership.user_id = (select auth.uid())
    and membership.tenant_id = private.current_tenant_id()
    and membership.status = 'active'
  limit 1;
$$;


ALTER FUNCTION public.current_profile_role() OWNER TO postgres;

--
-- Name: FUNCTION current_profile_role(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.current_profile_role() IS '当前租户内的业务角色（tenant_memberships），平台负责人无成员关系时回退全局身份';

--
-- Name: current_profile_status(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.current_profile_status() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when coalesce(profile.status, 'active') <> 'active' then coalesce(profile.status, 'active')
    when (
      (profile.global_role = 'platform_owner' and profile.role = 'platform_super_admin')
      or (profile.global_role = 'platform_deputy' and profile.role = 'tenant_operator')
      or (profile.global_role = 'platform_admin' and profile.role = 'admin')
      or (profile.global_role = 'platform_course_inspector' and profile.role = 'platform_course_inspector')
    ) then 'active'
    when private.current_tenant_id() is not null then 'active'
    else 'inactive'
  end
  from public.profiles as profile
  where profile.id = (select auth.uid());
$$;


ALTER FUNCTION public.current_profile_status() OWNER TO postgres;

--
-- Name: current_user_assignment_delivery_paper_id(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.current_user_assignment_delivery_paper_id(p_assignment_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when public.current_profile_role() = 'student' then
      private.assignment_delivery_paper_id(
        assignment.tenant_id, assignment.id, (select auth.uid())
      )
    else assignment.source_paper_id
  end
  from public.learning_assignments as assignment
  where assignment.tenant_id = private.current_tenant_id()
    and assignment.id = p_assignment_id
    and public.current_user_can_view_learning_assignment(assignment.id);
$$;


