--
-- Name: current_user_can_view_conversation_scenario(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.current_user_can_view_conversation_scenario(p_scenario_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.conversation_practice_scenarios as scenario
    where scenario.id = p_scenario_id
      and (
        scenario.tenant_id is null
        or scenario.tenant_id = private.current_tenant_id()
      )
      and (
        public.current_user_can_manage_conversation_practice()
        or (
          public.is_active_account()
          and private.current_tenant_id() is not null
          and (
            public.current_profile_role() in (
              'tenant_super_admin', 'platform_super_admin', 'ceo', 'teacher'
            )
            or (
              public.current_profile_role() = 'admin'
              and private.current_user_has_explicit_permission(
                'conversation_practice.manage',
                private.current_tenant_id()
              )
            )
          )
        )
        or (
          scenario.status = 'published'
          and public.student_feature_allowed('conversation_course')
          and private.current_student_has_app_access(
            private.current_tenant_id(),
            (select auth.uid()),
            scenario.student_app_id
          )
        )
      )
  );
$$;


ALTER FUNCTION public.current_user_can_view_conversation_scenario(p_scenario_id uuid) OWNER TO postgres;

--
-- Name: current_user_can_view_learning_assignment(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.current_user_can_view_learning_assignment(p_assignment_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.learning_assignments as assignment
    where assignment.id = p_assignment_id
      and assignment.tenant_id = private.current_tenant_id()
      and (
        private.current_staff_has_app_capability(
          assignment.tenant_id,
          assignment.student_app_id,
          'view_analytics'
        )
        or (
          assignment.status = 'published'
          and public.student_feature_allowed('learning_assignments')
          and private.current_student_has_app_access(
            assignment.tenant_id,
            (select auth.uid()),
            assignment.student_app_id
          )
          and (
            assignment.target_scope = 'all_students'
            or exists (
              select 1
              from public.learning_assignment_targets as target
              where target.assignment_id = assignment.id
                and target.student_id = (select auth.uid())
            )
          )
        )
      )
  );
$$;


ALTER FUNCTION public.current_user_can_view_learning_assignment(p_assignment_id uuid) OWNER TO postgres;

