--
-- Name: current_user_learning_assignment_attempt(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.current_user_learning_assignment_attempt(p_assignment_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_assignment public.learning_assignments%rowtype;
  v_started_at timestamptz;
  v_effective_due_at timestamptz;
  v_expires_at timestamptz;
begin
  select assignment.* into v_assignment
  from public.learning_assignments as assignment
  where assignment.id = p_assignment_id
    and assignment.tenant_id = private.current_tenant_id()
    and assignment.assignment_type = 'exam'
    and public.current_user_can_view_learning_assignment(assignment.id);
  if v_assignment.id is null then
    return null;
  end if;

  select counter.current_attempt_started_at into v_started_at
  from public.learning_assignment_submission_counters as counter
  where counter.tenant_id = v_assignment.tenant_id
    and counter.assignment_id = v_assignment.id
    and counter.student_id = (select auth.uid());
  if v_started_at is null then
    return null;
  end if;

  select assignment_window.effective_due_at into v_effective_due_at
  from public.current_user_assignment_window(p_assignment_id)
    as assignment_window
  limit 1;
  v_expires_at := least(
    v_started_at + make_interval(mins => v_assignment.duration_minutes),
    v_effective_due_at
  );
  return jsonb_build_object(
    'startedAt', v_started_at,
    'expiresAt', v_expires_at,
    'serverNow', now()
  );
end;
$$;


ALTER FUNCTION public.current_user_learning_assignment_attempt(p_assignment_id uuid) OWNER TO postgres;

--
-- Name: delete_guide_agent_navigation_rule(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.delete_guide_agent_navigation_rule(p_rule_id uuid, p_agent_profile_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_rule public.guide_agent_navigation_rules%rowtype;
  v_version integer;
begin
  if not private.is_platform_owner() then
    raise insufficient_privilege using message = 'platform owner required';
  end if;
  select * into v_rule
  from public.guide_agent_navigation_rules
  where id = p_rule_id and agent_profile_id = p_agent_profile_id
  for update;
  if not found then raise exception 'navigation rule not found'; end if;

  select coalesce(max(version_number), 0) + 1 into v_version
  from public.guide_agent_navigation_rule_versions where rule_id = v_rule.id;
  insert into public.guide_agent_navigation_rule_versions (
    rule_id, agent_profile_id, version_number, snapshot, change_type, actor_id
  ) values (
    v_rule.id,
    v_rule.agent_profile_id,
    v_version,
    jsonb_build_object(
      'name', v_rule.name,
      'trigger_phrases', to_jsonb(v_rule.trigger_phrases),
      'action_type', v_rule.action_type,
      'target_path', v_rule.target_path,
      'target_element_id', v_rule.target_element_id,
      'response_text', v_rule.response_text,
      'priority', v_rule.priority,
      'status', v_rule.status
    ),
    'deleted',
    v_actor_id
  );
  delete from public.guide_agent_navigation_rules where id = v_rule.id;
  insert into public.guide_agent_operation_logs (actor_id, action, target_type, target_id, summary, details)
  values (
    v_actor_id,
    '删除导航规则',
    'navigation_rule',
    v_rule.id,
    '删除规则“' || v_rule.name || '”',
    jsonb_build_object('version', v_version)
  );
  return v_rule.id;
end;
$$;


ALTER FUNCTION public.delete_guide_agent_navigation_rule(p_rule_id uuid, p_agent_profile_id uuid) OWNER TO postgres;

