--
-- Name: duplicate_assessment_paper(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.duplicate_assessment_paper(p_paper_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_source public.assessment_papers%rowtype;
  v_new_id uuid;
  v_new_code text;
begin
  if not public.current_user_can_manage_assessment_papers() then
    raise exception '当前账号不能复制标准试卷';
  end if;
  select * into v_source from public.assessment_papers
  where id = p_paper_id for update;
  if not found then raise exception '试卷不存在'; end if;

  v_new_code := case
    when v_source.paper_code ~ '^(HW|EX)-K1-((0[1-9]|1[0-6])|ST0[1-4]|MID|FIN)-V[0-9]+$'
      then regexp_replace(v_source.paper_code, '-V[0-9]+$',
        '-V' || (v_source.version + 1)::text)
    else (case when v_source.paper_type = 'homework' then 'HW-' else 'EX-' end)
      || lpad(nextval('public.assessment_paper_code_seq')::text, 6, '0')
  end;

  insert into public.assessment_papers (
    paper_code, paper_type, title, description, source_test_id,
    student_app_id, duration_minutes, passing_score, allow_resubmission,
    resubmission_policy_configured, total_points, question_count, version,
    status, created_by, updated_by
  ) values (
    v_new_code, v_source.paper_type, left(v_source.title || '（新版本）', 120),
    v_source.description, v_source.source_test_id, v_source.student_app_id,
    v_source.duration_minutes, v_source.passing_score, v_source.allow_resubmission,
    v_source.resubmission_policy_configured, v_source.total_points,
    v_source.question_count, v_source.version + 1, 'draft', auth.uid(), auth.uid()
  ) returning id into v_new_id;

  with copied as (
    insert into public.assessment_paper_questions (
      paper_id, source_bank_question_id, source_bank_version, question_type,
      stimulus_text, prompt, options, points, sort_order, difficulty, skill,
      audio_status, question_code, source_chapters, source_knowledge
    )
    select v_new_id, source_bank_question_id, source_bank_version, question_type,
      stimulus_text, prompt, options, points, sort_order, difficulty, skill,
      audio_status, question_code, source_chapters, source_knowledge
    from public.assessment_paper_questions where paper_id = p_paper_id
    order by sort_order returning id, sort_order
  )
  insert into public.assessment_paper_question_keys (
    question_id, correct_answer, explanation, rubric_snapshot
  )
  select copied.id, source_key.correct_answer, source_key.explanation,
    source_key.rubric_snapshot
  from copied
  join public.assessment_paper_questions as source_question
    on source_question.paper_id = p_paper_id
   and source_question.sort_order = copied.sort_order
  join public.assessment_paper_question_keys as source_key
    on source_key.question_id = source_question.id;

  return v_new_id;
end;
$_$;


ALTER FUNCTION public.duplicate_assessment_paper(p_paper_id uuid) OWNER TO postgres;

--
-- Name: edit_runtime_chapter_activity_v1(uuid, jsonb, uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.edit_runtime_chapter_activity_v1(p_actor uuid, p_scope jsonb, p_activity uuid, p_prompt jsonb, p_answer jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 perform runtime_publish_private.owner_guard(p_actor);
 perform runtime_publish_private.authoring_lock();
 if not exists(select 1 from runtime_publish_private.authoring_control where textbook_id=(p_scope->>'textbookId')::uuid and state='editing') then raise exception 'EDIT_WINDOW_REQUIRED'; end if;
 if not exists(select 1 from public.digital_textbook_activities a join public.digital_textbook_nodes n on n.id=a.node_id
  join public.digital_textbook_modules m on m.id=n.module_id join public.digital_textbook_chapters c on c.id=m.chapter_id
  join public.digital_textbook_versions v on v.id=c.version_id where a.id=p_activity and c.id=(p_scope->>'chapterId')::uuid
  and v.id=(p_scope->>'versionId')::uuid and v.textbook_id=(p_scope->>'textbookId')::uuid and a.activity_type='single_choice') then raise exception 'EDIT_ACTIVITY_SCOPE'; end if;
 if jsonb_typeof(p_prompt)<>'object' or (p_prompt-'zh-CN'-'ko-KR')<>'{}'::jsonb or not (p_prompt ? 'zh-CN') or jsonb_typeof(p_prompt->'zh-CN')<>'string'
  or length(btrim(p_prompt->>'zh-CN'))=0 or p_prompt is null then raise exception 'EDIT_PROMPT'; end if;
 if p_answer is null or (p_answer-'kind'-'value')<>'{}'::jsonb or p_answer->>'kind' is distinct from 'index' or jsonb_typeof(p_answer->'value')<>'number'
  or not exists(select 1 from public.digital_textbook_activities where id=p_activity and (p_answer->>'value')::numeric=trunc((p_answer->>'value')::numeric) and (p_answer->>'value')::numeric>=0 and (p_answer->>'value')::numeric<jsonb_array_length(options)) then raise exception 'EDIT_ANSWER'; end if;
 update public.digital_textbook_activities set prompt=p_prompt where id=p_activity;
 update public.digital_textbook_activity_secrets set answer_key=p_answer where activity_id=p_activity;
 if not found then raise exception 'EDIT_SECRET_MISSING'; end if;
 return jsonb_build_object('saved',true);
end $$;


ALTER FUNCTION public.edit_runtime_chapter_activity_v1(p_actor uuid, p_scope jsonb, p_activity uuid, p_prompt jsonb, p_answer jsonb) OWNER TO postgres;

--
-- Name: edit_runtime_grammar_card_v1(uuid, jsonb, uuid, jsonb, jsonb, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.edit_runtime_grammar_card_v1(p_actor uuid, p_scope jsonb, p_node uuid, p_expected_content jsonb, p_expected_identities jsonb, p_old_card jsonb, p_patch jsonb, p_identities jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare n public.digital_textbook_nodes%rowtype; next_cards jsonb; matches integer;
begin
 perform runtime_publish_private.owner_guard(p_actor);
 perform runtime_publish_private.authoring_lock();
 if not exists(select 1 from runtime_publish_private.authoring_control where textbook_id=(p_scope->>'textbookId')::uuid and state='editing') then raise exception 'EDIT_WINDOW_REQUIRED'; end if;
 select node.* into n from public.digital_textbook_nodes node
 join public.digital_textbook_modules m on m.id=node.module_id
 join public.digital_textbook_chapters c on c.id=m.chapter_id
 join public.digital_textbook_versions v on v.id=c.version_id
 where node.id=p_node and m.module_code='grammar' and c.id=(p_scope->>'chapterId')::uuid
 and v.id=(p_scope->>'versionId')::uuid and v.textbook_id=(p_scope->>'textbookId')::uuid for update of node;
 if not found or n.content is distinct from p_expected_content or n.authoring_grammar_identities is distinct from p_expected_identities then raise exception 'GRAMMAR_EDIT_CONFLICT'; end if;
 if jsonb_typeof(n.content->'grammarCards') is distinct from 'array' or n.content ? 'grammar' then raise exception 'GRAMMAR_FORMAT_CONFLICT'; end if;
 if p_patch is null or jsonb_typeof(p_patch) is distinct from 'object' or (p_patch-'form'-'function'-'caution'-'source')<>'{}'::jsonb
 or not (p_patch ?& array['form','function','caution','source']) or jsonb_typeof(p_patch->'form') is distinct from 'string' or length(btrim(p_patch->>'form'))=0 then raise exception 'GRAMMAR_EDIT_FIELDS'; end if;
 if exists(select 1 from jsonb_each(p_patch-'form') e where jsonb_typeof(e.value) is distinct from 'object'
 or (e.value-'zh-CN'-'ko-KR')<>'{}'::jsonb or jsonb_typeof(e.value->'zh-CN') is distinct from 'string' or jsonb_typeof(e.value->'ko-KR') is distinct from 'string') then raise exception 'GRAMMAR_EDIT_LOCALE'; end if;
 if p_identities is null or jsonb_typeof(p_identities) is distinct from 'array' then raise exception 'GRAMMAR_IDENTITY_SHAPE'; end if;
 if exists(select 1 from jsonb_array_elements(p_identities) e where jsonb_typeof(e) is distinct from 'object' or (e-'id'-'fingerprint')<>'{}'::jsonb
 or coalesce(e->>'id','') !~ '^[a-f0-9-]{36}$' or coalesce(e->>'fingerprint','') !~ '^[a-f0-9]{64}$')
 or (select count(*)<>count(distinct e->>'id') from jsonb_array_elements(p_identities)e) then raise exception 'GRAMMAR_IDENTITY_SHAPE'; end if;
 select count(*) into matches from jsonb_array_elements(n.content->'grammarCards') e where e=p_old_card;
 if matches<>1 then raise exception 'GRAMMAR_CARD_AMBIGUOUS'; end if;
 select jsonb_agg(case when e=p_old_card then e||p_patch else e end order by ord) into next_cards
 from jsonb_array_elements(n.content->'grammarCards') with ordinality a(e,ord);
 update public.digital_textbook_nodes set content=jsonb_set(n.content,'{grammarCards}',next_cards),authoring_grammar_identities=p_identities where id=p_node;
 return jsonb_build_object('saved',true);
end $_$;


ALTER FUNCTION public.edit_runtime_grammar_card_v1(p_actor uuid, p_scope jsonb, p_node uuid, p_expected_content jsonb, p_expected_identities jsonb, p_old_card jsonb, p_patch jsonb, p_identities jsonb) OWNER TO postgres;

--
-- Name: enforce_announcement_assignment(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enforce_announcement_assignment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  resolved_tenant_id uuid;
begin
  if auth.uid() is null then return new; end if;
  if not public.current_user_is_announcement_owner() then raise exception '只有负责人可以指定公告管理员'; end if;

  resolved_tenant_id := coalesce(new.tenant_id, private.current_tenant_id());
  new.tenant_id := resolved_tenant_id;

  if new.revoked_at is null and not exists (
    select 1
    from public.tenant_memberships as membership
    join public.profiles as profile on profile.id = membership.user_id
    where membership.user_id = new.admin_id
      and membership.tenant_id = resolved_tenant_id
      and membership.role = 'admin'
      and membership.status = 'active'
      and coalesce(profile.status, 'active') = 'active'
  ) then
    raise exception '只能授权状态正常的管理员账号';
  end if;

  if new.revoked_at is null then
    new.granted_by := auth.uid(); new.granted_at := now(); new.revoked_by := null;
  else
    new.revoked_by := auth.uid();
  end if;
  return new;
end;
$$;


ALTER FUNCTION public.enforce_announcement_assignment() OWNER TO postgres;

--
-- Name: enforce_announcement_attribution(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enforce_announcement_attribution() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if auth.uid() is null then
    return new;
  end if;

  if not public.current_user_can_access_announcements() then
    raise exception '当前账号没有公告管理权限';
  end if;

  if tg_op = 'INSERT' then
    new.created_by := auth.uid();
    new.created_at := now();
  else
    new.created_by := old.created_by;
    new.created_at := old.created_at;
  end if;

  new.updated_by := auth.uid();
  new.updated_at := now();

  if new.status = 'published' and (tg_op = 'INSERT' or old.status is distinct from 'published') then
    new.published_at := now();
  elsif new.status = 'draft' then
    new.published_at := null;
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.enforce_announcement_attribution() OWNER TO postgres;

--
-- Name: enforce_application_document_checklist_update(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enforce_application_document_checklist_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_can_manage boolean;
  target_is_locked boolean;
begin
  if auth.uid() is null then
    return new;
  end if;

  actor_can_manage := public.is_admin_account()
    or private.is_platform_catalog_manager();

  if actor_can_manage then
    if old.admin_locked_at is not null
       and new.admin_locked_at is not distinct from old.admin_locked_at then
      raise exception '这项材料已锁定，请先解锁再修改';
    end if;
    return new;
  end if;

  if auth.uid() <> old.user_id or new.user_id <> old.user_id then
    raise exception '只能更新自己的申请资料清单';
  end if;

  if old.admin_locked_at is not null then
    raise exception '这项材料已被管理员锁定，暂时无法修改';
  end if;

  if old.target_id is not null then
    select (documents_locked_at is not null) into target_is_locked
    from public.student_university_targets
    where id = old.target_id;

    if target_is_locked then
      raise exception '申请材料已提交锁定，如需修改请联系管理员解锁';
    end if;
  end if;

  if new.status not in ('preparing', 'completed', 'not_needed') then
    raise exception '申请资料状态只能是准备中、已完成或无需';
  end if;

  if (to_jsonb(new) - 'status' - 'updated_at')
     is distinct from (to_jsonb(old) - 'status' - 'updated_at') then
    raise exception '学生只能修改申请资料状态';
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.enforce_application_document_checklist_update() OWNER TO postgres;

