-- Name: enforce_application_document_target_owner(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enforce_application_document_target_owner() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.target_id is null then
    return new;
  end if;

  if not exists (
    select 1
    from public.student_university_targets as target
    where target.id = new.target_id
      and target.user_id = new.user_id
  ) then
    raise exception '申请资料必须属于目标大学对应的学生';
  end if;

  return new;
end;
$$;


