COMMENT ON FUNCTION public.evaluate_student_course_completion(p_student_id uuid, p_course_id uuid, p_policy_id uuid) IS '按已发布政策和权威学习证据幂等计算单学生结课资格；仅供 service_role 调用。';

--
-- Name: finalize_smart_textbook_recording_delete_v2(uuid, uuid, uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finalize_smart_textbook_recording_delete_v2(p_tenant_id uuid, p_student_id uuid, p_activity_id uuid, p_version_id uuid, p_evidence_id uuid, p_runtime_binding jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare e public.digital_textbook_speaking_evidence;
begin
  perform recording_private.require_service();
  perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':'||p_student_id::text||':'||p_activity_id::text,0));
  select * into e from public.digital_textbook_speaking_evidence where id=p_evidence_id for update;
  if e.id is null then return jsonb_build_object('state','already-absent'); end if;
  perform recording_private.check_scope(e,p_tenant_id,p_student_id,p_activity_id,p_version_id,p_runtime_binding);
  if e.consumed_at is not null or e.metadata->>'lifecycle' is distinct from 'delete-pending' then raise exception 'RECORDING_DELETE_NOT_CLAIMED'; end if;
  delete from public.digital_textbook_speaking_evidence where id=e.id;
  return jsonb_build_object('state','deleted');
end $$;


ALTER FUNCTION public.finalize_smart_textbook_recording_delete_v2(p_tenant_id uuid, p_student_id uuid, p_activity_id uuid, p_version_id uuid, p_evidence_id uuid, p_runtime_binding jsonb) OWNER TO postgres;

--
-- Name: get_assessment_paper_release_quality(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_assessment_paper_release_quality(p_paper_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_paper public.assessment_papers%rowtype;
  v_snapshot_matches boolean;
  v_all_skills boolean := true;
  v_objective_keys boolean;
  v_listening_ready boolean := true;
  v_source_counts_match boolean := true;
begin
  if not public.current_user_can_view_assessment_papers() then
    raise exception '当前账号不能查看标准试卷质检结果';
  end if;
  select * into v_paper from public.assessment_papers where id = p_paper_id;
  if v_paper.id is null then raise exception '标准试卷不存在'; end if;

  select count(*) = v_paper.question_count
    and coalesce(sum(question.points), 0) = v_paper.total_points
  into v_snapshot_matches
  from public.assessment_paper_questions as question
  where question.paper_id = p_paper_id;

  select not exists (
    select 1
    from public.assessment_paper_questions as question
    left join public.assessment_paper_question_keys as answer_key
      on answer_key.question_id = question.id
    where question.paper_id = p_paper_id
      and question.auto_graded
      and nullif(btrim(coalesce(answer_key.correct_answer, '')), '') is null
  ) into v_objective_keys;

  if v_paper.paper_type = 'homework' then
    select count(distinct question.skill) = 6 into v_all_skills
    from public.assessment_paper_questions as question
    where question.paper_id = p_paper_id
      and question.skill in (
        'vocabulary', 'grammar', 'listening', 'speaking', 'reading', 'writing'
      );
    select exists (
      select 1 from public.assessment_paper_questions as question
      where question.paper_id = p_paper_id
        and question.skill = 'listening'
        and nullif(btrim(question.stimulus_text), '') is not null
    ) into v_listening_ready;
    if v_paper.source_homework_plan_id is not null then
      select not exists (
        select 1
        from (
          select source.language_skill, count(*) as expected_count
          from public.chapter_homework_questions as source
          where source.plan_id = v_paper.source_homework_plan_id
          group by source.language_skill
        ) as expected
        left join (
          select question.skill as language_skill, count(*) as actual_count
          from public.assessment_paper_questions as question
          where question.paper_id = p_paper_id
          group by question.skill
        ) as actual using (language_skill)
        where expected.expected_count <> coalesce(actual.actual_count, 0)
      ) into v_source_counts_match;
    end if;
  end if;

  return jsonb_build_object(
    'snapshotMatches', v_snapshot_matches,
    'allSkills', v_all_skills,
    'objectiveKeys', v_objective_keys,
    'listeningReady', v_listening_ready,
    'sourceCountsMatch', v_source_counts_match,
    'ready', v_snapshot_matches and v_all_skills and v_objective_keys
      and v_listening_ready and v_source_counts_match
  );
end;
$$;


ALTER FUNCTION public.get_assessment_paper_release_quality(p_paper_id uuid) OWNER TO postgres;

--
-- Name: get_guide_agent_operations_metrics(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_guide_agent_operations_metrics(p_agent_profile_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_result jsonb;
begin
  if not private.is_platform_owner() then
    raise insufficient_privilege using message = 'platform owner required';
  end if;
  select jsonb_build_object(
    'conversations', (select count(*) from public.guide_agent_sessions where agent_profile_id = p_agent_profile_id),
    'studentQuestions', (
      select count(*) from public.guide_agent_messages as message
      join public.guide_agent_sessions as session on session.id = message.session_id
      where session.agent_profile_id = p_agent_profile_id and message.role = 'user'
    ),
    'localRuleReplies', (
      select count(*) from public.guide_agent_messages as message
      join public.guide_agent_sessions as session on session.id = message.session_id
      where session.agent_profile_id = p_agent_profile_id and message.role = 'assistant' and message.response_mode = 'local_rule'
    ),
    'modelReplies', (
      select count(*) from public.guide_agent_messages as message
      join public.guide_agent_sessions as session on session.id = message.session_id
      where session.agent_profile_id = p_agent_profile_id
        and message.role = 'assistant'
        and (message.response_mode = 'model' or (message.response_mode is null and message.provider is not null and message.provider <> 'local'))
    ),
    'failedRequests', (select count(*) from public.guide_agent_failures where agent_profile_id = p_agent_profile_id),
    'averageFirstTokenMs', (
      select round(avg(message.first_token_ms))::integer
      from public.guide_agent_messages as message
      join public.guide_agent_sessions as session on session.id = message.session_id
      where session.agent_profile_id = p_agent_profile_id
        and message.role = 'assistant'
        and message.response_mode = 'model'
        and message.first_token_ms is not null
    )
  ) into v_result;
  return v_result;
end;
$$;


ALTER FUNCTION public.get_guide_agent_operations_metrics(p_agent_profile_id uuid) OWNER TO postgres;

--
-- Name: get_institution_course_completion_statistics(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_institution_course_completion_statistics(p_student_app_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tenant_id uuid := private.current_tenant_id();
  v_result jsonb;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = '必须登录后查看结课统计';
  end if;
  if v_tenant_id is null
    or not private.has_current_tenant_role(
      array['tenant_super_admin', 'ceo']::text[]
    ) then
    raise exception using errcode = '42501', message = '只有机构负责人可以查看本机构结课统计';
  end if;
  if p_student_app_id is null then
    raise exception '学生应用不能为空';
  end if;

  with current_evaluations as materialized (
    select
      evaluation.id,
      evaluation.status,
      evaluation.eligible,
      evaluation.missing_requirements
    from public.student_course_completion_evaluations as evaluation
    where evaluation.tenant_id = v_tenant_id
      and evaluation.student_app_id = p_student_app_id
      and evaluation.status <> 'superseded'
  ),
  issued_evaluations as materialized (
    select distinct certificate.evaluation_id
    from public.course_completion_certificates as certificate
    join current_evaluations as evaluation
      on evaluation.id = certificate.evaluation_id
    where certificate.status = 'issued'
  ),
  summary as (
    select
      count(*)::integer as total_count,
      count(*) filter (
        where evaluation.status = 'eligible' and evaluation.eligible
      )::integer as eligible_count,
      count(issued.evaluation_id)::integer as issued_count
    from current_evaluations as evaluation
    left join issued_evaluations as issued
      on issued.evaluation_id = evaluation.id
  ),
  gap_counts as (
    select
      gap.value ->> 'key' as gap_key,
      gap.value ->> 'category' as gap_category,
      max(gap.value ->> 'title') as gap_title,
      count(*)::integer as gap_count
    from current_evaluations as evaluation
    cross join lateral jsonb_array_elements(
      evaluation.missing_requirements
    ) as gap(value)
    where nullif(gap.value ->> 'key', '') is not null
      and nullif(gap.value ->> 'category', '') is not null
    group by gap.value ->> 'key', gap.value ->> 'category'
  )
  select jsonb_build_object(
    'scope', 'institution',
    'tenantId', v_tenant_id,
    'totalEvaluations', summary.total_count,
    'eligibleCount', summary.eligible_count,
    'eligibleRate', case
      when summary.total_count = 0 then 0
      else round(100.0 * summary.eligible_count / summary.total_count, 1)
    end,
    'issuedCount', summary.issued_count,
    'issuanceRate', case
      when summary.eligible_count = 0 then 0
      else round(100.0 * summary.issued_count / summary.eligible_count, 1)
    end,
    'missingRequirementCount', coalesce((
      select sum(gap_count)::integer from gap_counts
    ), 0),
    'gaps', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'key', gap_key,
          'category', gap_category,
          'title', coalesce(nullif(gap_title, ''), gap_key),
          'count', gap_count
        )
        order by gap_count desc, gap_category, gap_key
      )
      from gap_counts
    ), '[]'::jsonb)
  ) into v_result
  from summary;

  return v_result;
end;
$$;


ALTER FUNCTION public.get_institution_course_completion_statistics(p_student_app_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION get_institution_course_completion_statistics(p_student_app_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_institution_course_completion_statistics(p_student_app_id uuid) IS '单次聚合查询返回当前机构结课资格率、有效证书颁发率及按 key/category 聚合的缺口分布。';

--
-- Name: get_institution_platform_learning_overview(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_institution_platform_learning_overview(p_tenant_id uuid DEFAULT NULL::uuid, p_now timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user_id uuid := (select auth.uid());
  v_current_tenant_id uuid := private.current_tenant_id();
  v_is_platform_owner boolean := private.is_platform_owner();
  v_scope text;
  v_today_start timestamptz;
  v_tomorrow_start timestamptz;
begin
  if v_user_id is null then
    raise exception using errcode = '42501', message = '当前账号无权查看学习概览';
  end if;

  if v_is_platform_owner then
    if p_tenant_id is not null then
      raise exception using
        errcode = '42501',
        message = '平台负责人只能使用全局机构汇总入口';
    end if;
    v_scope := 'platform';
  else
    if p_tenant_id is null
      or p_tenant_id is distinct from v_current_tenant_id
      or not exists (
        select 1
        from public.tenant_memberships as membership
        join public.profiles as profile on profile.id = membership.user_id
        where membership.tenant_id = p_tenant_id
          and membership.user_id = v_user_id
          and membership.role = 'tenant_super_admin'
          and membership.status = 'active'
          and coalesce(profile.status, 'active') = 'active'
      ) then
      raise exception using
        errcode = '42501',
        message = '机构负责人只能查看自己的当前机构';
    end if;
    v_scope := 'institution';
  end if;

  v_today_start := date_trunc('day', p_now at time zone 'Asia/Seoul')
    at time zone 'Asia/Seoul';
  v_tomorrow_start := v_today_start + interval '1 day';

  return (
    with authorized_tenants as materialized (
      select tenant.id, tenant.name
      from public.tenants as tenant
      where tenant.status = 'active'
        and (v_is_platform_owner or tenant.id = p_tenant_id)
    ),
    active_students as materialized (
      select membership.tenant_id, membership.user_id as student_id
      from public.tenant_memberships as membership
      join authorized_tenants as tenant on tenant.id = membership.tenant_id
      join public.profiles as profile on profile.id = membership.user_id
      where membership.role = 'student'
        and membership.status = 'active'
        and coalesce(profile.status, 'active') = 'active'
        and exists (
          select 1
          from public.student_app_enrollments as enrollment
          where enrollment.tenant_id = membership.tenant_id
            and enrollment.student_id = membership.user_id
            and enrollment.status = 'active'
            and enrollment.starts_at <= p_now
            and (enrollment.ends_at is null or enrollment.ends_at > p_now)
        )
    ),
    active_enrollments as materialized (
      select enrollment.tenant_id, enrollment.student_id,
        enrollment.app_id as student_app_id
      from public.student_app_enrollments as enrollment
      join active_students as student
        on student.tenant_id = enrollment.tenant_id
       and student.student_id = enrollment.student_id
      where enrollment.status = 'active'
        and enrollment.starts_at <= p_now
        and (enrollment.ends_at is null or enrollment.ends_at > p_now)
    ),
    activity_students as materialized (
      select distinct activity.tenant_id, activity.student_id
      from public.student_learning_activity_events as activity
      join active_students as student
        on student.tenant_id = activity.tenant_id
       and student.student_id = activity.student_id
      where activity.occurred_at >= v_today_start
        and activity.occurred_at < v_tomorrow_start
        and activity.event_type not in (
          'assignment_graded',
          'assignment_revision_required'
        )
    ),
    submission_rollups as materialized (
      select submission.tenant_id, submission.assignment_id,
        submission.student_id, min(submission.submitted_at) as first_submitted_at
      from public.learning_submissions as submission
      join authorized_tenants as tenant on tenant.id = submission.tenant_id
      group by submission.tenant_id, submission.assignment_id,
        submission.student_id
    ),
    chapter_completions as materialized (
      select progress.tenant_id, progress.student_id, progress.student_app_id,
        progress.test_slug, max(progress.completed_at) as completed_at
      from public.course_ebook_progress as progress
      join authorized_tenants as tenant on tenant.id = progress.tenant_id
      where progress.completed_at is not null
      group by progress.tenant_id, progress.student_id,
        progress.student_app_id, progress.test_slug
    ),
    assignment_audience as materialized (
      select
        enrollment.tenant_id,
        enrollment.student_id,
        enrollment.student_app_id,
        assignment.id as assignment_id,
        assignment.assignment_type,
        assignment.starts_at,
        case
          when assignment.unlock_after_chapter_completion
            and completion.completed_at is not null
            and coalesce(assignment.due_days_after_unlock, 0) > 0
            then completion.completed_at
              + make_interval(days => assignment.due_days_after_unlock)
          else assignment.due_at
        end as effective_due_at,
        assignment.allow_late_submission,
        assignment.unlock_after_chapter_completion,
        completion.completed_at as chapter_completed_at,
        progress.progress_state,
        submission.first_submitted_at,
        counter.current_attempt_started_at
      from active_enrollments as enrollment
      join public.learning_assignments as assignment
        on assignment.tenant_id = enrollment.tenant_id
       and assignment.student_app_id = enrollment.student_app_id
       and assignment.status = 'published'
       and assignment.assignment_type in ('homework', 'exam')
       and (
         assignment.target_scope = 'all_students'
         or exists (
           select 1
           from public.learning_assignment_targets as target
           where target.assignment_id = assignment.id
             and target.student_id = enrollment.student_id
         )
       )
      left join chapter_completions as completion
        on completion.tenant_id = assignment.tenant_id
       and completion.student_id = enrollment.student_id
       and completion.student_app_id = assignment.student_app_id
       and completion.test_slug = assignment.unlock_test_slug
      left join public.learning_assignment_progress as progress
        on progress.tenant_id = assignment.tenant_id
       and progress.assignment_id = assignment.id
       and progress.student_id = enrollment.student_id
      left join submission_rollups as submission
        on submission.tenant_id = assignment.tenant_id
       and submission.assignment_id = assignment.id
       and submission.student_id = enrollment.student_id
      left join public.learning_assignment_submission_counters as counter
        on counter.tenant_id = assignment.tenant_id
       and counter.assignment_id = assignment.id
       and counter.student_id = enrollment.student_id
    ),
    assignment_statuses as materialized (
      select audience.*,
        case
          when audience.progress_state in ('grading_completed', 'grade_released')
            then 'completed'
          when audience.progress_state in (
            'submitted_pending_grading',
            'objective_graded_pending_manual'
          ) then 'pending_grading'
          when (
            audience.unlock_after_chapter_completion
            and audience.chapter_completed_at is null
          ) or audience.starts_at > p_now then 'locked'
          when audience.effective_due_at < p_now then 'overdue'
          when audience.progress_state in ('in_progress', 'revision_required')
            then 'in_progress'
          else 'not_started'
        end as task_status
      from assignment_audience as audience
    ),
    assignment_facts as materialized (
      select status.*,
        (
          (status.starts_at >= v_today_start
            and status.starts_at < v_tomorrow_start)
          or (status.effective_due_at >= v_today_start
            and status.effective_due_at < v_tomorrow_start)
          or (status.task_status = 'overdue' and status.allow_late_submission)
        ) as is_required_today
      from assignment_statuses as status
    ),
    student_counts as (
      select student.tenant_id, count(*)::integer as student_count
      from active_students as student
      group by student.tenant_id
    ),
    activity_counts as (
      select activity.tenant_id, count(*)::integer as active_count
      from activity_students as activity
      group by activity.tenant_id
    ),
    assignment_counts as (
      select fact.tenant_id,
        count(*) filter (where fact.is_required_today)::integer
          as required_task_total,
        count(*) filter (
          where fact.is_required_today and fact.task_status = 'completed'
        )::integer as required_task_completed,
        count(*) filter (
          where fact.assignment_type = 'homework'
            and fact.effective_due_at <= p_now
        )::integer as homework_due_total,
        count(*) filter (
          where fact.assignment_type = 'homework'
            and fact.effective_due_at <= p_now
            and fact.first_submitted_at <= fact.effective_due_at
        )::integer as homework_on_time_count,
        count(*) filter (
          where fact.assignment_type = 'exam' and fact.starts_at <= p_now
        )::integer as exam_eligible_total,
        count(*) filter (
          where fact.assignment_type = 'exam'
            and fact.starts_at <= p_now
            and (
              fact.first_submitted_at is not null
              or fact.current_attempt_started_at is not null
            )
        )::integer as exam_participated_count
      from assignment_facts as fact
      group by fact.tenant_id
    ),
    practice_counts as (
      select progress.tenant_id,
        count(distinct progress.student_id)::integer as user_count
      from public.student_chapter_practice_progress as progress
      join active_students as student
        on student.tenant_id = progress.tenant_id
       and student.student_id = progress.student_id
      where progress.status in ('in_progress', 'needs_reinforcement', 'mastered')
        or progress.started_at is not null
        or progress.last_practiced_at is not null
      group by progress.tenant_id
    ),
    review_counts as (
      select review.tenant_id,
        count(distinct review.student_id)::integer as user_count
      from public.student_review_items as review
      join active_students as student
        on student.tenant_id = review.tenant_id
       and student.student_id = review.student_id
      where review.status in ('reviewing', 'mastered')
        or review.last_reviewed_at is not null
      group by review.tenant_id
    ),
    class_roster as materialized (
      select distinct assignment.tenant_id, assignment.teacher_id,
        assignment.student_app_id, assignment.student_id,
        coalesce(
          nullif(btrim(teacher.full_name), ''),
          nullif(btrim(teacher.login_id), ''),
          '老师 ' || right(assignment.teacher_id::text, 6)
        ) || ' · ' || app.short_title as class_name
      from public.tenant_student_assignments as assignment
      join active_enrollments as enrollment
        on enrollment.tenant_id = assignment.tenant_id
       and enrollment.student_id = assignment.student_id
       and enrollment.student_app_id = assignment.student_app_id
      join public.tenant_memberships as teacher_membership
        on teacher_membership.tenant_id = assignment.tenant_id
       and teacher_membership.user_id = assignment.teacher_id
       and teacher_membership.role = 'teacher'
       and teacher_membership.status = 'active'
      join public.profiles as teacher
        on teacher.id = assignment.teacher_id
       and coalesce(teacher.status, 'active') = 'active'
      join public.student_apps as app on app.id = assignment.student_app_id
    ),
    class_activity as (
      select roster.tenant_id, roster.teacher_id, roster.student_app_id,
        count(distinct roster.student_id) filter (
          where activity.student_id is not null
        )::integer as active_count
      from class_roster as roster
      left join public.student_learning_activity_events as activity
        on activity.tenant_id = roster.tenant_id
       and activity.student_id = roster.student_id
       and activity.student_app_id = roster.student_app_id
       and activity.occurred_at >= v_today_start
       and activity.occurred_at < v_tomorrow_start
       and activity.event_type not in (
         'assignment_graded',
         'assignment_revision_required'
       )
      group by roster.tenant_id, roster.teacher_id, roster.student_app_id
    ),
    class_tasks as (
      select roster.tenant_id, roster.teacher_id, roster.student_app_id,
        count(fact.assignment_id) filter (where fact.is_required_today)::integer
          as required_task_total,
        count(fact.assignment_id) filter (
          where fact.is_required_today and fact.task_status = 'completed'
        )::integer as required_task_completed
      from class_roster as roster
      left join assignment_facts as fact
        on fact.tenant_id = roster.tenant_id
       and fact.student_id = roster.student_id
       and fact.student_app_id = roster.student_app_id
      group by roster.tenant_id, roster.teacher_id, roster.student_app_id
    ),
    class_rollups as (
      select roster.tenant_id, roster.teacher_id, roster.student_app_id,
        min(roster.class_name) as class_name,
        count(distinct roster.student_id)::integer as student_count,
        coalesce(activity.active_count, 0)::integer as active_count,
        coalesce(task.required_task_total, 0)::integer as required_task_total,
        coalesce(task.required_task_completed, 0)::integer
          as required_task_completed
      from class_roster as roster
      left join class_activity as activity
        on activity.tenant_id = roster.tenant_id
       and activity.teacher_id = roster.teacher_id
       and activity.student_app_id = roster.student_app_id
      left join class_tasks as task
        on task.tenant_id = roster.tenant_id
       and task.teacher_id = roster.teacher_id
       and task.student_app_id = roster.student_app_id
      group by roster.tenant_id, roster.teacher_id, roster.student_app_id,
        activity.active_count, task.required_task_total,
        task.required_task_completed
    ),
    class_json as (
      select class.tenant_id,
        jsonb_agg(
          jsonb_build_object(
            'class_key', class.teacher_id::text || ':' || class.student_app_id::text,
            'class_name', class.class_name,
            'teacher_id', class.teacher_id,
            'student_app_id', class.student_app_id,
            'student_count', class.student_count,
            'active_count', class.active_count,
            'active_rate', case when class.student_count = 0 then 0 else
              round(class.active_count::numeric * 100 / class.student_count, 1)
            end,
            'required_task_total', class.required_task_total,
            'required_task_completed', class.required_task_completed,
            'required_completion_rate', case
              when class.required_task_total = 0 then 0 else round(
                class.required_task_completed::numeric * 100
                  / class.required_task_total,
                1
              )
            end
          )
          order by class.class_name, class.teacher_id, class.student_app_id
        ) as classes
      from class_rollups as class
      group by class.tenant_id
    ),
    institution_rows as (
      select tenant.id, tenant.name,
        coalesce(student.student_count, 0)::integer as student_count,
        coalesce(activity.active_count, 0)::integer as active_count,
        coalesce(assignment.required_task_total, 0)::integer
          as required_task_total,
        coalesce(assignment.required_task_completed, 0)::integer
          as required_task_completed,
        coalesce(assignment.homework_due_total, 0)::integer
          as homework_due_total,
        coalesce(assignment.homework_on_time_count, 0)::integer
          as homework_on_time_count,
        coalesce(assignment.exam_eligible_total, 0)::integer
          as exam_eligible_total,
        coalesce(assignment.exam_participated_count, 0)::integer
          as exam_participated_count,
        coalesce(practice.user_count, 0)::integer as chapter_practice_user_count,
        coalesce(review.user_count, 0)::integer as review_user_count,
        coalesce(class_json.classes, '[]'::jsonb) as classes
      from authorized_tenants as tenant
      left join student_counts as student on student.tenant_id = tenant.id
      left join activity_counts as activity on activity.tenant_id = tenant.id
      left join assignment_counts as assignment on assignment.tenant_id = tenant.id
      left join practice_counts as practice on practice.tenant_id = tenant.id
      left join review_counts as review on review.tenant_id = tenant.id
      left join class_json on class_json.tenant_id = tenant.id
    )
    select jsonb_build_object(
      'generated_at', p_now,
      'scope', v_scope,
      'institutions', coalesce(jsonb_agg(
        jsonb_build_object(
          'tenant_id', institution.id,
          'tenant_name', institution.name,
          'student_count', institution.student_count,
          'active_count', institution.active_count,
          'active_rate', case when institution.student_count = 0 then 0 else
            round(institution.active_count::numeric * 100
              / institution.student_count, 1)
          end,
          'required_task_total', institution.required_task_total,
          'required_task_completed', institution.required_task_completed,
          'required_completion_rate', case
            when institution.required_task_total = 0 then 0 else round(
              institution.required_task_completed::numeric * 100
                / institution.required_task_total,
              1
            )
          end,
          'homework_due_total', institution.homework_due_total,
          'homework_on_time_count', institution.homework_on_time_count,
          'homework_on_time_rate', case
            when institution.homework_due_total = 0 then 0 else round(
              institution.homework_on_time_count::numeric * 100
                / institution.homework_due_total,
              1
            )
          end,
          'exam_eligible_total', institution.exam_eligible_total,
          'exam_participated_count', institution.exam_participated_count,
          'exam_participation_rate', case
            when institution.exam_eligible_total = 0 then 0 else round(
              institution.exam_participated_count::numeric * 100
                / institution.exam_eligible_total,
              1
            )
          end,
          'chapter_practice_user_count', institution.chapter_practice_user_count,
          'chapter_practice_usage_rate', case
            when institution.student_count = 0 then 0 else round(
              institution.chapter_practice_user_count::numeric * 100
                / institution.student_count,
              1
            )
          end,
          'review_user_count', institution.review_user_count,
          'review_usage_rate', case
            when institution.student_count = 0 then 0 else round(
              institution.review_user_count::numeric * 100
                / institution.student_count,
              1
            )
          end,
          'classes', case
            when v_scope = 'institution' then institution.classes
            else '[]'::jsonb
          end
        ) order by institution.name, institution.id
      ), '[]'::jsonb)
    )
    from institution_rows as institution
  );
end;
$$;


ALTER FUNCTION public.get_institution_platform_learning_overview(p_tenant_id uuid, p_now timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION get_institution_platform_learning_overview(p_tenant_id uuid, p_now timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_institution_platform_learning_overview(p_tenant_id uuid, p_now timestamp with time zone) IS 'Packet 11 单次聚合：机构负责人仅本机构，平台负责人读取全部正常机构的匿名使用对比。';

--
-- Name: get_platform_assessment_paper_adoption_counts(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_platform_assessment_paper_adoption_counts(p_student_app_id uuid) RETURNS TABLE(paper_id uuid, institution_count bigint, assignment_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    paper.id,
    count(distinct assignment.tenant_id),
    count(assignment.id)
  from public.assessment_papers as paper
  left join public.learning_assignments as assignment
    on assignment.source_paper_id = paper.id
  where paper.student_app_id = p_student_app_id
    and public.current_user_can_manage_assessment_papers()
  group by paper.id;
$$;


ALTER FUNCTION public.get_platform_assessment_paper_adoption_counts(p_student_app_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION get_platform_assessment_paper_adoption_counts(p_student_app_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_platform_assessment_paper_adoption_counts(p_student_app_id uuid) IS '平台试卷工作台按整卷汇总采用机构数和布置次数，不返回学生数据。';

--
-- Name: get_platform_course_completion_trends(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_platform_course_completion_trends(p_student_app_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_result jsonb;
begin
  if auth.uid() is null or not coalesce(private.is_platform_owner(), false) then
    raise exception using errcode = '42501', message = '只有平台负责人可以查看跨机构结课趋势';
  end if;
  if p_student_app_id is null then
    raise exception '学生应用不能为空';
  end if;

  with current_evaluations as materialized (
    select
      evaluation.id,
      evaluation.tenant_id,
      evaluation.policy_id,
      evaluation.policy_version,
      evaluation.status,
      evaluation.eligible,
      date_trunc(
        'month', evaluation.evaluated_at at time zone 'Asia/Seoul'
      )::date as period_start
    from public.student_course_completion_evaluations as evaluation
    where evaluation.student_app_id = p_student_app_id
      and evaluation.status <> 'superseded'
  ),
  issued_evaluations as materialized (
    select distinct certificate.evaluation_id
    from public.course_completion_certificates as certificate
    join current_evaluations as evaluation
      on evaluation.id = certificate.evaluation_id
    where certificate.status = 'issued'
  ),
  trend_rows as (
    select
      evaluation.period_start,
      evaluation.policy_id,
      policy.policy_code,
      evaluation.policy_version,
      max(policy.title) as policy_title,
      count(distinct evaluation.tenant_id)::integer as institution_count,
      count(*)::integer as total_count,
      count(*) filter (
        where evaluation.status = 'eligible' and evaluation.eligible
      )::integer as eligible_count,
      count(issued.evaluation_id)::integer as issued_count
    from current_evaluations as evaluation
    join public.course_completion_policies as policy
      on policy.id = evaluation.policy_id
     and policy.version = evaluation.policy_version
     and policy.student_app_id = p_student_app_id
    left join issued_evaluations as issued
      on issued.evaluation_id = evaluation.id
    group by
      evaluation.period_start,
      evaluation.policy_id,
      policy.policy_code,
      evaluation.policy_version
  )
  select jsonb_build_object(
    'scope', 'platform',
    'trend', coalesce(jsonb_agg(
      jsonb_build_object(
        'periodStart', trend.period_start,
        'policyId', trend.policy_id,
        'policyCode', trend.policy_code,
        'policyVersion', trend.policy_version,
        'policyTitle', trend.policy_title,
        'institutionCount', trend.institution_count,
        'totalEvaluations', trend.total_count,
        'eligibleCount', trend.eligible_count,
        'eligibleRate', case
          when trend.total_count = 0 then 0
          else round(100.0 * trend.eligible_count / trend.total_count, 1)
        end,
        'issuedCount', trend.issued_count,
        'issuanceRate', case
          when trend.eligible_count = 0 then 0
          else round(100.0 * trend.issued_count / trend.eligible_count, 1)
        end
      )
      order by trend.period_start, trend.policy_id, trend.policy_version
    ), '[]'::jsonb)
  ) into v_result
  from trend_rows as trend;

  return v_result;
end;
$$;


ALTER FUNCTION public.get_platform_course_completion_trends(p_student_app_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION get_platform_course_completion_trends(p_student_app_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_platform_course_completion_trends(p_student_app_id uuid) IS '单次聚合查询返回跨机构月度结课趋势；不同 policy_id 与 policy_version 始终分组统计。';

--
-- Name: get_platform_document_review_overview(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_platform_document_review_overview() RETURNS TABLE(tenant_id uuid, tenant_slug text, tenant_name text, tenant_status text, active_student_count bigint, application_count bigint, preparing_count bigint, pending_review_count bigint, revision_required_count bigint, approved_count bigint, oldest_pending_at timestamp with time zone, last_activity_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not private.is_platform_owner() then
    raise exception '只有平台负责人可以查看机构资料审核概览';
  end if;

  return query
  with active_students as (
    select membership.tenant_id, count(*)::bigint as student_count
    from public.tenant_memberships as membership
    where membership.role = 'student'
      and membership.status = 'active'
    group by membership.tenant_id
  ),
  review_statistics as (
    select
      target.tenant_id,
      count(*) filter (where target.status <> 'researching')::bigint as total_count,
      count(*) filter (
        where target.status <> 'researching'
          and target.document_review_status = 'preparing'
      )::bigint as preparing_total,
      count(*) filter (
        where target.status <> 'researching'
          and target.document_review_status = 'pending_review'
      )::bigint as pending_total,
      count(*) filter (
        where target.status <> 'researching'
          and target.document_review_status = 'revision_required'
      )::bigint as revision_total,
      count(*) filter (
        where target.status <> 'researching'
          and target.document_review_status = 'approved'
      )::bigint as approved_total,
      min(target.document_review_submitted_at) filter (
        where target.document_review_status = 'pending_review'
      ) as oldest_pending,
      max(target.updated_at) filter (where target.status <> 'researching') as latest_activity
    from public.student_university_targets as target
    group by target.tenant_id
  )
  select
    tenant.id,
    tenant.slug,
    tenant.name,
    tenant.status,
    coalesce(student.student_count, 0)::bigint,
    coalesce(statistics.total_count, 0)::bigint,
    coalesce(statistics.preparing_total, 0)::bigint,
    coalesce(statistics.pending_total, 0)::bigint,
    coalesce(statistics.revision_total, 0)::bigint,
    coalesce(statistics.approved_total, 0)::bigint,
    statistics.oldest_pending,
    statistics.latest_activity
  from public.tenants as tenant
  left join active_students as student on student.tenant_id = tenant.id
  left join review_statistics as statistics on statistics.tenant_id = tenant.id
  order by
    case when tenant.status = 'active' then 0 else 1 end,
    coalesce(statistics.pending_total, 0) desc,
    tenant.name,
    tenant.id;
end;
$$;


ALTER FUNCTION public.get_platform_document_review_overview() OWNER TO postgres;

--
-- Name: FUNCTION get_platform_document_review_overview(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_platform_document_review_overview() IS '平台负责人专用机构级资料审核汇总；不返回任何学生身份或申请详情。';

--
-- Name: get_platform_grade_overview(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_platform_grade_overview() RETURNS TABLE(tenant_id uuid, tenant_slug text, tenant_name text, tenant_status text, active_student_count bigint, published_assignment_count bigint, grade_record_count bigint, average_score_percent numeric, pass_rate_percent numeric, pending_review_count bigint, last_grade_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not private.is_platform_owner() then
    raise exception '只有平台负责人可以查看机构成绩运行概览';
  end if;

  return query
  with active_students as (
    select membership.tenant_id, count(*)::bigint as student_count
    from public.tenant_memberships as membership
    where membership.role = 'student'
      and membership.status = 'active'
    group by membership.tenant_id
  ),
  published_assignments as (
    select assignment.tenant_id, count(*)::bigint as assignment_count
    from public.learning_assignments as assignment
    where assignment.status in ('published', 'closed')
    group by assignment.tenant_id
  ),
  latest_assignment_submissions as (
    select distinct on (
      submission.tenant_id,
      submission.assignment_id,
      submission.student_id
    )
      submission.tenant_id,
      submission.score,
      assignment.total_points,
      coalesce(submission.graded_at, submission.submitted_at) as recorded_at
    from public.learning_submissions as submission
    join public.learning_assignments as assignment
      on assignment.tenant_id = submission.tenant_id
     and assignment.id = submission.assignment_id
    where submission.status = 'graded'
      and submission.score is not null
      and assignment.total_points > 0
    order by
      submission.tenant_id,
      submission.assignment_id,
      submission.student_id,
      submission.attempt_number desc,
      coalesce(submission.graded_at, submission.submitted_at) desc,
      submission.id desc
  ),
  grade_rows as (
    select
      submission.tenant_id,
      (submission.score / submission.total_points * 100)::numeric as score_percent,
      (submission.score / submission.total_points * 100) >= 60 as passed,
      submission.recorded_at
    from latest_assignment_submissions as submission

    union all

    select
      attempt.tenant_id,
      attempt.score::numeric as score_percent,
      attempt.passed,
      attempt.attempted_at as recorded_at
    from public.chapter_test_attempts as attempt
  ),
  grade_statistics as (
    select
      grade.tenant_id,
      count(*)::bigint as record_count,
      round(avg(grade.score_percent), 2) as average_percent,
      round(
        avg(case when grade.passed then 100::numeric else 0::numeric end),
        2
      ) as pass_percent,
      max(grade.recorded_at) as latest_grade_at
    from grade_rows as grade
    group by grade.tenant_id
  ),
  pending_reviews as (
    select review.tenant_id, count(*)::bigint as review_count
    from public.grade_review_requests as review
    where review.status in ('pending', 'reviewing')
    group by review.tenant_id
  )
  select
    tenant.id,
    tenant.slug,
    tenant.name,
    tenant.status,
    coalesce(student.student_count, 0)::bigint,
    coalesce(assignment.assignment_count, 0)::bigint,
    coalesce(statistics.record_count, 0)::bigint,
    statistics.average_percent,
    statistics.pass_percent,
    coalesce(review.review_count, 0)::bigint,
    statistics.latest_grade_at
  from public.tenants as tenant
  left join active_students as student on student.tenant_id = tenant.id
  left join published_assignments as assignment on assignment.tenant_id = tenant.id
  left join grade_statistics as statistics on statistics.tenant_id = tenant.id
  left join pending_reviews as review on review.tenant_id = tenant.id
  order by
    case when tenant.status = 'active' then 0 else 1 end,
    tenant.name,
    tenant.id;
end;
$$;


ALTER FUNCTION public.get_platform_grade_overview() OWNER TO postgres;

--
-- Name: FUNCTION get_platform_grade_overview(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_platform_grade_overview() IS '平台负责人专用机构级成绩运行汇总；不返回任何学生级成绩或身份数据。';

--
-- Name: get_platform_help_center_overview(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_platform_help_center_overview() RETURNS TABLE(tenant_id uuid, tenant_name text, tenant_status text, active_members bigint, total_tickets bigint, open_tickets bigint, in_progress_tickets bigint, waiting_student_tickets bigint, resolved_tickets bigint, closed_tickets bigint, urgent_pending_tickets bigint, overdue_tickets bigint, resolution_rate numeric, oldest_waiting_at timestamp with time zone, last_updated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not private.is_platform_owner() then
    raise exception '只有平台负责人可以查看机构帮助中心总览';
  end if;

  return query
  select
    tenant.id,
    tenant.name,
    tenant.status,
    coalesce(member_stats.active_members, 0),
    coalesce(ticket_stats.total_tickets, 0),
    coalesce(ticket_stats.open_tickets, 0),
    coalesce(ticket_stats.in_progress_tickets, 0),
    coalesce(ticket_stats.waiting_student_tickets, 0),
    coalesce(ticket_stats.resolved_tickets, 0),
    coalesce(ticket_stats.closed_tickets, 0),
    coalesce(ticket_stats.urgent_pending_tickets, 0),
    coalesce(ticket_stats.overdue_tickets, 0),
    coalesce(ticket_stats.resolution_rate, 0),
    ticket_stats.oldest_waiting_at,
    ticket_stats.last_updated_at
  from public.tenants as tenant
  left join lateral (
    select count(distinct membership.user_id)::bigint as active_members
    from public.tenant_memberships as membership
    where membership.tenant_id = tenant.id
      and membership.status = 'active'
  ) as member_stats on true
  left join lateral (
    select
      count(*)::bigint as total_tickets,
      count(*) filter (where ticket.status = 'open')::bigint as open_tickets,
      count(*) filter (where ticket.status = 'in_progress')::bigint as in_progress_tickets,
      count(*) filter (where ticket.status = 'waiting_student')::bigint as waiting_student_tickets,
      count(*) filter (where ticket.status = 'resolved')::bigint as resolved_tickets,
      count(*) filter (where ticket.status = 'closed')::bigint as closed_tickets,
      count(*) filter (
        where ticket.priority = 'urgent'
          and ticket.status in ('open', 'in_progress')
      )::bigint as urgent_pending_tickets,
      count(*) filter (
        where (ticket.status = 'open' and ticket.created_at < now() - interval '24 hours')
           or (ticket.status = 'in_progress' and ticket.updated_at < now() - interval '72 hours')
      )::bigint as overdue_tickets,
      round(
        100.0 * count(*) filter (where ticket.status in ('resolved', 'closed'))
        / nullif(count(*), 0),
        1
      ) as resolution_rate,
      min(ticket.created_at) filter (where ticket.status = 'open') as oldest_waiting_at,
      max(ticket.updated_at) as last_updated_at
    from public.help_tickets as ticket
    where ticket.tenant_id = tenant.id
  ) as ticket_stats on true
  where tenant.status <> 'archived'
  order by tenant.name, tenant.id;
end;
$$;


ALTER FUNCTION public.get_platform_help_center_overview() OWNER TO postgres;

--
-- Name: FUNCTION get_platform_help_center_overview(); Type: COMMENT; Schema: public; Owner: postgres
