--
-- Name: get_platform_learning_record_overview(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_platform_learning_record_overview() RETURNS TABLE(tenant_id uuid, tenant_slug text, tenant_name text, tenant_status text, active_student_count bigint, total_record_count bigint, active_record_count bigint, student_visible_count bigint, internal_record_count bigint, attention_record_count bigint, plan_record_count bigint, last_record_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not private.is_platform_owner() then
    raise exception '只有平台负责人可以查看机构学习记录运行概览';
  end if;

  return query
  with active_students as (
    select membership.tenant_id, count(*)::bigint as student_count
    from public.tenant_memberships as membership
    where membership.role = 'student'
      and membership.status = 'active'
    group by membership.tenant_id
  ),
  record_statistics as (
    select
      note.tenant_id,
      count(*)::bigint as total_count,
      count(*) filter (where note.status = 'active')::bigint as active_count,
      count(*) filter (
        where note.status = 'active'
          and note.visibility = 'student_visible'
      )::bigint as visible_count,
      count(*) filter (
        where note.status = 'active'
          and note.visibility = 'internal'
      )::bigint as internal_count,
      count(*) filter (
        where note.status = 'active'
          and note.record_type = 'attention'
      )::bigint as attention_count,
      count(*) filter (
        where note.status = 'active'
          and note.record_type = 'plan'
      )::bigint as plan_count,
      max(note.occurred_at) as latest_record_at
    from public.learning_record_notes as note
    group by note.tenant_id
  )
  select
    tenant.id,
    tenant.slug,
    tenant.name,
    tenant.status,
    coalesce(student.student_count, 0)::bigint,
    coalesce(statistics.total_count, 0)::bigint,
    coalesce(statistics.active_count, 0)::bigint,
    coalesce(statistics.visible_count, 0)::bigint,
    coalesce(statistics.internal_count, 0)::bigint,
    coalesce(statistics.attention_count, 0)::bigint,
    coalesce(statistics.plan_count, 0)::bigint,
    statistics.latest_record_at
  from public.tenants as tenant
  left join active_students as student on student.tenant_id = tenant.id
  left join record_statistics as statistics on statistics.tenant_id = tenant.id
  order by
    case when tenant.status = 'active' then 0 else 1 end,
    tenant.name,
    tenant.id;
end;
$$;


ALTER FUNCTION public.get_platform_learning_record_overview() OWNER TO postgres;

--
-- Name: FUNCTION get_platform_learning_record_overview(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_platform_learning_record_overview() IS '平台负责人专用机构级学习记录汇总；不返回任何学生身份或记录正文。';

--
-- Name: get_platform_management_app_overview(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_platform_management_app_overview(p_app_id uuid) RETURNS TABLE(tenant_id uuid, tenant_name text, active_students bigint, active_staff bigint, assignments bigint, published_assignments bigint, submissions bigint, graded_submissions bigint, notes bigint, active_notes bigint, scenarios bigint, published_scenarios bigint, conversation_practices bigint, completed_conversation_practices bigint)
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
begin
  if p_app_id is null or not private.is_platform_owner() then
    raise exception '只有平台负责人可以查看跨机构应用汇总'
      using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.student_apps as app
    where app.id = p_app_id
  ) then
    raise exception '应用不存在'
      using errcode = '22023';
  end if;

  return query
  with active_tenants as materialized (
    select tenant.id as tenant_id, tenant.name as tenant_name
    from public.tenants as tenant
    where tenant.status = 'active'
  ),
  enrollment_totals as (
    select
      enrollment.tenant_id,
      count(*) filter (where enrollment.status = 'active')::bigint
        as active_students
    from public.student_app_enrollments as enrollment
    join active_tenants as tenant
      on tenant.tenant_id = enrollment.tenant_id
    where enrollment.tenant_id = tenant.tenant_id
      and enrollment.app_id = p_app_id
    group by enrollment.tenant_id
  ),
  staff_totals as (
    select
      staff_assignment.tenant_id,
      count(*) filter (where staff_assignment.status = 'active')::bigint
        as active_staff
    from public.staff_app_assignments as staff_assignment
    join active_tenants as tenant
      on tenant.tenant_id = staff_assignment.tenant_id
    where staff_assignment.tenant_id = tenant.tenant_id
      and staff_assignment.app_id = p_app_id
    group by staff_assignment.tenant_id
  ),
  assignment_totals as (
    select
      assignment.tenant_id,
      count(*)::bigint as assignments,
      count(*) filter (where assignment.status = 'published')::bigint
        as published_assignments
    from public.learning_assignments as assignment
    join active_tenants as tenant
      on tenant.tenant_id = assignment.tenant_id
    where assignment.tenant_id = tenant.tenant_id
      and assignment.student_app_id = p_app_id
    group by assignment.tenant_id
  ),
  submission_totals as (
    select
      submission.tenant_id,
      count(*)::bigint as submissions,
      count(*) filter (where submission.status = 'graded')::bigint
        as graded_submissions
    from public.learning_submissions as submission
    join active_tenants as tenant
      on tenant.tenant_id = submission.tenant_id
    join public.learning_assignments as assignment
      on assignment.tenant_id = submission.tenant_id
     and assignment.id = submission.assignment_id
    where submission.tenant_id = tenant.tenant_id
      and assignment.tenant_id = tenant.tenant_id
      and assignment.student_app_id = p_app_id
    group by submission.tenant_id
  ),
  note_totals as (
    select
      note.tenant_id,
      count(*)::bigint as notes,
      count(*) filter (where note.status = 'active')::bigint as active_notes
    from public.learning_record_notes as note
    join active_tenants as tenant
      on tenant.tenant_id = note.tenant_id
    where note.tenant_id = tenant.tenant_id
      and note.student_app_id = p_app_id
    group by note.tenant_id
  ),
  scenario_totals as (
    select
      scenario.tenant_id,
      count(*)::bigint as scenarios,
      count(*) filter (where scenario.status = 'published')::bigint
        as published_scenarios
    from public.conversation_practice_scenarios as scenario
    join active_tenants as tenant
      on tenant.tenant_id = scenario.tenant_id
    where scenario.tenant_id = tenant.tenant_id
      and scenario.student_app_id = p_app_id
    group by scenario.tenant_id
  ),
  conversation_totals as (
    select
      progress.tenant_id,
      count(*)::bigint as conversation_practices,
      count(*) filter (where progress.status = 'completed')::bigint
        as completed_conversation_practices
    from public.conversation_practice_progress as progress
    join active_tenants as tenant
      on tenant.tenant_id = progress.tenant_id
    join public.conversation_practice_scenarios as scenario
      on scenario.tenant_id = progress.tenant_id
     and scenario.id = progress.scenario_id
    where progress.tenant_id = tenant.tenant_id
      and scenario.tenant_id = tenant.tenant_id
      and scenario.student_app_id = p_app_id
    group by progress.tenant_id
  ),
  overview as (
    select
      tenant.tenant_id,
      tenant.tenant_name,
      coalesce(enrollment.active_students, 0)::bigint as active_students,
      coalesce(staff.active_staff, 0)::bigint as active_staff,
      coalesce(assignment.assignments, 0)::bigint as assignments,
      coalesce(assignment.published_assignments, 0)::bigint
        as published_assignments,
      coalesce(submission.submissions, 0)::bigint as submissions,
      coalesce(submission.graded_submissions, 0)::bigint
        as graded_submissions,
      coalesce(note.notes, 0)::bigint as notes,
      coalesce(note.active_notes, 0)::bigint as active_notes,
      coalesce(scenario.scenarios, 0)::bigint as scenarios,
      coalesce(scenario.published_scenarios, 0)::bigint
        as published_scenarios,
      coalesce(conversation.conversation_practices, 0)::bigint
        as conversation_practices,
      coalesce(conversation.completed_conversation_practices, 0)::bigint
        as completed_conversation_practices
    from active_tenants as tenant
    left join enrollment_totals as enrollment
      on enrollment.tenant_id = tenant.tenant_id
    left join staff_totals as staff
      on staff.tenant_id = tenant.tenant_id
    left join assignment_totals as assignment
      on assignment.tenant_id = tenant.tenant_id
    left join submission_totals as submission
      on submission.tenant_id = tenant.tenant_id
    left join note_totals as note
      on note.tenant_id = tenant.tenant_id
    left join scenario_totals as scenario
      on scenario.tenant_id = tenant.tenant_id
    left join conversation_totals as conversation
      on conversation.tenant_id = tenant.tenant_id
  )
  select
    overview.tenant_id,
    overview.tenant_name,
    overview.active_students,
    overview.active_staff,
    overview.assignments,
    overview.published_assignments,
    overview.submissions,
    overview.graded_submissions,
    overview.notes,
    overview.active_notes,
    overview.scenarios,
    overview.published_scenarios,
    overview.conversation_practices,
    overview.completed_conversation_practices
  from overview
  where overview.active_students
      + overview.active_staff
      + overview.assignments
      + overview.notes
      + overview.scenarios
      + overview.conversation_practices > 0
  order by overview.tenant_name, overview.tenant_id;
end;
$$;


ALTER FUNCTION public.get_platform_management_app_overview(p_app_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION get_platform_management_app_overview(p_app_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_platform_management_app_overview(p_app_id uuid) IS '平台负责人按应用读取活跃机构级汇总；SECURITY INVOKER，逐表绑定 tenant_id；学习时长因既有 RLS 由服务器分页合并。';

--
-- Name: get_platform_visa_case_audit(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_platform_visa_case_audit() RETURNS TABLE(tenant_id uuid, case_reference text, visa_type text, application_channel text, case_status text, task_count bigint, approved_task_count bigint, pending_task_count bigint, support_task_count bigint, target_entry_date date, planned_entry_date date, oldest_pending_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not private.is_platform_owner() then
    raise exception '只有平台负责人可以巡检机构签证案件';
  end if;

  return query
  with task_statistics as (
    select
      task.tenant_id,
      task.user_id,
      count(*) filter (where task.is_archived = false)::bigint as total_count,
      count(*) filter (where task.status = 'approved' and task.is_archived = false)::bigint as approved_count,
      count(*) filter (where task.status in ('submitted', 'reviewing') and task.is_archived = false)::bigint as pending_count,
      count(*) filter (where task.status in ('revision_required', 'blocked') and task.is_archived = false)::bigint as support_count,
      min(coalesce(task.submitted_at, task.updated_at)) filter (
        where task.status in ('submitted', 'reviewing') and task.is_archived = false
      ) as oldest_pending
    from public.student_visa_tasks as task
    group by task.tenant_id, task.user_id
  )
  select
    visa_case.tenant_id,
    upper(right(replace(visa_case.id::text, '-', ''), 8)),
    visa_case.visa_type,
    visa_case.application_channel,
    visa_case.case_status,
    coalesce(task_data.total_count, 0)::bigint,
    coalesce(task_data.approved_count, 0)::bigint,
    coalesce(task_data.pending_count, 0)::bigint,
    coalesce(task_data.support_count, 0)::bigint,
    visa_case.target_entry_date,
    visa_case.planned_entry_date,
    task_data.oldest_pending,
    visa_case.updated_at
  from public.student_visa_cases as visa_case
  left join task_statistics as task_data
    on task_data.tenant_id = visa_case.tenant_id
   and task_data.user_id = visa_case.user_id
  order by
    coalesce(task_data.pending_count, 0) desc,
    coalesce(task_data.support_count, 0) desc,
    visa_case.updated_at desc,
    visa_case.id;
end;
$$;


ALTER FUNCTION public.get_platform_visa_case_audit() OWNER TO postgres;

--
-- Name: FUNCTION get_platform_visa_case_audit(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_platform_visa_case_audit() IS '平台负责人巡检机构签证案件的匿名运行明细，不返回学生身份、院校或材料内容。';

--
-- Name: get_platform_visa_management_overview(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_platform_visa_management_overview() RETURNS TABLE(tenant_id uuid, tenant_slug text, tenant_name text, tenant_status text, active_student_count bigint, case_count bigint, admin_preparing_count bigint, preparing_count bigint, submitted_count bigint, additional_documents_count bigint, approved_count bigint, issued_count bigint, pending_task_count bigint, support_task_count bigint, upcoming_entry_count bigint, oldest_pending_at timestamp with time zone, last_activity_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not private.is_platform_owner() then
    raise exception '只有平台负责人可以查看机构签证运行概览';
  end if;

  return query
  with active_students as (
    select membership.tenant_id, count(*)::bigint as student_count
    from public.tenant_memberships as membership
    where membership.role = 'student'
      and membership.status = 'active'
    group by membership.tenant_id
  ),
  case_statistics as (
    select
      visa_case.tenant_id,
      count(*)::bigint as total_count,
      count(*) filter (where visa_case.case_status = 'admin_preparing')::bigint as admin_preparing_total,
      count(*) filter (where visa_case.case_status in ('planning', 'preparing', 'ready_to_submit'))::bigint as preparing_total,
      count(*) filter (where visa_case.case_status = 'submitted')::bigint as submitted_total,
      count(*) filter (where visa_case.case_status = 'additional_documents')::bigint as additional_total,
      count(*) filter (where visa_case.case_status = 'approved')::bigint as approved_total,
      count(*) filter (where visa_case.case_status = 'issued')::bigint as issued_total,
      count(*) filter (
        where visa_case.case_status <> 'closed'
          and coalesce(visa_case.planned_entry_date, visa_case.target_entry_date)
            between current_date and current_date + 30
      )::bigint as upcoming_entry_total,
      max(visa_case.updated_at) as latest_activity
    from public.student_visa_cases as visa_case
    group by visa_case.tenant_id
  ),
  task_statistics as (
    select
      task.tenant_id,
      count(*) filter (where task.status in ('submitted', 'reviewing') and task.is_archived = false)::bigint as pending_total,
      count(*) filter (where task.status in ('revision_required', 'blocked') and task.is_archived = false)::bigint as support_total,
      min(coalesce(task.submitted_at, task.updated_at)) filter (
        where task.status in ('submitted', 'reviewing') and task.is_archived = false
      ) as oldest_pending,
      max(task.updated_at) filter (where task.is_archived = false) as latest_activity
    from public.student_visa_tasks as task
    group by task.tenant_id
  )
  select
    tenant.id,
    tenant.slug,
    tenant.name,
    tenant.status,
    coalesce(student.student_count, 0)::bigint,
    coalesce(case_data.total_count, 0)::bigint,
    coalesce(case_data.admin_preparing_total, 0)::bigint,
    coalesce(case_data.preparing_total, 0)::bigint,
    coalesce(case_data.submitted_total, 0)::bigint,
    coalesce(case_data.additional_total, 0)::bigint,
    coalesce(case_data.approved_total, 0)::bigint,
    coalesce(case_data.issued_total, 0)::bigint,
    coalesce(task_data.pending_total, 0)::bigint,
    coalesce(task_data.support_total, 0)::bigint,
    coalesce(case_data.upcoming_entry_total, 0)::bigint,
    task_data.oldest_pending,
    case
      when case_data.latest_activity is null then task_data.latest_activity
      when task_data.latest_activity is null then case_data.latest_activity
      else greatest(case_data.latest_activity, task_data.latest_activity)
    end
  from public.tenants as tenant
  left join active_students as student on student.tenant_id = tenant.id
  left join case_statistics as case_data on case_data.tenant_id = tenant.id
  left join task_statistics as task_data on task_data.tenant_id = tenant.id
  order by
    case when tenant.status = 'active' then 0 else 1 end,
    coalesce(task_data.pending_total, 0) desc,
    coalesce(task_data.support_total, 0) desc,
    tenant.name,
    tenant.id;
end;
$$;


ALTER FUNCTION public.get_platform_visa_management_overview() OWNER TO postgres;

