-- Name: FUNCTION get_student_assigned_teachers(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_student_assigned_teachers() IS '学生查询自己被分配的负责老师姓名（代课老师）；仅返回 auth.uid() 自己的分配记录。';

--
-- Name: get_teacher_class_today_snapshot(uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_teacher_class_today_snapshot(p_tenant_id uuid, p_student_app_id uuid, p_student_id uuid DEFAULT NULL::uuid, p_now timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_teacher_id uuid := (select auth.uid());
  v_today_start timestamptz;
  v_tomorrow_start timestamptz;
begin
  if v_teacher_id is null
    or p_tenant_id is distinct from (select private.current_tenant_id())
    or not exists (
      select 1
      from public.tenant_memberships as membership
      join public.profiles as profile on profile.id = membership.user_id
      where membership.tenant_id = p_tenant_id
        and membership.user_id = v_teacher_id
        and membership.role = 'teacher'
        and membership.status = 'active'
        and coalesce(profile.status, 'active') = 'active'
    )
    or not private.current_staff_has_app_capability(
      p_tenant_id,
      p_student_app_id,
      'view_analytics'
    ) then
    raise exception using
      errcode = '42501',
      message = '当前老师没有查看该应用班级数据的权限';
  end if;

  -- A deep link is rejected before any student profile or task row is read.
  if p_student_id is not null
    and not private.current_teacher_has_student_app_access(
      p_tenant_id,
      p_student_id,
      p_student_app_id
    ) then
    raise exception using
      errcode = '42501',
      message = '该学生不在当前老师的教学分配范围内';
  end if;

  v_today_start := date_trunc('day', p_now at time zone 'Asia/Seoul')
    at time zone 'Asia/Seoul';
  v_tomorrow_start := v_today_start + interval '1 day';

  return (
    with authorized_students as materialized (
      select distinct on (assignment.student_id)
        assignment.student_id,
        profile.full_name,
        profile.login_id,
        greatest(assignment.created_at, enrollment.starts_at) as tracking_started_at
      from public.tenant_student_assignments as assignment
      join public.student_app_enrollments as enrollment
        on enrollment.tenant_id = assignment.tenant_id
       and enrollment.student_id = assignment.student_id
       and enrollment.app_id = assignment.student_app_id
      join public.tenant_memberships as membership
        on membership.tenant_id = assignment.tenant_id
       and membership.user_id = assignment.student_id
       and membership.role = 'student'
       and membership.status = 'active'
      join public.profiles as profile
        on profile.id = assignment.student_id
       and coalesce(profile.status, 'active') = 'active'
      where assignment.tenant_id = p_tenant_id
        and assignment.teacher_id = v_teacher_id
        and assignment.student_app_id = p_student_app_id
        and (p_student_id is null or assignment.student_id = p_student_id)
        and enrollment.status = 'active'
        and enrollment.starts_at <= p_now
        and (enrollment.ends_at is null or enrollment.ends_at > p_now)
        and private.current_teacher_has_student_app_access(
          assignment.tenant_id,
          assignment.student_id,
          assignment.student_app_id
        )
      order by assignment.student_id, assignment.created_at desc
    ),
    activity_rollups as materialized (
      select
        student.student_id,
        max(activity.occurred_at) as last_activity_at,
        coalesce(
          bool_or(
            activity.occurred_at >= v_today_start
            and activity.occurred_at < v_tomorrow_start
          ),
          false
        ) as studied_today
      from authorized_students as student
      left join public.student_learning_activity_events as activity
        on activity.tenant_id = p_tenant_id
       and activity.student_id = student.student_id
       and activity.student_app_id = p_student_app_id
       -- Teacher-side grading/revision events are written into the student's
       -- timeline for history, but they are not evidence that the student
       -- studied today and must not reset the no-learning streak.
       and activity.event_type not in (
         'assignment_graded',
         'assignment_revision_required'
       )
      group by student.student_id
    ),
    assignment_audience as materialized (
      select
        student.student_id,
        assignment.id as assignment_id,
        assignment.title,
        assignment.assignment_type,
        assignment.starts_at,
        case
          when assignment.unlock_after_chapter_completion
            and chapter_progress.completed_at is not null
            and coalesce(assignment.due_days_after_unlock, 0) > 0
            then chapter_progress.completed_at
              + make_interval(days => assignment.due_days_after_unlock)
          else assignment.due_at
        end as effective_due_at,
        assignment.allow_late_submission,
        assignment.unlock_after_chapter_completion,
        chapter_progress.completed_at as chapter_completed_at,
        progress.progress_state,
        progress.updated_at as progress_updated_at
      from authorized_students as student
      join public.learning_assignments as assignment
        on assignment.tenant_id = p_tenant_id
       and assignment.student_app_id = p_student_app_id
       and assignment.status = 'published'
       and assignment.assignment_type in ('homework', 'exam')
       and (
         assignment.target_scope = 'all_students'
         or exists (
           select 1
           from public.learning_assignment_targets as target
           where target.assignment_id = assignment.id
             and target.student_id = student.student_id
         )
       )
      left join public.learning_assignment_progress as progress
        on progress.tenant_id = assignment.tenant_id
       and progress.assignment_id = assignment.id
       and progress.student_id = student.student_id
      left join public.course_ebook_progress as chapter_progress
        on chapter_progress.tenant_id = assignment.tenant_id
       and chapter_progress.student_id = student.student_id
       and chapter_progress.student_app_id = assignment.student_app_id
       and chapter_progress.test_slug = assignment.unlock_test_slug
       and chapter_progress.completed_at is not null
    ),
    task_statuses as materialized (
      select
        audience.*,
        case
          when audience.progress_state in ('grading_completed', 'grade_released')
            then 'completed'
          when audience.progress_state in (
            'submitted_pending_grading',
            'objective_graded_pending_manual'
          ) then 'pending_grading'
          when (
            audience.unlock_after_chapter_completion
            and audience.chapter_completed_at is null
          ) or audience.starts_at > p_now then 'locked'
          when audience.effective_due_at < p_now then 'overdue'
          when audience.progress_state in ('in_progress', 'revision_required')
            then 'in_progress'
          else 'not_started'
        end as task_status
      from assignment_audience as audience
    ),
    task_facts as materialized (
      select
        task.*,
        (
          (task.starts_at >= v_today_start and task.starts_at < v_tomorrow_start)
          or (
            task.effective_due_at >= v_today_start
            and task.effective_due_at < v_tomorrow_start
          )
          or (
            task.task_status = 'overdue'
            and task.allow_late_submission
          )
        ) as is_required_today
      from task_statuses as task
    ),
    student_rollups as materialized (
      select
        student.student_id,
        student.full_name,
        student.login_id,
        activity.studied_today,
        activity.last_activity_at,
        greatest(
          0,
          (v_today_start at time zone 'Asia/Seoul')::date
            - (
                coalesce(activity.last_activity_at, student.tracking_started_at)
                at time zone 'Asia/Seoul'
              )::date
        )::integer as inactive_days,
        count(task.assignment_id) filter (where task.is_required_today)::integer
          as required_task_total,
        count(task.assignment_id) filter (
          where task.is_required_today and task.task_status = 'completed'
        )::integer as required_task_completed,
        count(task.assignment_id) filter (
          where task.is_required_today
            and task.task_status in ('not_started', 'locked')
        )::integer as not_started_task_count,
        count(task.assignment_id) filter (
          where task.is_required_today and task.task_status = 'in_progress'
        )::integer as in_progress_task_count,
        count(task.assignment_id) filter (
          where task.is_required_today and task.task_status = 'completed'
        )::integer as completed_task_count,
        count(task.assignment_id) filter (
          where task.task_status = 'overdue'
        )::integer as overdue_task_count,
        count(task.assignment_id) filter (
          where task.task_status = 'pending_grading'
        )::integer as pending_grading_task_count
      from authorized_students as student
      join activity_rollups as activity on activity.student_id = student.student_id
      left join task_facts as task on task.student_id = student.student_id
      group by
        student.student_id,
        student.full_name,
        student.login_id,
        student.tracking_started_at,
        activity.studied_today,
        activity.last_activity_at
    ),
    class_summary as (
      select
        count(*)::integer as student_count,
        count(*) filter (where studied_today)::integer as studied_today_count,
        coalesce(sum(required_task_total), 0)::integer as required_task_total,
        coalesce(sum(required_task_completed), 0)::integer
          as required_task_completed,
        count(*) filter (where not_started_task_count > 0)::integer
          as not_started_count,
        count(*) filter (where in_progress_task_count > 0)::integer
          as in_progress_count,
        count(*) filter (where completed_task_count > 0)::integer
          as completed_count,
        count(*) filter (where overdue_task_count > 0)::integer
          as overdue_count,
        count(*) filter (where pending_grading_task_count > 0)::integer
          as pending_grading_count,
        count(*) filter (where inactive_days >= 3)::integer
          as continuous_no_learning_count
      from student_rollups
    )
    select jsonb_build_object(
      'generated_at', p_now,
      'summary', jsonb_build_object(
        'student_count', summary.student_count,
        'studied_today_count', summary.studied_today_count,
        'required_task_total', summary.required_task_total,
        'required_task_completed', summary.required_task_completed,
        'required_completion_rate', case
          when summary.required_task_total = 0 then 0
          else round(
            summary.required_task_completed::numeric
              * 100 / summary.required_task_total,
            1
          )
        end,
        'not_started_count', summary.not_started_count,
        'in_progress_count', summary.in_progress_count,
        'completed_count', summary.completed_count,
        'overdue_count', summary.overdue_count,
        'pending_grading_count', summary.pending_grading_count,
        'continuous_no_learning_count', summary.continuous_no_learning_count
      ),
      'students', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'student_id', student.student_id,
            'full_name', student.full_name,
            'login_id', student.login_id,
            'studied_today', student.studied_today,
            'last_activity_at', student.last_activity_at,
            'inactive_days', student.inactive_days,
            'continuous_no_learning', student.inactive_days >= 3,
            'required_task_total', student.required_task_total,
            'required_task_completed', student.required_task_completed,
            'not_started_task_count', student.not_started_task_count,
            'in_progress_task_count', student.in_progress_task_count,
            'completed_task_count', student.completed_task_count,
            'overdue_task_count', student.overdue_task_count,
            'pending_grading_task_count', student.pending_grading_task_count
          )
          order by coalesce(student.full_name, student.login_id, student.student_id::text)
        )
        from student_rollups as student
      ), '[]'::jsonb),
      'tasks', case
        when p_student_id is null then '[]'::jsonb
        else coalesce((
          select jsonb_agg(
            jsonb_build_object(
              'assignment_id', task.assignment_id,
              'title', task.title,
              'assignment_type', task.assignment_type,
              'status', task.task_status,
              'starts_at', task.starts_at,
              'due_at', task.effective_due_at,
              'is_required_today', task.is_required_today
            )
            order by
              task.is_required_today desc,
              task.effective_due_at,
              task.assignment_id
          )
          from task_facts as task
          where task.student_id = p_student_id
            and (
              task.is_required_today
              or task.task_status in ('overdue', 'pending_grading', 'in_progress')
            )
        ), '[]'::jsonb)
      end
    )
    from class_summary as summary
  );
end;
$$;


ALTER FUNCTION public.get_teacher_class_today_snapshot(p_tenant_id uuid, p_student_app_id uuid, p_student_id uuid, p_now timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION get_teacher_class_today_snapshot(p_tenant_id uuid, p_student_app_id uuid, p_student_id uuid, p_now timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_teacher_class_today_snapshot(p_tenant_id uuid, p_student_app_id uuid, p_student_id uuid, p_now timestamp with time zone) IS '老师班级今日只读快照：按应用级教学分配授权，以单次聚合查询返回汇总、学生状态与可选学生明细。';

--
-- Name: get_teaching_script_source_review(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_teaching_script_source_review(p_version_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare current_source jsonb; current_token text; previous public.teaching_script_source_reviews;
begin
  if auth.uid() is null or not coalesce(private.is_platform_owner(), false) then raise exception '只有平台负责人可以复核教学脚本'; end if;
  current_source := private.teaching_script_source_snapshot(p_version_id);
  current_token := private.teaching_script_review_token(p_version_id);
  if current_source is null or current_token is null then raise exception '脚本或教材来源不存在'; end if;
  select * into previous from public.teaching_script_source_reviews where script_version_id = p_version_id;
  return jsonb_build_object('source', current_source, 'scriptToken', current_token,
    'previousSource', previous.source_snapshot, 'revision', coalesce(previous.revision, 0),
    'reviewedAt', previous.reviewed_at, 'sourceChanged', previous.source_snapshot is distinct from current_source,
    'scriptChanged', previous.script_token is distinct from current_token,
    'status', case when previous.script_version_id is null then 'unreviewed'
      when previous.source_snapshot is distinct from current_source or previous.script_token is distinct from current_token then 'changed' else 'reviewed' end);
end;
$$;


ALTER FUNCTION public.get_teaching_script_source_review(p_version_id uuid) OWNER TO postgres;

--
-- Name: get_tenant_admin_dashboard_summary(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_tenant_admin_dashboard_summary(p_tenant_id uuid) RETURNS TABLE(active_members bigint, published_assignments bigint, draft_assignments bigint, published_announcements bigint, draft_announcements bigint, open_help_tickets bigint, pending_grade_reviews bigint, pending_document_reviews bigint, pending_visa_tasks bigint, attention_records bigint)
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
begin
  if p_tenant_id is null
    or p_tenant_id is distinct from private.current_tenant_id()
    or not public.is_admin_account()
  then
    raise exception '无权读取该机构的管理首页汇总'
      using errcode = '42501';
  end if;

  return query
  select
    (
      select count(*)::bigint
      from public.tenant_memberships as membership
      where membership.tenant_id = p_tenant_id
        and membership.status = 'active'
    ),
    (
      select count(*)::bigint
      from public.learning_assignments as assignment
      where assignment.tenant_id = p_tenant_id
        and assignment.status = 'published'
    ),
    (
      select count(*)::bigint
      from public.learning_assignments as assignment
      where assignment.tenant_id = p_tenant_id
        and assignment.status = 'draft'
    ),
    (
      select count(*)::bigint
      from public.announcements as announcement
      where announcement.tenant_id = p_tenant_id
        and announcement.scope = 'tenant'
        and announcement.status = 'published'
    ),
    (
      select count(*)::bigint
      from public.announcements as announcement
      where announcement.tenant_id = p_tenant_id
        and announcement.scope = 'tenant'
        and announcement.status = 'draft'
    ),
    (
      select count(*)::bigint
      from public.help_tickets as ticket
      where ticket.tenant_id = p_tenant_id
        and ticket.status in ('open', 'in_progress')
    ),
    (
      select count(*)::bigint
      from public.grade_review_requests as review
      where review.tenant_id = p_tenant_id
        and review.status = 'pending'
    ),
    (
      select count(*)::bigint
      from public.student_university_targets as target
      where target.tenant_id = p_tenant_id
        and target.document_review_status = 'pending_review'
    ),
    (
      select count(*)::bigint
      from public.student_visa_tasks as task
      where task.tenant_id = p_tenant_id
        and not task.is_archived
        and task.status in (
          'submitted', 'reviewing', 'revision_required', 'blocked'
        )
    ),
    (
      select count(*)::bigint
      from public.learning_record_notes as note
      where note.tenant_id = p_tenant_id
        and note.status = 'active'
        and note.record_type = 'attention'
    );
end;
$$;


ALTER FUNCTION public.get_tenant_admin_dashboard_summary(p_tenant_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION get_tenant_admin_dashboard_summary(p_tenant_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_tenant_admin_dashboard_summary(p_tenant_id uuid) IS '当前租户管理员的管理首页聚合计数；显式绑定 current_tenant_id，并继续应用调用者 RLS。';

--
-- Name: get_tenant_management_app_metrics(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_tenant_management_app_metrics(p_tenant_id uuid, p_app_ids uuid[]) RETURNS TABLE(app_id uuid, students bigint, work_items bigint, staff bigint)
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
begin
  if p_tenant_id is null
    or p_tenant_id is distinct from private.current_tenant_id()
    or not public.is_admin_account()
  then
    raise exception '无权读取该机构的应用汇总'
      using errcode = '42501';
  end if;

  return query
  with requested_apps as (
    select distinct requested_app_id as app_id
    from unnest(coalesce(p_app_ids, array[]::uuid[])) as requested_app_id
  )
  select
    requested.app_id,
    (
      select count(*)::bigint
      from public.student_app_enrollments as enrollment
      where enrollment.tenant_id = p_tenant_id
        and enrollment.app_id = requested.app_id
        and enrollment.status = 'active'
    ) as students,
    case
      when requested.app_id = '10000000-0000-4000-8000-000000000005'::uuid
      then (
        select count(*)::bigint
        from public.student_university_targets as target
        where target.tenant_id = p_tenant_id
      )
      else (
        select count(*)::bigint
        from public.learning_assignments as assignment
        where assignment.tenant_id = p_tenant_id
          and assignment.student_app_id = requested.app_id
      )
    end as work_items,
    (
      select count(*)::bigint
      from public.staff_app_assignments as staff_assignment
      where staff_assignment.tenant_id = p_tenant_id
        and staff_assignment.app_id = requested.app_id
        and staff_assignment.status = 'active'
    ) as staff
  from requested_apps as requested;
end;
$$;


ALTER FUNCTION public.get_tenant_management_app_metrics(p_tenant_id uuid, p_app_ids uuid[]) OWNER TO postgres;

--
-- Name: FUNCTION get_tenant_management_app_metrics(p_tenant_id uuid, p_app_ids uuid[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_tenant_management_app_metrics(p_tenant_id uuid, p_app_ids uuid[]) IS '当前租户管理员按可见应用读取聚合指标；所有租户业务表都显式按 tenant_id 限定。';

--
-- Name: get_tenant_student_learning_record_overview(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_tenant_student_learning_record_overview() RETURNS TABLE(student_id uuid, full_name text, email text, membership_tier text, completed_lesson_count bigint, active_lesson_count bigint, submission_count bigint, graded_submission_count bigint, conversation_practice_count bigint, grade_count bigint, note_count bigint, attention_count bigint, last_learning_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not public.current_user_can_view_learning_records() then
    raise exception '当前账号没有学习记录查看权限';
  end if;

  return query
  with active_students as (
    select
      membership.user_id as student_id,
      profile.full_name,
      profile.email,
      membership.membership_tier
    from public.tenant_memberships as membership
    join public.profiles as profile on profile.id = membership.user_id
    where membership.tenant_id = private.current_tenant_id()
      and membership.role = 'student'
      and membership.status = 'active'
      and coalesce(profile.status, 'active') = 'active'
      and (
        public.current_profile_role() <> 'teacher'
        or exists (
          select 1
          from public.tenant_student_assignments as assignment
          where assignment.tenant_id = membership.tenant_id
            and assignment.student_id = membership.user_id
            and assignment.teacher_id = (select auth.uid())
        )
      )
  ),
  lesson_statistics as (
    select
      progress.user_id as student_id,
      count(*) filter (where progress.status = 'completed')::bigint as completed_count,
      count(*) filter (where progress.status <> 'completed')::bigint as active_count,
      max(coalesce(progress.completed_at, progress.last_viewed_at, progress.updated_at)) as latest_at
    from public.lesson_progress as progress
    where progress.tenant_id = private.current_tenant_id()
    group by progress.user_id
  ),
  submission_statistics as (
    select
      submission.student_id,
      count(*)::bigint as submission_count,
      count(*) filter (where submission.status = 'graded')::bigint as graded_count,
      max(coalesce(submission.graded_at, submission.submitted_at)) as latest_at
    from public.learning_submissions as submission
    where submission.tenant_id = private.current_tenant_id()
    group by submission.student_id
  ),
  conversation_statistics as (
    select
      progress.user_id as student_id,
      coalesce(sum(progress.practice_count), 0)::bigint as practice_count,
      max(progress.last_practiced_at) as latest_at
    from public.conversation_practice_progress as progress
    where progress.tenant_id = private.current_tenant_id()
    group by progress.user_id
  ),
  grade_statistics as (
    select
      record.student_id,
      count(*)::bigint as grade_count,
      max(record.graded_at) as latest_at
    from public.grade_records as record
    where record.tenant_id = private.current_tenant_id()
    group by record.student_id
  ),
  note_statistics as (
    select
      note.student_id,
      count(*) filter (where note.status = 'active')::bigint as note_count,
      count(*) filter (
        where note.status = 'active' and note.record_type = 'attention'
      )::bigint as attention_count
    from public.learning_record_notes as note
    where note.tenant_id = private.current_tenant_id()
    group by note.student_id
  )
  select
    student.student_id,
    student.full_name,
    student.email,
    student.membership_tier,
    coalesce(lesson.completed_count, 0)::bigint,
    coalesce(lesson.active_count, 0)::bigint,
    coalesce(submission.submission_count, 0)::bigint,
    coalesce(submission.graded_count, 0)::bigint,
    coalesce(conversation.practice_count, 0)::bigint,
    coalesce(grade_record.grade_count, 0)::bigint,
    coalesce(note.note_count, 0)::bigint,
    coalesce(note.attention_count, 0)::bigint,
    greatest(
      lesson.latest_at,
      submission.latest_at,
      conversation.latest_at,
      grade_record.latest_at
    )
  from active_students as student
  left join lesson_statistics as lesson on lesson.student_id = student.student_id
  left join submission_statistics as submission on submission.student_id = student.student_id
  left join conversation_statistics as conversation on conversation.student_id = student.student_id
  left join grade_statistics as grade_record on grade_record.student_id = student.student_id
  left join note_statistics as note on note.student_id = student.student_id
  order by coalesce(student.full_name, student.email, student.student_id::text);
end;
$$;


ALTER FUNCTION public.get_tenant_student_learning_record_overview() OWNER TO postgres;

--
-- Name: FUNCTION get_tenant_student_learning_record_overview(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_tenant_student_learning_record_overview() IS '机构学习记录管理表：每个有效学生账号自动形成一行，并汇总真实学习活动与辅导备注。';

--
-- Name: get_tenant_student_learning_record_overview_by_app(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_tenant_student_learning_record_overview_by_app(p_student_app_id uuid) RETURNS TABLE(student_id uuid, full_name text, email text, membership_tier text, completed_lesson_count bigint, active_lesson_count bigint, submission_count bigint, graded_submission_count bigint, conversation_practice_count bigint, grade_count bigint, note_count bigint, attention_count bigint, last_learning_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not private.current_staff_has_app_capability(
    private.current_tenant_id(), p_student_app_id, 'view_analytics'
  ) then
    raise exception '当前账号没有该应用的数据权限';
  end if;

  return query
  with active_students as (
    select
      enrollment.student_id,
      profile.full_name,
      profile.email,
      membership.membership_tier
    from public.student_app_enrollments as enrollment
    join public.tenant_memberships as membership
      on membership.tenant_id = enrollment.tenant_id
     and membership.user_id = enrollment.student_id
    join public.profiles as profile on profile.id = enrollment.student_id
    where enrollment.tenant_id = private.current_tenant_id()
      and enrollment.app_id = p_student_app_id
      and enrollment.status = 'active'
      and enrollment.starts_at <= now()
      and (enrollment.ends_at is null or enrollment.ends_at > now())
      and membership.role = 'student'
      and membership.status = 'active'
      and coalesce(profile.status, 'active') = 'active'
      and (
        public.current_profile_role() <> 'teacher'
        or private.current_teacher_has_student_app_access(
          enrollment.tenant_id, enrollment.student_id, p_student_app_id
        )
      )
  ),
  lesson_statistics as (
    select
      progress.user_id as student_id,
      count(*) filter (where progress.status = 'completed')::bigint as completed_count,
      count(*) filter (where progress.status <> 'completed')::bigint as active_count,
      max(coalesce(progress.completed_at, progress.last_viewed_at, progress.updated_at)) as latest_at
    from public.lesson_progress as progress
    join public.courses as course on course.id = progress.course_id
    where progress.tenant_id = private.current_tenant_id()
      and course.student_app_id = p_student_app_id
    group by progress.user_id
  ),
  submission_statistics as (
    select
      submission.student_id,
      count(*)::bigint as submission_count,
      count(*) filter (where submission.status = 'graded')::bigint as graded_count,
      max(coalesce(submission.graded_at, submission.submitted_at)) as latest_at
    from public.learning_submissions as submission
    join public.learning_assignments as assignment
      on assignment.id = submission.assignment_id
    where submission.tenant_id = private.current_tenant_id()
      and assignment.student_app_id = p_student_app_id
    group by submission.student_id
  ),
  conversation_statistics as (
    select
      progress.user_id as student_id,
      coalesce(sum(progress.practice_count), 0)::bigint as practice_count,
      max(progress.last_practiced_at) as latest_at
    from public.conversation_practice_progress as progress
    join public.conversation_practice_scenarios as scenario
      on scenario.id = progress.scenario_id
    where progress.tenant_id = private.current_tenant_id()
      and scenario.student_app_id = p_student_app_id
    group by progress.user_id
  ),
  grade_statistics as (
    select
      record.student_id,
      count(*)::bigint as grade_count,
      max(record.graded_at) as latest_at
    from public.grade_records as record
    join public.grade_items as item on item.id = record.item_id
    left join public.courses as course on course.id = item.course_id
    left join public.learning_assignments as assignment
      on assignment.id = item.source_assignment_id
    where record.tenant_id = private.current_tenant_id()
      and coalesce(course.student_app_id, assignment.student_app_id) = p_student_app_id
    group by record.student_id
  ),
  note_statistics as (
    select
      note.student_id,
      count(*) filter (where note.status = 'active')::bigint as note_count,
      count(*) filter (
        where note.status = 'active' and note.record_type = 'attention'
      )::bigint as attention_count
    from public.learning_record_notes as note
    where note.tenant_id = private.current_tenant_id()
      and note.student_app_id = p_student_app_id
    group by note.student_id
  )
  select
    student.student_id,
    student.full_name,
    student.email,
    student.membership_tier,
    coalesce(lesson.completed_count, 0)::bigint,
    coalesce(lesson.active_count, 0)::bigint,
    coalesce(submission.submission_count, 0)::bigint,
    coalesce(submission.graded_count, 0)::bigint,
    coalesce(conversation.practice_count, 0)::bigint,
    coalesce(grade_record.grade_count, 0)::bigint,
    coalesce(note.note_count, 0)::bigint,
    coalesce(note.attention_count, 0)::bigint,
    greatest(
      lesson.latest_at,
      submission.latest_at,
      conversation.latest_at,
      grade_record.latest_at
    )
  from active_students as student
  left join lesson_statistics as lesson on lesson.student_id = student.student_id
  left join submission_statistics as submission on submission.student_id = student.student_id
  left join conversation_statistics as conversation on conversation.student_id = student.student_id
  left join grade_statistics as grade_record on grade_record.student_id = student.student_id
  left join note_statistics as note on note.student_id = student.student_id
  order by coalesce(student.full_name, student.email, student.student_id::text);
end;
$$;


ALTER FUNCTION public.get_tenant_student_learning_record_overview_by_app(p_student_app_id uuid) OWNER TO postgres;

--
-- Name: grade_learning_submission(uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.grade_learning_submission(p_submission_id uuid, p_decision text, p_overall_feedback text, p_scores jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_submission public.learning_submissions%rowtype;
  v_item jsonb;
  v_answer_id uuid;
  v_points numeric(8,2);
  v_feedback text;
  v_rubric_scores jsonb;
  v_max_points numeric(8,2);
  v_total numeric(8,2) := 0;
  v_expected integer;
  v_received integer;
begin
  select submission.* into v_submission
  from public.learning_submissions as submission
  join public.learning_assignments as assignment
    on assignment.tenant_id = submission.tenant_id
   and assignment.id = submission.assignment_id
  where submission.id = p_submission_id
    and submission.tenant_id = private.current_tenant_id()
    and private.current_staff_has_app_capability(
      assignment.tenant_id, assignment.student_app_id, 'manage_assessments'
    )
    and (
      public.current_profile_role() <> 'teacher'
      or private.current_teacher_has_student_app_access(
        assignment.tenant_id, submission.student_id, assignment.student_app_id
      )
    )
  for update of submission;

  if v_submission.id is null then
    raise exception '提交记录不存在或当前账号没有该应用的批改权限';
  end if;
  if v_submission.submission_state = 'grade_released' then
    raise exception '成绩已经发布，不能再次修改批改结果';
  end if;
  if p_decision not in ('graded', 'revision_required') then
    raise exception '批改结果不正确';
  end if;
  p_overall_feedback := btrim(coalesce(p_overall_feedback, ''));
  if char_length(p_overall_feedback) > 3000 then
    raise exception '总体评语不能超过 3000 个字';
  end if;
  if p_decision = 'revision_required' and char_length(p_overall_feedback) < 2 then
    raise exception '退回重做时必须填写明确原因';
  end if;
  if p_scores is null or jsonb_typeof(p_scores) <> 'array' then
    raise exception '评分数据格式不正确';
  end if;

  select count(*) into v_expected
  from public.learning_submission_answers
  where tenant_id = v_submission.tenant_id and submission_id = p_submission_id;
  select count(distinct value->>'answerId') into v_received
  from jsonb_array_elements(p_scores) as value;
  if v_expected = 0 or v_received <> v_expected
    or jsonb_array_length(p_scores) <> v_expected then
    raise exception '请填写全部题目的评分';
  end if;

  for v_item in select value from jsonb_array_elements(p_scores)
  loop
    begin
      v_answer_id := (v_item->>'answerId')::uuid;
      v_points := (v_item->>'points')::numeric;
    exception when others then
      raise exception '评分中包含无效数据';
    end;
    v_feedback := nullif(btrim(coalesce(v_item->>'feedback', '')), '');
    v_rubric_scores := case
      when v_item ? 'rubricScores' and jsonb_typeof(v_item->'rubricScores') = 'object'
        then v_item->'rubricScores'
      else null
    end;
    if v_feedback is not null and char_length(v_feedback) > 2000 then
      raise exception '单题评语不能超过 2000 个字';
    end if;

    select question.points into v_max_points
    from public.learning_submission_answers as answer
    join public.learning_assignment_questions as question
      on question.tenant_id = answer.tenant_id and question.id = answer.question_id
    where answer.id = v_answer_id
      and answer.tenant_id = v_submission.tenant_id
      and answer.submission_id = p_submission_id;
    if not found then raise exception '评分中包含不属于本次提交的答案'; end if;
    if v_points < 0 or v_points > v_max_points then
      raise exception '单题得分必须在 0 分和题目满分之间';
    end if;

    update public.learning_submission_answers
    set awarded_points = v_points,
        rubric_scores = v_rubric_scores,
        grader_feedback = v_feedback,
        updated_at = now()
    where id = v_answer_id and tenant_id = v_submission.tenant_id;
    v_total := v_total + v_points;
  end loop;

  update public.learning_submissions
  set status = case when p_decision = 'revision_required'
        then 'revision_required' else 'submitted' end,
      score = null,
      computed_score = case when p_decision = 'graded' then v_total else null end,
      overall_feedback = nullif(p_overall_feedback, ''),
      submission_state = case when p_decision = 'revision_required'
        then 'revision_required' else 'grading_completed' end,
      grading_completed_at = case when p_decision = 'graded' then now() else null end,
      grade_release_confirmed_at = null,
      grade_release_confirmed_by = null,
      grade_released_at = null,
      graded_at = now(),
      graded_by = auth.uid(),
      updated_at = now()
  where id = p_submission_id and tenant_id = v_submission.tenant_id;
end;
$$;


ALTER FUNCTION public.grade_learning_submission(p_submission_id uuid, p_decision text, p_overall_feedback text, p_scores jsonb) OWNER TO postgres;

--
-- Name: FUNCTION grade_learning_submission(p_submission_id uuid, p_decision text, p_overall_feedback text, p_scores jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.grade_learning_submission(p_submission_id uuid, p_decision text, p_overall_feedback text, p_scores jsonb) IS '原子化保存逐题评分与总体批改结果';

--
-- Name: grant_question_bank_admin(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.grant_question_bank_admin(p_admin_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not private.is_platform_owner() then
    raise exception '只有平台负责人可以授权题库管理员';
  end if;

  if not exists (
    select 1
    from public.profiles as profile
    where profile.id = p_admin_id
      and profile.global_role = 'platform_deputy'
      and profile.role = 'tenant_operator'
      and coalesce(profile.status, 'active') = 'active'
  ) then
    raise exception '只能授权正常状态的平台副负责人';
  end if;

  insert into public.question_bank_admin_assignments (
    admin_id,
    granted_by,
    granted_at,
    revoked_at,
    revoked_by
  )
  values (
    p_admin_id,
    auth.uid(),
    now(),
    null,
    null
  )
  on conflict (admin_id) do update set
    granted_by = excluded.granted_by,
    granted_at = excluded.granted_at,
    revoked_at = null,
    revoked_by = null;
end;
$$;


ALTER FUNCTION public.grant_question_bank_admin(p_admin_id uuid) OWNER TO postgres;

--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  insert into public.profiles (id, full_name, role)
  values (
    new.id,
    coalesce(new.raw_user_meta_data->>'name', new.raw_user_meta_data->>'full_name'),
    'student'
  )
  on conflict (id) do nothing;

  return new;
end;
$$;


ALTER FUNCTION public.handle_new_user() OWNER TO postgres;

--
-- Name: import_assignment_grades(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.import_assignment_grades(p_assignment_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_assignment public.learning_assignments%rowtype; v_item_id uuid;
begin
  if not public.current_user_can_manage_grade_center() then raise exception '当前账号没有成绩管理权限'; end if;
  select * into v_assignment from public.learning_assignments where id = p_assignment_id;
  if v_assignment.id is null then raise exception '作业或考试不存在'; end if;
  insert into public.grade_items (title, description, item_type, term, total_points, source_assignment_id, course_id, status, created_by, updated_by)
  values (v_assignment.title, v_assignment.description, case when v_assignment.assignment_type in ('homework','quiz','exam') then v_assignment.assignment_type else 'other' end, '', v_assignment.total_points, v_assignment.id, v_assignment.course_id, 'draft', auth.uid(), auth.uid())
  on conflict (source_assignment_id) do update set title = excluded.title, description = excluded.description, total_points = excluded.total_points, course_id = excluded.course_id, updated_by = auth.uid(), updated_at = now()
  returning id into v_item_id;
  insert into public.grade_records (item_id, student_id, record_status, score, feedback, graded_by, graded_at)
  select v_item_id, latest.student_id, 'graded', latest.score, coalesce(latest.overall_feedback, ''), auth.uid(), coalesce(latest.graded_at, now())
  from (
    select distinct on (submission.student_id) submission.student_id, submission.score, submission.overall_feedback, submission.graded_at
    from public.learning_submissions as submission
    where submission.assignment_id = p_assignment_id and submission.status = 'graded' and submission.score is not null
    order by submission.student_id, submission.attempt_number desc
  ) as latest
  on conflict (item_id, student_id) do update set record_status = 'graded', score = excluded.score, feedback = excluded.feedback, graded_by = auth.uid(), graded_at = excluded.graded_at, updated_at = now();
  return v_item_id;
end;
$$;


ALTER FUNCTION public.import_assignment_grades(p_assignment_id uuid) OWNER TO postgres;

--
-- Name: initialize_documents_when_target_prepares(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.initialize_documents_when_target_prepares() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  target_stage text;
begin
  target_stage := coalesce(new.admission_track, 'language');

  if tg_op = 'UPDATE'
     and old.admission_track is distinct from new.admission_track
     and new.status <> 'researching' then
    delete from public.student_application_documents as document
    using public.university_application_document_requirements as requirement
    where document.target_id = new.id
      and document.requirement_id = requirement.id
      and requirement.admission_stage <> target_stage;
  end if;

  if new.status <> 'researching' then
    perform public.initialize_target_application_documents(new.id);
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.initialize_documents_when_target_prepares() OWNER TO postgres;

--
-- Name: initialize_student_visa_requirements(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.initialize_student_visa_requirements(requested_user_id uuid, requested_target_id uuid, requested_visa_type text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  source_university_id uuid;
  source_tenant_id uuid;
begin
  select target.university_id, target.tenant_id
  into source_university_id, source_tenant_id
  from public.student_university_targets as target
  where target.id = requested_target_id
    and target.user_id = requested_user_id;

  if source_university_id is null then
    return;
  end if;

  if auth.uid() is not null
     and private.current_tenant_id() is not null
     and source_tenant_id <> private.current_tenant_id() then
    raise exception '无权初始化其他租户的签证任务';
  end if;

  insert into public.student_visa_tasks (
    tenant_id,
    user_id,
    task_key,
    requirement_id,
    title,
    description,
    stage,
    sort_order,
    is_archived
  )
  select
    source_tenant_id,
    requested_user_id,
    requirement.requirement_key,
    requirement.id,
    requirement.title,
    requirement.description,
    requirement.stage,
    requirement.sort_order,
    false
  from public.university_visa_application_requirements as requirement
  where requirement.university_id = source_university_id
    and requirement.visa_type = requested_visa_type
    and requirement.is_active = true
  on conflict (tenant_id, user_id, task_key)
  do update set
    requirement_id = excluded.requirement_id,
    title = excluded.title,
    description = excluded.description,
    stage = excluded.stage,
    sort_order = excluded.sort_order,
    is_archived = false;
end;
$$;


ALTER FUNCTION public.initialize_student_visa_requirements(requested_user_id uuid, requested_target_id uuid, requested_visa_type text) OWNER TO postgres;

--
-- Name: initialize_student_visa_workspace(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.initialize_student_visa_workspace() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  created_case_id uuid;
  resolved_visa_type text;
  actual_visa_type text;
  resolved_target_id uuid;
  resolved_application_channel text;
begin
  if auth.uid() is null or not public.student_feature_allowed('visa_tasks') then
    raise exception '当前账号没有签证准备操作权限';
  end if;

  select
    target.id,
    case
      when target.admission_track = 'language' or target.degree_level = 'language' then 'd4_language'
      when target.admission_track in ('bachelor_fresh', 'bachelor_transfer') or target.degree_level = 'bachelor' then 'd2_bachelor'
      when target.admission_track = 'master' or target.degree_level = 'master' then 'd2_master'
      when target.admission_track = 'doctor' or target.degree_level = 'doctor' then 'd2_doctor'
      else 'd4_language'
    end,
    target.visa_application_channel
  into resolved_target_id, resolved_visa_type, resolved_application_channel
  from public.student_university_targets as target
  where target.user_id = auth.uid()
    and target.application_stage >= 9
    and target.visa_application_channel is not null
  order by target.application_stage desc, target.priority desc, target.updated_at desc
  limit 1;

  if not found then
    raise exception '管理员确认签证办理方式并点亮第九步后才会建立签证准备路线';
  end if;

  created_case_id := public.initialize_student_visa_workspace_for_user(auth.uid(), resolved_visa_type);

  update public.student_visa_cases
  set
    source_target_id = resolved_target_id,
    application_channel = resolved_application_channel
  where id = created_case_id
    and (
      source_target_id is distinct from resolved_target_id
      or application_channel is distinct from resolved_application_channel
    );

  select visa_type into actual_visa_type
  from public.student_visa_cases
  where id = created_case_id;

  perform public.initialize_student_visa_requirements(
    auth.uid(),
    resolved_target_id,
    actual_visa_type
  );

  return created_case_id;
end;
$$;


ALTER FUNCTION public.initialize_student_visa_workspace() OWNER TO postgres;

--
-- Name: FUNCTION initialize_student_visa_workspace(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.initialize_student_visa_workspace() IS '阶段 9 之后为当前学生补建签证档案；正常情况下由申请阶段触发器自动完成';

--
-- Name: initialize_student_visa_workspace_for_user(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.initialize_student_visa_workspace_for_user(requested_user_id uuid, requested_visa_type text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  created_case_id uuid;
  resolved_visa_type text;
  resolved_tenant_id uuid;
begin
  if requested_user_id is null then
    raise exception '缺少学生账号';
  end if;

  resolved_tenant_id := coalesce(private.current_tenant_id(), private.default_tenant_of(requested_user_id));
  if resolved_tenant_id is null then
    raise exception '缺少租户上下文';
  end if;

  resolved_visa_type := case
    when requested_visa_type in ('d4_language', 'd2_bachelor', 'd2_master', 'd2_doctor')
      then requested_visa_type
    else 'd4_language'
  end;

  insert into public.student_visa_cases (tenant_id, user_id, visa_type)
  values (resolved_tenant_id, requested_user_id, resolved_visa_type)
  on conflict (tenant_id, user_id) do nothing;

  select id into created_case_id
  from public.student_visa_cases
  where user_id = requested_user_id
    and tenant_id = resolved_tenant_id;

  return created_case_id;
end;
$$;


ALTER FUNCTION public.initialize_student_visa_workspace_for_user(requested_user_id uuid, requested_visa_type text) OWNER TO postgres;

--
-- Name: FUNCTION initialize_student_visa_workspace_for_user(requested_user_id uuid, requested_visa_type text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.initialize_student_visa_workspace_for_user(requested_user_id uuid, requested_visa_type text) IS '内部使用：为指定学生幂等建立签证档案，签证任务由来源大学模板生成';

--
-- Name: initialize_target_application_documents(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.initialize_target_application_documents(requested_target_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  target_record public.student_university_targets%rowtype;
  target_stage text;
begin
  select * into target_record
  from public.student_university_targets
  where id = requested_target_id;

  if not found
     or target_record.status = 'researching'
     or target_record.university_id is null then
    return;
  end if;

  -- 由登录用户触发时，目标必须属于当前租户；触发器链内（如管理员更新学生行）
  -- 行本身已通过 RLS 校验，这里再挡一次直接 RPC 越权。
  if auth.uid() is not null
     and private.current_tenant_id() is not null
     and target_record.tenant_id <> private.current_tenant_id() then
    raise exception '无权初始化其他租户的申请材料';
  end if;

  target_stage := coalesce(target_record.admission_track, 'language');

  insert into public.student_application_documents (
    tenant_id,
    user_id,
    target_id,
    document_key,
    requirement_id,
    title,
    category,
    notes,
    status,
    sort_order
  )
  select
    target_record.tenant_id,
    target_record.user_id,
    target_record.id,
    requirement.requirement_key,
    requirement.id,
    requirement.title,
    requirement.category,
    requirement.description,
    'preparing',
    requirement.sort_order
  from public.university_application_document_requirements as requirement
  where requirement.university_id = target_record.university_id
    and requirement.admission_stage = target_stage
    and requirement.is_active = true
  on conflict (target_id, document_key) where target_id is not null
  do update set
    requirement_id = excluded.requirement_id,
    title = excluded.title,
    category = excluded.category,
    notes = excluded.notes,
    sort_order = excluded.sort_order;
end;
$$;


ALTER FUNCTION public.initialize_target_application_documents(requested_target_id uuid) OWNER TO postgres;

--
-- Name: initialize_visa_workspace_from_application_stage(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.initialize_visa_workspace_from_application_stage() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  created_case_id uuid;
  resolved_visa_type text;
  actual_visa_type text;
begin
  if new.visa_application_channel is null then
    raise exception '请先确认签证办理方式，再点亮第九步';
  end if;

  resolved_visa_type := case
    when new.admission_track = 'language' or new.degree_level = 'language' then 'd4_language'
    when new.admission_track in ('bachelor_fresh', 'bachelor_transfer') or new.degree_level = 'bachelor' then 'd2_bachelor'
    when new.admission_track = 'master' or new.degree_level = 'master' then 'd2_master'
    when new.admission_track = 'doctor' or new.degree_level = 'doctor' then 'd2_doctor'
    else 'd4_language'
  end;

  perform set_config('app.system_managed_visa_sync', 'on', true);

  created_case_id := public.initialize_student_visa_workspace_for_user(new.user_id, resolved_visa_type);

  update public.student_visa_cases
  set
    source_target_id = new.id,
    application_channel = new.visa_application_channel
  where id = created_case_id
    and (
      source_target_id is distinct from new.id
      or application_channel is distinct from new.visa_application_channel
    );

  select visa_type into actual_visa_type
  from public.student_visa_cases
  where id = created_case_id;

  perform public.initialize_student_visa_requirements(
    new.user_id,
    new.id,
    actual_visa_type
  );

  return new;
end;
$$;


ALTER FUNCTION public.initialize_visa_workspace_from_application_stage() OWNER TO postgres;

--
-- Name: FUNCTION initialize_visa_workspace_from_application_stage(); Type: COMMENT; Schema: public; Owner: postgres
