--
-- Name: is_valid_university_deadline(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.is_valid_university_deadline(p_value text) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $_$
begin
  if p_value is null then
    return true;
  end if;

  if p_value !~ '^\d{4}-\d{2}-\d{2}$' then
    return false;
  end if;

  return to_char(p_value::date, 'YYYY-MM-DD') = p_value;
exception
  when others then
    return false;
end;
$_$;


