--
-- Name: course_completion_certificates; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.course_completion_certificates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    student_id uuid NOT NULL,
    student_app_id uuid NOT NULL,
    course_id uuid NOT NULL,
    evaluation_id uuid NOT NULL,
    certificate_number text NOT NULL,
    status text DEFAULT 'issued'::text NOT NULL,
    student_name_snapshot text NOT NULL,
    course_title_snapshot text NOT NULL,
    policy_snapshot jsonb NOT NULL,
    evidence_snapshot jsonb NOT NULL,
    overall_score_snapshot numeric(7,3),
    issued_by uuid NOT NULL,
    issued_at timestamp with time zone NOT NULL,
    revoked_by uuid,
    revoked_at timestamp with time zone,
    revocation_reason text,
    reissued_from_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT course_completion_certificates_course_title_check CHECK (((char_length(btrim(course_title_snapshot)) >= 1) AND (char_length(btrim(course_title_snapshot)) <= 200))),
    CONSTRAINT course_completion_certificates_evidence_snapshot_check CHECK ((jsonb_typeof(evidence_snapshot) = 'object'::text)),
    CONSTRAINT course_completion_certificates_number_format_check CHECK ((certificate_number ~ '^CERT-[0-9]{4}-[0-9A-F]{8}-[0-9A-F]{8}-[0-9A-F]{8}-[0-9A-F]{8}$'::text)),
    CONSTRAINT course_completion_certificates_policy_snapshot_check CHECK ((jsonb_typeof(policy_snapshot) = 'object'::text)),
    CONSTRAINT course_completion_certificates_reissue_self_check CHECK (((reissued_from_id IS NULL) OR (reissued_from_id <> id))),
    CONSTRAINT course_completion_certificates_revocation_check CHECK ((((status = 'issued'::text) AND (revoked_by IS NULL) AND (revoked_at IS NULL) AND (revocation_reason IS NULL)) OR ((status = ANY (ARRAY['revoked'::text, 'reissued'::text])) AND (revoked_by IS NOT NULL) AND (revoked_at IS NOT NULL) AND (revocation_reason IS NOT NULL) AND ((char_length(btrim(revocation_reason)) >= 2) AND (char_length(btrim(revocation_reason)) <= 1000))))),
    CONSTRAINT course_completion_certificates_score_check CHECK (((overall_score_snapshot IS NULL) OR ((overall_score_snapshot >= (0)::numeric) AND (overall_score_snapshot <= (100)::numeric)))),
    CONSTRAINT course_completion_certificates_status_check CHECK ((status = ANY (ARRAY['issued'::text, 'revoked'::text, 'reissued'::text]))),
    CONSTRAINT course_completion_certificates_student_name_check CHECK (((char_length(btrim(student_name_snapshot)) >= 1) AND (char_length(btrim(student_name_snapshot)) <= 200)))
);

ALTER TABLE ONLY public.course_completion_certificates FORCE ROW LEVEL SECURITY;


ALTER TABLE public.course_completion_certificates OWNER TO postgres;

--
-- Name: TABLE course_completion_certificates; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.course_completion_certificates IS '结课证书本体；姓名、课程、政策、证据和综合成绩均固定为颁发时快照。所有业务写入必须经过证书 RPC。';

--
-- Name: COLUMN course_completion_certificates.certificate_number; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.course_completion_certificates.certificate_number IS '服务端以 pgcrypto 生成的全局唯一公开编号，含 128 位加密安全随机熵。';

--
-- Name: COLUMN course_completion_certificates.status; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.course_completion_certificates.status IS 'issued=有效，revoked=已撤销，reissued=该旧证书已被新证书替代。';

--
-- Name: COLUMN course_completion_certificates.reissued_from_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.course_completion_certificates.reissued_from_id IS '重新颁发时指向被替代的旧证书；旧证书保留并改为 reissued。';

--
-- Name: issue_course_completion_certificate(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.issue_course_completion_certificate(p_evaluation_id uuid) RETURNS public.course_completion_certificates
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_actor_name text;
  v_evaluation public.student_course_completion_evaluations;
  v_existing public.course_completion_certificates;
  v_certificate public.course_completion_certificates;
  v_student_name text;
  v_course_title text;
  v_now timestamptz := clock_timestamp();
begin
  if v_actor_id is null then
    raise exception '必须登录后颁发证书';
  end if;

  select evaluation.* into v_evaluation
  from public.student_course_completion_evaluations as evaluation
  where evaluation.id = p_evaluation_id
  for update;

  if not found then
    raise exception '结课资格记录不存在';
  end if;
  if not private.current_actor_can_issue_tenant_certificate(v_evaluation.tenant_id) then
    raise exception '只有对应机构负责人可以颁发本机构证书';
  end if;
  if v_evaluation.status <> 'eligible' or not v_evaluation.eligible then
    raise exception '只有 eligible 状态的结课资格记录可以颁发证书';
  end if;

  select certificate.* into v_existing
  from public.course_completion_certificates as certificate
  where certificate.evaluation_id = p_evaluation_id
    and certificate.status = 'issued';

  if found then
    return v_existing;
  end if;

  select certificate.* into v_existing
  from public.course_completion_certificates as certificate
  where certificate.evaluation_id = p_evaluation_id
    and certificate.reissued_from_id is null;

  if found then
    raise exception '该资格记录的原证书已撤销或被替代，请使用重新颁发 RPC';
  end if;

  select nullif(btrim(profile.full_name), '') into v_student_name
  from public.profiles as profile
  where profile.id = v_evaluation.student_id;
  if v_student_name is null then
    raise exception '颁发证书前必须填写学生姓名';
  end if;

  select nullif(btrim(course.title), '') into v_course_title
  from public.courses as course
  where course.id = v_evaluation.course_id
    and course.student_app_id = v_evaluation.student_app_id;
  if v_course_title is null then
    raise exception '资格记录对应的课程不存在或课程名称为空';
  end if;

  select coalesce(nullif(btrim(profile.full_name), ''), '机构负责人')
  into v_actor_name
  from public.profiles as profile
  where profile.id = v_actor_id;

  insert into public.course_completion_certificates (
    tenant_id, student_id, student_app_id, course_id, evaluation_id,
    status, student_name_snapshot, course_title_snapshot,
    policy_snapshot, evidence_snapshot, overall_score_snapshot,
    issued_by, issued_at, created_at
  ) values (
    v_evaluation.tenant_id,
    v_evaluation.student_id,
    v_evaluation.student_app_id,
    v_evaluation.course_id,
    v_evaluation.id,
    'issued',
    v_student_name,
    v_course_title,
    jsonb_build_object(
      'policyId', v_evaluation.policy_id,
      'policyVersion', v_evaluation.policy_version,
      'evaluationVersion', v_evaluation.evaluation_version,
      'evaluatedAt', v_evaluation.evaluated_at,
      'requirements', v_evaluation.requirements_snapshot
    ),
    v_evaluation.evidence_snapshot,
    v_evaluation.overall_score,
    v_actor_id,
    v_now,
    v_now
  ) returning * into v_certificate;

  insert into public.course_completion_certificate_events (
    tenant_id, certificate_id, event_type, actor_id,
    actor_name_snapshot, metadata, created_at
  ) values (
    v_certificate.tenant_id,
    v_certificate.id,
    'issued',
    v_actor_id,
    v_actor_name,
    jsonb_build_object('evaluationId', v_evaluation.id),
    v_now
  );

  return v_certificate;
end;
$$;


ALTER FUNCTION public.issue_course_completion_certificate(p_evaluation_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION issue_course_completion_certificate(p_evaluation_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.issue_course_completion_certificate(p_evaluation_id uuid) IS '对应机构负责人为 eligible 资格原子颁发证书；并发重复调用返回同一张有效证书。';

--
-- Name: list_grade_center_students(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.list_grade_center_students() RETURNS TABLE(id uuid, full_name text, email text, membership_tier text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.current_user_can_manage_grade_center() then raise exception '当前账号没有成绩管理权限'; end if;
  return query select profile.id, profile.full_name, profile.email, membership.membership_tier
  from public.tenant_memberships as membership
  join public.profiles as profile on profile.id = membership.user_id
  where membership.tenant_id = private.current_tenant_id()
    and membership.role = 'student'
    and membership.status = 'active'
    and coalesce(profile.status, 'active') = 'active'
  order by coalesce(profile.full_name, profile.email, profile.id::text);
end;
$$;


ALTER FUNCTION public.list_grade_center_students() OWNER TO postgres;

--
-- Name: list_guide_agent_conversations(uuid, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.list_guide_agent_conversations(p_agent_profile_id uuid, p_query text, p_limit integer, p_offset integer, p_audit_scope text) RETURNS TABLE(id uuid, tenant_id uuid, student_id uuid, status text, created_at timestamp with time zone, updated_at timestamp with time zone, student_name text, tenant_name text, total_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_query text := nullif(btrim(p_query), '');
begin
  if not private.is_platform_owner() then
    raise insufficient_privilege using message = 'platform owner required';
  end if;
  if p_limit not between 1 and 50 or p_offset < 0 then raise exception 'invalid pagination'; end if;
  if v_query is not null and char_length(v_query) > 100 then raise exception 'query too long'; end if;
  if p_audit_scope not in ('overview', 'conversations') then raise exception 'invalid audit scope'; end if;

  insert into public.guide_agent_operation_logs (actor_id, action, target_type, target_id, summary, details)
  values (
    v_actor_id,
    '查看学生会话',
    'conversation_collection',
    p_agent_profile_id,
    case when p_audit_scope = 'overview' then '查看 Agent 最近会话摘要' else '查看 Agent 学生会话记录' end,
    jsonb_build_object('scope', p_audit_scope, 'page', floor(p_offset::numeric / p_limit) + 1, 'pageSize', p_limit, 'hasQuery', v_query is not null)
  );

  return query
  select
    session.id,
    session.tenant_id,
    session.student_id,
    session.status,
    session.created_at,
    session.updated_at,
    coalesce(nullif(btrim(profile.full_name), ''), nullif(btrim(profile.email), ''), '未填写姓名') as student_name,
    coalesce(nullif(btrim(tenant.name), ''), '未知机构') as tenant_name,
    count(*) over() as total_count
  from public.guide_agent_sessions as session
  left join public.profiles as profile on profile.id = session.student_id
  left join public.tenants as tenant on tenant.id = session.tenant_id
  where session.agent_profile_id = p_agent_profile_id
    and (
      v_query is null
      or lower(coalesce(profile.full_name, '')) like '%' || lower(v_query) || '%'
      or lower(coalesce(profile.email, '')) like '%' || lower(v_query) || '%'
      or lower(coalesce(tenant.name, '')) like '%' || lower(v_query) || '%'
      or exists (
        select 1
        from public.guide_agent_messages as message
        where message.session_id = session.id
          and lower(message.content) like '%' || lower(v_query) || '%'
      )
    )
  order by session.updated_at desc, session.id desc
  limit p_limit
  offset p_offset;
end;
$$;


ALTER FUNCTION public.list_guide_agent_conversations(p_agent_profile_id uuid, p_query text, p_limit integer, p_offset integer, p_audit_scope text) OWNER TO postgres;

--
-- Name: list_guide_agent_deleted_navigation_rules(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.list_guide_agent_deleted_navigation_rules(p_agent_profile_id uuid) RETURNS TABLE(rule_id uuid, name text, last_version_number integer, deleted_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not private.is_platform_owner() then
    raise insufficient_privilege using message = 'platform owner required';
  end if;

  return query
  select distinct on (version.rule_id)
    version.rule_id,
    coalesce(nullif(btrim(version.snapshot ->> 'name'), ''), '未命名规则') as name,
    version.version_number as last_version_number,
    version.created_at as deleted_at
  from public.guide_agent_navigation_rule_versions as version
  where version.agent_profile_id = p_agent_profile_id
    and not exists (
      select 1 from public.guide_agent_navigation_rules as rule
      where rule.id = version.rule_id
    )
  order by version.rule_id, version.version_number desc;
end;
$$;


ALTER FUNCTION public.list_guide_agent_deleted_navigation_rules(p_agent_profile_id uuid) OWNER TO postgres;

