--
-- Name: list_learning_assignment_students(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.list_learning_assignment_students() RETURNS TABLE(id uuid, full_name text, email text, membership_tier text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.current_user_is_assignment_manager() then
    raise exception '当前账号没有教学管理权限';
  end if;
  return query select profile.id, profile.full_name, profile.email, membership.membership_tier
  from public.tenant_memberships as membership
  join public.profiles as profile on profile.id = membership.user_id
  where membership.tenant_id = private.current_tenant_id()
    and membership.role = 'student'
    and membership.status = 'active'
    and coalesce(profile.status, 'active') = 'active'
  order by coalesce(profile.full_name, profile.email, profile.id::text);
end;
$$;


ALTER FUNCTION public.list_learning_assignment_students() OWNER TO postgres;

--
-- Name: list_learning_assignment_students_by_app(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.list_learning_assignment_students_by_app(p_student_app_id uuid) RETURNS TABLE(id uuid, full_name text, email text, membership_tier text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not private.current_staff_has_app_capability(
    private.current_tenant_id(), p_student_app_id, 'manage_assessments'
  ) then
    raise exception '当前账号没有该应用的作业管理权限';
  end if;

  return query
  select profile.id, profile.full_name, profile.email, membership.membership_tier
  from public.student_app_enrollments as enrollment
  join public.tenant_memberships as membership
    on membership.tenant_id = enrollment.tenant_id
   and membership.user_id = enrollment.student_id
  join public.profiles as profile on profile.id = enrollment.student_id
  where enrollment.tenant_id = private.current_tenant_id()
    and enrollment.app_id = p_student_app_id
    and enrollment.status = 'active'
    and enrollment.starts_at <= now()
    and (enrollment.ends_at is null or enrollment.ends_at > now())
    and membership.role = 'student'
    and membership.status = 'active'
    and coalesce(profile.status, 'active') = 'active'
    and (
      public.current_profile_role() <> 'teacher'
      or private.current_teacher_has_student_app_access(
        enrollment.tenant_id, enrollment.student_id, p_student_app_id
      )
    )
  order by coalesce(profile.full_name, profile.email, profile.id::text);
end;
$$;


ALTER FUNCTION public.list_learning_assignment_students_by_app(p_student_app_id uuid) OWNER TO postgres;

