--
-- Name: list_teaching_script_source_review_status(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.list_teaching_script_source_review_status(p_app_id uuid) RETURNS TABLE(script_version_id uuid, review_status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.uid() is null or not coalesce(private.is_platform_owner(), false) then raise exception '只有平台负责人可以复核教学脚本'; end if;
  return query select v.id, case when r.script_version_id is null then 'unreviewed'
    when r.source_snapshot is distinct from private.teaching_script_source_snapshot(v.id)
      or r.script_token is distinct from private.teaching_script_review_token(v.id) then 'changed' else 'reviewed' end
  from public.learning_agent_script_versions v
  join public.learning_agent_lessons l on l.id = v.lesson_id
  join public.digital_textbook_modules m on m.id = l.module_id
  join public.digital_textbook_chapters c on c.id = m.chapter_id
  join public.digital_textbook_versions tv on tv.id = c.version_id
  join public.digital_textbooks t on t.id = tv.textbook_id
  left join public.teaching_script_source_reviews r on r.script_version_id = v.id
  where t.student_app_id = p_app_id and v.status in ('draft', 'published');
end;
$$;


ALTER FUNCTION public.list_teaching_script_source_review_status(p_app_id uuid) OWNER TO postgres;

--
-- Name: log_document_review_status_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.log_document_review_status_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.document_review_status is distinct from old.document_review_status then
    insert into public.document_review_events (
      tenant_id,
      target_id,
      actor_id,
      previous_status,
      new_status,
      note
    ) values (
      new.tenant_id,
      new.id,
      auth.uid(),
      old.document_review_status,
      new.document_review_status,
      new.document_review_note
    );
  end if;
  return new;
end;
$$;


ALTER FUNCTION public.log_document_review_status_change() OWNER TO postgres;

--
-- Name: log_student_visa_task_event(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.log_student_visa_task_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  event_name text;
begin
  if tg_op = 'INSERT' then
    event_name := 'created';
  elsif old.status is not distinct from new.status then
    return new;
  else
    event_name := case new.status
      when 'submitted' then 'submitted'
      when 'reviewing' then 'review_started'
      when 'approved' then 'approved'
      when 'revision_required' then 'revision_requested'
      else 'status_updated'
    end;
  end if;

  insert into public.student_visa_task_events (
    task_id, user_id, actor_id, event_type, from_status, to_status,
    submission_version, note
  ) values (
    new.id, new.user_id, auth.uid(), event_name,
    case when tg_op = 'INSERT' then null else old.status end,
    new.status, new.submission_version,
    case when new.status = 'revision_required' then new.admin_note else new.student_note end
  );
  return new;
end;
$$;


ALTER FUNCTION public.log_student_visa_task_event() OWNER TO postgres;

--
-- Name: mark_visible_announcements_read(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mark_visible_announcements_read(requested_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  viewer_tenant_id uuid;
  marked_count integer;
begin
  if auth.uid() is null or not public.is_active_account() then
    raise exception '请先登录正常账号';
  end if;

  viewer_tenant_id := private.current_tenant_id();

  insert into public.announcement_reads (announcement_id, user_id, tenant_id, read_at)
  select announcement.id, auth.uid(), viewer_tenant_id, now()
  from public.announcements as announcement
  where announcement.id = any(coalesce(requested_ids, array[]::uuid[]))
    and announcement.status = 'published'
    and (
      announcement.scope = 'platform'
      or (
        announcement.scope = 'tenant'
        and announcement.tenant_id = viewer_tenant_id
      )
    )
  on conflict (announcement_id, user_id)
  do update set read_at = excluded.read_at;

  get diagnostics marked_count = row_count;
  return marked_count;
end;
$$;


ALTER FUNCTION public.mark_visible_announcements_read(requested_ids uuid[]) OWNER TO postgres;

--
-- Name: migrate_chapter_test_question_reviews_to_review_items(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.migrate_chapter_test_question_reviews_to_review_items() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_review public.chapter_test_question_reviews%rowtype;
  v_count integer := 0;
begin
  if auth.role() is distinct from 'service_role'
    and current_user not in ('postgres', 'supabase_admin') then
    raise exception '只有数据库迁移或服务角色可以执行历史收藏迁移';
  end if;
  for v_review in
    select * from public.chapter_test_question_reviews order by created_at, id
  loop
    perform private.capture_legacy_chapter_review_item_row(v_review);
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;


ALTER FUNCTION public.migrate_chapter_test_question_reviews_to_review_items() OWNER TO postgres;

--
-- Name: FUNCTION migrate_chapter_test_question_reviews_to_review_items(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.migrate_chapter_test_question_reviews_to_review_items() IS '幂等映射 chapter_test_question_reviews 到 student_review_items。部署迁移已执行；需要补跑时使用 service_role 调用 RPC。';

--
-- Name: move_learning_agent_script_node(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.move_learning_agent_script_node(p_node_id uuid, p_direction text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'auth'
    AS $$
declare
  v_node public.learning_agent_script_nodes%rowtype;
  v_neighbor public.learning_agent_script_nodes%rowtype;
begin
  if auth.uid() is null or not private.is_platform_owner() then
    raise exception '只有平台负责人可以调整教学节点';
  end if;
  if p_direction not in ('up', 'down') then raise exception '节点移动方向不正确'; end if;

  select node.* into v_node
  from public.learning_agent_script_nodes node
  join public.learning_agent_script_versions version on version.id = node.script_version_id
  where node.id = p_node_id and version.status = 'draft'
  for update of node;
  if not found then raise exception '只有草稿节点可以调整顺序'; end if;

  if p_direction = 'up' then
    select * into v_neighbor
    from public.learning_agent_script_nodes
    where script_version_id = v_node.script_version_id and sort_order < v_node.sort_order
    order by sort_order desc limit 1 for update;
  else
    select * into v_neighbor
    from public.learning_agent_script_nodes
    where script_version_id = v_node.script_version_id and sort_order > v_node.sort_order
    order by sort_order asc limit 1 for update;
  end if;

  if v_neighbor.id is null then return false; end if;
  set constraints learning_agent_script_nodes_version_order_key deferred;
  update public.learning_agent_script_nodes set sort_order = v_neighbor.sort_order where id = v_node.id;
  update public.learning_agent_script_nodes set sort_order = v_node.sort_order where id = v_neighbor.id;

  insert into public.learning_agent_publish_logs (
    lesson_id, script_version_id, action, actor_id, details
  )
  select version.lesson_id, v_node.script_version_id, 'reorder_node', auth.uid(),
    jsonb_build_object('nodeId', v_node.id, 'direction', p_direction)
  from public.learning_agent_script_versions version
  where version.id = v_node.script_version_id;

  return true;
end;
$$;


ALTER FUNCTION public.move_learning_agent_script_node(p_node_id uuid, p_direction text) OWNER TO postgres;

--
-- Name: normalize_lesson_progress_consistency(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.normalize_lesson_progress_consistency() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  new.progress_percent := greatest(0, least(100, coalesce(new.progress_percent, 0)));

  if new.status = 'completed' then
    new.progress_percent := 100;
    if new.completed_at is null then
      if tg_op = 'UPDATE' then
        new.completed_at := coalesce(old.completed_at, now());
      else
        new.completed_at := now();
      end if;
    end if;
  else
    if new.progress_percent >= 100 then
      new.progress_percent := 99;
    end if;
    if new.status = 'not_started' and new.progress_percent > 0 then
      new.status := 'in_progress';
    end if;
    new.completed_at := null;
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.normalize_lesson_progress_consistency() OWNER TO postgres;

--
-- Name: FUNCTION normalize_lesson_progress_consistency(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.normalize_lesson_progress_consistency() IS '统一课时进度状态：完成固定为 100%，未完成最高为 99%，有进度时不得保持未开始。';

--
-- Name: process_course_completion_refresh_tasks(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.process_course_completion_refresh_tasks(p_limit integer DEFAULT 25) RETURNS TABLE(task_id uuid, status text, target_count integer, succeeded_count integer, failed_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_worker_token uuid := gen_random_uuid();
  v_task_ids uuid[] := '{}'::uuid[];
begin
  if auth.role() is distinct from 'service_role' then
    raise exception '只有 service_role 可以执行结课资格刷新任务';
  end if;
  if coalesce(p_limit, 0) not between 1 and 200 then
    raise exception '批量任务数量必须在 1 到 200 之间';
  end if;

  with claimed as (
    update public.course_completion_refresh_tasks as task
    set status = 'processing', worker_token = v_worker_token,
        attempt_count = task.attempt_count + 1,
        started_at = clock_timestamp(), finished_at = null,
        last_error = null, updated_at = now()
    where task.id in (
      select candidate.id
      from public.course_completion_refresh_tasks as candidate
      where candidate.status = 'pending'
        and candidate.available_at <= now()
      order by candidate.available_at, candidate.created_at
      for update skip locked
      limit p_limit
    )
    returning task.id
  )
  select coalesce(array_agg(claimed.id), '{}'::uuid[])
  into v_task_ids
  from claimed;

  insert into public.course_completion_refresh_task_results (
    task_id, student_id, tenant_id, evaluation_id, succeeded,
    error_code, error_message, attempted_at
  )
  with targets as materialized (
    select distinct on (task.id, enrollment.student_id)
      task.id as task_id,
      enrollment.student_id,
      enrollment.tenant_id,
      task.course_id,
      task.policy_id
    from public.course_completion_refresh_tasks as task
    join public.student_app_enrollments as enrollment
      on enrollment.app_id = task.student_app_id
     and enrollment.status = 'active'
     and enrollment.starts_at <= now()
     and (enrollment.ends_at is null or enrollment.ends_at > now())
     and (task.tenant_id is null or enrollment.tenant_id = task.tenant_id)
     and (task.student_id is null or enrollment.student_id = task.student_id)
    join public.tenant_memberships as membership
      on membership.tenant_id = enrollment.tenant_id
     and membership.user_id = enrollment.student_id
     and membership.role = 'student'
     and membership.status = 'active'
    where task.worker_token = v_worker_token
      and task.status = 'processing'
    order by task.id, enrollment.student_id,
      membership.is_default desc, membership.joined_at, enrollment.tenant_id
  ), outcomes as (
    select target.task_id, target.student_id, target.tenant_id,
      result.evaluation_id, result.succeeded,
      result.error_code, result.error_message
    from targets as target
    cross join lateral private.try_evaluate_student_course_completion(
      target.student_id, target.course_id, target.policy_id
    ) as result
  )
  select outcome.task_id, outcome.student_id, outcome.tenant_id,
    outcome.evaluation_id, outcome.succeeded,
    outcome.error_code, outcome.error_message, clock_timestamp()
  from outcomes as outcome
  on conflict on constraint course_completion_refresh_task_results_pkey do update
  set tenant_id = excluded.tenant_id,
      evaluation_id = excluded.evaluation_id,
      succeeded = excluded.succeeded,
      error_code = excluded.error_code,
      error_message = excluded.error_message,
      attempted_at = excluded.attempted_at;

  update public.course_completion_refresh_tasks as task
  set target_count = result.target_count,
      succeeded_count = result.succeeded_count,
      failed_count = result.failed_count,
      status = case
        when result.failed_count = 0 then 'succeeded'
        when result.succeeded_count = 0 then 'failed'
        else 'partial_failed'
      end,
      last_error = result.last_error,
      worker_token = null,
      finished_at = clock_timestamp(),
      updated_at = now()
  from (
    select selected_task.id as task_id,
      count(task_result.student_id)::integer as target_count,
      count(*) filter (where task_result.succeeded)::integer
        as succeeded_count,
      count(*) filter (where not task_result.succeeded)::integer
        as failed_count,
      left(string_agg(
        task_result.error_code || ': ' || task_result.error_message,
        E'\n' order by task_result.student_id
      ) filter (where not task_result.succeeded), 2000) as last_error
    from unnest(v_task_ids) as claimed(task_id)
    join public.course_completion_refresh_tasks as selected_task
      on selected_task.id = claimed.task_id
    left join public.course_completion_refresh_task_results as task_result
      on task_result.task_id = selected_task.id
    group by selected_task.id
  ) as result
  where task.id = result.task_id
    and task.worker_token = v_worker_token
    and task.status = 'processing';

  return query
  select task.id, task.status, task.target_count,
    task.succeeded_count, task.failed_count
  from public.course_completion_refresh_tasks as task
  where task.id = any(v_task_ids)
  order by task.created_at;
end;
$$;


