--
-- Name: publish_assessment_paper_batch(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.publish_assessment_paper_batch(p_paper_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_paper_id uuid;
  v_published_count integer := 0;
begin
  if not public.current_user_can_release_assessment_papers() then
    raise exception '只有平台负责人可以批量发布标准试卷';
  end if;
  if p_paper_ids is null
    or cardinality(p_paper_ids) not between 1 and 100
    or (
      select count(distinct paper_id)
      from unnest(p_paper_ids) as requested(paper_id)
    ) <> cardinality(p_paper_ids) then
    raise exception '批量发布的试卷编号不正确';
  end if;

  for v_paper_id in
    select requested.paper_id
    from unnest(p_paper_ids) with ordinality as requested(paper_id, position)
    order by requested.position
  loop
    update public.assessment_papers
    set status = 'published', published_at = coalesce(published_at, now()),
        updated_by = auth.uid(), updated_at = now()
    where id = v_paper_id and status = 'draft';
    if not found then
      raise exception '批量发布中包含不存在或不是草稿的试卷';
    end if;

    perform private.validate_assessment_paper_release(v_paper_id);
    v_published_count := v_published_count + 1;
  end loop;
  return v_published_count;
end;
$$;


ALTER FUNCTION public.publish_assessment_paper_batch(p_paper_ids uuid[]) OWNER TO postgres;

