-- Name: FUNCTION publish_assessment_paper_batch(p_paper_ids uuid[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.publish_assessment_paper_batch(p_paper_ids uuid[]) IS '平台负责人原子发布一组已通过权威质检的标准试卷草稿。';

--
-- Name: publish_chapter_homework_plan(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.publish_chapter_homework_plan(p_plan_id uuid, p_status text DEFAULT 'published'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_plan public.chapter_homework_plans%rowtype;
  v_test public.course_tests%rowtype;
  v_paper public.assessment_papers%rowtype;
  v_paper_id uuid;
  v_paper_code text;
  v_student_app_id uuid;
  v_question record;
  v_paper_question_id uuid;
  v_sort_order integer := 0;
  v_enabled_skill_count integer;
begin
  if not public.current_user_can_release_assessment_papers() then
    raise exception '只有平台负责人可以发布或撤回章节作业';
  end if;
  if p_status not in ('draft', 'published') then
    raise exception '章节作业状态不正确';
  end if;

  select * into v_plan
  from public.chapter_homework_plans
  where id = p_plan_id
  for update;
  if not found then raise exception '章节作业计划不存在'; end if;

  select * into v_paper
  from public.assessment_papers
  where source_homework_plan_id = v_plan.id
  for update;

  if p_status = 'draft' then
    if v_paper.id is null then raise exception '章节作业尚未生成标准卷'; end if;
    update public.assessment_papers
    set status = 'draft', published_at = null,
        updated_by = auth.uid(), updated_at = now()
    where id = v_paper.id;
    update public.chapter_homework_plans
    set status = 'draft', version = version + 1, updated_at = now()
    where id = v_plan.id;
    return v_paper.id;
  end if;

  select * into v_test from public.course_tests where id = v_plan.test_id;
  select test.student_app_id into v_student_app_id
  from public.chapter_tests as test where test.id = v_plan.test_id;
  if v_test.id is null or v_student_app_id is null then
    raise exception '章节作业缺少有效的章节或应用归属';
  end if;

  perform private.sync_chapter_homework_six_skills(v_plan.test_id);
  select count(*) into v_enabled_skill_count
  from public.chapter_homework_skill_settings
  where plan_id = v_plan.id and enabled
    and target_question_count > 0
    and language_skill in (
      'vocabulary', 'grammar', 'listening', 'speaking', 'reading', 'writing'
    );
  if v_enabled_skill_count <> 6 then
    raise exception '词汇、语法、听力、口语、阅读、写作六项内容齐全后才能发布';
  end if;

  if v_paper.id is null then
    v_paper_code := 'HW-' || lpad(
      nextval('public.assessment_paper_code_seq')::text, 6, '0'
    );
    insert into public.assessment_papers (
      paper_code, paper_type, title, description, source_test_id,
      source_homework_plan_id, student_app_id, duration_minutes,
      passing_score, allow_resubmission, total_points, question_count,
      version, status, created_by, updated_by
    ) values (
      v_paper_code, 'homework', v_plan.title,
      '按本章教材完成词汇、语法、听力、口语、阅读、写作六项练习。',
      v_plan.test_id, v_plan.id, v_student_app_id, v_plan.duration_minutes,
      v_plan.passing_score, v_plan.allow_resubmission, 0, 0, 1,
      'draft', auth.uid(), auth.uid()
    ) returning id into v_paper_id;
  else
    if v_paper.status <> 'draft' then
      raise exception '请先把当前发布版本撤回为草稿';
    end if;
    v_paper_id := v_paper.id;
    update public.assessment_papers
    set title = v_plan.title,
        description = '按本章教材完成词汇、语法、听力、口语、阅读、写作六项练习。',
        duration_minutes = v_plan.duration_minutes,
        passing_score = v_plan.passing_score,
        allow_resubmission = v_plan.allow_resubmission,
        version = version + 1,
        updated_by = auth.uid(), updated_at = now()
    where id = v_paper_id;
    delete from public.assessment_paper_questions where paper_id = v_paper_id;
  end if;

  for v_question in
    select question.*
    from public.chapter_homework_questions as question
    where question.plan_id = v_plan.id
    order by case question.language_skill
      when 'vocabulary' then 1 when 'grammar' then 2
      when 'listening' then 3 when 'speaking' then 4
      when 'reading' then 5 when 'writing' then 6 end,
      question.sort_order
  loop
    insert into public.assessment_paper_questions (
      paper_id, source_bank_question_id, source_bank_version, question_type,
      stimulus_text, prompt, options, points, sort_order, difficulty, skill
    ) values (
      v_paper_id, v_question.source_bank_question_id,
      coalesce(v_question.source_bank_version, 1), v_question.question_type,
      v_question.stimulus_text, left(v_question.prompt, 3000),
      v_question.options, v_question.points, v_sort_order,
      v_question.difficulty, v_question.language_skill
    ) returning id into v_paper_question_id;

    insert into public.assessment_paper_question_keys (
      question_id, correct_answer, explanation
    ) values (
      v_paper_question_id, v_question.correct_answer,
      left(v_question.explanation, 3000)
    );
    v_sort_order := v_sort_order + 1;
  end loop;

  update public.assessment_papers
  set question_count = v_sort_order,
      total_points = (
        select coalesce(sum(points), 0)
        from public.assessment_paper_questions where paper_id = v_paper_id
      ),
      status = 'published', published_at = now(), updated_at = now()
  where id = v_paper_id;

  update public.chapter_homework_plans
  set status = 'published',
      version = case when status is distinct from 'published'
        then version + 1 else version end,
      updated_at = now()
  where id = v_plan.id;

  return v_paper_id;
end;
$$;


ALTER FUNCTION public.publish_chapter_homework_plan(p_plan_id uuid, p_status text) OWNER TO postgres;

--
-- Name: FUNCTION publish_chapter_homework_plan(p_plan_id uuid, p_status text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.publish_chapter_homework_plan(p_plan_id uuid, p_status text) IS '平台负责人发布章节作业，并同步为机构可选择的标准作业卷。';

--
-- Name: publish_digital_textbook_chapter(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.publish_digital_textbook_chapter(p_chapter_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  chapter_number_value integer;
  chapter_test_id_value uuid;
  chapter_test_slug_value text;
  version_id_value uuid;
  textbook_id_value uuid;
  question_count integer := 0;
  invalid_question_count integer := 0;
begin
  if auth.uid() is null or not private.is_platform_owner() then
    raise exception '只有平台负责人可以发布教材章节';
  end if;

  -- Global authoring lock BEFORE any row lock, same order as the Publisher.
  perform runtime_publish_private.authoring_lock();

  select
    chapter.chapter_number,
    chapter.chapter_test_id,
    version.id,
    textbook.id
  into
    chapter_number_value,
    chapter_test_id_value,
    version_id_value,
    textbook_id_value
  from public.digital_textbook_chapters as chapter
  join public.digital_textbook_versions as version on version.id = chapter.version_id
  join public.digital_textbooks as textbook on textbook.id = version.textbook_id
  where chapter.id = p_chapter_id
  for update of chapter, version, textbook;

  if not found then
    raise exception '没有找到要发布的教材章节';
  end if;

  if chapter_number_value > 0 and chapter_test_id_value is null then
    raise exception '当前章节尚未关联章节测试';
  end if;

  if chapter_test_id_value is not null then
    select
      test.slug
    into chapter_test_slug_value
    from public.chapter_tests as test
    where test.id = chapter_test_id_value
    for update;

    if chapter_test_slug_value is null then
      raise exception '当前章节测试还没有可发布题目';
    end if;

    perform 1
    from public.chapter_test_questions as question
    where question.test_id = chapter_test_id_value
    for update;

    select
      count(question.id) filter (
        where question.is_chapter_test_item = true
          and question.question_type = 'single_choice'
      ),
      count(question.id) filter (
        where question.is_chapter_test_item = true
          and (
            question.question_type is distinct from 'single_choice'
            or nullif(btrim(question.prompt), '') is null
            or case
              when jsonb_typeof(question.options) = 'array'
                then jsonb_array_length(question.options) <> 4
              else true
            end
            or question.correct_option is null
            or question.correct_option < 0
            or question.correct_option > 3
          )
      )
    into question_count, invalid_question_count
    from public.chapter_test_questions as question
    where question.test_id = chapter_test_id_value;

    if question_count = 0 then
      raise exception '当前章节测试还没有可发布题目';
    end if;

    if invalid_question_count > 0 then
      raise exception '章节测试存在未完成配置的题目';
    end if;

    update public.chapter_test_questions
    set status = 'published',
        updated_at = now()
    where test_id = chapter_test_id_value
      and is_chapter_test_item = true
      and question_type = 'single_choice'
      and status is distinct from 'published';

    update public.chapter_tests
    set status = 'published',
        updated_at = now()
    where id = chapter_test_id_value and status is distinct from 'published';
  end if;

  update public.digital_textbooks
  set status = 'published',
      updated_at = now()
  where id = textbook_id_value and status is distinct from 'published';

  update public.digital_textbook_versions
  set status = 'published',
      updated_at = now()
  where id = version_id_value and status is distinct from 'published';

  update public.digital_textbook_chapters
  set status = 'published',
      production_status = case
        when production_status is null then null
        else 'published'
      end,
      updated_at = now()
  where id = p_chapter_id and (status is distinct from 'published' or (production_status is not null and production_status is distinct from 'published'));

  return jsonb_build_object(
    'chapterNumber', chapter_number_value,
    'testSlug', chapter_test_slug_value,
    'publishedQuestions', question_count
  );
end;
$$;


ALTER FUNCTION public.publish_digital_textbook_chapter(p_chapter_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION publish_digital_textbook_chapter(p_chapter_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.publish_digital_textbook_chapter(p_chapter_id uuid) IS '平台负责人一次发布教材章节、关联章节测试及有效测试题；数据库内再次校验身份并保持事务原子性。';

--
-- Name: publish_institution_curriculum_plan(uuid, uuid, text, timestamp with time zone, timestamp with time zone, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.publish_institution_curriculum_plan(p_student_app_id uuid, p_template_id uuid, p_title text, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_student_ids uuid[]) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_plan_id uuid;
  v_tenant_id uuid := private.current_tenant_id();
  v_user_id uuid := auth.uid();
  v_published_at timestamptz := now();
begin
  if v_tenant_id is null or v_user_id is null then
    raise exception '当前登录上下文无效';
  end if;
  if p_title is null or char_length(btrim(p_title)) not between 1 and 180 then
    raise exception '机构计划名称长度无效';
  end if;
  if p_ends_at <= p_starts_at then
    raise exception '计划结束时间必须晚于开始时间';
  end if;
  if p_student_ids is null or cardinality(p_student_ids) = 0 then
    raise exception '请至少选择一名学生';
  end if;
  if cardinality(p_student_ids) <> (
    select count(distinct student_id)
    from unnest(p_student_ids) as selected(student_id)
  ) then
    raise exception '学生列表包含重复账号';
  end if;

  insert into public.institution_curriculum_plans (
    tenant_id,
    student_app_id,
    template_id,
    title,
    starts_at,
    ends_at,
    status,
    created_by,
    published_by,
    published_at
  ) values (
    v_tenant_id,
    p_student_app_id,
    p_template_id,
    btrim(p_title),
    p_starts_at,
    p_ends_at,
    'published',
    v_user_id,
    v_user_id,
    v_published_at
  )
  returning id into v_plan_id;

  insert into public.institution_curriculum_plan_students (
    plan_id,
    tenant_id,
    student_id,
    assigned_by
  )
  select
    v_plan_id,
    v_tenant_id,
    student_id,
    v_user_id
  from unnest(p_student_ids) as selected(student_id);

  return v_plan_id;
end;
$$;


ALTER FUNCTION public.publish_institution_curriculum_plan(p_student_app_id uuid, p_template_id uuid, p_title text, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_student_ids uuid[]) OWNER TO postgres;

--
-- Name: publish_learning_agent_script_version_unchecked(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.publish_learning_agent_script_version_unchecked(p_script_version_id uuid, p_change_note text DEFAULT ''::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'auth'
    AS $$
declare
  v_version public.learning_agent_script_versions%rowtype;
  v_node_count integer;
  v_terminal_count integer;
  v_reachable_count integer;
  v_has_cycle boolean;
  v_missing_link text;
begin
  if auth.uid() is null or not private.is_platform_owner() then
    raise exception '只有平台负责人可以发布教学脚本';
  end if;

  select * into v_version
  from public.learning_agent_script_versions
  where id = p_script_version_id
  for update;
  if not found then raise exception '没有找到要发布的教学脚本'; end if;
  if v_version.status <> 'draft' then raise exception '只有草稿版本可以发布'; end if;

  select count(*) into v_node_count
  from public.learning_agent_script_nodes
  where script_version_id = p_script_version_id;
  if v_node_count = 0 then raise exception '教学脚本至少需要一个小节'; end if;

  if exists (
    select 1 from public.learning_agent_script_nodes node
    where node.script_version_id = p_script_version_id
      and nullif(trim(node.teacher_script->>'zh-CN'), '') is null
  ) then
    raise exception '每个教学小节都必须填写中文老师台词';
  end if;

  select coalesce(node.next_node_key, node.remediation_node_key) into v_missing_link
  from public.learning_agent_script_nodes node
  where node.script_version_id = p_script_version_id
    and (
      (node.next_node_key is not null and not exists (
        select 1 from public.learning_agent_script_nodes target
        where target.script_version_id = p_script_version_id
          and target.node_key = node.next_node_key
      ))
      or
      (node.remediation_node_key is not null and not exists (
        select 1 from public.learning_agent_script_nodes target
        where target.script_version_id = p_script_version_id
          and target.node_key = node.remediation_node_key
      ))
    )
  limit 1;
  if v_missing_link is not null then raise exception '教学流程引用了不存在的小节：%', v_missing_link; end if;

  select count(*) into v_terminal_count
  from public.learning_agent_script_nodes node
  where node.script_version_id = p_script_version_id
    and node.configuration->'terminal' = 'true'::jsonb;
  if v_terminal_count <> 1 then
    raise exception '教学流程必须且只能设置一个“结束当前学习步骤”的小节';
  end if;

  if exists (
    select 1 from public.learning_agent_script_nodes node
    where node.script_version_id = p_script_version_id
      and node.configuration->'terminal' = 'true'::jsonb
      and node.next_node_key is not null
  ) then
    raise exception '结束小节不能再设置后续跳转';
  end if;

  if exists (
    select 1 from public.learning_agent_script_nodes node
    where node.script_version_id = p_script_version_id
      and node.configuration->'terminal' is distinct from 'true'::jsonb
      and node.next_node_key is null
      and not exists (
        select 1 from public.learning_agent_script_nodes later
        where later.script_version_id = p_script_version_id
          and later.sort_order > node.sort_order
      )
  ) then
    raise exception '最后一个小节必须设置为“结束当前学习步骤”';
  end if;

  with recursive flow_walk as (
    select
      first_node.id,
      first_node.node_key,
      first_node.sort_order,
      first_node.next_node_key,
      first_node.configuration,
      array[first_node.id]::uuid[] as visited_ids,
      false as has_cycle
    from (
      select node.id, node.node_key, node.sort_order, node.next_node_key, node.configuration
      from public.learning_agent_script_nodes node
      where node.script_version_id = p_script_version_id
      order by node.sort_order, node.id
      limit 1
    ) first_node

    union all

    select
      target.id,
      target.node_key,
      target.sort_order,
      target.next_node_key,
      target.configuration,
      current_node.visited_ids || target.id,
      target.id = any(current_node.visited_ids)
    from flow_walk current_node
    join lateral (
      select candidate.id, candidate.node_key, candidate.sort_order,
        candidate.next_node_key, candidate.configuration
      from public.learning_agent_script_nodes candidate
      where candidate.script_version_id = p_script_version_id
        and (
          (current_node.next_node_key is not null and candidate.node_key = current_node.next_node_key)
          or
          (
            current_node.next_node_key is null
            and current_node.configuration->'terminal' is distinct from 'true'::jsonb
            and candidate.sort_order > current_node.sort_order
          )
        )
      order by candidate.sort_order, candidate.id
      limit 1
    ) target on true
    where not current_node.has_cycle
      and current_node.configuration->'terminal' is distinct from 'true'::jsonb
  )
  select count(distinct id), coalesce(bool_or(has_cycle), false)
  into v_reachable_count, v_has_cycle
  from flow_walk;

  if v_has_cycle then raise exception '教学流程存在循环跳转，请重新选择后续小节'; end if;
  if v_reachable_count <> v_node_count then
    raise exception '教学流程中存在无法到达的小节，请检查跳转设置和小节顺序';
  end if;

  if exists (
    select 1 from public.learning_agent_script_nodes node
    where node.script_version_id = p_script_version_id
      and node.node_type = 'question'
      and node.reference_activity_id is null
      and coalesce(node.configuration->'interaction'->>'kind', '') <> 'single_choice'
  ) then
    raise exception '理解检查必须新建单选题或选择一个教材活动';
  end if;

  if exists (
    select 1 from public.learning_agent_script_nodes node
    where node.script_version_id = p_script_version_id
      and coalesce(node.configuration->'interaction'->>'kind', '') = 'single_choice'
      and (
        jsonb_typeof(node.configuration->'interaction'->'options') <> 'array'
        or jsonb_array_length(node.configuration->'interaction'->'options') < 2
        or not exists (
          select 1 from public.learning_agent_node_interaction_secrets secret
          where secret.node_id = node.id
            and secret.correct_option_index >= 0
            and secret.correct_option_index < jsonb_array_length(node.configuration->'interaction'->'options')
        )
      )
  ) then
    raise exception '自定义单选检查缺少有效选项或正确答案';
  end if;

  if exists (
    select 1 from public.learning_agent_script_nodes node
    where node.script_version_id = p_script_version_id
      and (
        (node.action_type = 'focus_activity' and node.reference_activity_id is null)
        or
        (node.action_type = 'play_expression' and coalesce(node.configuration->'studentTask'->>'kind', '') <> 'play_expression_audio')
        or node.action_type not in ('none', 'focus_activity', 'play_expression')
      )
  ) then
    raise exception '教学小节包含无效的页面联动设置';
  end if;

  update public.learning_agent_script_versions
  set status = 'archived'
  where lesson_id = v_version.lesson_id and status = 'published';

  update public.learning_agent_script_versions
  set status = 'published',
      change_note = left(trim(coalesce(p_change_note, '')), 500),
      published_by = auth.uid(),
      published_at = now()
  where id = p_script_version_id;

  update public.learning_agent_lessons
  set revision = v_version.version_number,
      status = 'published'
  where id = v_version.lesson_id;

  insert into public.learning_agent_publish_logs (
    lesson_id, script_version_id, action, actor_id, details
  ) values (
    v_version.lesson_id, p_script_version_id, 'publish', auth.uid(),
    jsonb_build_object(
      'changeNote', left(trim(coalesce(p_change_note, '')), 500),
      'nodeCount', v_node_count,
      'terminalCount', v_terminal_count
    )
  );

  return jsonb_build_object(
    'scriptVersionId', p_script_version_id,
    'versionNumber', v_version.version_number,
    'nodeCount', v_node_count
  );
end;
$$;


ALTER FUNCTION public.publish_learning_agent_script_version_unchecked(p_script_version_id uuid, p_change_note text) OWNER TO postgres;

--
-- Name: publish_runtime_snapshot_base_v2(uuid, jsonb, jsonb, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.publish_runtime_snapshot_base_v2(p_actor uuid, p_scope jsonb, p_expected jsonb, p_operation text, p_bundle jsonb, p_target text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  result jsonb;
  captured jsonb;
begin
  perform runtime_publish_private.owner_guard(p_actor);
  perform runtime_publish_private.authoring_lock();

  if p_operation = 'publish' then
    captured := runtime_publish_private.capture(p_scope);
    if p_bundle #> '{privatePayload,dependencies}' is distinct from captured then
      raise exception 'PUBLICATION_SOURCE_CAPTURE_CONFLICT' using errcode = '40001';
    end if;

    if exists (
      select 1
      from jsonb_array_elements(captured -> 'digital_textbook_activities') as activity
      where not (
        activity ->> 'activity_key' = 'dialogue-roleplay'
        and activity ->> 'activity_type' = 'speaking'
      )
      and (
        select count(*)
        from jsonb_array_elements(captured -> 'digital_textbook_activity_secrets') as secret
        where secret ->> 'activity_id' = activity ->> 'id'
      ) <> 1
    ) then
      raise exception 'PUBLICATION_GRADER_DEPENDENCY_MISSING';
    end if;
  else
    if not exists (
      select 1
      from runtime_publish_private.dependency_fences
      where snapshot_id = p_target
    ) then
      raise exception 'PUBLICATION_UNFENCED_ROLLBACK';
    end if;
  end if;

  result := public.publish_runtime_snapshot_v1(
    p_actor, p_scope, p_expected, p_operation, p_bundle, p_target
  );
  if p_operation = 'publish' then
    insert into runtime_publish_private.dependency_fences
    values (p_bundle ->> 'snapshotId', p_scope, captured)
    on conflict (snapshot_id) do nothing;
  end if;
  return result;
end
$$;


ALTER FUNCTION public.publish_runtime_snapshot_base_v2(p_actor uuid, p_scope jsonb, p_expected jsonb, p_operation text, p_bundle jsonb, p_target text) OWNER TO postgres;

--
-- Name: publish_runtime_snapshot_v1(uuid, jsonb, jsonb, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.publish_runtime_snapshot_v1(p_actor uuid, p_scope jsonb, p_expected jsonb, p_operation text, p_bundle jsonb, p_target text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  t uuid := (p_scope->>'textbookId')::uuid; v uuid := (p_scope->>'versionId')::uuid; c uuid := (p_scope->>'chapterId')::uuid;
  old runtime_publish_private.pointers%rowtype; doc jsonb; dest text; gen bigint;
begin
  perform runtime_publish_private.owner_guard(p_actor);
  if p_operation not in ('publish','rollback') or p_operation is null then raise exception 'PUBLICATION_OPERATION'; end if;
  if not exists(select 1 from public.digital_textbook_chapters ch join public.digital_textbook_versions ver on ver.id=ch.version_id where ch.id=c and ver.id=v and ver.textbook_id=t) then raise exception 'PUBLICATION_SCOPE'; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(t::text||'/'||v::text||'/'||c::text, 4171));
  select * into old from runtime_publish_private.pointers where textbook_id=t and version_id=v and chapter_id=c for update;
  if (old.snapshot_id is null and p_expected is not null and p_expected<>'null'::jsonb) or
     (old.snapshot_id is not null and (p_expected->>'snapshotId' is distinct from old.snapshot_id or p_expected->>'generation' is distinct from old.generation::text)) then
    raise exception 'PUBLICATION_CONFLICT' using errcode='40001';
  end if;
  if p_operation='publish' then
    if p_bundle is null or p_bundle->'scope' is distinct from p_scope or p_bundle->>'revision' is distinct from 'publish-foundation/1' or jsonb_typeof(p_bundle->'privatePayload') is distinct from 'object' then raise exception 'PUBLICATION_BUNDLE'; end if;
    dest:=p_bundle->>'snapshotId'; doc:=p_bundle-'privatePayload';
    if p_bundle#>>'{privatePayload,result,manifest}' is distinct from (p_bundle->'manifest')::text or
       p_bundle#>>'{privatePayload,result,report,sourceRevision}' is distinct from p_bundle->>'sourceRevision' then raise exception 'PUBLICATION_ASSOCIATION'; end if;
    if exists(select 1 from runtime_publish_private.snapshots where id=dest) then
      if not exists(select 1 from runtime_publish_private.snapshots s join runtime_publish_private.bindings b on b.snapshot_id=s.id where s.id=dest and s.document=doc and b.payload=p_bundle->'privatePayload' and b.digest=p_bundle->>'privateDigest') then raise exception 'PUBLICATION_ID_COLLISION'; end if;
    else
      insert into runtime_publish_private.snapshots(id,textbook_id,version_id,chapter_id,document,created_by) values(dest,t,v,c,doc,p_actor);
      insert into runtime_publish_private.bindings(snapshot_id,payload,digest) values(dest,p_bundle->'privatePayload',p_bundle->>'privateDigest');
    end if;
  else
    dest:=p_target;
    if not exists(select 1 from runtime_publish_private.history where textbook_id=t and version_id=v and chapter_id=c and to_snapshot=dest) then raise exception 'ROLLBACK_NOT_PUBLISHED'; end if;
  end if;
  gen:=coalesce(old.generation,0)+1;
  insert into runtime_publish_private.pointers values(t,v,c,dest,gen)
    on conflict(textbook_id,version_id,chapter_id) do update set snapshot_id=excluded.snapshot_id,generation=excluded.generation;
  insert into runtime_publish_private.history(textbook_id,version_id,chapter_id,from_snapshot,to_snapshot,generation,operation,actor_id)
    values(t,v,c,old.snapshot_id,dest,gen,p_operation,p_actor);
  return jsonb_build_object('snapshotId',dest,'generation',gen);
end $$;


ALTER FUNCTION public.publish_runtime_snapshot_v1(p_actor uuid, p_scope jsonb, p_expected jsonb, p_operation text, p_bundle jsonb, p_target text) OWNER TO postgres;

--
-- Name: publish_runtime_snapshot_v2(uuid, jsonb, jsonb, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.publish_runtime_snapshot_v2(p_actor uuid, p_scope jsonb, p_expected jsonb, p_operation text, p_bundle jsonb, p_target text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  result jsonb;
  state_value text;
  book uuid := (p_scope ->> 'textbookId')::uuid;
begin
  perform runtime_publish_private.owner_guard(p_actor);
  perform runtime_publish_private.authoring_lock();
  select state into state_value
  from runtime_publish_private.authoring_control
  where textbook_id = book;
  if state_value = 'draining' then
    raise exception 'TEXTBOOK_DRAIN_INCOMPLETE';
  end if;
  if exists (
    select 1
    from runtime_publish_private.retired_snapshots
    where snapshot_id = case
      when p_operation = 'publish' then p_bundle ->> 'snapshotId'
      else p_target
    end
  ) then
    raise exception 'RETIRED_SNAPSHOT_NOT_EXECUTABLE';
  end if;
  result := public.publish_runtime_snapshot_base_v2(
    p_actor, p_scope, p_expected, p_operation, p_bundle, p_target
  );
  update runtime_publish_private.authoring_control
  set state = 'open'
  where textbook_id = book;
  return result;
end
$$;


ALTER FUNCTION public.publish_runtime_snapshot_v2(p_actor uuid, p_scope jsonb, p_expected jsonb, p_operation text, p_bundle jsonb, p_target text) OWNER TO postgres;

--
-- Name: publish_teaching_script_checked(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.publish_teaching_script_checked(p_script_version_id uuid, p_change_note text, p_expected_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'auth'
    AS $$
declare v_snapshot jsonb;
begin
  if auth.uid() is null or not private.is_platform_owner() then raise exception '只有平台负责人可以发布教学脚本'; end if;
  -- Short commit-time locks cover updates, answers, deletion, insertion and ordering.
  -- No database lock is held while the application checks R2 over the network.
  lock table public.learning_agent_script_nodes in share row exclusive mode;
  lock table public.learning_agent_node_interaction_secrets in share row exclusive mode;
  perform 1 from public.learning_agent_script_versions where id = p_script_version_id for update;
  v_snapshot := public.teaching_script_publish_snapshot(p_script_version_id);
  if p_expected_token is null or v_snapshot->>'token' is distinct from p_expected_token then
    raise exception '检查期间教学脚本已修改，请重新检查后再发布。';
  end if;
  return public.publish_learning_agent_script_version_unchecked(p_script_version_id, p_change_note);
end;
$$;


ALTER FUNCTION public.publish_teaching_script_checked(p_script_version_id uuid, p_change_note text, p_expected_token text) OWNER TO postgres;

--
-- Name: read_chapter_practice_snapshots(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.read_chapter_practice_snapshots(p_app_id uuid) RETURNS TABLE(chapter_id uuid, version_id uuid, lesson_id uuid, chapter_test_id uuid, snapshot jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select b.chapter_id, b.version_id, t.lesson_id, c.chapter_test_id, b.snapshot from public.chapter_practice_bindings b
  join public.digital_textbook_chapters c on c.id = b.chapter_id and c.version_id = b.version_id
  join public.digital_textbook_versions v on v.id = c.version_id
  join public.digital_textbooks t on t.id = v.textbook_id and t.student_app_id = b.student_app_id
  where auth.uid() is not null and private.current_user_can_read_student_app(p_app_id)
    and b.student_app_id = p_app_id and b.is_enabled
    and c.status = 'published' and v.status = 'published' and t.status = 'published'
  order by b.chapter_id;
$$;


ALTER FUNCTION public.read_chapter_practice_snapshots(p_app_id uuid) OWNER TO postgres;

--
-- Name: read_runtime_publication_v1(jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.read_runtime_publication_v1(p_scope jsonb, p_history_actor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result jsonb;
begin
  if p_history_actor is not null then
    perform runtime_publish_private.owner_guard(p_history_actor);
    select coalesce(jsonb_agg(to_jsonb(h) order by generation),'[]'::jsonb) into result from runtime_publish_private.history h
      where textbook_id=(p_scope->>'textbookId')::uuid and version_id=(p_scope->>'versionId')::uuid and chapter_id=(p_scope->>'chapterId')::uuid;
  else
    select jsonb_build_object('pointer',jsonb_build_object('snapshotId',p.snapshot_id,'generation',p.generation),'bundle',s.document||jsonb_build_object('privatePayload',b.payload)) into result
      from runtime_publish_private.pointers p join runtime_publish_private.snapshots s on s.id=p.snapshot_id join runtime_publish_private.bindings b on b.snapshot_id=s.id and b.digest=s.document->>'privateDigest'
      where p.textbook_id=(p_scope->>'textbookId')::uuid and p.version_id=(p_scope->>'versionId')::uuid and p.chapter_id=(p_scope->>'chapterId')::uuid;
  end if;
  return result;
end $$;


ALTER FUNCTION public.read_runtime_publication_v1(p_scope jsonb, p_history_actor uuid) OWNER TO postgres;

--
-- Name: read_runtime_snapshot_for_owner_v1(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.read_runtime_snapshot_for_owner_v1(p_actor uuid, p_scope jsonb, p_snapshot text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare artifact jsonb;
begin
  perform runtime_publish_private.owner_guard(p_actor);
  select s.document||jsonb_build_object('privatePayload',b.payload) into artifact
    from runtime_publish_private.snapshots s join runtime_publish_private.bindings b on b.snapshot_id=s.id and b.digest=s.document->>'privateDigest'
    where s.id=p_snapshot and s.textbook_id=(p_scope->>'textbookId')::uuid and s.version_id=(p_scope->>'versionId')::uuid and s.chapter_id=(p_scope->>'chapterId')::uuid
    and exists(select 1 from runtime_publish_private.history h where h.to_snapshot=s.id);
  if artifact is null then raise exception 'ROLLBACK_NOT_PUBLISHED'; end if;
  return artifact;
end $$;


ALTER FUNCTION public.read_runtime_snapshot_for_owner_v1(p_actor uuid, p_scope jsonb, p_snapshot text) OWNER TO postgres;

--
-- Name: record_conversation_practice(uuid, integer, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_conversation_practice(p_scenario_id uuid, p_confidence integer, p_reflection text, p_completed boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tenant_id uuid := private.current_tenant_id();
begin
  if not (
    public.is_active_account()
    and public.current_profile_role() = 'student'
    and public.student_feature_allowed('conversation_course')
  ) then
    raise exception '当前会员档位没有会话课程权限';
  end if;
  if not exists (
    select 1
    from public.conversation_practice_scenarios as scenario
    where scenario.id = p_scenario_id
      and (
        scenario.tenant_id is null
        or scenario.tenant_id = v_tenant_id
      )
      and scenario.status = 'published'
      and private.current_student_has_app_access(
        v_tenant_id,
        (select auth.uid()),
        scenario.student_app_id
      )
  ) then
    raise exception '该会话场景尚未开放';
  end if;
  if p_confidence is not null and p_confidence not between 1 and 5 then
    raise exception '请填写 1 至 5 级的自信程度';
  end if;
  if char_length(coalesce(p_reflection, '')) > 1200 then
    raise exception '练习复盘不能超过 1200 个字';
  end if;

  insert into public.conversation_practice_progress (
    tenant_id, user_id, scenario_id, status, practice_count, confidence,
    reflection, first_practiced_at, last_practiced_at, completed_at
  ) values (
    v_tenant_id, auth.uid(), p_scenario_id,
    case when coalesce(p_completed, false) then 'completed' else 'practicing' end,
    1, p_confidence, coalesce(p_reflection, ''), now(), now(),
    case when coalesce(p_completed, false) then now() else null end
  )
  on conflict (user_id, scenario_id) do update
  set status = case
        when coalesce(p_completed, false) then 'completed'
        else public.conversation_practice_progress.status
      end,
      practice_count = public.conversation_practice_progress.practice_count + 1,
      confidence = p_confidence,
      reflection = coalesce(p_reflection, ''),
      last_practiced_at = now(),
      completed_at = case
        when coalesce(p_completed, false)
          then coalesce(public.conversation_practice_progress.completed_at, now())
        else public.conversation_practice_progress.completed_at
      end;
end;
$$;


ALTER FUNCTION public.record_conversation_practice(p_scenario_id uuid, p_confidence integer, p_reflection text, p_completed boolean) OWNER TO postgres;

--
-- Name: course_ebook_progress; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.course_ebook_progress (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid DEFAULT private.current_tenant_id() NOT NULL,
    student_id uuid NOT NULL,
    test_slug text NOT NULL,
    current_page integer DEFAULT 0 NOT NULL,
    total_pages integer NOT NULL,
    progress_percent integer DEFAULT 0 NOT NULL,
    last_read_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    read_pages integer[] DEFAULT '{}'::integer[] NOT NULL,
    reading_seconds integer DEFAULT 0 NOT NULL,
    student_app_id uuid NOT NULL,
    completion_source text DEFAULT 'ebook'::text NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT course_ebook_progress_completion_source_check CHECK ((completion_source = ANY (ARRAY['ebook'::text, 'smart_textbook'::text, 'both'::text]))),
    CONSTRAINT course_ebook_progress_current_page_check CHECK ((current_page >= 0)),
    CONSTRAINT course_ebook_progress_progress_percent_check CHECK (((progress_percent >= 0) AND (progress_percent <= 100))),
    CONSTRAINT course_ebook_progress_total_pages_check CHECK ((total_pages > 0))
);


ALTER TABLE public.course_ebook_progress OWNER TO postgres;

--
-- Name: TABLE course_ebook_progress; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.course_ebook_progress IS '按章节测试 slug 保存每一本电子书的当前页、总页数和最高阅读进度。';

--
-- Name: COLUMN course_ebook_progress.read_pages; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.course_ebook_progress.read_pages IS '达到有效停留时间后计入阅读进度的页码集合。';

--
-- Name: COLUMN course_ebook_progress.completion_source; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.course_ebook_progress.completion_source IS 'Compatibility completion source. smart_textbook never fabricates ebook reading_seconds.';

--
-- Name: record_ebook_progress(text, integer, integer, integer[], integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_ebook_progress(p_test_slug text, p_current_page integer, p_total_pages integer, p_new_read_pages integer[], p_reading_seconds integer DEFAULT 0) RETURNS public.course_ebook_progress
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_tenant_id uuid := private.current_tenant_id();
  v_row public.course_ebook_progress%rowtype;
  v_existing integer[];
  v_merged integer[];
  v_existing_seconds integer := 0;
  v_increment integer := least(35, greatest(coalesce(p_reading_seconds, 0), 0));
  v_seconds integer;
  v_percent integer;
begin
  if v_user_id is null or v_tenant_id is null then
    raise exception '请登录有效的机构账号后再记录学习进度';
  end if;
  if not public.student_feature_allowed('korean_course') then
    raise exception '当前会员档位没有权限记录这本教材的学习进度';
  end if;
  if p_test_slug is null or length(trim(p_test_slug)) = 0 then
    raise exception '章节编号不正确';
  end if;
  if not exists (
    select 1
    from public.chapter_tests as test
    where test.slug = p_test_slug
      and test.status = 'published'
      and test.student_app_id = '10000000-0000-4000-8000-000000000001'::uuid
  ) then
    raise exception '章节不存在或尚未发布';
  end if;
  if p_total_pages is null or p_total_pages <= 0 or p_total_pages > 2000 then
    raise exception '总页数不正确';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      v_tenant_id::text || ':' || v_user_id::text || ':' || p_test_slug,
      0
    )
  );

  select progress.read_pages, coalesce(progress.reading_seconds, 0)
  into v_existing, v_existing_seconds
  from public.course_ebook_progress as progress
  where progress.tenant_id = v_tenant_id
    and progress.student_id = v_user_id
    and progress.test_slug = p_test_slug;

  select coalesce(array_agg(distinct page order by page), '{}'::integer[])
  into v_merged
  from unnest(
    coalesce(v_existing, '{}'::integer[])
      || coalesce(p_new_read_pages, '{}'::integer[])
  ) as page
  where page >= 0 and page < p_total_pages;

  v_seconds := least(1000000, coalesce(v_existing_seconds, 0) + v_increment);
  v_percent := least(100, round(v_seconds::numeric / 600 * 100));

  update public.course_ebook_progress as progress
  set
    current_page = least(
      greatest(coalesce(p_current_page, 0), 0),
      p_total_pages - 1
    ),
    total_pages = p_total_pages,
    read_pages = v_merged,
    reading_seconds = v_seconds,
    progress_percent = v_percent,
    last_read_at = now(),
    updated_at = now()
  where progress.tenant_id = v_tenant_id
    and progress.student_id = v_user_id
    and progress.test_slug = p_test_slug
  returning * into v_row;

  if not found then
    insert into public.course_ebook_progress (
      tenant_id, student_id, test_slug, current_page, total_pages,
      read_pages, reading_seconds, progress_percent, last_read_at, updated_at
    ) values (
      v_tenant_id,
      v_user_id,
      p_test_slug,
      least(greatest(coalesce(p_current_page, 0), 0), p_total_pages - 1),
      p_total_pages,
      v_merged,
      v_seconds,
      v_percent,
      now(),
      now()
    )
    returning * into v_row;
  end if;

  -- 明细只能记录数据库认可的有效增量；不能由客户端直接放大统计时长。
  if v_increment > 0 then
    insert into public.learning_time_log (
      tenant_id, student_id, test_slug, source, seconds, recorded_at
    ) values (
      v_tenant_id, v_user_id, p_test_slug, 'ebook', v_increment, now()
    );
  end if;

  return v_row;
end;
$$;


ALTER FUNCTION public.record_ebook_progress(p_test_slug text, p_current_page integer, p_total_pages integer, p_new_read_pages integer[], p_reading_seconds integer) OWNER TO postgres;

--
-- Name: FUNCTION record_ebook_progress(p_test_slug text, p_current_page integer, p_total_pages integer, p_new_read_pages integer[], p_reading_seconds integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.record_ebook_progress(p_test_slug text, p_current_page integer, p_total_pages integer, p_new_read_pages integer[], p_reading_seconds integer) IS '幂等片段调用的电子书累计进度写入；更新现有行后再插入新行，避免 INSERT 触发器重置累计秒数。';

--
-- Name: record_ebook_progress_segment(uuid, text, integer, integer, integer[], integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_ebook_progress_segment(p_event_id uuid, p_test_slug text, p_current_page integer, p_total_pages integer, p_new_read_pages integer[], p_reading_seconds integer) RETURNS public.course_ebook_progress
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_tenant_id uuid := private.current_tenant_id();
  v_inserted_event uuid;
  v_row public.course_ebook_progress%rowtype;
begin
  if v_user_id is null or v_tenant_id is null then
    raise exception '请登录有效的机构账号后再记录学习进度';
  end if;
  if p_event_id is null then
    raise exception '计时片段编号不能为空';
  end if;
  if p_reading_seconds is null or p_reading_seconds < 0 or p_reading_seconds > 35 then
    raise exception '阅读时长不正确';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      v_tenant_id::text || ':' || v_user_id::text || ':' || p_test_slug,
      0
    )
  );

  insert into public.ebook_reading_segments (
    tenant_id, student_id, event_id, test_slug, seconds
  ) values (
    v_tenant_id, v_user_id, p_event_id, p_test_slug, p_reading_seconds
  )
  on conflict (tenant_id, student_id, event_id) do nothing
  returning event_id into v_inserted_event;

  if v_inserted_event is null then
    select * into v_row
    from public.course_ebook_progress as progress
    where progress.tenant_id = v_tenant_id
      and progress.student_id = v_user_id
      and progress.test_slug = p_test_slug;

    if not found then
      raise exception '找不到该计时片段对应的电子书进度';
    end if;
    return v_row;
  end if;

  delete from public.ebook_reading_segments as segment
  where segment.tenant_id = v_tenant_id
    and segment.student_id = v_user_id
    and segment.recorded_at < now() - interval '1 day';

  select * into v_row
  from public.record_ebook_progress(
    p_test_slug,
    p_current_page,
    p_total_pages,
    p_new_read_pages,
    p_reading_seconds
  );

  return v_row;
end;
$$;


ALTER FUNCTION public.record_ebook_progress_segment(p_event_id uuid, p_test_slug text, p_current_page integer, p_total_pages integer, p_new_read_pages integer[], p_reading_seconds integer) OWNER TO postgres;

--
-- Name: record_library_download(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_library_download(p_resource_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tenant_id uuid := private.current_tenant_id();
begin
  if private.is_platform_owner() then
    if not exists (
      select 1 from public.library_resources where id = p_resource_id
    ) then
      raise exception '资料不存在';
    end if;
  else
    if v_tenant_id is null
      or not public.is_active_account()
      or not exists (
        select 1
        from public.library_resources as resource
        join public.courses as course on course.id = resource.course_id
        where resource.id = p_resource_id
          and resource.tenant_id is null
          and resource.content_scope = 'platform'
          and resource.status = 'published'
          and private.current_user_can_read_student_app(course.student_app_id)
      )
    then
      raise exception '无权下载该资料';
    end if;

    insert into public.library_downloads (
      tenant_id,
      resource_id,
      user_id
    )
    values (
      v_tenant_id,
      p_resource_id,
      auth.uid()
    );
  end if;

  update public.library_resources
  set download_count = download_count + 1
  where id = p_resource_id;
end;
$$;


ALTER FUNCTION public.record_library_download(p_resource_id uuid) OWNER TO postgres;

--
-- Name: record_smart_textbook_attempt(uuid, uuid, uuid, uuid, jsonb, boolean, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_smart_textbook_attempt(p_tenant_id uuid, p_student_id uuid, p_activity_id uuid, p_version_id uuid, p_response jsonb, p_is_correct boolean, p_score numeric) RETURNS TABLE(attempt_number integer, node_completed boolean, completion_percent integer, mastery_score integer, node_attempt_count integer)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_node_id uuid;
  v_max_attempts integer;
  v_attempt_number integer;
  v_total_required integer;
  v_completed_required integer;
  v_completion_percent integer;
  v_mastery_score integer;
  v_node_attempt_count integer;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'SMART_TEXTBOOK_SERVICE_ROLE_REQUIRED' using errcode = '42501';
  end if;

  if p_score is not null and (p_score < 0 or p_score > 100) then
    raise exception 'SMART_TEXTBOOK_SCORE_OUT_OF_RANGE' using errcode = '22023';
  end if;

  select activity.node_id, activity.max_attempts
  into v_node_id, v_max_attempts
  from public.digital_textbook_activities activity
  join public.digital_textbook_nodes node on node.id = activity.node_id
  join public.digital_textbook_modules module on module.id = node.module_id
  join public.digital_textbook_chapters chapter on chapter.id = module.chapter_id
  where activity.id = p_activity_id
    and chapter.version_id = p_version_id;

  if v_node_id is null then
    raise exception 'SMART_TEXTBOOK_ACTIVITY_VERSION_MISMATCH' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(p_tenant_id::text || ':' || p_student_id::text || ':' || p_activity_id::text, 0)
  );

  select coalesce(max(attempt.attempt_number), 0), count(*)::integer
  into v_attempt_number, v_node_attempt_count
  from public.digital_textbook_attempts attempt
  where attempt.tenant_id = p_tenant_id
    and attempt.student_id = p_student_id
    and attempt.activity_id = p_activity_id;

  if v_node_attempt_count >= v_max_attempts then
    raise exception 'MAX_ATTEMPTS_REACHED: %', v_max_attempts using errcode = 'P0001';
  end if;

  v_attempt_number := v_attempt_number + 1;

  insert into public.digital_textbook_attempts (
    tenant_id, student_id, activity_id, version_id, attempt_number,
    response, is_correct, score
  ) values (
    p_tenant_id, p_student_id, p_activity_id, p_version_id, v_attempt_number,
    coalesce(p_response, 'null'::jsonb), p_is_correct, p_score
  );

  perform pg_advisory_xact_lock(
    hashtextextended(p_tenant_id::text || ':' || p_student_id::text || ':' || v_node_id::text, 1)
  );

  select count(*)::integer
  into v_total_required
  from public.digital_textbook_activities activity
  where activity.node_id = v_node_id
    and activity.counts_toward_completion;

  select count(distinct activity.id)::integer
  into v_completed_required
  from public.digital_textbook_activities activity
  join public.digital_textbook_attempts attempt
    on attempt.activity_id = activity.id
   and attempt.tenant_id = p_tenant_id
   and attempt.student_id = p_student_id
   and attempt.version_id = p_version_id
   and attempt.is_correct is true
  where activity.node_id = v_node_id
    and activity.counts_toward_completion;

  v_completion_percent := case
    when v_total_required = 0 then 0
    else round(100.0 * v_completed_required / v_total_required)::integer
  end;

  select coalesce(round(avg(best.best_score)), 0)::integer
  into v_mastery_score
  from (
    select max(attempt.score) as best_score
    from public.digital_textbook_activities activity
    left join public.digital_textbook_attempts attempt
      on attempt.activity_id = activity.id
     and attempt.tenant_id = p_tenant_id
     and attempt.student_id = p_student_id
     and attempt.version_id = p_version_id
    where activity.node_id = v_node_id
      and activity.counts_toward_completion
    group by activity.id
  ) best;

  select count(*)::integer
  into v_node_attempt_count
  from public.digital_textbook_attempts attempt
  join public.digital_textbook_activities activity on activity.id = attempt.activity_id
  where activity.node_id = v_node_id
    and attempt.tenant_id = p_tenant_id
    and attempt.student_id = p_student_id
    and attempt.version_id = p_version_id;

  insert into public.digital_textbook_node_progress (
    tenant_id, student_id, node_id, version_id, status,
    completion_percent, mastery_score, attempt_count,
    last_activity_at, updated_at
  ) values (
    p_tenant_id, p_student_id, v_node_id, p_version_id,
    case when v_total_required > 0 and v_completed_required = v_total_required
      then 'completed' else 'in_progress' end,
    v_completion_percent, v_mastery_score, v_node_attempt_count,
    now(), now()
  )
  on conflict (tenant_id, student_id, node_id, version_id) do update set
    status = excluded.status,
    completion_percent = excluded.completion_percent,
    mastery_score = excluded.mastery_score,
    attempt_count = excluded.attempt_count,
    last_activity_at = excluded.last_activity_at,
    updated_at = excluded.updated_at;

  return query select
    v_attempt_number,
    v_total_required > 0 and v_completed_required = v_total_required,
    v_completion_percent,
    v_mastery_score,
    v_node_attempt_count;
end;
$$;


ALTER FUNCTION public.record_smart_textbook_attempt(p_tenant_id uuid, p_student_id uuid, p_activity_id uuid, p_version_id uuid, p_response jsonb, p_is_correct boolean, p_score numeric) OWNER TO postgres;

--
-- Name: FUNCTION record_smart_textbook_attempt(p_tenant_id uuid, p_student_id uuid, p_activity_id uuid, p_version_id uuid, p_response jsonb, p_is_correct boolean, p_score numeric); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.record_smart_textbook_attempt(p_tenant_id uuid, p_student_id uuid, p_activity_id uuid, p_version_id uuid, p_response jsonb, p_is_correct boolean, p_score numeric) IS 'Service-only compatibility entry point. Legacy open NULL/NULL submissions qualify for completion; false/0 is rejected.';

--
-- Name: record_smart_textbook_attempt(uuid, uuid, uuid, uuid, jsonb, boolean, numeric, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_smart_textbook_attempt(p_tenant_id uuid, p_student_id uuid, p_activity_id uuid, p_version_id uuid, p_response jsonb, p_is_correct boolean, p_score numeric, p_meets_completion_requirements boolean) RETURNS TABLE(attempt_number integer, node_completed boolean, completion_percent integer, mastery_score integer, node_attempt_count integer)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_node_id uuid;
  v_activity_type text;
  v_max_attempts integer;
  v_attempt_number integer;
  v_total_required integer;
  v_completed_required integer;
  v_completion_percent integer;
  v_mastery_score integer;
  v_node_attempt_count integer;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'SMART_TEXTBOOK_SERVICE_ROLE_REQUIRED'
      using errcode = '42501';
  end if;

  if p_score is not null and (p_score < 0 or p_score > 100) then
    raise exception 'SMART_TEXTBOOK_SCORE_OUT_OF_RANGE'
      using errcode = '22023';
  end if;

  select activity.node_id, activity.activity_type, activity.max_attempts
  into v_node_id, v_activity_type, v_max_attempts
  from public.digital_textbook_activities as activity
  join public.digital_textbook_nodes as node on node.id = activity.node_id
  join public.digital_textbook_modules as module on module.id = node.module_id
  join public.digital_textbook_chapters as chapter on chapter.id = module.chapter_id
  where activity.id = p_activity_id
    and chapter.version_id = p_version_id;

  if v_node_id is null then
    raise exception 'SMART_TEXTBOOK_ACTIVITY_VERSION_MISMATCH'
      using errcode = '22023';
  end if;

  if v_activity_type in ('speaking', 'writing', 'self_check') then
    if p_is_correct is not null or p_score is not null then
      raise exception 'SMART_TEXTBOOK_OPEN_ACTIVITY_CANNOT_BE_SCORED'
        using errcode = '22023';
    end if;
    if p_meets_completion_requirements is null then
      raise exception 'SMART_TEXTBOOK_OPEN_ACTIVITY_QUALIFICATION_REQUIRED'
        using errcode = '22023';
    end if;
  elsif p_meets_completion_requirements is not null then
    raise exception 'SMART_TEXTBOOK_OBJECTIVE_ACTIVITY_QUALIFICATION_FORBIDDEN'
      using errcode = '22023';
  end if;

  -- Serialize attempt numbering and max-attempt enforcement per learner/activity.
  perform pg_advisory_xact_lock(
    hashtextextended(
      p_tenant_id::text || ':' || p_student_id::text || ':' || p_activity_id::text,
      0
    )
  );

  select coalesce(max(attempt.attempt_number), 0), count(*)::integer
  into v_attempt_number, v_node_attempt_count
  from public.digital_textbook_attempts as attempt
  where attempt.tenant_id = p_tenant_id
    and attempt.student_id = p_student_id
    and attempt.activity_id = p_activity_id;

  if v_node_attempt_count >= v_max_attempts then
    raise exception 'MAX_ATTEMPTS_REACHED: %', v_max_attempts
      using errcode = 'P0001';
  end if;

  v_attempt_number := v_attempt_number + 1;

  insert into public.digital_textbook_attempts (
    tenant_id, student_id, activity_id, version_id, attempt_number,
    response, is_correct, score, meets_completion_requirements
  ) values (
    p_tenant_id, p_student_id, p_activity_id, p_version_id, v_attempt_number,
    coalesce(p_response, 'null'::jsonb), p_is_correct, p_score,
    coalesce(p_meets_completion_requirements, false)
  );

  -- Keep the attempt and its derived progress update atomic for a learner/node.
  perform pg_advisory_xact_lock(
    hashtextextended(
      p_tenant_id::text || ':' || p_student_id::text || ':' || v_node_id::text,
      1
    )
  );

  select count(*)::integer
  into v_total_required
  from public.digital_textbook_activities as activity
  where activity.node_id = v_node_id
    and activity.counts_toward_completion;

  select count(distinct activity.id)::integer
  into v_completed_required
  from public.digital_textbook_activities as activity
  join public.digital_textbook_attempts as attempt
    on attempt.activity_id = activity.id
   and attempt.tenant_id = p_tenant_id
   and attempt.student_id = p_student_id
   and attempt.version_id = p_version_id
   and (
     attempt.is_correct is true
     or (
       activity.activity_type in ('speaking', 'writing', 'self_check')
       and attempt.meets_completion_requirements
     )
   )
  where activity.node_id = v_node_id
    and activity.counts_toward_completion;

  v_completion_percent := case
    when v_total_required = 0 then 0
    else round(100.0 * v_completed_required / v_total_required)::integer
  end;

  -- Open activities are excluded by type, even if legacy or forged rows ever
  -- contain a numeric score. Only objective activity scores affect mastery.
  select coalesce(round(avg(best.best_score)), 0)::integer
  into v_mastery_score
  from (
    select max(attempt.score) as best_score
    from public.digital_textbook_activities as activity
    left join public.digital_textbook_attempts as attempt
      on attempt.activity_id = activity.id
     and attempt.tenant_id = p_tenant_id
     and attempt.student_id = p_student_id
     and attempt.version_id = p_version_id
    where activity.node_id = v_node_id
      and activity.counts_toward_completion
      and activity.activity_type in (
        'single_choice', 'multiple_choice', 'fill_blank', 'ordering', 'listening'
      )
    group by activity.id
  ) as best;

  select count(*)::integer
  into v_node_attempt_count
  from public.digital_textbook_attempts as attempt
  join public.digital_textbook_activities as activity
    on activity.id = attempt.activity_id
  where activity.node_id = v_node_id
    and attempt.tenant_id = p_tenant_id
    and attempt.student_id = p_student_id
    and attempt.version_id = p_version_id;

  insert into public.digital_textbook_node_progress (
    tenant_id, student_id, node_id, version_id, status,
    completion_percent, mastery_score, attempt_count,
    last_activity_at, updated_at
  ) values (
    p_tenant_id, p_student_id, v_node_id, p_version_id,
    case
      when v_total_required > 0 and v_completed_required = v_total_required
        then 'completed'
      else 'in_progress'
    end,
    v_completion_percent, v_mastery_score, v_node_attempt_count,
    now(), now()
  )
  on conflict (tenant_id, student_id, node_id, version_id) do update set
    status = excluded.status,
    completion_percent = excluded.completion_percent,
    mastery_score = excluded.mastery_score,
    attempt_count = excluded.attempt_count,
    last_activity_at = excluded.last_activity_at,
    updated_at = excluded.updated_at;

  return query select
    v_attempt_number,
    v_total_required > 0 and v_completed_required = v_total_required,
    v_completion_percent,
    v_mastery_score,
    v_node_attempt_count;
end;
$$;


ALTER FUNCTION public.record_smart_textbook_attempt(p_tenant_id uuid, p_student_id uuid, p_activity_id uuid, p_version_id uuid, p_response jsonb, p_is_correct boolean, p_score numeric, p_meets_completion_requirements boolean) OWNER TO postgres;

--
-- Name: FUNCTION record_smart_textbook_attempt(p_tenant_id uuid, p_student_id uuid, p_activity_id uuid, p_version_id uuid, p_response jsonb, p_is_correct boolean, p_score numeric, p_meets_completion_requirements boolean); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.record_smart_textbook_attempt(p_tenant_id uuid, p_student_id uuid, p_activity_id uuid, p_version_id uuid, p_response jsonb, p_is_correct boolean, p_score numeric, p_meets_completion_requirements boolean) IS 'Service-only atomic attempt recorder. Open activities always persist NULL correctness and score, use a separate completion-qualification flag, and never contribute to mastery.';

--
-- Name: record_smart_textbook_speaking_attempt(uuid, uuid, uuid, uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_smart_textbook_speaking_attempt(p_tenant_id uuid, p_student_id uuid, p_activity_id uuid, p_version_id uuid, p_response jsonb, p_evidence_id uuid) RETURNS TABLE(attempt_number integer, node_completed boolean, completion_percent integer, mastery_score integer, node_attempt_count integer)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare
  evidence public.digital_textbook_speaking_evidence%rowtype;
  stored_size bigint;
  stored_mime text;
  recorded_attempt_number integer;
  recorded_node_completed boolean;
  recorded_completion_percent integer;
  recorded_mastery_score integer;
  recorded_node_attempt_count integer;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'SMART_TEXTBOOK_SERVICE_ROLE_REQUIRED'
      using errcode = '42501';
  end if;

  select * into evidence
  from public.digital_textbook_speaking_evidence
  where id = p_evidence_id
  for update;

  if evidence.id is null
    or evidence.tenant_id <> p_tenant_id
    or evidence.student_id <> p_student_id
    or evidence.activity_id <> p_activity_id
    or evidence.consumed_at is not null
    or evidence.created_at < now() - interval '24 hours'
    or evidence.byte_size < 2048
    or evidence.object_key <> (
      p_tenant_id::text || '/' || p_student_id::text || '/' ||
      p_activity_id::text || '/' || p_evidence_id::text ||
      case evidence.mime_type
        when 'audio/ogg' then '.ogg'
        when 'audio/mp4' then '.m4a'
        when 'audio/mpeg' then '.mp3'
        else '.webm'
      end
    )
  then
    raise exception 'SMART_TEXTBOOK_RECORDING_EVIDENCE_INVALID'
      using errcode = '22023';
  end if;

  select
    case
      when object.metadata->>'size' ~ '^[0-9]+$'
        then (object.metadata->>'size')::bigint
      else 0
    end,
    coalesce(object.metadata->>'mimetype', object.metadata->>'contentType')
  into stored_size, stored_mime
  from storage.objects as object
  where object.bucket_id = 'digital-textbook-student-recordings'
    and object.name = evidence.object_key;

  if coalesce(stored_size, 0) < 2048
    or stored_size <> evidence.byte_size
    or split_part(coalesce(stored_mime, ''), ';', 1) <> evidence.mime_type
  then
    raise exception 'SMART_TEXTBOOK_RECORDING_OBJECT_INVALID'
      using errcode = '22023';
  end if;

  select
    result.attempt_number,
    result.node_completed,
    result.completion_percent,
    result.mastery_score,
    result.node_attempt_count
  into
    recorded_attempt_number,
    recorded_node_completed,
    recorded_completion_percent,
    recorded_mastery_score,
    recorded_node_attempt_count
  from public.record_smart_textbook_attempt(
    p_tenant_id,
    p_student_id,
    p_activity_id,
    p_version_id,
    p_response,
    null,
    null,
    true
  ) as result;

  update public.digital_textbook_speaking_evidence
  set consumed_at = now(),
      consumed_attempt_number = recorded_attempt_number
  where id = evidence.id;

  return query select
    recorded_attempt_number,
    recorded_node_completed,
    recorded_completion_percent,
    recorded_mastery_score,
    recorded_node_attempt_count;
end;
$_$;


ALTER FUNCTION public.record_smart_textbook_speaking_attempt(p_tenant_id uuid, p_student_id uuid, p_activity_id uuid, p_version_id uuid, p_response jsonb, p_evidence_id uuid) OWNER TO postgres;

--
-- Name: record_smart_textbook_speaking_attempt_v2(uuid, uuid, uuid, uuid, jsonb, uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_smart_textbook_speaking_attempt_v2(p_tenant_id uuid, p_student_id uuid, p_activity_id uuid, p_version_id uuid, p_response jsonb, p_evidence_id uuid, p_runtime_binding jsonb, p_proof jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare e public.digital_textbook_speaking_evidence; result jsonb; kind text;
begin
  perform recording_private.require_service();
  perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':'||p_student_id::text||':'||p_activity_id::text,0));
  select * into e from public.digital_textbook_speaking_evidence where id=p_evidence_id for update;
  perform recording_private.check_scope(e,p_tenant_id,p_student_id,p_activity_id,p_version_id,p_runtime_binding);
  kind := recording_private.identity(e)->>'kind';
  if kind not in ('independent-output','legacy-speaking') then raise exception 'RECORDING_SPEAKING_KIND'; end if;
  perform recording_private.verify(e,p_version_id,p_runtime_binding,'speaking-completion',p_response,p_proof);
  -- Qualification is issued by the existing application grader, bound into the
  -- signed response. This RPC does not invent a second score or grading policy.
  select to_jsonb(r) into result from public.record_smart_textbook_attempt(
    p_tenant_id,p_student_id,p_activity_id,p_version_id,p_response,null,null,true) r;
  update public.digital_textbook_speaking_evidence set consumed_at=clock_timestamp(),
    consumed_attempt_number=(result->>'attempt_number')::integer,
    metadata=jsonb_set(metadata,'{lifecycle}','"consumed"') where id=e.id;
  return result;
end $$;


ALTER FUNCTION public.record_smart_textbook_speaking_attempt_v2(p_tenant_id uuid, p_student_id uuid, p_activity_id uuid, p_version_id uuid, p_response jsonb, p_evidence_id uuid, p_runtime_binding jsonb, p_proof jsonb) OWNER TO postgres;

--
-- Name: record_student_practice_listening_reviews(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_student_practice_listening_reviews(p_block_id uuid, p_answers jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_tenant_id uuid := private.current_tenant_id();
  v_block public.chapter_practice_blocks%rowtype;
  v_unit public.chapter_practice_units%rowtype;
  v_course_id uuid;
  v_answer jsonb;
  v_question public.growth_toolbox_questions%rowtype;
  v_key public.growth_toolbox_question_keys%rowtype;
  v_response text;
  v_is_correct boolean;
  v_count integer := 0;
begin
  if v_user_id is null or v_tenant_id is null then
    raise exception '请登录后再保存听辨结果';
  end if;
  if jsonb_typeof(p_answers) <> 'array'
    or jsonb_array_length(p_answers) not between 1 and 100 then
    raise exception '听辨作答内容不完整';
  end if;
  select * into v_block
  from public.chapter_practice_blocks
  where id = p_block_id
    and block_type = 'listening'
    and status = 'published';
  select * into v_unit
  from public.chapter_practice_units
  where id = v_block.practice_unit_id
    and status = 'published';
  if v_block.id is null or v_unit.id is null
    or v_block.source_type is distinct from 'growth_toolbox_exercise'
    or v_block.source_id is null
    or not private.current_student_has_app_access(
      v_tenant_id, v_user_id, v_unit.student_app_id
    ) then
    raise exception '听辨内容不存在或当前账号无权保存';
  end if;
  select lesson.course_id into v_course_id
  from public.course_chapters as chapter
  join public.lessons as lesson on lesson.id = chapter.lesson_id
  where chapter.id = v_unit.course_chapter_id;

  for v_answer in select value from jsonb_array_elements(p_answers)
  loop
    begin
      v_response := btrim(v_answer ->> 'response');
      if nullif(v_response, '') is null or char_length(v_response) > 5000 then
        raise exception '听辨答案长度不正确';
      end if;
      select * into v_question
      from public.growth_toolbox_questions
      where id = (v_answer ->> 'questionId')::uuid
        and exercise_id = v_block.source_id;
      select * into v_key
      from public.growth_toolbox_question_keys
      where question_id = v_question.id;
      if v_question.id is null or v_key.question_id is null then
        raise exception '听辨题或答案配置不存在';
      end if;
      select exists (
        select 1
        from jsonb_array_elements_text(v_key.accepted_answers) as accepted(value)
        where lower(regexp_replace(btrim(accepted.value), '[[:space:][:punct:]]+', '', 'g'))
          = lower(regexp_replace(v_response, '[[:space:][:punct:]]+', '', 'g'))
      ) into v_is_correct;
      if v_is_correct then continue; end if;

      perform private.merge_student_review_item(
        v_tenant_id, v_user_id, v_unit.student_app_id,
        'practice_self_check', v_unit.id, v_question.id,
        v_course_id, v_unit.course_chapter_id, 'listening',
        jsonb_build_object(
          'sourceVersion', v_unit.version,
          'sourceTitle', v_unit.title,
          'blockTitle', v_block.title,
          'sourceBlockId', v_block.id,
          'sourceExerciseId', v_block.source_id,
          'prompt', v_question.prompt,
          'questionType', v_question.question_type,
          'content', v_question.content_payload,
          'maxScore', v_question.max_score
        ),
        jsonb_build_object('answer', v_response),
        jsonb_build_object(
          'acceptedAnswers', v_key.accepted_answers,
          'correctAnswer', v_key.accepted_answers -> 0,
          'explanation', v_key.explanation,
          'improvementTask', '重听本题材料，对照解析完成一次正确作答。'
        ),
        now(), 1, now()
      );
      v_count := v_count + 1;
    exception when others then
      raise exception '听辨错题校验失败：%', sqlerrm;
    end;
  end loop;
  return v_count;
end;
$$;


ALTER FUNCTION public.record_student_practice_listening_reviews(p_block_id uuid, p_answers jsonb) OWNER TO postgres;

--
-- Name: FUNCTION record_student_practice_listening_reviews(p_block_id uuid, p_answers jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.record_student_practice_listening_reviews(p_block_id uuid, p_answers jsonb) IS '学生听辨进度保存成功后调用；使用发布题目私有答案归集错题。';

--
-- Name: record_student_practice_self_check_review(uuid, uuid, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_student_practice_self_check_review(p_practice_unit_id uuid, p_block_id uuid, p_review_topics text[]) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_tenant_id uuid := private.current_tenant_id();
  v_unit public.chapter_practice_units%rowtype;
  v_block public.chapter_practice_blocks%rowtype;
  v_course_id uuid;
  v_topics text[];
  v_topic text;
  v_skill_key text;
begin
  if v_user_id is null or v_tenant_id is null then
    raise exception '请登录后再保存自我检测';
  end if;
  select * into v_unit
  from public.chapter_practice_units
  where id = p_practice_unit_id and status = 'published';
  select * into v_block
  from public.chapter_practice_blocks
  where id = p_block_id
    and practice_unit_id = p_practice_unit_id
    and block_type = 'self_check'
    and status = 'published';
  if v_unit.id is null or v_block.id is null
    or not private.current_student_has_app_access(
      v_tenant_id, v_user_id, v_unit.student_app_id
    ) then
    raise exception '自我检测内容不存在或当前账号无权保存';
  end if;
  if coalesce(array_length(p_review_topics, 1), 0) = 0 then return null; end if;
  if array_length(p_review_topics, 1) > 20
    or exists (select 1 from unnest(p_review_topics) as topic where char_length(topic) > 500) then
    raise exception '待加强主题数量或长度不正确';
  end if;

  if jsonb_typeof(v_block.content_payload -> 'skills') = 'array' then
    select array_agg(distinct btrim(value)) into v_topics
    from jsonb_array_elements_text(v_block.content_payload -> 'skills') as value
    where btrim(value) <> '';
  elsif jsonb_typeof(v_block.content_payload -> 'skills') = 'object' then
    select array_agg(distinct btrim(value)) into v_topics
    from jsonb_each_text(v_block.content_payload -> 'skills')
    where btrim(value) <> '';
  elsif nullif(btrim(v_block.content_payload ->> 'prompt'), '') is not null then
    v_topics := array[btrim(v_block.content_payload ->> 'prompt')];
  else
    v_topics := array[v_unit.title];
  end if;
  if exists (
    select 1 from unnest(p_review_topics) as requested(topic)
    where not (requested.topic = any(coalesce(v_topics, array[]::text[])))
  ) then
    raise exception '待加强主题与当前发布内容不一致';
  end if;

  v_topic := p_review_topics[1];
  if jsonb_typeof(v_block.content_payload -> 'skills') = 'object' then
    select key into v_skill_key
    from jsonb_each_text(v_block.content_payload -> 'skills')
    where value = v_topic
    limit 1;
  end if;
  select lesson.course_id into v_course_id
  from public.course_chapters as chapter
  join public.lessons as lesson on lesson.id = chapter.lesson_id
  where chapter.id = v_unit.course_chapter_id;

  return private.merge_student_review_item(
    v_tenant_id, v_user_id, v_unit.student_app_id,
    'practice_self_check', v_unit.id, v_block.id,
    v_course_id, v_unit.course_chapter_id,
    coalesce(v_skill_key, v_topic),
    jsonb_build_object(
      'sourceVersion', v_unit.version,
      'sourceTitle', v_unit.title,
      'blockTitle', v_block.title,
      'prompt', '判断本章主题是否已经掌握',
      'topics', v_topics,
      'reviewTopics', p_review_topics,
      'sourceBlockType', v_block.block_type
    ),
    jsonb_build_object(
      'reviewTopics', p_review_topics,
      'answer', '还需加强'
    ),
    jsonb_build_object(
      'expectedAnswer', '已经掌握',
      'improvementTask', '回看待加强主题并完成对应练习后，再次进行自我检测。'
    ),
    now(), 1, now()
  );
end;
$$;


ALTER FUNCTION public.record_student_practice_self_check_review(p_practice_unit_id uuid, p_block_id uuid, p_review_topics text[]) OWNER TO postgres;

--
-- Name: FUNCTION record_student_practice_self_check_review(p_practice_unit_id uuid, p_block_id uuid, p_review_topics text[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.record_student_practice_self_check_review(p_practice_unit_id uuid, p_block_id uuid, p_review_topics text[]) IS '学生巩固自测保存成功后调用；只归集当前发布内容中标记为还需加强的主题。';

--
-- Name: recording_domain_request_v1(text, uuid, text, bigint, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.recording_domain_request_v1(p_operation text, p_request_id uuid, p_instance_id text, p_epoch bigint, p_tenant_id uuid, p_student_id uuid, p_domain text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare c recording_private.domain_control%rowtype;
  r recording_private.domain_requests%rowtype; actual_domain text;
begin
  if auth.role() is distinct from 'service_role' then raise exception 'RECORDING_FORBIDDEN'; end if;
  -- All admission/check/release/control operations take this same lock first.
  select * into strict c from recording_private.domain_control where singleton for update;
  if p_operation = 'release' then
    delete from recording_private.domain_requests where id=p_request_id and instance_id=p_instance_id
      and epoch=p_epoch and tenant_id=p_tenant_id and student_id=p_student_id and domain=p_domain
      and uploading_evidence_id is null;
    if not found then raise exception 'RECORDING_LEASE_MISMATCH'; end if;
    return jsonb_build_object('released',true);
  end if;
  actual_domain := case when c.enabled and c.cohort @> jsonb_build_array(jsonb_build_object(
    'tenantId',p_tenant_id::text,'studentId',p_student_id::text)) then 'v2' else 'v1' end;
  if p_epoch is distinct from c.epoch or p_domain is distinct from actual_domain
    or not exists(select 1 from recording_private.domain_instances where id=p_instance_id and acknowledged_epoch=c.epoch)
    then raise exception 'RECORDING_EPOCH_MISMATCH'; end if;
  if p_operation = 'enter' then
    if c.state <> 'open' then raise exception 'RECORDING_DRAINING'; end if;
    -- Rollback is deliberately conservative across this learner's whole domain.
    if p_domain='v1' and exists(select 1 from public.digital_textbook_speaking_evidence e
      where e.tenant_id=p_tenant_id and e.student_id=p_student_id and
        (e.metadata ? 'runtimeBinding' or e.metadata ? 'lifecycle'))
      then raise exception 'RECORDING_ROLLBACK_FENCED'; end if;
    insert into recording_private.domain_requests(id,instance_id,epoch,tenant_id,student_id,domain)
      values(p_request_id,p_instance_id,p_epoch,p_tenant_id,p_student_id,p_domain);
  elsif p_operation = 'check' then
    select * into r from recording_private.domain_requests where id=p_request_id;
    if not found or r.instance_id is distinct from p_instance_id or r.epoch is distinct from p_epoch
      or r.tenant_id is distinct from p_tenant_id or r.student_id is distinct from p_student_id
      or r.domain is distinct from p_domain or c.state='fenced'
      then raise exception 'RECORDING_LEASE_MISMATCH'; end if;
    -- Already admitted requests may finish while draining; switch is prohibited
    -- until their leases (including cleanup/retries) have all been released.
  else raise exception 'RECORDING_OPERATION_INVALID'; end if;
  return jsonb_build_object('epoch',c.epoch,'domain',actual_domain,'requestId',p_request_id);
end $$;


ALTER FUNCTION public.recording_domain_request_v1(p_operation text, p_request_id uuid, p_instance_id text, p_epoch bigint, p_tenant_id uuid, p_student_id uuid, p_domain text) OWNER TO postgres;

--
-- Name: recording_domain_upload_v1(text, uuid, text, bigint, uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.recording_domain_upload_v1(p_operation text, p_request_id uuid, p_instance_id text, p_epoch bigint, p_tenant_id uuid, p_student_id uuid, p_domain text, p_evidence_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform public.recording_domain_request_v1('check',p_request_id,p_instance_id,p_epoch,p_tenant_id,p_student_id,p_domain);
  if p_domain <> 'v2' or p_evidence_id is null then raise exception 'RECORDING_OPERATION_INVALID'; end if;
  if p_operation='reserve' then
    if exists(select 1 from public.digital_textbook_speaking_evidence where id=p_evidence_id)
      then raise exception 'RECORDING_UPLOAD_ID_CONFLICT'; end if;
    update recording_private.domain_requests set uploading_evidence_id=p_evidence_id
      where id=p_request_id and uploading_evidence_id is null;
    if not found then raise exception 'RECORDING_UPLOAD_CONFLICT'; end if;
  elsif p_operation='settle' then
    update recording_private.domain_requests set uploading_evidence_id=null
      where id=p_request_id and uploading_evidence_id=p_evidence_id;
    if not found then raise exception 'RECORDING_UPLOAD_CONFLICT'; end if;
  elsif p_operation='assert-settled' then
    if exists(select 1 from recording_private.domain_requests where uploading_evidence_id=p_evidence_id)
      then raise exception 'RECORDING_UPLOAD_PENDING'; end if;
  else raise exception 'RECORDING_OPERATION_INVALID'; end if;
  return jsonb_build_object('ok',true);
end $$;


ALTER FUNCTION public.recording_domain_upload_v1(p_operation text, p_request_id uuid, p_instance_id text, p_epoch bigint, p_tenant_id uuid, p_student_id uuid, p_domain text, p_evidence_id uuid) OWNER TO postgres;

--
-- Name: reissue_course_completion_certificate(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reissue_course_completion_certificate(p_certificate_id uuid, p_reason text, p_evaluation_id uuid DEFAULT NULL::uuid) RETURNS public.course_completion_certificates
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_actor_name text;
  v_previous public.course_completion_certificates;
  v_existing public.course_completion_certificates;
  v_evaluation public.student_course_completion_evaluations;
  v_certificate public.course_completion_certificates;
  v_student_name text;
  v_course_title text;
  v_reason text := nullif(btrim(p_reason), '');
  v_now timestamptz := clock_timestamp();
begin
  if v_actor_id is null then
    raise exception '必须登录后重新颁发证书';
  end if;
  if v_reason is null or char_length(v_reason) not between 2 and 1000 then
    raise exception '重新颁发必须提供 2 至 1000 字的审核原因';
  end if;

  select certificate.* into v_previous
  from public.course_completion_certificates as certificate
  where certificate.id = p_certificate_id
  for update;

  if not found then
    raise exception '原证书不存在';
  end if;
  if not private.current_actor_can_issue_tenant_certificate(v_previous.tenant_id) then
    raise exception '只有对应机构负责人可以重新颁发本机构证书';
  end if;

  if v_previous.status = 'reissued' then
    select certificate.* into v_existing
    from public.course_completion_certificates as certificate
    where certificate.reissued_from_id = v_previous.id;
    if found then
      return v_existing;
    end if;
  end if;
  if v_previous.status <> 'revoked' then
    raise exception '只有 revoked 状态的证书可以重新颁发';
  end if;

  select evaluation.* into v_evaluation
  from public.student_course_completion_evaluations as evaluation
  where evaluation.id = coalesce(p_evaluation_id, v_previous.evaluation_id)
  for update;

  if not found then
    raise exception '重新颁发使用的结课资格记录不存在';
  end if;
  if v_evaluation.status <> 'eligible' or not v_evaluation.eligible then
    raise exception '重新颁发仍必须使用 eligible 状态的结课资格记录';
  end if;
  if (
    v_evaluation.tenant_id,
    v_evaluation.student_id,
    v_evaluation.student_app_id,
    v_evaluation.course_id
  ) is distinct from (
    v_previous.tenant_id,
    v_previous.student_id,
    v_previous.student_app_id,
    v_previous.course_id
  ) then
    raise exception '重新颁发资格必须属于原证书的同一机构、学生和课程';
  end if;

  select nullif(btrim(profile.full_name), '') into v_student_name
  from public.profiles as profile
  where profile.id = v_previous.student_id;
  if v_student_name is null then
    raise exception '重新颁发证书前必须填写学生姓名';
  end if;

  select nullif(btrim(course.title), '') into v_course_title
  from public.courses as course
  where course.id = v_previous.course_id
    and course.student_app_id = v_previous.student_app_id;
  if v_course_title is null then
    raise exception '原证书对应的课程不存在或课程名称为空';
  end if;

  select coalesce(nullif(btrim(profile.full_name), ''), '机构负责人')
  into v_actor_name
  from public.profiles as profile
  where profile.id = v_actor_id;

  insert into public.course_completion_certificates (
    tenant_id, student_id, student_app_id, course_id, evaluation_id,
    status, student_name_snapshot, course_title_snapshot,
    policy_snapshot, evidence_snapshot, overall_score_snapshot,
    issued_by, issued_at, reissued_from_id, created_at
  ) values (
    v_evaluation.tenant_id,
    v_evaluation.student_id,
    v_evaluation.student_app_id,
    v_evaluation.course_id,
    v_evaluation.id,
    'issued',
    v_student_name,
    v_course_title,
    jsonb_build_object(
      'policyId', v_evaluation.policy_id,
      'policyVersion', v_evaluation.policy_version,
      'evaluationVersion', v_evaluation.evaluation_version,
      'evaluatedAt', v_evaluation.evaluated_at,
      'requirements', v_evaluation.requirements_snapshot
    ),
    v_evaluation.evidence_snapshot,
    v_evaluation.overall_score,
    v_actor_id,
    v_now,
    v_previous.id,
    v_now
  ) returning * into v_certificate;

  update public.course_completion_certificates
  set status = 'reissued'
  where id = v_previous.id;

  insert into public.course_completion_certificate_events (
    tenant_id, certificate_id, event_type, actor_id,
    actor_name_snapshot, reason, metadata, created_at
  ) values (
    v_certificate.tenant_id,
    v_certificate.id,
    'reissued',
    v_actor_id,
    v_actor_name,
    v_reason,
    jsonb_build_object(
      'reissuedFromId', v_previous.id,
      'previousCertificateNumber', v_previous.certificate_number,
      'evaluationId', v_evaluation.id
    ),
    v_now
  );

  return v_certificate;
end;
$$;


ALTER FUNCTION public.reissue_course_completion_certificate(p_certificate_id uuid, p_reason text, p_evaluation_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION reissue_course_completion_certificate(p_certificate_id uuid, p_reason text, p_evaluation_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.reissue_course_completion_certificate(p_certificate_id uuid, p_reason text, p_evaluation_id uuid) IS '对应机构负责人基于 eligible 资格重新颁发新编号；第三参数可指定同一学生课程的新版资格。';

--
-- Name: release_current_user_due_assignment_grades(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.release_current_user_due_assignment_grades() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_released integer;
begin
  if auth.uid() is null or public.current_profile_role() <> 'student'
    or not public.is_active_account() then
    return 0;
  end if;

  update public.learning_submissions as submission
  set status = 'graded', score = submission.computed_score,
      submission_state = 'grade_released', grade_released_at = now(),
      updated_at = now()
  from public.learning_assignments as assignment
  where assignment.tenant_id = submission.tenant_id
    and assignment.id = submission.assignment_id
    and submission.tenant_id = private.current_tenant_id()
    and submission.student_id = auth.uid()
    and submission.submission_state = 'grading_completed'
    and submission.grade_release_confirmed_at is not null
    and assignment.grade_release_at is not null
    and assignment.grade_release_at <= now();
  get diagnostics v_released = row_count;
  return v_released;
end;
$$;


ALTER FUNCTION public.release_current_user_due_assignment_grades() OWNER TO postgres;

--
-- Name: release_learning_submission_grade(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.release_learning_submission_grade(p_submission_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_submission public.learning_submissions%rowtype;
  v_assignment public.learning_assignments%rowtype;
  v_release_now boolean;
begin
  select submission.* into v_submission
  from public.learning_submissions as submission
  join public.learning_assignments as assignment
    on assignment.tenant_id = submission.tenant_id
   and assignment.id = submission.assignment_id
  where submission.id = p_submission_id
    and submission.tenant_id = private.current_tenant_id()
    and private.current_staff_has_app_capability(
      assignment.tenant_id, assignment.student_app_id, 'manage_assessments'
    )
    and (
      public.current_profile_role() <> 'teacher'
      or private.current_teacher_has_student_app_access(
        assignment.tenant_id, submission.student_id, assignment.student_app_id
      )
    )
  for update of submission;

  if v_submission.id is null then
    raise exception '提交记录不存在或当前账号没有该应用的发布权限';
  end if;
  select assignment.* into v_assignment
  from public.learning_assignments as assignment
  where assignment.id = v_submission.assignment_id
    and assignment.tenant_id = v_submission.tenant_id;
  if v_submission.submission_state <> 'grading_completed'
    or v_submission.computed_score is null
    or v_submission.grading_completed_at is null then
    raise exception '只有完成全部批改后才能发布成绩';
  end if;
  if exists (
    select 1 from public.learning_submission_answers as answer
    where answer.tenant_id = v_submission.tenant_id
      and answer.submission_id = v_submission.id
      and answer.awarded_points is null
  ) then
    raise exception '仍有主观题未完成评分，不能发布成绩';
  end if;

  v_release_now := v_assignment.grade_release_at is null
    or v_assignment.grade_release_at <= now();
  update public.learning_submissions
  set grade_release_confirmed_at = now(),
      grade_release_confirmed_by = auth.uid(),
      status = case when v_release_now then 'graded' else 'submitted' end,
      score = case when v_release_now then computed_score else null end,
      submission_state = case when v_release_now
        then 'grade_released' else 'grading_completed' end,
      grade_released_at = case when v_release_now then now() else null end,
      updated_at = now()
  where id = v_submission.id and tenant_id = v_submission.tenant_id;

  return jsonb_build_object(
    'released', v_release_now,
    'scheduled', not v_release_now,
    'releaseAt', v_assignment.grade_release_at
  );
end;
$$;


ALTER FUNCTION public.release_learning_submission_grade(p_submission_id uuid) OWNER TO postgres;

--
-- Name: replace_chapter_test_questions(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.replace_chapter_test_questions(p_test_id uuid, p_question_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_requested_count integer;
  v_valid_count integer;
begin
  if not public.current_user_can_manage_assessment_papers() then
    raise exception '只有平台负责人或指定管理员可以设置章节测试题目';
  end if;

  if not exists (
    select 1
    from public.course_tests
    where id = p_test_id
      and status <> 'archived'
  ) then
    raise exception '章节测试不存在或已经归档';
  end if;

  select count(distinct question_id)
  into v_requested_count
  from unnest(coalesce(p_question_ids, array[]::uuid[])) as question_id;

  if v_requested_count not between 1 and 100 then
    raise exception '章节测试需要选择 1 至 100 道题目';
  end if;

  if cardinality(coalesce(p_question_ids, array[]::uuid[])) <> v_requested_count then
    raise exception '选题中不能包含重复题目';
  end if;

  select count(*)
  into v_valid_count
  from public.course_test_questions
  where id = any(p_question_ids)
    and test_id = p_test_id
    and status = 'published'
    and question_type = 'single_choice';

  if v_valid_count <> v_requested_count then
    raise exception '选题中包含不属于本章、未发布或非单选题的内容';
  end if;

  update public.course_test_questions
  set is_chapter_test_item = id = any(p_question_ids),
      updated_by = auth.uid(),
      updated_at = now()
  where test_id = p_test_id
    and question_type = 'single_choice';

  update public.course_tests
  set version = version + 1,
      updated_at = now()
  where id = p_test_id;

  return v_requested_count;
end;
$$;


ALTER FUNCTION public.replace_chapter_test_questions(p_test_id uuid, p_question_ids uuid[]) OWNER TO postgres;

--
-- Name: FUNCTION replace_chapter_test_questions(p_test_id uuid, p_question_ids uuid[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.replace_chapter_test_questions(p_test_id uuid, p_question_ids uuid[]) IS '平台按难度随机选题后，原子替换指定章节当前提供给学生的测试题目。';

--
-- Name: request_grade_review(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.request_grade_review(p_record_id uuid, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_student uuid; v_item_status text; v_id uuid;
begin
  select record.student_id, item.status into v_student, v_item_status
  from public.grade_records as record
  join public.grade_items as item on item.id = record.item_id
  where record.id = p_record_id and record.tenant_id = private.current_tenant_id();
  if v_student is distinct from auth.uid() or v_item_status is distinct from 'published' then raise exception '无权申请该成绩复核'; end if;
  if char_length(trim(coalesce(p_reason, ''))) not between 2 and 2000 then raise exception '复核原因需要填写 2 至 2000 个字'; end if;
  if exists (select 1 from public.grade_review_requests where record_id = p_record_id and status in ('pending','reviewing')) then raise exception '该成绩已有正在处理的复核申请'; end if;
  insert into public.grade_review_requests (record_id, student_id, reason)
  values (p_record_id, auth.uid(), trim(p_reason))
  on conflict (record_id) do update set reason = excluded.reason, status = 'pending', response = '', handled_by = null, requested_at = now(), handled_at = null, updated_at = now()
  returning id into v_id;
  return v_id;
end;
$$;


ALTER FUNCTION public.request_grade_review(p_record_id uuid, p_reason text) OWNER TO postgres;

--
-- Name: request_institution_course_completion_refresh(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.request_institution_course_completion_refresh(p_course_id uuid, p_student_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tenant_id uuid := private.current_tenant_id();
  v_student_app_id uuid;
  v_task_id uuid;
begin
  select course.student_app_id into v_student_app_id
  from public.courses as course where course.id = p_course_id;

  if auth.uid() is null or v_tenant_id is null or v_student_app_id is null
    or not private.current_staff_has_app_capability(
      v_tenant_id, v_student_app_id, 'manage_assessments'
    ) then
    raise exception '当前账号没有该课程的结课资格刷新权限';
  end if;

  if p_student_id is not null and not exists (
    select 1
    from public.tenant_memberships as membership
    join public.student_app_enrollments as enrollment
      on enrollment.tenant_id = membership.tenant_id
     and enrollment.student_id = membership.user_id
     and enrollment.app_id = v_student_app_id
     and enrollment.status = 'active'
     and enrollment.starts_at <= now()
     and (enrollment.ends_at is null or enrollment.ends_at > now())
    where membership.tenant_id = v_tenant_id
      and membership.user_id = p_student_id
      and membership.role = 'student'
      and membership.status = 'active'
  ) then
    raise exception '该学生不在当前机构或没有该课程应用的有效学籍';
  end if;

  v_task_id := private.enqueue_completion_refresh_task(
    'institution_manual', v_tenant_id, p_student_id, v_student_app_id,
    p_course_id, null, 'institution', v_tenant_id::text,
    case when p_student_id is null then '机构手动批量刷新结课资格'
      else '机构手动刷新单学生结课资格' end,
    'institution-manual:' || gen_random_uuid()::text, auth.uid(), now()
  );
  return v_task_id;
end;
$$;


ALTER FUNCTION public.request_institution_course_completion_refresh(p_course_id uuid, p_student_id uuid) OWNER TO postgres;

--
-- Name: request_source_grade_review(text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.request_source_grade_review(p_source_type text, p_source_result_id uuid, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tenant_id uuid := private.current_tenant_id();
  v_review_id uuid;
  v_existing_status text;
  v_source_title text;
  v_source_score numeric;
  v_source_total numeric;
  v_source_context jsonb := '{}'::jsonb;
begin
  if auth.uid() is null then
    raise exception '请先登录后再申请成绩复核';
  end if;

  if p_source_type not in ('assignment_submission', 'chapter_test_attempt') then
    raise exception '成绩来源不正确';
  end if;

  if char_length(trim(coalesce(p_reason, ''))) not between 2 and 2000 then
    raise exception '复核原因需要填写 2 至 2000 个字';
  end if;

  -- 同一学生对同一条成绩的复核申请必须串行处理，避免双击并发时
  -- 两个事务都读到"尚无申请"，其中一个撞唯一索引报出原始数据库错误。
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      coalesce(v_tenant_id::text, '') || ':' || auth.uid()::text || ':' ||
        p_source_type || ':' || p_source_result_id::text,
      0
    )
  );

  if p_source_type = 'assignment_submission' then
    select
      assignment.title,
      submission.score,
      assignment.total_points,
      jsonb_build_object(
        'assignment_id', assignment.id,
        'assignment_type', assignment.assignment_type,
        'attempt_number', submission.attempt_number
      )
    into
      v_source_title,
      v_source_score,
      v_source_total,
      v_source_context
    from public.learning_submissions as submission
    join public.learning_assignments as assignment
      on assignment.tenant_id = submission.tenant_id
     and assignment.id = submission.assignment_id
    where submission.tenant_id = v_tenant_id
      and submission.id = p_source_result_id
      and submission.student_id = auth.uid()
      and submission.status = 'graded'
      and submission.score is not null;
  else
    select
      coalesce(test.title, attempt.test_slug),
      attempt.score,
      100,
      jsonb_build_object(
        'test_slug', attempt.test_slug,
        'correct_count', attempt.correct_count,
        'total_questions', attempt.total_questions,
        'passed', attempt.passed
      )
    into
      v_source_title,
      v_source_score,
      v_source_total,
      v_source_context
    from public.chapter_test_attempts as attempt
    left join public.chapter_tests as test
      on test.slug = attempt.test_slug
    where attempt.tenant_id = v_tenant_id
      and attempt.id = p_source_result_id
      and attempt.student_id = auth.uid();
  end if;

  if v_source_title is null then
    raise exception '未找到可复核的成绩记录';
  end if;

  select review.id, review.status
  into v_review_id, v_existing_status
  from public.grade_review_requests as review
  where review.tenant_id = v_tenant_id
    and review.student_id = auth.uid()
    and review.source_type = p_source_type
    and review.source_result_id = p_source_result_id;

  if v_existing_status in ('pending', 'reviewing') then
    raise exception '该成绩已有正在处理的复核申请';
  end if;

  if v_review_id is null then
    insert into public.grade_review_requests (
      tenant_id,
      record_id,
      student_id,
      source_type,
      source_result_id,
      source_title,
      source_score,
      source_total_points,
      source_context,
      reason
    )
    values (
      v_tenant_id,
      null,
      auth.uid(),
      p_source_type,
      p_source_result_id,
      v_source_title,
      v_source_score,
      v_source_total,
      v_source_context,
      trim(p_reason)
    )
    returning id into v_review_id;
  else
    update public.grade_review_requests
    set
      source_title = v_source_title,
      source_score = v_source_score,
      source_total_points = v_source_total,
      source_context = v_source_context,
      reason = trim(p_reason),
      status = 'pending',
      response = '',
      handled_by = null,
      requested_at = now(),
      handled_at = null,
      updated_at = now()
    where id = v_review_id;
  end if;

  return v_review_id;
end;
$$;


ALTER FUNCTION public.request_source_grade_review(p_source_type text, p_source_result_id uuid, p_reason text) OWNER TO postgres;

--
-- Name: FUNCTION request_source_grade_review(p_source_type text, p_source_result_id uuid, p_reason text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.request_source_grade_review(p_source_type text, p_source_result_id uuid, p_reason text) IS '学生针对本人真实作业提交或章节测试结果发起成绩复核；同一来源的申请用 advisory lock 串行化，避免并发重复申请撞唯一索引报出原始数据库错误。';

--
-- Name: require_visa_channel_before_stage_nine(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.require_visa_channel_before_stage_nine() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.application_stage >= 9 and new.visa_application_channel is null then
    raise exception '请先确认签证办理方式，再点亮第九步';
  end if;
  return new;
end;
$$;


