-- Name: FUNCTION require_visa_channel_before_stage_nine(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.require_visa_channel_before_stage_nine() IS '禁止未确认签证办理通道的大学申请进入第九步';

--
-- Name: resolve_grade_review(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resolve_grade_review(p_review_id uuid, p_status text, p_response text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tenant_id uuid := private.current_tenant_id();
  v_student_id uuid;
  v_app_id uuid;
begin
  select review.student_id, private.grade_review_student_app_id(review.id)
    into v_student_id, v_app_id
  from public.grade_review_requests as review
  where review.id = p_review_id
    and review.tenant_id = v_tenant_id;

  if v_app_id is null
    or not private.current_staff_has_app_capability(
      v_tenant_id, v_app_id, 'manage_assessments'
    )
    or (
      public.current_profile_role() = 'teacher'
      and not private.current_teacher_has_student_app_access(
        v_tenant_id, v_student_id, v_app_id
      )
    ) then
    raise exception '复核申请不存在或当前账号没有该应用的处理权限';
  end if;
  if p_status not in ('reviewing', 'resolved', 'rejected')
    or char_length(trim(coalesce(p_response, ''))) > 3000 then
    raise exception '复核状态或回复不正确';
  end if;

  update public.grade_review_requests
  set status = p_status,
      response = trim(coalesce(p_response, '')),
      handled_by = auth.uid(),
      handled_at = case
        when p_status in ('resolved', 'rejected') then now()
        else null
      end,
      updated_at = now()
  where id = p_review_id
    and tenant_id = v_tenant_id;
end;
$$;


ALTER FUNCTION public.resolve_grade_review(p_review_id uuid, p_status text, p_response text) OWNER TO postgres;

--
-- Name: review_chapter_practice_binding(uuid, uuid, integer, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.review_chapter_practice_binding(p_app_id uuid, p_chapter_id uuid, p_expected_revision integer, p_expected_snapshot jsonb, p_enabled boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  source_version uuid;
  current_snapshot jsonb;
  result_id uuid;
begin
  if auth.uid() is null or not coalesce(private.is_platform_owner(), false) then
    raise exception '没有权限维护教材练习关联';
  end if;
  if p_enabled is null or p_expected_revision is null or p_expected_revision < 0 then
    raise exception '无效的复核请求';
  end if;
  if not p_enabled then
    update public.chapter_practice_bindings set is_enabled = false,
      revision = revision + 1, reviewed_at = now(), reviewed_by = auth.uid()
    where student_app_id = p_app_id and chapter_id = p_chapter_id and revision = p_expected_revision
    returning id into result_id;
    if result_id is null then raise exception '关联已被修改，请刷新后重新核对'; end if;
    return result_id;
  end if;

  perform runtime_publish_private.authoring_lock();
  -- Lock authoring rows so an in-place edit cannot slip between comparison and approval.
  select v.id into source_version
  from public.digital_textbook_chapters c
  join public.digital_textbook_versions v on v.id = c.version_id
  join public.digital_textbooks t on t.id = v.textbook_id
  where c.id = p_chapter_id and t.student_app_id = p_app_id
    and c.status = 'published' and v.status = 'published' and t.status = 'published'
  for share of c, v, t;
  if source_version is null then raise exception '只能关联当前应用已发布的教材章节'; end if;
  perform m.id from public.digital_textbook_modules m where m.chapter_id = p_chapter_id for share;
  perform n.id from public.digital_textbook_nodes n
    join public.digital_textbook_modules m on m.id = n.module_id
    where m.chapter_id = p_chapter_id for share of n;

  if exists(select 1 from public.digital_textbook_nodes n join public.digital_textbook_modules m on m.id=n.module_id
    where m.chapter_id=p_chapter_id and m.module_code='grammar' and n.content ? 'grammarCards'
    and jsonb_typeof(n.content->'grammarCards') is distinct from 'array') then raise exception '语法卡格式无效，请核对教材来源'; end if;
  if exists(select 1 from public.digital_textbook_nodes n join public.digital_textbook_modules m on m.id=n.module_id
    cross join lateral jsonb_array_elements(case when jsonb_typeof(n.content->'grammarCards')='array' then n.content->'grammarCards' else '[]'::jsonb end)e
    where m.chapter_id=p_chapter_id and m.module_code='grammar' and not private.valid_textbook_grammar_card(e)) then raise exception '语法卡格式无效，请核对教材来源'; end if;

  select coalesce(jsonb_agg(jsonb_build_object('nodeId', items.node_id, 'kind', items.kind, 'value', items.value)
    order by items.node_id, items.kind, items.ordinality), '[]'::jsonb) into current_snapshot
  from (
    select n.id as node_id, m.module_code as kind, elem.value, elem.ordinality
    from public.digital_textbook_nodes n
    join public.digital_textbook_modules m on m.id = n.module_id
    cross join lateral jsonb_array_elements(
      (case when jsonb_typeof(n.content -> m.module_code) = 'array' then n.content -> m.module_code else '[]'::jsonb end)
      || (case when m.module_code='grammar' and jsonb_typeof(n.content->'grammarCards')='array' then n.content->'grammarCards' else '[]'::jsonb end)
    ) with ordinality elem(value, ordinality)
    where m.chapter_id = p_chapter_id and m.module_code in ('vocabulary', 'grammar')
      and jsonb_typeof(elem.value) = 'object'
      and case when m.module_code = 'vocabulary' then
        coalesce(elem.value->>'ko', '') <> '' or coalesce(elem.value->>'zh', '') <> ''
      else coalesce(elem.value->>'title', '') <> '' or coalesce(elem.value->>'form','') <> '' end
  ) items;
  if current_snapshot = '[]'::jsonb or current_snapshot is distinct from p_expected_snapshot then
    raise exception '教材内容已变化或为空，请刷新并重新核对后再确认';
  end if;
  if p_expected_revision = 0 then
    insert into public.chapter_practice_bindings (student_app_id, chapter_id, version_id, snapshot, reviewed_by)
    values (p_app_id, p_chapter_id, source_version, current_snapshot, auth.uid())
    on conflict (student_app_id, chapter_id) do nothing returning id into result_id;
  else
    update public.chapter_practice_bindings set snapshot = current_snapshot, version_id = source_version,
      is_enabled = true, revision = revision + 1, reviewed_at = now(), reviewed_by = auth.uid()
    where student_app_id = p_app_id and chapter_id = p_chapter_id and revision = p_expected_revision
    returning id into result_id;
  end if;
  if result_id is null then raise exception '关联已被修改，请刷新后重新核对'; end if;
  return result_id;
end;
$$;


ALTER FUNCTION public.review_chapter_practice_binding(p_app_id uuid, p_chapter_id uuid, p_expected_revision integer, p_expected_snapshot jsonb, p_enabled boolean) OWNER TO postgres;

--
-- Name: revoke_course_completion_certificate(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.revoke_course_completion_certificate(p_certificate_id uuid, p_reason text) RETURNS public.course_completion_certificates
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_actor_name text;
  v_certificate public.course_completion_certificates;
  v_reason text := nullif(btrim(p_reason), '');
  v_now timestamptz := clock_timestamp();
begin
  if v_actor_id is null then
    raise exception '必须登录后撤销证书';
  end if;
  if v_reason is null or char_length(v_reason) not between 2 and 1000 then
    raise exception '撤销证书必须提供 2 至 1000 字的明确原因';
  end if;

  select certificate.* into v_certificate
  from public.course_completion_certificates as certificate
  where certificate.id = p_certificate_id
  for update;

  if not found then
    raise exception '证书不存在';
  end if;
  if not (
    private.current_actor_can_issue_tenant_certificate(v_certificate.tenant_id)
    or private.is_platform_owner()
  ) then
    raise exception '只有对应机构负责人或平台负责人可以撤销该证书';
  end if;
  if v_certificate.status <> 'issued' then
    raise exception '只有 issued 状态的有效证书可以撤销';
  end if;

  select coalesce(nullif(btrim(profile.full_name), ''), '负责人')
  into v_actor_name
  from public.profiles as profile
  where profile.id = v_actor_id;

  update public.course_completion_certificates
  set status = 'revoked',
      revoked_by = v_actor_id,
      revoked_at = v_now,
      revocation_reason = v_reason
  where id = v_certificate.id
  returning * into v_certificate;

  insert into public.course_completion_certificate_events (
    tenant_id, certificate_id, event_type, actor_id,
    actor_name_snapshot, reason, metadata, created_at
  ) values (
    v_certificate.tenant_id,
    v_certificate.id,
    'revoked',
    v_actor_id,
    v_actor_name,
    v_reason,
    jsonb_build_object('previousStatus', 'issued'),
    v_now
  );

  return v_certificate;
end;
$$;


ALTER FUNCTION public.revoke_course_completion_certificate(p_certificate_id uuid, p_reason text) OWNER TO postgres;

