--
-- Name: runtime_publication_request_v1(text, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.runtime_publication_request_v1(p_operation text, p_actor uuid, p_tenant uuid, p_textbook uuid, p_request uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 perform runtime_publish_private.authoring_lock();
 if p_actor is null or p_tenant is null or p_request is null or not exists(select 1 from public.profiles where id=p_actor and status='active') then raise exception 'RUNTIME_REQUEST_AUTH'; end if;
 if p_operation='enter' then
  if exists(select 1 from runtime_publish_private.authoring_control where textbook_id=p_textbook and state<>'open') then raise exception 'TEXTBOOK_TEST_RUN_STOPPED'; end if;
  insert into runtime_publish_private.runtime_requests(id,textbook_id,actor_id,tenant_id) values(p_request,p_textbook,p_actor,p_tenant);
 elsif p_operation='leave' then
  update runtime_publish_private.runtime_requests set finished_at=coalesce(finished_at,clock_timestamp())
   where id=p_request and textbook_id=p_textbook and actor_id=p_actor and tenant_id=p_tenant;
  if not found then raise exception 'RUNTIME_REQUEST_OWNER'; end if;
 else raise exception 'RUNTIME_REQUEST_OPERATION'; end if;
 return jsonb_build_object('ok',true);
end $$;


ALTER FUNCTION public.runtime_publication_request_v1(p_operation text, p_actor uuid, p_tenant uuid, p_textbook uuid, p_request uuid) OWNER TO postgres;

--
-- Name: runtime_publication_session_base_v1(text, uuid, uuid, uuid, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.runtime_publication_session_base_v1(p_operation text, p_actor uuid, p_tenant uuid, p_ref uuid DEFAULT NULL::uuid, p_scope jsonb DEFAULT NULL::jsonb, p_expected jsonb DEFAULT NULL::jsonb, p_locale text DEFAULT 'zh-CN'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare s runtime_publish_private.sessions%rowtype; ptr runtime_publish_private.pointers%rowtype; artifact jsonb;
begin
  if p_actor is null or p_tenant is null or not exists(select 1 from public.profiles where id=p_actor and status='active') then raise exception 'LEARNING_SESSION_AUTH'; end if;
  if p_operation='issue' then
    -- Lock serializes issue versus publication: validation's expected pointer cannot race.
    select * into ptr from runtime_publish_private.pointers where textbook_id=(p_scope->>'textbookId')::uuid and version_id=(p_scope->>'versionId')::uuid and chapter_id=(p_scope->>'chapterId')::uuid for share;
    if ptr.snapshot_id is null or p_expected->>'snapshotId' is distinct from ptr.snapshot_id or p_expected->>'generation' is distinct from ptr.generation::text then raise exception 'PUBLICATION_CONFLICT'; end if;
    insert into runtime_publish_private.sessions(actor_id,tenant_id,snapshot_id,locale) values(p_actor,p_tenant,ptr.snapshot_id,p_locale) returning * into s;
  elsif p_operation in ('resolve','revoke') then
    select * into s from runtime_publish_private.sessions where id=p_ref and actor_id=p_actor and tenant_id=p_tenant and not revoked and expires_at>clock_timestamp();
    if s.id is null then raise exception 'LEARNING_SESSION_EXPIRED_OR_OWNER'; end if;
    if p_operation='revoke' then update runtime_publish_private.sessions set revoked=true where id=s.id; return '{}'::jsonb; end if;
  else raise exception 'LEARNING_SESSION_OPERATION'; end if;
  select document||jsonb_build_object('privatePayload',b.payload) into artifact from runtime_publish_private.snapshots a join runtime_publish_private.bindings b on b.snapshot_id=a.id and b.digest=a.document->>'privateDigest' where a.id=s.snapshot_id;
  if artifact is null then raise exception 'LEARNING_SESSION_SNAPSHOT_MISSING'; end if;
  return jsonb_build_object('sessionRef','learning-session-'||s.id::text,'expiresAt',extract(epoch from s.expires_at)*1000,'locale',s.locale,'bundle',artifact);
end $$;


ALTER FUNCTION public.runtime_publication_session_base_v1(p_operation text, p_actor uuid, p_tenant uuid, p_ref uuid, p_scope jsonb, p_expected jsonb, p_locale text) OWNER TO postgres;

--
-- Name: runtime_publication_session_v1(text, uuid, uuid, uuid, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.runtime_publication_session_v1(p_operation text, p_actor uuid, p_tenant uuid, p_ref uuid DEFAULT NULL::uuid, p_scope jsonb DEFAULT NULL::jsonb, p_expected jsonb DEFAULT NULL::jsonb, p_locale text DEFAULT 'zh-CN'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result jsonb; book uuid;
begin
 perform runtime_publish_private.authoring_lock();
 result:=public.runtime_publication_session_base_v1(p_operation,p_actor,p_tenant,p_ref,p_scope,p_expected,p_locale);
 if p_operation<>'revoke' then
  book:=(result#>>'{bundle,scope,textbookId}')::uuid;
  if exists(select 1 from runtime_publish_private.authoring_control where textbook_id=book and state<>'open')
   or exists(select 1 from runtime_publish_private.retired_snapshots where snapshot_id=result#>>'{bundle,snapshotId}') then raise exception 'TEXTBOOK_SESSION_RETIRED'; end if;
 end if;
 return result;
end $$;


ALTER FUNCTION public.runtime_publication_session_v1(p_operation text, p_actor uuid, p_tenant uuid, p_ref uuid, p_scope jsonb, p_expected jsonb, p_locale text) OWNER TO postgres;

--
-- Name: runtime_recording_dependency_v1(uuid, uuid, bigint, text, text, uuid, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.runtime_recording_dependency_v1(p_tenant uuid, p_student uuid, p_epoch bigint, p_instance text, p_key text, p_nonce uuid, p_time bigint, p_mac text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare k bytea; message text; valid boolean; signature text; fn regprocedure;
begin
 if abs(extract(epoch from clock_timestamp())::bigint-p_time)>30 then raise exception 'ADMISSION_KEY_EXPIRED';end if;
 select secret into k from recording_private.proof_keys where id=p_key and enabled;
 message='runtime-admission/1|'||p_tenant||'|'||p_student||'|'||p_epoch||'|'||p_instance||'|'||p_key||'|'||p_nonce||'|'||p_time;
 if k is null or encode(recording_private.mac(convert_to(message,'UTF8'),k),'hex') is distinct from p_mac then
  raise exception 'ADMISSION_KEY_MISMATCH';end if;
 select exists(select 1 from recording_private.domain_control c where c.singleton and c.state='open'
  and c.enabled and c.epoch=p_epoch and c.cohort @> jsonb_build_array(jsonb_build_object('tenantId',p_tenant,'studentId',p_student))
  and exists(select 1 from recording_private.domain_instances where id=p_instance and acknowledged_epoch=p_epoch)) into valid;
 if not valid then raise exception 'ADMISSION_RECORDING_FENCED';end if;
 foreach signature in array array[
  'public.record_smart_textbook_speaking_attempt_v2(uuid,uuid,uuid,uuid,jsonb,uuid,jsonb,jsonb)',
  'public.complete_smart_textbook_roleplay_v2(uuid,uuid,uuid,uuid,text,text,jsonb,jsonb)',
  'public.claim_smart_textbook_recording_delete_v2(uuid,uuid,uuid,uuid,uuid,jsonb)',
  'public.finalize_smart_textbook_recording_delete_v2(uuid,uuid,uuid,uuid,uuid,jsonb)',
  'public.recording_domain_request_v1(text,uuid,text,bigint,uuid,uuid,text)',
  'public.recording_domain_upload_v1(text,uuid,text,bigint,uuid,uuid,text,uuid)'
 ] loop
  fn=to_regprocedure(signature);
  if fn is null or not has_function_privilege('service_role',fn,'EXECUTE') then raise exception 'ADMISSION_RECORDING_RPC_MISSING';end if;
 end loop;
 return jsonb_build_object('ready',true,'epoch',p_epoch);
end$$;


ALTER FUNCTION public.runtime_recording_dependency_v1(p_tenant uuid, p_student uuid, p_epoch bigint, p_instance text, p_key text, p_nonce uuid, p_time bigint, p_mac text) OWNER TO postgres;

--
-- Name: save_conversation_practice_scenario(uuid, text, text, text, text, text, jsonb, jsonb, jsonb, text, text, integer, boolean, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.save_conversation_practice_scenario(p_id uuid, p_title text, p_description text, p_category text, p_difficulty text, p_situation text, p_learning_objectives jsonb, p_sample_dialogue jsonb, p_key_expressions jsonb, p_starter_prompt text, p_practice_tips text, p_duration_minutes integer, p_is_featured boolean, p_sort_order integer, p_status text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_id uuid;
begin
  if not public.current_user_can_manage_conversation_practice() then
    raise exception '当前账号没有会话练习管理权限';
  end if;

  if char_length(trim(coalesce(p_title, ''))) not between 2 and 100 then
    raise exception '场景标题需要填写 2 至 100 个字';
  end if;
  if char_length(coalesce(p_description, '')) > 500
     or char_length(coalesce(p_situation, '')) > 1500
     or char_length(coalesce(p_starter_prompt, '')) > 1000
     or char_length(coalesce(p_practice_tips, '')) > 1500 then
    raise exception '场景内容超过允许长度';
  end if;
  if p_category not in ('daily', 'campus', 'travel', 'interview', 'workplace')
     or p_difficulty not in ('beginner', 'intermediate', 'advanced')
     or p_status not in ('draft', 'published', 'archived') then
    raise exception '场景分类、难度或状态不正确';
  end if;
  if p_duration_minutes not between 1 and 120
     or p_sort_order not between 0 and 100000 then
    raise exception '练习时长或排序值不正确';
  end if;
  if jsonb_typeof(coalesce(p_learning_objectives, '[]'::jsonb)) <> 'array'
     or jsonb_typeof(coalesce(p_sample_dialogue, '[]'::jsonb)) <> 'array'
     or jsonb_typeof(coalesce(p_key_expressions, '[]'::jsonb)) <> 'array' then
    raise exception '场景结构化内容格式不正确';
  end if;
  if jsonb_array_length(coalesce(p_learning_objectives, '[]'::jsonb)) > 20
     or jsonb_array_length(coalesce(p_sample_dialogue, '[]'::jsonb)) > 50
     or jsonb_array_length(coalesce(p_key_expressions, '[]'::jsonb)) > 30 then
    raise exception '学习内容条目过多';
  end if;

  if p_id is null then
    insert into public.conversation_practice_scenarios (
      tenant_id, student_app_id, title, description, category, difficulty,
      situation, learning_objectives, sample_dialogue, key_expressions,
      starter_prompt, practice_tips, duration_minutes, is_featured, sort_order,
      status, published_at, created_by, updated_by
    ) values (
      null, '10000000-0000-4000-8000-000000000001'::uuid,
      trim(p_title), coalesce(p_description, ''), p_category, p_difficulty,
      coalesce(p_situation, ''),
      coalesce(p_learning_objectives, '[]'::jsonb),
      coalesce(p_sample_dialogue, '[]'::jsonb),
      coalesce(p_key_expressions, '[]'::jsonb),
      coalesce(p_starter_prompt, ''), coalesce(p_practice_tips, ''),
      p_duration_minutes, coalesce(p_is_featured, false), p_sort_order, p_status,
      case when p_status = 'published' then now() else null end,
      auth.uid(), auth.uid()
    ) returning id into v_id;
  else
    update public.conversation_practice_scenarios
    set title = trim(p_title),
        description = coalesce(p_description, ''),
        category = p_category,
        difficulty = p_difficulty,
        situation = coalesce(p_situation, ''),
        learning_objectives = coalesce(p_learning_objectives, '[]'::jsonb),
        sample_dialogue = coalesce(p_sample_dialogue, '[]'::jsonb),
        key_expressions = coalesce(p_key_expressions, '[]'::jsonb),
        starter_prompt = coalesce(p_starter_prompt, ''),
        practice_tips = coalesce(p_practice_tips, ''),
        duration_minutes = p_duration_minutes,
        is_featured = coalesce(p_is_featured, false),
        sort_order = p_sort_order,
        status = p_status,
        published_at = case
          when p_status = 'published' and status <> 'published' then now()
          when p_status = 'draft' then null
          else published_at
        end,
        updated_by = auth.uid(),
        updated_at = now()
    where id = p_id
      and tenant_id is null
    returning id into v_id;

    if v_id is null then
      raise exception '会话场景不存在或已经被移除';
    end if;
  end if;

  return v_id;
end;
$$;


ALTER FUNCTION public.save_conversation_practice_scenario(p_id uuid, p_title text, p_description text, p_category text, p_difficulty text, p_situation text, p_learning_objectives jsonb, p_sample_dialogue jsonb, p_key_expressions jsonb, p_starter_prompt text, p_practice_tips text, p_duration_minutes integer, p_is_featured boolean, p_sort_order integer, p_status text) OWNER TO postgres;

--
-- Name: save_grade_item(uuid, text, text, text, text, numeric, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.save_grade_item(p_id uuid, p_title text, p_description text, p_item_type text, p_term text, p_total_points numeric, p_weight_percent numeric, p_status text, p_course_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid;
begin
  if not public.current_user_can_manage_grade_center() then raise exception '当前账号没有成绩管理权限'; end if;
  if char_length(trim(coalesce(p_title, ''))) not between 2 and 120 or char_length(coalesce(p_description, '')) > 2000 or char_length(coalesce(p_term, '')) > 60 then raise exception '成绩项目内容长度不正确'; end if;
  if p_item_type not in ('homework', 'quiz', 'exam', 'course', 'final', 'other') or p_status not in ('draft', 'published', 'archived') then raise exception '成绩项目类型或状态不正确'; end if;
  if p_total_points <= 0 or p_total_points > 10000 or p_weight_percent < 0 or p_weight_percent > 100 then raise exception '满分或权重不正确'; end if;
  if p_course_id is not null and not exists (
    select 1 from public.courses where id = p_course_id and tenant_id = private.current_tenant_id()
  ) then raise exception '所选课程不存在'; end if;
  if p_id is null then
    insert into public.grade_items (title, description, item_type, term, total_points, weight_percent, status, course_id, published_at, created_by, updated_by)
    values (trim(p_title), trim(coalesce(p_description, '')), p_item_type, trim(coalesce(p_term, '')), p_total_points, p_weight_percent, p_status, p_course_id, case when p_status = 'published' then now() else null end, auth.uid(), auth.uid()) returning id into v_id;
  else
    update public.grade_items set title = trim(p_title), description = trim(coalesce(p_description, '')), item_type = p_item_type, term = trim(coalesce(p_term, '')), total_points = p_total_points, weight_percent = p_weight_percent, status = p_status, course_id = p_course_id, published_at = case when p_status = 'published' and status <> 'published' then now() when p_status = 'draft' then null else published_at end, updated_by = auth.uid(), updated_at = now() where id = p_id returning id into v_id;
    if v_id is null then raise exception '成绩项目不存在'; end if;
    if exists (select 1 from public.grade_records where item_id = p_id and score > p_total_points) then raise exception '新满分低于现有学生得分'; end if;
  end if;
  return v_id;
end;
$$;


ALTER FUNCTION public.save_grade_item(p_id uuid, p_title text, p_description text, p_item_type text, p_term text, p_total_points numeric, p_weight_percent numeric, p_status text, p_course_id uuid) OWNER TO postgres;

--
-- Name: save_grade_record(uuid, uuid, text, numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.save_grade_record(p_item_id uuid, p_student_id uuid, p_record_status text, p_score numeric, p_feedback text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_total numeric; v_id uuid;
begin
  if not public.current_user_can_manage_grade_center() then raise exception '当前账号没有成绩管理权限'; end if;
  select total_points into v_total from public.grade_items
  where id = p_item_id and tenant_id = private.current_tenant_id();
  if v_total is null then raise exception '成绩项目不存在'; end if;
  if not exists (
    select 1 from public.tenant_memberships as membership
    where membership.user_id = p_student_id
      and membership.tenant_id = private.current_tenant_id()
      and membership.role = 'student'
      and membership.status = 'active'
  ) then raise exception '学生账号无效'; end if;
  if p_record_status not in ('graded', 'absent', 'exempt') then raise exception '成绩记录状态不正确'; end if;
  if p_record_status = 'graded' and (p_score is null or p_score < 0 or p_score > v_total) then raise exception '学生得分需要在 0 和满分之间'; end if;
  if p_record_status <> 'graded' then p_score := null; end if;
  if char_length(coalesce(p_feedback, '')) > 3000 then raise exception '成绩评语过长'; end if;
  insert into public.grade_records (item_id, student_id, record_status, score, feedback, graded_by)
  values (p_item_id, p_student_id, p_record_status, p_score, trim(coalesce(p_feedback, '')), auth.uid())
  on conflict (item_id, student_id) do update set record_status = excluded.record_status, score = excluded.score, feedback = excluded.feedback, graded_by = auth.uid(), graded_at = now(), updated_at = now()
  returning id into v_id;
  return v_id;
end;
$$;


ALTER FUNCTION public.save_grade_record(p_item_id uuid, p_student_id uuid, p_record_status text, p_score numeric, p_feedback text) OWNER TO postgres;

--
-- Name: save_guide_agent_navigation_rule(uuid, uuid, text, text[], text, text, text, text, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.save_guide_agent_navigation_rule(p_rule_id uuid, p_agent_profile_id uuid, p_name text, p_trigger_phrases text[], p_action_type text, p_target_path text, p_target_element_id text, p_response_text text, p_priority integer, p_status text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_rule public.guide_agent_navigation_rules%rowtype;
  v_version integer;
  v_change_type text;
begin
  if not private.is_platform_owner() then
    raise insufficient_privilege using message = 'platform owner required';
  end if;
  if not exists (
    select 1 from public.learning_agent_profiles
    where id = p_agent_profile_id and agent_code = 'uply-guide-agent' and status = 'published'
  ) then
    raise exception 'guide agent profile not found';
  end if;

  if p_rule_id is null then
    insert into public.guide_agent_navigation_rules (
      agent_profile_id, name, trigger_phrases, action_type, target_path,
      target_element_id, response_text, priority, status, created_by, updated_by
    ) values (
      p_agent_profile_id, btrim(p_name), p_trigger_phrases, p_action_type, p_target_path,
      case when p_action_type = 'highlight' then nullif(btrim(p_target_element_id), '') else null end,
      btrim(p_response_text), p_priority, p_status, v_actor_id, v_actor_id
    ) returning * into v_rule;
    v_change_type := 'created';
  else
    update public.guide_agent_navigation_rules
    set name = btrim(p_name),
        trigger_phrases = p_trigger_phrases,
        action_type = p_action_type,
        target_path = p_target_path,
        target_element_id = case when p_action_type = 'highlight' then nullif(btrim(p_target_element_id), '') else null end,
        response_text = btrim(p_response_text),
        priority = p_priority,
        status = p_status,
        updated_by = v_actor_id
    where id = p_rule_id and agent_profile_id = p_agent_profile_id
    returning * into v_rule;
    if not found then raise exception 'navigation rule not found'; end if;
    v_change_type := 'updated';
  end if;

  select coalesce(max(version_number), 0) + 1 into v_version
  from public.guide_agent_navigation_rule_versions
  where rule_id = v_rule.id;

  insert into public.guide_agent_navigation_rule_versions (
    rule_id, agent_profile_id, version_number, snapshot, change_type, actor_id
  ) values (
    v_rule.id,
    v_rule.agent_profile_id,
    v_version,
    jsonb_build_object(
      'name', v_rule.name,
      'trigger_phrases', to_jsonb(v_rule.trigger_phrases),
      'action_type', v_rule.action_type,
      'target_path', v_rule.target_path,
      'target_element_id', v_rule.target_element_id,
      'response_text', v_rule.response_text,
      'priority', v_rule.priority,
      'status', v_rule.status
    ),
    v_change_type,
    v_actor_id
  );

  insert into public.guide_agent_operation_logs (
    actor_id, action, target_type, target_id, summary, details
  ) values (
    v_actor_id,
    case when v_change_type = 'created' then '新增导航规则' else '更新导航规则' end,
    'navigation_rule',
    v_rule.id,
    case when v_change_type = 'created' then '新增规则“' else '更新规则“' end || v_rule.name || '”',
    jsonb_build_object('version', v_version, 'targetPath', v_rule.target_path, 'actionType', v_rule.action_type, 'status', v_rule.status)
  );

  return v_rule.id;
end;
$$;


ALTER FUNCTION public.save_guide_agent_navigation_rule(p_rule_id uuid, p_agent_profile_id uuid, p_name text, p_trigger_phrases text[], p_action_type text, p_target_path text, p_target_element_id text, p_response_text text, p_priority integer, p_status text) OWNER TO postgres;

--
-- Name: save_help_article(uuid, text, text, text, text, boolean, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.save_help_article(p_id uuid, p_title text, p_summary text, p_content text, p_category text, p_is_featured boolean, p_sort_order integer, p_status text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  saved_id uuid;
  current_tenant uuid;
begin
  if not public.current_user_can_manage_help_articles() then
    raise exception '当前账号没有帮助文章管理权限';
  end if;
  if char_length(trim(coalesce(p_title, ''))) not between 2 and 120
     or char_length(trim(coalesce(p_content, ''))) not between 2 and 10000
     or char_length(coalesce(p_summary, '')) > 500 then
    raise exception '帮助文章标题、摘要或正文长度不正确';
  end if;
  if p_category not in ('platform', 'account', 'course', 'study', 'visa', 'service')
     or p_status not in ('draft', 'published', 'archived')
     or p_sort_order not between 0 and 100000 then
    raise exception '帮助文章分类、状态或排序值不正确';
  end if;

  current_tenant := private.current_tenant_id();
  if p_id is null then
    insert into public.help_articles (
      tenant_id, title, summary, content, category, is_featured, sort_order,
      status, published_at, created_by, updated_by
    ) values (
      current_tenant,
      trim(p_title),
      trim(coalesce(p_summary, '')),
      trim(p_content),
      p_category,
      coalesce(p_is_featured, false),
      p_sort_order,
      p_status,
      case when p_status = 'published' then now() else null end,
      auth.uid(),
      auth.uid()
    ) returning id into saved_id;
  else
    update public.help_articles
    set title = trim(p_title),
        summary = trim(coalesce(p_summary, '')),
        content = trim(p_content),
        category = p_category,
        is_featured = coalesce(p_is_featured, false),
        sort_order = p_sort_order,
        status = p_status,
        published_at = case
          when p_status = 'published' and status <> 'published' then now()
          when p_status = 'draft' then null
          else published_at
        end,
        updated_by = auth.uid(),
        updated_at = now()
    where id = p_id and tenant_id = current_tenant
    returning id into saved_id;

    if saved_id is null then raise exception '帮助文章不存在'; end if;
  end if;

  return saved_id;
end;
$$;


ALTER FUNCTION public.save_help_article(p_id uuid, p_title text, p_summary text, p_content text, p_category text, p_is_featured boolean, p_sort_order integer, p_status text) OWNER TO postgres;

--
-- Name: save_learning_assignment_draft(uuid, jsonb, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.save_learning_assignment_draft(p_assignment_id uuid, p_answers jsonb, p_active_step integer, p_request_id uuid) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tenant_id uuid := private.current_tenant_id();
  v_student_id uuid := auth.uid();
  v_saved_at timestamptz;
  v_item record;
  v_question_id uuid;
begin
  if v_student_id is null
    or p_request_id is null
    or public.current_profile_role() <> 'student'
    or not public.is_active_account()
    or not public.current_user_can_view_learning_assignment_questions(
      p_assignment_id
    )
  then
    raise exception '当前账号不能保存这份作业草稿';
  end if;

  insert into public.learning_assignment_submission_counters (
    tenant_id, assignment_id, student_id, attempt_count
  )
  select
    v_tenant_id,
    p_assignment_id,
    v_student_id,
    coalesce(max(submission.attempt_number), 0)
  from public.learning_submissions as submission
  where submission.tenant_id = v_tenant_id
    and submission.assignment_id = p_assignment_id
    and submission.student_id = v_student_id
  on conflict (tenant_id, assignment_id, student_id) do nothing;

  perform counter.attempt_count
  from public.learning_assignment_submission_counters as counter
  where counter.tenant_id = v_tenant_id
    and counter.assignment_id = p_assignment_id
    and counter.student_id = v_student_id
  for update;

  -- A delayed autosave from the form that just committed must not recreate
  -- the cleared draft or move authoritative progress back to in_progress.
  select submission.submitted_at into v_saved_at
  from public.learning_submissions as submission
  where submission.tenant_id = v_tenant_id
    and submission.assignment_id = p_assignment_id
    and submission.student_id = v_student_id
    and submission.request_id = p_request_id;
  if found then
    return v_saved_at;
  end if;

  if not public.current_user_can_submit_learning_assignment(p_assignment_id)
  then
    raise exception '这份任务当前不能继续保存草稿';
  end if;
  if p_answers is null or jsonb_typeof(p_answers) <> 'object'
    or (select count(*) from jsonb_object_keys(p_answers)) > 100 then
    raise exception '草稿答案格式不正确';
  end if;
  if coalesce(p_active_step, -1) not between 0 and 10 then
    raise exception '草稿步骤不正确';
  end if;

  for v_item in select key, value from jsonb_each(p_answers)
  loop
    begin
      v_question_id := v_item.key::uuid;
    exception when others then
      raise exception '草稿中包含无效题目';
    end;
    if jsonb_typeof(v_item.value) <> 'string'
      or char_length(v_item.value #>> '{}') > 10000
      or not exists (
        select 1
        from public.learning_assignment_questions as question
        where question.id = v_question_id
          and question.assignment_id = p_assignment_id
          and question.tenant_id = v_tenant_id
      )
    then
      raise exception '草稿中包含无效答案';
    end if;
  end loop;

  insert into public.learning_assignment_drafts (
    tenant_id, assignment_id, student_id, request_id,
    answers, active_step, updated_at
  ) values (
    v_tenant_id, p_assignment_id, v_student_id, p_request_id,
    p_answers, p_active_step, now()
  )
  on conflict (tenant_id, assignment_id, student_id) do update
  set request_id = excluded.request_id,
      answers = excluded.answers,
      active_step = excluded.active_step,
      updated_at = now()
  returning updated_at into v_saved_at;
  return v_saved_at;
end;
$$;


ALTER FUNCTION public.save_learning_assignment_draft(p_assignment_id uuid, p_answers jsonb, p_active_step integer, p_request_id uuid) OWNER TO postgres;

--
-- Name: save_learning_record_note(uuid, uuid, text, text, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.save_learning_record_note(p_id uuid, p_student_id uuid, p_record_type text, p_title text, p_content text, p_next_action text, p_visibility text, p_occurred_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid;
begin
  if not (
    public.current_user_can_manage_learning_records()
    or (
      public.is_active_account()
      and public.current_profile_role() = 'teacher'
      and exists (
        select 1
        from public.tenant_student_assignments as assignment
        where assignment.tenant_id = private.current_tenant_id()
          and assignment.student_id = p_student_id
          and assignment.teacher_id = (select auth.uid())
      )
    )
  ) then raise exception '当前账号没有学习记录管理权限'; end if;
  if not exists (
    select 1 from public.tenant_memberships as membership
    where membership.user_id = p_student_id
      and membership.tenant_id = private.current_tenant_id()
      and membership.role = 'student'
      and membership.status = 'active'
  ) then raise exception '学生账号无效'; end if;
  if p_record_type not in ('coaching','evaluation','milestone','attention','plan') or p_visibility not in ('student_visible','internal') then raise exception '记录类型或可见范围不正确'; end if;
  if char_length(trim(coalesce(p_title,''))) not between 2 and 120 or char_length(trim(coalesce(p_content,''))) not between 2 and 5000 or char_length(coalesce(p_next_action,'')) > 2000 then raise exception '记录标题、内容或下一步建议长度不正确'; end if;
  if p_id is null then
    insert into public.learning_record_notes (student_id, record_type, title, content, next_action, visibility, occurred_at, created_by, updated_by)
    values (p_student_id, p_record_type, trim(p_title), trim(p_content), trim(coalesce(p_next_action,'')), p_visibility, coalesce(p_occurred_at, now()), auth.uid(), auth.uid()) returning id into v_id;
  else
    update public.learning_record_notes set record_type = p_record_type, title = trim(p_title), content = trim(p_content), next_action = trim(coalesce(p_next_action,'')), visibility = p_visibility, occurred_at = coalesce(p_occurred_at, occurred_at), updated_by = auth.uid(), updated_at = now()
    where id = p_id and student_id = p_student_id and tenant_id = private.current_tenant_id()
    returning id into v_id;
    if v_id is null then raise exception '学习记录不存在'; end if;
  end if;
  return v_id;
end;
$$;


ALTER FUNCTION public.save_learning_record_note(p_id uuid, p_student_id uuid, p_record_type text, p_title text, p_content text, p_next_action text, p_visibility text, p_occurred_at timestamp with time zone) OWNER TO postgres;

--
-- Name: save_learning_record_note(uuid, uuid, text, text, text, text, text, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.save_learning_record_note(p_id uuid, p_student_id uuid, p_record_type text, p_title text, p_content text, p_next_action text, p_visibility text, p_occurred_at timestamp with time zone, p_student_app_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tenant_id uuid := private.current_tenant_id();
  v_id uuid;
begin
  if not private.current_staff_has_app_capability(
    v_tenant_id, p_student_app_id, 'manage_assessments'
  ) then
    raise exception '当前账号没有该应用的辅导备注管理权限';
  end if;
  if public.current_profile_role() = 'teacher'
    and not private.current_teacher_has_student_app_access(
      v_tenant_id, p_student_id, p_student_app_id
    ) then
    raise exception '只能管理当前应用中自己负责学生的辅导备注';
  end if;
  if not exists (
    select 1
    from public.student_app_enrollments as enrollment
    join public.tenant_memberships as membership
      on membership.tenant_id = enrollment.tenant_id
     and membership.user_id = enrollment.student_id
    where enrollment.tenant_id = v_tenant_id
      and enrollment.student_id = p_student_id
      and enrollment.app_id = p_student_app_id
      and enrollment.status = 'active'
      and enrollment.starts_at <= now()
      and (enrollment.ends_at is null or enrollment.ends_at > now())
      and membership.role = 'student'
      and membership.status = 'active'
  ) then
    raise exception '学生未开通当前应用';
  end if;
  if p_record_type not in (
    'coaching', 'evaluation', 'milestone', 'attention', 'plan'
  ) or p_visibility not in ('student_visible', 'internal') then
    raise exception '记录类型或可见范围不正确';
  end if;
  if char_length(trim(coalesce(p_title, ''))) not between 2 and 120
    or char_length(trim(coalesce(p_content, ''))) not between 2 and 5000
    or char_length(coalesce(p_next_action, '')) > 2000 then
    raise exception '记录标题、内容或下一步建议长度不正确';
  end if;

  if p_id is null then
    insert into public.learning_record_notes (
      tenant_id,
      student_app_id,
      student_id,
      record_type,
      title,
      content,
      next_action,
      visibility,
      occurred_at,
      created_by,
      updated_by
    ) values (
      v_tenant_id,
      p_student_app_id,
      p_student_id,
      p_record_type,
      trim(p_title),
      trim(p_content),
      trim(coalesce(p_next_action, '')),
      p_visibility,
      coalesce(p_occurred_at, now()),
      auth.uid(),
      auth.uid()
    ) returning id into v_id;
  else
    update public.learning_record_notes
    set record_type = p_record_type,
        title = trim(p_title),
        content = trim(p_content),
        next_action = trim(coalesce(p_next_action, '')),
        visibility = p_visibility,
        occurred_at = coalesce(p_occurred_at, occurred_at),
        updated_by = auth.uid(),
        updated_at = now()
    where id = p_id
      and tenant_id = v_tenant_id
      and student_id = p_student_id
      and student_app_id = p_student_app_id
    returning id into v_id;
    if v_id is null then
      raise exception '当前应用中不存在该学习记录';
    end if;
  end if;
  return v_id;
end;
$$;


ALTER FUNCTION public.save_learning_record_note(p_id uuid, p_student_id uuid, p_record_type text, p_title text, p_content text, p_next_action text, p_visibility text, p_occurred_at timestamp with time zone, p_student_app_id uuid) OWNER TO postgres;

--
-- Name: save_library_resource(uuid, text, text, text, text, text, text, text, bigint, text, boolean, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.save_library_resource(p_id uuid, p_title text, p_description text, p_category text, p_resource_type text, p_file_path text, p_original_file_name text, p_mime_type text, p_file_size bigint, p_external_url text, p_is_featured boolean, p_sort_order integer, p_status text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid;
begin
  if not private.is_platform_owner() then
    raise exception '只有平台负责人可以整理和上传资料';
  end if;

  if char_length(trim(coalesce(p_title, ''))) not between 2 and 140
    or char_length(coalesce(p_description, '')) > 3000
  then
    raise exception '资料标题或说明长度不正确';
  end if;
  if p_category not in ('language', 'study', 'application', 'visa', 'career', 'tools')
    or p_resource_type not in ('document', 'image', 'spreadsheet', 'presentation', 'archive', 'link')
    or p_status not in ('draft', 'published', 'archived')
    or p_sort_order not between 0 and 100000
  then
    raise exception '资料分类、类型、状态或排序不正确';
  end if;

  if p_resource_type = 'link' then
    if p_external_url is null or p_external_url !~ '^https?://' then
      raise exception '外部链接地址不正确';
    end if;
    p_file_path := null;
    p_original_file_name := null;
    p_mime_type := null;
    p_file_size := null;
  else
    if p_file_path is null
      or p_original_file_name is null
      or p_file_size is null
      or p_file_size not between 1 and 15728640
    then
      raise exception '资料文件信息不完整';
    end if;
    p_external_url := null;
  end if;

  if p_id is null then
    insert into public.library_resources (
      tenant_id,
      content_scope,
      title,
      description,
      category,
      resource_type,
      file_path,
      original_file_name,
      mime_type,
      file_size,
      external_url,
      is_featured,
      sort_order,
      status,
      published_at,
      created_by,
      updated_by
    )
    values (
      null,
      'platform',
      trim(p_title),
      trim(coalesce(p_description, '')),
      p_category,
      p_resource_type,
      p_file_path,
      p_original_file_name,
      p_mime_type,
      p_file_size,
      p_external_url,
      coalesce(p_is_featured, false),
      p_sort_order,
      p_status,
      case when p_status = 'published' then now() else null end,
      auth.uid(),
      auth.uid()
    )
    returning id into v_id;
  else
    update public.library_resources
    set tenant_id = null,
        content_scope = 'platform',
        title = trim(p_title),
        description = trim(coalesce(p_description, '')),
        category = p_category,
        resource_type = p_resource_type,
        file_path = p_file_path,
        original_file_name = p_original_file_name,
        mime_type = p_mime_type,
        file_size = p_file_size,
        external_url = p_external_url,
        is_featured = coalesce(p_is_featured, false),
        sort_order = p_sort_order,
        status = p_status,
        published_at = case
          when p_status = 'published' and status <> 'published' then now()
          when p_status = 'draft' then null
          else published_at
        end,
        updated_by = auth.uid(),
        updated_at = now()
    where id = p_id
    returning id into v_id;

    if v_id is null then
      raise exception '资料不存在';
    end if;
  end if;

  return v_id;
end;
$$;


ALTER FUNCTION public.save_library_resource(p_id uuid, p_title text, p_description text, p_category text, p_resource_type text, p_file_path text, p_original_file_name text, p_mime_type text, p_file_size bigint, p_external_url text, p_is_featured boolean, p_sort_order integer, p_status text) OWNER TO postgres;

--
-- Name: save_library_resource(uuid, uuid, text, text, text, text, text, text, text, bigint, text, boolean, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.save_library_resource(p_id uuid, p_course_id uuid, p_title text, p_description text, p_category text, p_resource_type text, p_file_path text, p_original_file_name text, p_mime_type text, p_file_size bigint, p_external_url text, p_is_featured boolean, p_sort_order integer, p_status text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid;
begin
  if not private.is_platform_owner() then
    raise exception '只有平台负责人可以整理和上传资料';
  end if;

  if not exists (
    select 1
    from public.courses as course
    where course.id = p_course_id
      and course.tenant_id is null
      and course.content_scope = 'platform'
  ) then
    raise exception '请选择有效的平台课程';
  end if;

  v_id := public.save_library_resource(
    p_id,
    p_title,
    p_description,
    p_category,
    p_resource_type,
    p_file_path,
    p_original_file_name,
    p_mime_type,
    p_file_size,
    p_external_url,
    p_is_featured,
    p_sort_order,
    p_status
  );

  update public.library_resources
  set course_id = p_course_id,
      updated_at = now()
  where id = v_id;

  return v_id;
end;
$$;


