--
-- Name: save_standard_question(uuid, uuid, text, text, jsonb, integer, text, text, text, numeric, text, jsonb, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.save_standard_question(p_question_id uuid, p_test_id uuid, p_question_type text, p_prompt text, p_options jsonb, p_correct_option integer, p_correct_answer text, p_explanation text, p_skill text, p_default_points numeric, p_difficulty text, p_tags jsonb, p_status text, p_ebook_section_step text, p_ebook_page_reference text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_question_id uuid;
  v_sort_order integer;
  v_current_test_id uuid;
begin
  if not private.can_manage_standard_question_bank() then
    raise exception '当前账号没有标准题库编辑权限';
  end if;

  p_prompt := btrim(coalesce(p_prompt, ''));
  p_explanation := btrim(coalesce(p_explanation, ''));
  p_skill := btrim(coalesce(p_skill, ''));
  p_correct_answer := nullif(btrim(coalesce(p_correct_answer, '')), '');
  p_options := coalesce(p_options, '[]'::jsonb);
  p_tags := coalesce(p_tags, '[]'::jsonb);
  p_ebook_section_step := btrim(coalesce(p_ebook_section_step, ''));
  p_ebook_page_reference := btrim(coalesce(p_ebook_page_reference, ''));

  perform 1 from public.chapter_tests where id = p_test_id;
  if not found then raise exception '所选课程章节不存在'; end if;
  if p_question_type <> 'single_choice' then raise exception '章节测试题库只允许四选一题'; end if;
  if char_length(p_prompt) not between 1 and 3000 then raise exception '题目不能为空且不能超过 3000 个字'; end if;
  if char_length(p_explanation) > 3000 then raise exception '解析不能超过 3000 个字'; end if;
  if char_length(p_skill) not between 1 and 80 then raise exception '知识点需要填写 1 至 80 个字'; end if;
  if p_default_points is null or p_default_points <= 0 or p_default_points > 1000 then raise exception '默认分值需要大于 0 且不超过 1000'; end if;
  if p_difficulty not in ('foundation', 'medium') then raise exception '章节测试题难度只能是基础或中等'; end if;
  if p_status not in ('draft', 'published', 'archived') then raise exception '发布状态不正确'; end if;
  if jsonb_typeof(p_tags) <> 'array' then raise exception '标签格式不正确'; end if;
  if p_ebook_section_step not in ('STEP 01', 'STEP 02', 'STEP 03', 'STEP 04', 'STEP 05', 'STEP 06', 'STEP 07', 'STEP 08') then
    raise exception '请选择电子书目录来源';
  end if;
  if char_length(p_ebook_page_reference) > 80 then raise exception '电子书页码说明不能超过 80 个字'; end if;
  if jsonb_typeof(p_options) <> 'array' or jsonb_array_length(p_options) <> 4 then raise exception '章节测试单选题必须正好有四个选项'; end if;
  if p_correct_option is null or p_correct_option < 0 or p_correct_option >= 4 then raise exception '请选择正确答案'; end if;
  p_correct_answer := null;

  if p_question_id is null then
    select coalesce(max(sort_order), 0) + 1 into v_sort_order
    from public.chapter_test_questions where test_id = p_test_id;
    insert into public.chapter_test_questions (
      test_id, question_key, prompt, options, correct_option, correct_answer,
      explanation, skill, sort_order, question_type, default_points, difficulty,
      tags, status, version, created_by, updated_by, is_chapter_test_item,
      ebook_section_step, ebook_page_reference
    ) values (
      p_test_id, 'bank-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 16),
      p_prompt, p_options, p_correct_option, p_correct_answer, p_explanation,
      p_skill, v_sort_order, p_question_type, p_default_points, p_difficulty,
      p_tags, p_status, 1, auth.uid(), auth.uid(), false,
      p_ebook_section_step, p_ebook_page_reference
    ) returning id into v_question_id;
  else
    select test_id into v_current_test_id
    from public.chapter_test_questions where id = p_question_id;
    if not found then raise exception '题目不存在'; end if;
    if v_current_test_id <> p_test_id then
      select coalesce(max(sort_order), 0) + 1 into v_sort_order
      from public.chapter_test_questions where test_id = p_test_id;
    else
      select sort_order into v_sort_order
      from public.chapter_test_questions where id = p_question_id;
    end if;
    update public.chapter_test_questions set
      test_id = p_test_id,
      prompt = p_prompt,
      options = p_options,
      correct_option = p_correct_option,
      correct_answer = p_correct_answer,
      explanation = p_explanation,
      skill = p_skill,
      sort_order = v_sort_order,
      question_type = p_question_type,
      default_points = p_default_points,
      difficulty = p_difficulty,
      tags = p_tags,
      status = p_status,
      version = version + 1,
      ebook_section_step = p_ebook_section_step,
      ebook_page_reference = p_ebook_page_reference,
      updated_by = auth.uid(),
      updated_at = now()
    where id = p_question_id
    returning id into v_question_id;
  end if;
  return v_question_id;
end;
$$;


ALTER FUNCTION public.save_standard_question(p_question_id uuid, p_test_id uuid, p_question_type text, p_prompt text, p_options jsonb, p_correct_option integer, p_correct_answer text, p_explanation text, p_skill text, p_default_points numeric, p_difficulty text, p_tags jsonb, p_status text, p_ebook_section_step text, p_ebook_page_reference text) OWNER TO postgres;

--
-- Name: save_teaching_script_node_atomic(uuid, timestamp with time zone, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.save_teaching_script_node_atomic(p_node_id uuid, p_expected_updated_at timestamp with time zone, p_node jsonb, p_secret jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'auth'
    AS $$
declare
  v_current public.learning_agent_script_nodes%rowtype;
  v_input public.learning_agent_script_nodes%rowtype;
  v_version_id uuid;
  v_status text;
begin
  if auth.uid() is null or not private.is_platform_owner() then
    raise exception '只有平台负责人可以修改教学脚本';
  end if;
  -- Same table-lock order as publication, before taking any version/row locks.
  lock table public.learning_agent_script_nodes in row exclusive mode;
  lock table public.learning_agent_node_interaction_secrets in row exclusive mode;
  select script_version_id into v_version_id from public.learning_agent_script_nodes where id = p_node_id;
  select status into v_status from public.learning_agent_script_versions where id = v_version_id for update;
  if v_status is distinct from 'draft' then raise exception '只有草稿中的教学小节可以修改。'; end if;
  select * into v_current from public.learning_agent_script_nodes where id = p_node_id for update;
  if not found or v_current.updated_at is distinct from p_expected_updated_at then
    raise exception '这个小节已经被其他操作更新，请刷新页面后重新编辑，避免覆盖别人的修改。';
  end if;
  v_input := jsonb_populate_record(v_current, p_node);
  if v_input.configuration #>> '{interaction,kind}' = 'single_choice' then
    if p_secret is null or jsonb_typeof(v_input.configuration #> '{interaction,options}') is distinct from 'array' then
      raise exception '单选题必须同时保存选项和正确答案。';
    end if;
    if jsonb_array_length(v_input.configuration #> '{interaction,options}') not between 2 and 6
      or (p_secret->>'correct_option_index') is null
      or (p_secret->>'correct_option_index')::integer not between 0 and jsonb_array_length(v_input.configuration #> '{interaction,options}') - 1 then
      raise exception '正确答案与当前选项不匹配。';
    end if;
  end if;
  update public.learning_agent_script_nodes set
    node_key = v_input.node_key, node_type = v_input.node_type, title = v_input.title,
    teacher_script = v_input.teacher_script, configuration = v_input.configuration,
    reference_activity_id = v_input.reference_activity_id, action_type = v_input.action_type,
    next_node_key = v_input.next_node_key, remediation_node_key = v_input.remediation_node_key,
    is_required = v_input.is_required
  where id = p_node_id;
  if v_input.configuration #>> '{interaction,kind}' = 'single_choice' then
    insert into public.learning_agent_node_interaction_secrets
      (node_id, correct_option_index, correct_feedback, incorrect_feedback, evaluation)
    values (p_node_id, (p_secret->>'correct_option_index')::smallint,
      p_secret->'correct_feedback', p_secret->'incorrect_feedback', p_secret->'evaluation')
    on conflict (node_id) do update set
      correct_option_index = excluded.correct_option_index, correct_feedback = excluded.correct_feedback,
      incorrect_feedback = excluded.incorrect_feedback, evaluation = excluded.evaluation;
  else
    delete from public.learning_agent_node_interaction_secrets where node_id = p_node_id;
  end if;
  return jsonb_build_object('id', p_node_id);
end;
$$;


ALTER FUNCTION public.save_teaching_script_node_atomic(p_node_id uuid, p_expected_updated_at timestamp with time zone, p_node jsonb, p_secret jsonb) OWNER TO postgres;

