--
-- Name: set_application_teacher_assignment(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_application_teacher_assignment(p_student_id uuid, p_teacher_id uuid, p_app_id uuid, p_operation text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tenant_id uuid := private.current_tenant_id();
begin
  if v_tenant_id is null
    or not private.current_staff_has_app_capability(
      v_tenant_id, p_app_id, 'manage_students'
    ) then
    raise exception '当前账号没有管理该应用师生关系的权限';
  end if;
  if p_operation = 'remove' then
    delete from public.tenant_student_assignments
    where tenant_id = v_tenant_id
      and student_id = p_student_id
      and teacher_id = p_teacher_id
      and student_app_id = p_app_id;
  elsif p_operation = 'assign' then
    insert into public.tenant_student_assignments (
      tenant_id, student_id, teacher_id, student_app_id, assigned_by
    ) values (
      v_tenant_id, p_student_id, p_teacher_id, p_app_id, auth.uid()
    )
    on conflict (tenant_id, student_id, teacher_id, student_app_id) do nothing;
  else
    raise exception '师生分配操作不正确';
  end if;
end;
$$;


ALTER FUNCTION public.set_application_teacher_assignment(p_student_id uuid, p_teacher_id uuid, p_app_id uuid, p_operation text) OWNER TO postgres;

--
-- Name: set_default_tenant(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_default_tenant(requested_tenant_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.uid() is null then
    raise exception '需要登录后才能切换租户';
  end if;

  if not private.is_tenant_member(requested_tenant_id) then
    raise exception '无权访问该租户';
  end if;

  perform 1
  from public.tenant_memberships as membership
  where membership.user_id = auth.uid()
  for update;

  update public.tenant_memberships
  set is_default = false
  where user_id = auth.uid()
    and is_default;

  update public.tenant_memberships
  set is_default = true,
      updated_at = now()
  where tenant_id = requested_tenant_id
    and user_id = auth.uid()
    and status = 'active';
end;
$$;


ALTER FUNCTION public.set_default_tenant(requested_tenant_id uuid) OWNER TO postgres;

--
-- Name: set_guide_agent_navigation_rule_status(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_guide_agent_navigation_rule_status(p_rule_id uuid, p_agent_profile_id uuid, p_status text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_rule public.guide_agent_navigation_rules%rowtype;
  v_version integer;
begin
  if not private.is_platform_owner() then
    raise insufficient_privilege using message = 'platform owner required';
  end if;
  if p_status not in ('enabled', 'disabled') then raise exception 'invalid rule status'; end if;

  update public.guide_agent_navigation_rules
  set status = p_status, updated_by = v_actor_id
  where id = p_rule_id and agent_profile_id = p_agent_profile_id
  returning * into v_rule;
  if not found then raise exception 'navigation rule not found'; end if;

  select coalesce(max(version_number), 0) + 1 into v_version
  from public.guide_agent_navigation_rule_versions where rule_id = v_rule.id;
  insert into public.guide_agent_navigation_rule_versions (
    rule_id, agent_profile_id, version_number, snapshot, change_type, actor_id
  ) values (
    v_rule.id,
    v_rule.agent_profile_id,
    v_version,
    jsonb_build_object(
      'name', v_rule.name,
      'trigger_phrases', to_jsonb(v_rule.trigger_phrases),
      'action_type', v_rule.action_type,
      'target_path', v_rule.target_path,
      'target_element_id', v_rule.target_element_id,
      'response_text', v_rule.response_text,
      'priority', v_rule.priority,
      'status', v_rule.status
    ),
    p_status,
    v_actor_id
  );
  insert into public.guide_agent_operation_logs (actor_id, action, target_type, target_id, summary, details)
  values (
    v_actor_id,
    case when p_status = 'enabled' then '启用导航规则' else '停用导航规则' end,
    'navigation_rule',
    v_rule.id,
    case when p_status = 'enabled' then '启用规则“' else '停用规则“' end || v_rule.name || '”',
    jsonb_build_object('version', v_version, 'status', p_status)
  );
  return v_rule.id;
end;
$$;


ALTER FUNCTION public.set_guide_agent_navigation_rule_status(p_rule_id uuid, p_agent_profile_id uuid, p_status text) OWNER TO postgres;

--
-- Name: set_learning_agent_model(text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_learning_agent_model(p_agent_code text, p_provider text, p_model text, p_changed_by uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_profile_id uuid;
  v_previous_provider text;
  v_previous_model text;
begin
  if p_provider not in ('qwen', 'deepseek') then
    raise exception 'unsupported learning agent provider';
  end if;
  if p_model !~ '^[A-Za-z0-9._:-]{2,100}$' then
    raise exception 'invalid learning agent model';
  end if;

  select profile.id, secret.provider, secret.model
    into v_profile_id, v_previous_provider, v_previous_model
  from public.learning_agent_profiles profile
  join public.learning_agent_profile_secrets secret
    on secret.agent_profile_id = profile.id
  where profile.agent_code = p_agent_code
    and profile.status = 'published'
  for update of secret;

  if v_profile_id is null then
    raise exception 'learning agent not found';
  end if;
  if v_previous_provider = p_provider and v_previous_model = p_model then
    return;
  end if;

  update public.learning_agent_profile_secrets
  set provider = p_provider,
      model = p_model,
      updated_at = pg_catalog.now()
  where agent_profile_id = v_profile_id;

  insert into public.learning_agent_model_change_logs (
    agent_profile_id,
    changed_by,
    previous_provider,
    previous_model,
    next_provider,
    next_model
  ) values (
    v_profile_id,
    p_changed_by,
    v_previous_provider,
    v_previous_model,
    p_provider,
    p_model
  );
end;
$_$;


ALTER FUNCTION public.set_learning_agent_model(p_agent_code text, p_provider text, p_model text, p_changed_by uuid) OWNER TO postgres;

--
-- Name: set_platform_tenant_application_settings(uuid, uuid, boolean, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_platform_tenant_application_settings(p_tenant_id uuid, p_app_id uuid, p_is_enabled boolean, p_status text, p_custom_title text, p_expected_updated_at timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_updated_at timestamptz;
  v_platform_status text;
  v_title text := nullif(btrim(coalesce(p_custom_title, '')), '');
begin
  if not private.is_platform_tenant_manager() or private.current_tenant_id() is not null then
    raise exception '只有平台负责人或副负责人可以调整机构应用设置' using errcode = '42501';
  end if;
  if p_tenant_id is null or p_app_id is null or p_expected_updated_at is null or p_is_enabled is null
    or p_status is null or p_status not in ('active', 'coming_soon', 'hidden') then
    raise exception '应用设置参数不完整或状态无效' using errcode = '22023';
  end if;
  if char_length(coalesce(v_title, '')) > 80 then
    raise exception '应用显示名称不能超过 80 个字' using errcode = '22023';
  end if;
  select app.default_status into v_platform_status from public.student_apps as app where app.id = p_app_id;
  if not found then raise exception '应用不存在' using errcode = '22023'; end if;
  if p_is_enabled and p_status = 'active' and v_platform_status <> 'active' then
    raise exception '平台应用尚未开放，不能启用机构应用' using errcode = '22023';
  end if;
  if p_is_enabled and p_status = 'active' and not exists (
    select 1 from public.tenants where id = p_tenant_id and status = 'active'
  ) then
    raise exception '机构未运行，不能启用机构应用' using errcode = '22023';
  end if;
  update public.tenant_student_apps
  set is_enabled = p_is_enabled, status = p_status, custom_title = v_title,
      updated_at = clock_timestamp()
  where tenant_id = p_tenant_id and app_id = p_app_id
    and updated_at = p_expected_updated_at
  returning updated_at into v_updated_at;
  if not found then
    raise exception '设置已被其他人修改或机构未注册此应用，请刷新后重试' using errcode = '40001';
  end if;
  return v_updated_at;
end;
$$;


ALTER FUNCTION public.set_platform_tenant_application_settings(p_tenant_id uuid, p_app_id uuid, p_is_enabled boolean, p_status text, p_custom_title text, p_expected_updated_at timestamp with time zone) OWNER TO postgres;

--
-- Name: set_profile_management_timestamps(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_profile_management_timestamps() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  new.updated_at := now();

  if new.profile_completed_at is null
     and nullif(btrim(coalesce(new.full_name, '')), '') is not null then
    new.profile_completed_at := now();
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.set_profile_management_timestamps() OWNER TO postgres;

--
-- Name: set_staff_application_access(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_staff_application_access(p_staff_id uuid, p_app_id uuid, p_status text, p_access_role text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tenant_id uuid := private.current_tenant_id();
begin
  if v_tenant_id is null
    or not private.current_staff_has_app_capability(
      v_tenant_id, p_app_id, 'manage_availability'
    ) then
    raise exception '只有机构负责人可以调整员工应用权限';
  end if;
  if p_status not in ('active', 'inactive') then
    raise exception '员工应用状态不正确';
  end if;
  if p_access_role not in ('administrator', 'operator', 'teacher', 'viewer') then
    raise exception '员工应用角色不正确';
  end if;
  if not exists (
    select 1
    from public.tenant_memberships as membership
    where membership.tenant_id = v_tenant_id
      and membership.user_id = p_staff_id
      and membership.role in ('teacher', 'admin', 'ceo', 'tenant_super_admin')
      and membership.status = 'active'
  ) then
    raise exception '目标账号不是当前机构的有效员工';
  end if;

  insert into public.staff_app_assignments (
    tenant_id, staff_id, app_id, access_role,
    can_manage_students, can_manage_content, can_manage_assessments,
    can_view_analytics, status, assigned_by
  ) values (
    v_tenant_id,
    p_staff_id,
    p_app_id,
    p_access_role,
    p_access_role in ('administrator', 'operator'),
    p_access_role = 'administrator',
    p_access_role in ('administrator', 'operator', 'teacher'),
    true,
    p_status,
    auth.uid()
  )
  on conflict (tenant_id, staff_id, app_id) do update
  set access_role = excluded.access_role,
      can_manage_students = excluded.can_manage_students,
      can_manage_content = excluded.can_manage_content,
      can_manage_assessments = excluded.can_manage_assessments,
      can_view_analytics = excluded.can_view_analytics,
      status = excluded.status,
      assigned_by = auth.uid(),
      updated_at = now();
end;
$$;


ALTER FUNCTION public.set_staff_application_access(p_staff_id uuid, p_app_id uuid, p_status text, p_access_role text) OWNER TO postgres;

--
-- Name: set_student_application_enrollment(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_student_application_enrollment(p_student_id uuid, p_app_id uuid, p_status text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tenant_id uuid := private.current_tenant_id();
  v_tier text;
begin
  if v_tenant_id is null
    or not private.current_staff_has_app_capability(
      v_tenant_id, p_app_id, 'manage_students'
    ) then
    raise exception '当前账号没有管理该应用学生的权限';
  end if;
  if p_status not in ('active', 'paused', 'completed', 'cancelled') then
    raise exception '学生应用状态不正确';
  end if;

  select membership.membership_tier into v_tier
  from public.tenant_memberships as membership
  where membership.tenant_id = v_tenant_id
    and membership.user_id = p_student_id
    and membership.role = 'student'
    and membership.status = 'active';
  if not found then
    raise exception '目标账号不是当前机构的有效学生';
  end if;

  insert into public.student_app_enrollments (
    tenant_id, student_id, app_id, status, access_tier, enrolled_by
  ) values (
    v_tenant_id, p_student_id, p_app_id, p_status, v_tier, auth.uid()
  )
  on conflict (tenant_id, student_id, app_id) do update
  set status = excluded.status,
      access_tier = excluded.access_tier,
      enrolled_by = auth.uid(),
      updated_at = now();
end;
$$;


ALTER FUNCTION public.set_student_application_enrollment(p_student_id uuid, p_app_id uuid, p_status text) OWNER TO postgres;

