--
-- Name: set_tenant_application_settings(uuid, boolean, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_tenant_application_settings(p_app_id uuid, p_is_enabled boolean, p_status text, p_custom_title text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tenant_id uuid := private.current_tenant_id();
  v_custom_title text := nullif(btrim(coalesce(p_custom_title, '')), '');
  v_platform_status text;
begin
  if v_tenant_id is null
    or not private.current_staff_has_app_capability(
      v_tenant_id, p_app_id, 'manage_availability'
    ) then
    raise exception '只有机构负责人可以修改应用开放设置';
  end if;
  if p_status not in ('active', 'coming_soon', 'hidden') then
    raise exception '机构应用状态不正确';
  end if;
  if char_length(coalesce(v_custom_title, '')) > 80 then
    raise exception '应用显示名称不能超过 80 个字';
  end if;

  select app.default_status into v_platform_status
  from public.student_apps as app
  where app.id = p_app_id;
  if not found then
    raise exception '平台应用不存在';
  end if;
  if p_status = 'active' and v_platform_status <> 'active' then
    raise exception '平台标准应用仍在建设中，暂时不能切换为运行中';
  end if;

  update public.tenant_student_apps
  set is_enabled = p_is_enabled,
      status = p_status,
      custom_title = v_custom_title,
      updated_at = now()
  where tenant_id = v_tenant_id
    and app_id = p_app_id;
  if not found then
    raise exception '当前机构没有注册该应用';
  end if;
end;
$$;


ALTER FUNCTION public.set_tenant_application_settings(p_app_id uuid, p_is_enabled boolean, p_status text, p_custom_title text) OWNER TO postgres;

--
-- Name: set_tenant_lifecycle_status(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_tenant_lifecycle_status(requested_tenant_id uuid, requested_status text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare target public.tenants%rowtype; audit_action text;
begin
  if not private.is_platform_tenant_manager() then raise exception '只有负责人或副负责人可以变更租户状态'; end if;
  if requested_status not in ('active', 'suspended', 'archived') then raise exception '租户状态不正确'; end if;
  select * into target from public.tenants where id = requested_tenant_id for update;
  if not found then raise exception '租户不存在'; end if;
  if target.id = '00000000-0000-4000-8000-000000000001'::uuid and requested_status <> 'active' then raise exception '默认 PUFFY 租户不能停用'; end if;
  update public.tenants set status = requested_status where id = target.id;
  audit_action := case requested_status when 'active' then 'restored' when 'suspended' then 'suspended' else 'archived' end;
  insert into public.tenant_lifecycle_audit_logs (tenant_id, tenant_slug, actor_id, action, details)
  values (target.id, target.slug, auth.uid(), audit_action, jsonb_build_object('previous_status', target.status));
end;
$$;


ALTER FUNCTION public.set_tenant_lifecycle_status(requested_tenant_id uuid, requested_status text) OWNER TO postgres;

--
-- Name: set_user_permission_grant(uuid, text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_user_permission_grant(requested_subject_user_id uuid, requested_permission_key text, requested_tenant_id uuid DEFAULT NULL::uuid, requested_enabled boolean DEFAULT true) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  grant_id bigint;
  actor_id uuid := auth.uid();
begin
  if actor_id is null or not private.is_platform_owner() then
    raise exception '只有平台负责人可以修改统一权限';
  end if;

  if requested_permission_key not in (
    'standard_question_bank.manage',
    'conversation_practice.manage',
    'grade_center.manage',
    'learning_records.manage',
    'document_reviews.manage',
    'visa_management.manage'
  ) then
    raise exception '权限编号无效';
  end if;

  if requested_tenant_id is null then
    if requested_permission_key <> 'standard_question_bank.manage' then
      raise exception '该权限必须指定机构';
    end if;
    if not exists (
      select 1 from public.profiles as profile
      where profile.id = requested_subject_user_id
        and profile.global_role in ('platform_deputy', 'platform_admin')
        and coalesce(profile.status, 'active') = 'active'
    ) then
      raise exception '只能给正常的平台副负责人或平台管理员授权';
    end if;
  else
    if requested_permission_key = 'standard_question_bank.manage' then
      raise exception '标准题库权限只能在平台范围分配';
    end if;
    if not exists (
      select 1
      from public.tenant_memberships as membership
      join public.profiles as profile on profile.id = membership.user_id
      where membership.tenant_id = requested_tenant_id
        and membership.user_id = requested_subject_user_id
        and membership.role = 'admin'
        and membership.status = 'active'
        and coalesce(profile.status, 'active') = 'active'
    ) then
      raise exception '只能给当前机构状态正常的管理员授权';
    end if;
  end if;

  if requested_enabled then
    select permission_grant.id
      into grant_id
    from public.permission_grants as permission_grant
    where permission_grant.subject_user_id = requested_subject_user_id
      and permission_grant.permission_key = requested_permission_key
      and permission_grant.revoked_at is null
      and (
        (requested_tenant_id is null and permission_grant.scope_type = 'platform' and permission_grant.tenant_id is null)
        or (requested_tenant_id is not null and permission_grant.scope_type = 'tenant' and permission_grant.tenant_id = requested_tenant_id)
      )
    limit 1;

    if grant_id is null then
      insert into public.permission_grants (
        scope_type,
        tenant_id,
        subject_user_id,
        permission_key,
        granted_by
      ) values (
        case when requested_tenant_id is null then 'platform' else 'tenant' end,
        requested_tenant_id,
        requested_subject_user_id,
        requested_permission_key,
        actor_id
      ) returning id into grant_id;

      insert into public.permission_grant_audit_logs (
        permission_grant_id,
        actor_id,
        subject_user_id,
        tenant_id,
        permission_key,
        action
      ) values (
        grant_id,
        actor_id,
        requested_subject_user_id,
        requested_tenant_id,
        requested_permission_key,
        'granted'
      );
    end if;
  else
    update public.permission_grants
    set revoked_by = actor_id,
        revoked_at = now()
    where subject_user_id = requested_subject_user_id
      and permission_key = requested_permission_key
      and revoked_at is null
      and (
        (requested_tenant_id is null and scope_type = 'platform' and tenant_id is null)
        or (requested_tenant_id is not null and scope_type = 'tenant' and tenant_id = requested_tenant_id)
      )
    returning id into grant_id;

    if grant_id is not null then
      insert into public.permission_grant_audit_logs (
        permission_grant_id,
        actor_id,
        subject_user_id,
        tenant_id,
        permission_key,
        action
      ) values (
        grant_id,
        actor_id,
        requested_subject_user_id,
        requested_tenant_id,
        requested_permission_key,
        'revoked'
      );
    end if;
  end if;

  return grant_id;
end;
$$;


ALTER FUNCTION public.set_user_permission_grant(requested_subject_user_id uuid, requested_permission_key text, requested_tenant_id uuid, requested_enabled boolean) OWNER TO postgres;

--
-- Name: start_learning_assignment_attempt(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.start_learning_assignment_attempt(p_assignment_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tenant_id uuid := private.current_tenant_id();
  v_student_id uuid := auth.uid();
  v_assignment public.learning_assignments%rowtype;
  v_attempt integer;
  v_started_at timestamptz;
  v_effective_due_at timestamptz;
  v_expires_at timestamptz;
  v_idempotent boolean := true;
begin
  select assignment.* into v_assignment
  from public.learning_assignments as assignment
  where assignment.id = p_assignment_id
    and assignment.tenant_id = v_tenant_id
  for key share;
  if v_assignment.id is null
    or v_assignment.assignment_type <> 'exam'
    or v_assignment.duration_minutes is null
    or v_student_id is null
    or public.current_profile_role() <> 'student'
    or not public.is_active_account()
    or not public.current_user_can_view_learning_assignment_questions(
      p_assignment_id
    ) then
    raise exception '当前账号不能开始这场考试';
  end if;

  insert into public.learning_assignment_submission_counters (
    tenant_id, assignment_id, student_id, attempt_count
  )
  select v_tenant_id, p_assignment_id, v_student_id,
    coalesce(max(submission.attempt_number), 0)
  from public.learning_submissions as submission
  where submission.tenant_id = v_tenant_id
    and submission.assignment_id = p_assignment_id
    and submission.student_id = v_student_id
  on conflict (tenant_id, assignment_id, student_id) do nothing;

  select counter.attempt_count, counter.current_attempt_started_at
  into v_attempt, v_started_at
  from public.learning_assignment_submission_counters as counter
  where counter.tenant_id = v_tenant_id
    and counter.assignment_id = p_assignment_id
    and counter.student_id = v_student_id
  for update;

  if v_started_at is null then
    if v_assignment.status <> 'published'
      or v_assignment.starts_at > now()
      or not public.current_user_can_submit_learning_assignment(p_assignment_id)
      or v_attempt >= v_assignment.max_attempts then
      raise exception '考试尚未开放、已经截止或作答次数已用完';
    end if;
    v_started_at := now();
    v_idempotent := false;
    update public.learning_assignment_submission_counters
    set current_attempt_started_at = v_started_at,
        updated_at = now()
    where tenant_id = v_tenant_id
      and assignment_id = p_assignment_id
      and student_id = v_student_id;

    insert into public.learning_assignment_progress (
      tenant_id, assignment_id, student_id, progress_state,
      latest_submission_id, attempts_used, updated_at
    ) values (
      v_tenant_id, p_assignment_id, v_student_id, 'in_progress',
      null, v_attempt, now()
    )
    on conflict (tenant_id, assignment_id, student_id) do update
    set progress_state = 'in_progress',
        latest_submission_id = null,
        attempts_used = excluded.attempts_used,
        updated_at = now();
  end if;

  select assignment_window.effective_due_at into v_effective_due_at
  from public.current_user_assignment_window(p_assignment_id)
    as assignment_window
  limit 1;
  v_expires_at := least(
    v_started_at + make_interval(mins => v_assignment.duration_minutes),
    v_effective_due_at
  );
  return jsonb_build_object(
    'startedAt', v_started_at,
    'expiresAt', v_expires_at,
    'serverNow', now(),
    'idempotent', v_idempotent
  );
end;
$$;


ALTER FUNCTION public.start_learning_assignment_attempt(p_assignment_id uuid) OWNER TO postgres;

--
-- Name: student_feature_allowed(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.student_feature_allowed(requested_feature text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    coalesce((
      select case
        when membership.role in (
          'teacher',
          'admin',
          'ceo',
          'tenant_super_admin'
        ) then true
        when membership.status <> 'active' then false
        when requested_feature = 'message_services' then true
        when membership.membership_tier in ('vip1', 'vip2', 'vip3')
          and requested_feature in (
            'dashboard_section',
            'university_target',
            'university_comparison',
            'application_documents',
            'visa_tasks',
            'course_preview'
          ) then true
        when membership.membership_tier in ('vip2', 'vip3')
          and requested_feature in (
            'learning_assignments',
            'korean_course',
            'ai_conversation_experience'
          ) then true
        when membership.membership_tier = 'vip3'
          and requested_feature = 'conversation_course' then true
        else false
      end
      from public.tenant_memberships as membership
      where membership.user_id = (select auth.uid())
        and membership.tenant_id = private.current_tenant_id()
    ), false)
    and exists (
      select 1
      from public.profiles as profile
      where profile.id = (select auth.uid())
        and coalesce(profile.status, 'active') = 'active'
    );
$$;


ALTER FUNCTION public.student_feature_allowed(requested_feature text) OWNER TO postgres;

--
-- Name: FUNCTION student_feature_allowed(requested_feature text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.student_feature_allowed(requested_feature text) IS '按当前租户成员档位判断学生功能；VIP1 起开放大学对比，VIP2 开放韩语课程、作业考试和 AI 交流，VIP3 另开放会话课程';

--
-- Name: submit_assignment_remediation_answer(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.submit_assignment_remediation_answer(p_question_id uuid, p_answer text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tenant_id uuid := private.current_tenant_id();
  v_question public.learning_assignment_questions%rowtype;
  v_key public.learning_assignment_question_keys%rowtype;
  v_answer text := btrim(coalesce(p_answer, ''));
  v_correct boolean;
  v_attempt_count integer;
begin
  if public.current_profile_role() <> 'student' or not public.is_active_account()
  then raise exception '当前账号不能进行错题重练'; end if;
  if char_length(v_answer) not between 1 and 10000 then
    raise exception '请先填写重练答案';
  end if;
  select * into v_question
  from public.learning_assignment_questions
  where id = p_question_id and tenant_id = v_tenant_id and auto_graded;
  if v_question.id is null or not exists (
    select 1
    from public.learning_submission_answers as submitted_answer
    join public.learning_submissions as submission
      on submission.id = submitted_answer.submission_id
    where submitted_answer.question_id = v_question.id
      and submission.student_id = auth.uid()
      and submission.assignment_id = v_question.assignment_id
      and submission.status = 'graded'
      and coalesce(submitted_answer.awarded_points, 0) < v_question.points
  ) then
    raise exception '这道题当前不属于可重练错题';
  end if;
  select * into v_key from public.learning_assignment_question_keys
  where question_id = v_question.id and tenant_id = v_tenant_id;
  if nullif(btrim(coalesce(v_key.correct_answer, '')), '') is null then
    raise exception '这道题暂时没有可用的重练判定';
  end if;
  v_correct := private.normalize_assignment_answer(v_answer)
    = private.normalize_assignment_answer(v_key.correct_answer);
  insert into public.learning_assignment_remediation_attempts (
    tenant_id, assignment_id, question_id, student_id, answer_text, is_correct
  ) values (
    v_tenant_id, v_question.assignment_id, v_question.id,
    auth.uid(), v_answer, v_correct
  );
  select count(*) into v_attempt_count
  from public.learning_assignment_remediation_attempts
  where tenant_id = v_tenant_id and student_id = auth.uid()
    and question_id = v_question.id;
  return jsonb_build_object(
    'correct', v_correct,
    'message', case when v_correct then '回答正确，这道错题已经掌握。'
      when v_attempt_count >= 2 then '还不正确，请对照答案后再做一次。'
      else '还不正确，再检查一次词形或选项。' end,
    'correctAnswer', case when v_correct or v_attempt_count >= 2
      then v_key.correct_answer else null end,
    'explanation', case when v_correct or v_attempt_count >= 2
      then v_key.explanation else null end
  );
end;
$$;


ALTER FUNCTION public.submit_assignment_remediation_answer(p_question_id uuid, p_answer text) OWNER TO postgres;

--
-- Name: submit_course_test(text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.submit_course_test(p_test_slug text, p_answers jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_tenant_id uuid := private.current_tenant_id();
  v_test public.course_tests%rowtype;
  v_question public.course_test_questions%rowtype;
  v_selected integer;
  v_correct boolean;
  v_correct_count integer := 0;
  v_total_questions integer := 0;
  v_score integer;
  v_passed boolean;
  v_results jsonb := '[]'::jsonb;
  v_dimensions jsonb := '{}'::jsonb;
  v_dimension_scores jsonb := '{}'::jsonb;
  v_dimension_key text;
  v_dimension_value jsonb;
  v_dimension_correct integer;
  v_dimension_total integer;
  v_attempt_id uuid;
  v_lesson_course_id uuid;
begin
  if v_user_id is null or v_tenant_id is null then raise exception '请登录有效的机构账号后再提交测试'; end if;
  if not public.student_feature_allowed('korean_course') then raise exception '当前会员档位没有权限提交这项测试'; end if;
  if jsonb_typeof(p_answers) is distinct from 'object' then raise exception '答案格式不正确'; end if;
  select * into v_test from public.course_tests where slug = p_test_slug and status = 'published';
  if not found then raise exception '没有找到这份章节测试'; end if;

  if v_test.lesson_id is not null and exists (
    select 1
    from public.course_tests as prior_test
    where prior_test.lesson_id = v_test.lesson_id
      and prior_test.status = 'published'
      and prior_test.chapter_number < v_test.chapter_number
      and not exists (
        select 1
        from public.course_test_attempts as prior_attempt
        where prior_attempt.tenant_id = v_tenant_id
          and prior_attempt.student_id = v_user_id
          and prior_attempt.test_id = prior_test.id
      )
  ) then
    raise exception '请先完成前面章节的测试，再提交这一章';
  end if;

  select count(*) into v_total_questions
  from public.course_test_questions
  where test_id = v_test.id
    and status = 'published'
    and question_type = 'single_choice'
    and is_chapter_test_item;
  if v_total_questions = 0 or (select count(*) from jsonb_object_keys(p_answers)) <> v_total_questions then
    raise exception '请完成全部题目后再交卷';
  end if;

  for v_question in
    select * from public.course_test_questions
    where test_id = v_test.id
      and status = 'published'
      and question_type = 'single_choice'
      and is_chapter_test_item
    order by sort_order
  loop
    if not (p_answers ? v_question.question_key) then raise exception '请完成全部题目后再交卷'; end if;
    begin
      v_selected := (p_answers ->> v_question.question_key)::integer;
    exception when invalid_text_representation then
      raise exception '有一道题的答案格式不正确';
    end;
    if v_selected < 0 or v_selected >= jsonb_array_length(v_question.options) then raise exception '有一道题的选项不正确'; end if;
    v_correct := v_selected = v_question.correct_option;
    if v_correct then v_correct_count := v_correct_count + 1; end if;
    v_dimension_correct := coalesce((v_dimensions -> v_question.skill ->> 'correct')::integer, 0) + case when v_correct then 1 else 0 end;
    v_dimension_total := coalesce((v_dimensions -> v_question.skill ->> 'total')::integer, 0) + 1;
    v_dimensions := jsonb_set(
      v_dimensions, array[v_question.skill],
      jsonb_build_object('label', coalesce(v_test.skills ->> v_question.skill, v_question.skill), 'correct', v_dimension_correct, 'total', v_dimension_total),
      true
    );
    v_results := v_results || jsonb_build_array(jsonb_build_object(
      'id', v_question.question_key,
      'selectedOption', v_selected,
      'correctOption', v_question.correct_option,
      'correct', v_correct,
      'explanation', v_question.explanation
    ));
  end loop;

  v_score := round((v_correct_count::numeric / v_total_questions::numeric) * 100);
  v_passed := v_score >= v_test.passing_score;
  for v_dimension_key, v_dimension_value in select key, value from jsonb_each(v_dimensions)
  loop
    v_dimension_correct := (v_dimension_value ->> 'correct')::integer;
    v_dimension_total := (v_dimension_value ->> 'total')::integer;
    v_dimension_scores := jsonb_set(
      v_dimension_scores, array[v_dimension_key],
      v_dimension_value || jsonb_build_object('percent', round((v_dimension_correct::numeric / v_dimension_total::numeric) * 100)),
      true
    );
  end loop;

  insert into public.course_test_attempts (
    tenant_id, student_id, test_id, test_slug, test_version, score,
    correct_count, total_questions, passed, answers, dimension_scores
  ) values (
    v_tenant_id, v_user_id, v_test.id, v_test.slug, v_test.version, v_score,
    v_correct_count, v_total_questions, v_passed, p_answers, v_dimension_scores
  ) returning id into v_attempt_id;

  if v_passed and v_test.lesson_id is not null then
    if not exists (
      select 1
      from public.course_tests as remaining_test
      where remaining_test.lesson_id = v_test.lesson_id
        and remaining_test.status = 'published'
        and not exists (
          select 1
          from public.course_test_attempts as passed_attempt
          where passed_attempt.tenant_id = v_tenant_id
            and passed_attempt.student_id = v_user_id
            and passed_attempt.test_id = remaining_test.id
            and passed_attempt.passed
        )
    ) then
      select course_id into v_lesson_course_id
      from public.lessons
      where id = v_test.lesson_id;

      if v_lesson_course_id is not null then
        insert into public.lesson_progress (
          user_id, tenant_id, course_id, lesson_id, status,
          progress_percent, started_at, last_viewed_at, completed_at, updated_at
        ) values (
          v_user_id, v_tenant_id, v_lesson_course_id, v_test.lesson_id, 'completed',
          100, now(), now(), now(), now()
        )
        on conflict (user_id, lesson_id) do update
        set status = 'completed',
            progress_percent = 100,
            completed_at = coalesce(public.lesson_progress.completed_at, excluded.completed_at),
            last_viewed_at = excluded.last_viewed_at,
            updated_at = excluded.updated_at;
      end if;
    end if;
  end if;

  return jsonb_build_object(
    'attemptId', v_attempt_id, 'score', v_score, 'correctCount', v_correct_count,
    'totalQuestions', v_total_questions, 'passed', v_passed,
    'dimensionScores', v_dimension_scores, 'questions', v_results
  );
end;
$$;


ALTER FUNCTION public.submit_course_test(p_test_slug text, p_answers jsonb) OWNER TO postgres;

--
-- Name: FUNCTION submit_course_test(p_test_slug text, p_answers jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.submit_course_test(p_test_slug text, p_answers jsonb) IS '判分并记录章节测试：要求同一课时内编号更小的已发布章节测试都至少提交过一次，否则拒绝，防止绕过前端顺序限制直接跳章提交；通过某课时全部章节测试时联动标记该课时 lesson_progress 为已完成。真正的用时限制仍需服务端考试session（暂未实现）。';

--
-- Name: submit_learning_assignment(uuid, jsonb, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.submit_learning_assignment(p_assignment_id uuid, p_answers jsonb, p_request_id uuid, p_submission_intent text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_tenant_id uuid := private.current_tenant_id();
  v_student_id uuid := auth.uid();
  v_assignment public.learning_assignments%rowtype;
  v_existing public.learning_submissions%rowtype;
  v_submission_id uuid;
  v_attempt integer;
  v_attempt_started_at timestamptz;
  v_effective_due_at timestamptz;
  v_authoritative_deadline timestamptz;
  v_minimum_engagement interval;
  v_payload_hash text;
  v_answer jsonb;
  v_question_id uuid;
  v_answer_text text;
  v_question_type text;
  v_options jsonb;
  v_question_count integer;
  v_answer_count integer;
  v_answered_count integer;
  v_unanswered_count integer;
  v_manual_count integer;
  v_objective_score numeric(8,2);
  v_submission_state text;
begin
  if p_request_id is null then
    raise exception '提交请求编号不正确';
  end if;
  if p_answers is null or jsonb_typeof(p_answers) <> 'array' then
    raise exception '答案格式不正确';
  end if;
  if p_submission_intent not in (
    'complete', 'confirmed_incomplete', 'time_expired'
  ) then
    raise exception '提交方式不正确';
  end if;
  v_payload_hash := md5(jsonb_build_object(
    'answers', p_answers, 'intent', p_submission_intent
  )::text);

  select assignment.* into v_assignment
  from public.learning_assignments as assignment
  where assignment.id = p_assignment_id
    and assignment.tenant_id = v_tenant_id
  for key share;
  if v_assignment.id is null
    or v_student_id is null
    or public.current_profile_role() <> 'student'
    or not public.is_active_account() then
    raise exception '任务不可提交，可能尚未发布、已截止或未分配给当前账号';
  end if;

  insert into public.learning_assignment_submission_counters (
    tenant_id, assignment_id, student_id, attempt_count
  )
  select v_tenant_id, p_assignment_id, v_student_id,
    coalesce(max(submission.attempt_number), 0)
  from public.learning_submissions as submission
  where submission.tenant_id = v_tenant_id
    and submission.assignment_id = p_assignment_id
    and submission.student_id = v_student_id
  on conflict (tenant_id, assignment_id, student_id) do nothing;

  select counter.attempt_count, counter.current_attempt_started_at
  into v_attempt, v_attempt_started_at
  from public.learning_assignment_submission_counters as counter
  where counter.tenant_id = v_tenant_id
    and counter.assignment_id = p_assignment_id
    and counter.student_id = v_student_id
  for update;

  select submission.* into v_existing
  from public.learning_submissions as submission
  where submission.tenant_id = v_tenant_id
    and submission.assignment_id = p_assignment_id
    and submission.student_id = v_student_id
    and submission.request_id = p_request_id;
  if v_existing.id is not null then
    if v_existing.request_payload_hash <> v_payload_hash then
      raise exception '同一提交请求编号不能用于不同答案';
    end if;
    return jsonb_build_object(
      'submissionId', v_existing.id,
      'attemptNumber', v_existing.attempt_number,
      'workflowState', v_existing.submission_state,
      'idempotent', true
    );
  end if;

  if not public.current_user_can_view_learning_assignment(p_assignment_id)
    or v_assignment.status <> 'published'
    or v_assignment.starts_at > now() then
    raise exception '任务不可提交，可能尚未发布、已截止或未分配给当前账号';
  end if;
  if v_attempt >= v_assignment.max_attempts then
    raise exception '已达到本任务允许的提交次数';
  end if;
  if v_attempt > 0 and not v_assignment.allow_resubmission and not exists (
    select 1 from public.learning_submissions as submission
    where submission.tenant_id = v_tenant_id
      and submission.assignment_id = p_assignment_id
      and submission.student_id = v_student_id
      and submission.status = 'revision_required'
  ) then
    raise exception '该任务不允许重复提交';
  end if;

  select assignment_window.effective_due_at into v_effective_due_at
  from public.current_user_assignment_window(p_assignment_id)
    as assignment_window
  limit 1;

  select count(*) into v_question_count
  from public.learning_assignment_questions as question
  where question.tenant_id = v_tenant_id
    and question.assignment_id = p_assignment_id
    and question.delivery_paper_id is not distinct from
      private.assignment_delivery_paper_id(
        v_tenant_id, p_assignment_id, v_student_id
      );
  select
    count(distinct value->>'questionId'),
    count(*) filter (where btrim(coalesce(value->>'answer', '')) <> '')
  into v_answer_count, v_answered_count
  from jsonb_array_elements(p_answers) as value;
  if v_question_count = 0
    or v_answer_count <> v_question_count
    or jsonb_array_length(p_answers) <> v_question_count then
    raise exception '答案必须与本任务题目一一对应';
  end if;
  v_unanswered_count := v_question_count - v_answered_count;

  if v_assignment.assignment_type = 'exam' then
    if v_assignment.duration_minutes is null
      or v_attempt_started_at is null then
      raise exception '请先通过考试说明页开始作答';
    end if;
    v_authoritative_deadline := least(
      v_attempt_started_at
        + make_interval(mins => v_assignment.duration_minutes),
      v_effective_due_at
    );
    if p_submission_intent = 'time_expired' then
      if now() < v_authoritative_deadline
        or now() > v_authoritative_deadline + interval '5 minutes' then
        raise exception '自动交卷只允许在服务端计时结束后的五分钟内执行';
      end if;
    elsif now() > v_authoritative_deadline then
      raise exception '考试计时已经结束，请使用到期自动交卷';
    elsif v_effective_due_at < now() and not v_assignment.allow_late_submission then
      raise exception '任务不可提交，可能尚未发布、已截止或未分配给当前账号';
    end if;

    if v_unanswered_count > 0 then
      if p_submission_intent = 'confirmed_incomplete' then
        v_minimum_engagement := least(
          interval '5 minutes',
          greatest(
            interval '1 minute',
            make_interval(secs => v_assignment.duration_minutes * 6)
          )
        );
        if v_answered_count = 0
          or now() < v_attempt_started_at + v_minimum_engagement
          or now() >= v_authoritative_deadline then
          raise exception '未答确认提交需要至少完成一题并达到最短有效作答时间';
        end if;
      elsif p_submission_intent <> 'time_expired' then
        raise exception '存在未答题，请确认未答提交或等待系统到期交卷';
      end if;
    end if;
  else
    if v_unanswered_count > 0 then
      raise exception '请完成全部题目后再提交';
    end if;
    if not (
      v_assignment.allow_late_submission
      or (not v_assignment.unlock_after_chapter_completion
        and v_assignment.due_at >= now())
      or (v_effective_due_at is not null and v_effective_due_at >= now())
    ) then
      raise exception '任务不可提交，可能尚未发布、已截止或未分配给当前账号';
    end if;
    p_submission_intent := 'complete';
  end if;
  if v_unanswered_count = 0 and p_submission_intent <> 'time_expired' then
    p_submission_intent := 'complete';
  end if;
  v_attempt := v_attempt + 1;

  insert into public.learning_submissions (
    tenant_id, assignment_id, student_id, attempt_number, status,
    request_id, request_payload_hash, submission_state, submitted_at,
    attempt_started_at, submission_intent, unanswered_count
  ) values (
    v_tenant_id, p_assignment_id, v_student_id, v_attempt, 'submitted',
    p_request_id, v_payload_hash, 'submitted_pending_grading', now(),
    v_attempt_started_at, p_submission_intent, v_unanswered_count
  ) returning id into v_submission_id;

  for v_answer in select value from jsonb_array_elements(p_answers)
  loop
    begin
      v_question_id := (v_answer->>'questionId')::uuid;
    exception when others then
      raise exception '答案中包含无效题目';
    end;
    v_answer_text := btrim(coalesce(v_answer->>'answer', ''));
    if char_length(v_answer_text) > 10000 then
      raise exception '单题答案不能超过 10000 个字';
    end if;
    select question.question_type, question.options
    into v_question_type, v_options
    from public.learning_assignment_questions as question
    where question.id = v_question_id
      and question.assignment_id = p_assignment_id
      and question.tenant_id = v_tenant_id
      and question.delivery_paper_id is not distinct from
        private.assignment_delivery_paper_id(
          v_tenant_id, p_assignment_id, v_student_id
        );
    if not found then
      raise exception '答案中包含不属于本任务的题目';
    end if;
    if v_answer_text <> '' and v_question_type = 'single_choice'
      and not exists (
        select 1 from jsonb_array_elements_text(v_options) as option
        where option = v_answer_text
      ) then
      raise exception '选择题答案不在有效选项中';
    end if;
    if v_answer_text <> '' and v_question_type = 'file_link'
      and v_answer_text !~* '^https?://[^[:space:]]+$' then
      raise exception '附件链接需要使用完整的 http 或 https 地址';
    end if;
    insert into public.learning_submission_answers (
      tenant_id, submission_id, question_id, answer_text
    ) values (
      v_tenant_id, v_submission_id, v_question_id, v_answer_text
    );
  end loop;

  select
    count(*) filter (
      where not question.auto_graded and answer.answer_text <> ''
    ),
    coalesce(sum(answer.awarded_points), 0)
  into v_manual_count, v_objective_score
  from public.learning_submission_answers as answer
  join public.learning_assignment_questions as question
    on question.tenant_id = answer.tenant_id
   and question.id = answer.question_id
  where answer.tenant_id = v_tenant_id
    and answer.submission_id = v_submission_id;

  if v_manual_count > 0 then
    v_submission_state := 'objective_graded_pending_manual';
    update public.learning_submissions
    set submission_state = v_submission_state,
        objective_graded_at = now(), updated_at = now()
    where tenant_id = v_tenant_id and id = v_submission_id;
  else
    v_submission_state := case
      when v_assignment.grade_release_at is null
        or v_assignment.grade_release_at <= now()
      then 'grade_released' else 'grading_completed' end;
    update public.learning_submissions
    set status = case when v_submission_state = 'grade_released'
          then 'graded' else 'submitted' end,
        score = case when v_submission_state = 'grade_released'
          then v_objective_score else null end,
        computed_score = v_objective_score,
        submission_state = v_submission_state,
        objective_graded_at = now(), grading_completed_at = now(),
        grade_released_at = case when v_submission_state = 'grade_released'
          then now() else null end,
        graded_at = now(), updated_at = now()
    where tenant_id = v_tenant_id and id = v_submission_id;
  end if;

  update public.learning_assignment_submission_counters
  set attempt_count = v_attempt,
      current_attempt_started_at = null,
      updated_at = now()
  where tenant_id = v_tenant_id
    and assignment_id = p_assignment_id
    and student_id = v_student_id;

  return jsonb_build_object(
    'submissionId', v_submission_id,
    'attemptNumber', v_attempt,
    'workflowState', v_submission_state,
    'idempotent', false
  );
end;
$_$;


ALTER FUNCTION public.submit_learning_assignment(p_assignment_id uuid, p_answers jsonb, p_request_id uuid, p_submission_intent text) OWNER TO postgres;

--
-- Name: submit_toolbox_practice(uuid, jsonb, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.submit_toolbox_practice(p_exercise_id uuid, p_answers jsonb, p_active_seconds integer, p_client_event_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_user_id uuid := auth.uid();
  v_tenant_id uuid := private.current_tenant_id();
  v_exercise public.growth_toolbox_exercises%rowtype;
  v_session_id uuid;
  v_existing public.toolbox_practice_sessions%rowtype;
  v_answer jsonb;
  v_question record;
  v_question_id uuid;
  v_response text;
  v_normalized_response text;
  v_is_correct boolean;
  v_answered integer := 0;
  v_correct integer := 0;
  v_earned numeric := 0;
  v_max numeric := 0;
  v_item_count integer := 0;
begin
  if v_user_id is null or v_tenant_id is null then
    raise exception '请登录有效的机构账号后再提交练习';
  end if;

  if not exists (
    select 1
    from public.tenant_memberships as membership
    where membership.tenant_id = v_tenant_id
      and membership.user_id = v_user_id
      and membership.status = 'active'
      and membership.role = 'student'
  ) then
    raise exception '只有当前机构的学生账号可以提交练习';
  end if;

  if p_exercise_id is null or p_client_event_id is null then
    raise exception '练习编号不完整';
  end if;
  if p_answers is null or jsonb_typeof(p_answers) <> 'array' then
    raise exception '练习答案格式不正确';
  end if;
  if jsonb_array_length(p_answers) > 100 then
    raise exception '练习答案数量超过限制';
  end if;
  if coalesce(p_active_seconds, 0) not between 0 and 7200 then
    raise exception '练习时间不正确';
  end if;

  select * into v_exercise
  from public.growth_toolbox_exercises as exercise
  where exercise.id = p_exercise_id
    and exercise.status = 'published'
    and (exercise.tenant_id is null or exercise.tenant_id = v_tenant_id)
    and private.current_user_can_read_student_app(exercise.student_app_id);

  if v_exercise.id is null then
    raise exception '练习不存在、尚未发布或当前应用无权访问';
  end if;

  select count(*)::integer, coalesce(sum(question.max_score), 0)
    into v_item_count, v_max
  from public.growth_toolbox_questions as question
  where question.exercise_id = p_exercise_id;

  if v_item_count = 0 then
    raise exception '练习尚未配置题目';
  end if;

  insert into public.toolbox_practice_sessions (
    tenant_id,
    student_id,
    student_app_id,
    exercise_id,
    skill,
    status,
    active_seconds,
    item_count,
    answered_count,
    correct_count,
    earned_score,
    max_score,
    client_event_id,
    completed_at
  ) values (
    v_tenant_id,
    v_user_id,
    v_exercise.student_app_id,
    p_exercise_id,
    v_exercise.skill,
    'started',
    coalesce(p_active_seconds, 0),
    v_item_count,
    0,
    0,
    0,
    v_max,
    p_client_event_id,
    null
  )
  on conflict (tenant_id, student_id, client_event_id) do nothing
  returning id into v_session_id;

  if v_session_id is null then
    select * into v_existing
    from public.toolbox_practice_sessions
    where tenant_id = v_tenant_id
      and student_id = v_user_id
      and client_event_id = p_client_event_id;

    return jsonb_build_object(
      'sessionId', v_existing.id,
      'answeredCount', v_existing.answered_count,
      'correctCount', v_existing.correct_count,
      'earnedScore', v_existing.earned_score,
      'maxScore', v_existing.max_score,
      'percentage', case when v_existing.max_score > 0
        then round(v_existing.earned_score / v_existing.max_score * 100, 1)
        else 0 end,
      'duplicate', true
    );
  end if;

  for v_answer in
    select value from jsonb_array_elements(p_answers)
  loop
    begin
      v_question_id := (v_answer->>'questionId')::uuid;
    exception when others then
      continue;
    end;

    select
      question.id,
      question.primary_skill,
      question.question_type,
      question.max_score,
      answer_key.accepted_answers
    into v_question
    from public.growth_toolbox_questions as question
    join public.growth_toolbox_question_keys as answer_key
      on answer_key.question_id = question.id
    where question.id = v_question_id
      and question.exercise_id = p_exercise_id;

    if v_question.id is null then
      continue;
    end if;

    v_response := trim(coalesce(v_answer->>'response', ''));
    if v_response = '' then
      continue;
    end if;

    v_normalized_response := lower(
      regexp_replace(v_response, '[[:space:][:punct:]，。！？、]+', '', 'g')
    );
    select exists (
      select 1
      from jsonb_array_elements_text(v_question.accepted_answers) as accepted(value)
      where lower(
        regexp_replace(accepted.value, '[[:space:][:punct:]，。！？、]+', '', 'g')
      ) = v_normalized_response
    ) into v_is_correct;

    v_answered := v_answered + 1;
    v_correct := v_correct + case when v_is_correct then 1 else 0 end;
    v_earned := v_earned + case when v_is_correct then v_question.max_score else 0 end;

    insert into public.toolbox_practice_attempts (
      tenant_id,
      session_id,
      student_id,
      question_id,
      skill,
      response_payload,
      is_correct,
      earned_score,
      max_score,
      duration_seconds,
      evaluated_by
    ) values (
      v_tenant_id,
      v_session_id,
      v_user_id,
      v_question.id,
      v_question.primary_skill,
      jsonb_build_object('value', v_response),
      v_is_correct,
      case when v_is_correct then v_question.max_score else 0 end,
      v_question.max_score,
      case
        when coalesce(v_answer->>'durationSeconds', '') ~ '^[0-9]+$'
          then least((v_answer->>'durationSeconds')::integer, 7200)
        else 0
      end,
      'automatic'
    );
  end loop;

  update public.toolbox_practice_sessions
  set
    status = 'completed',
    answered_count = v_answered,
    correct_count = v_correct,
    earned_score = v_earned,
    completed_at = now(),
    updated_at = now()
  where id = v_session_id;

  return jsonb_build_object(
    'sessionId', v_session_id,
    'answeredCount', v_answered,
    'correctCount', v_correct,
    'earnedScore', v_earned,
    'maxScore', v_max,
    'percentage', case when v_max > 0
      then round(v_earned / v_max * 100, 1)
      else 0 end,
    'duplicate', false
  );
end;
$_$;


ALTER FUNCTION public.submit_toolbox_practice(p_exercise_id uuid, p_answers jsonb, p_active_seconds integer, p_client_event_id uuid) OWNER TO postgres;

