--
-- Name: sync_application_documents_due_date(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sync_application_documents_due_date() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update public.student_application_documents as document
  set due_date = new.application_deadline
  where document.target_id = new.id
    and document.due_date is distinct from new.application_deadline;

  return new;
end;
$$;


ALTER FUNCTION public.sync_application_documents_due_date() OWNER TO postgres;

--
-- Name: sync_auth_registration_metadata(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sync_auth_registration_metadata() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
begin
  update public.profiles
  set
    email = coalesce(new.email, profiles.email),
    full_name = coalesce(
      nullif(btrim(profiles.full_name), ''),
      nullif(btrim(new.raw_user_meta_data ->> 'full_name'), ''),
      nullif(btrim(new.raw_user_meta_data ->> 'name'), '')
    ),
    registered_at = coalesce(profiles.registered_at, new.created_at),
    registration_source = coalesce(
      nullif(new.raw_app_meta_data ->> 'provider', ''),
      profiles.registration_source,
      'email'
    )
  where profiles.id = new.id;

  return new;
end;
$$;


ALTER FUNCTION public.sync_auth_registration_metadata() OWNER TO postgres;

