--
-- Name: sync_university_application_document_requirement(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sync_university_application_document_requirement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'UPDATE'
     and old.is_active
     and (
       old.university_id is distinct from new.university_id
       or old.admission_stage is distinct from new.admission_stage
     ) then
    delete from public.student_application_documents
    where requirement_id = old.id;
  end if;

  if new.is_active then
    insert into public.student_application_documents (
      user_id,
      target_id,
      document_key,
      requirement_id,
      title,
      category,
      notes,
      status,
      sort_order
    )
    select
      target.user_id,
      target.id,
      new.requirement_key,
      new.id,
      new.title,
      new.category,
      new.description,
      'preparing',
      new.sort_order
    from public.student_university_targets as target
    where target.university_id = new.university_id
      and coalesce(target.admission_track, 'language') = new.admission_stage
      and target.status <> 'researching'
    on conflict (target_id, document_key) where target_id is not null
    do update set
      requirement_id = excluded.requirement_id,
      title = excluded.title,
      category = excluded.category,
      notes = excluded.notes,
      sort_order = excluded.sort_order;
  else
    delete from public.student_application_documents
    where requirement_id = new.id;
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.sync_university_application_document_requirement() OWNER TO postgres;

--
-- Name: sync_university_visa_application_requirement(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sync_university_visa_application_requirement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'UPDATE'
     and old.is_active
     and (
       old.university_id is distinct from new.university_id
       or old.visa_type is distinct from new.visa_type
     ) then
    delete from public.student_visa_tasks
    where requirement_id = old.id
      and submission_version = 0
      and status in ('pending', 'in_progress', 'blocked');

    update public.student_visa_tasks
    set is_archived = true
    where requirement_id = old.id
      and is_archived = false;
  end if;

  if new.is_active then
    insert into public.student_visa_tasks (
      tenant_id,
      user_id,
      task_key,
      requirement_id,
      title,
      description,
      stage,
      sort_order,
      is_archived
    )
    select
      visa_case.tenant_id,
      visa_case.user_id,
      new.requirement_key,
      new.id,
      new.title,
      new.description,
      new.stage,
      new.sort_order,
      false
    from public.student_visa_cases as visa_case
    join public.student_university_targets as target
      on target.id = visa_case.source_target_id
     and target.tenant_id = visa_case.tenant_id
    where target.university_id = new.university_id
      and visa_case.visa_type = new.visa_type
    on conflict (tenant_id, user_id, task_key)
    do update set
      requirement_id = excluded.requirement_id,
      title = excluded.title,
      description = excluded.description,
      stage = excluded.stage,
      sort_order = excluded.sort_order,
      is_archived = false;
  else
    delete from public.student_visa_tasks
    where requirement_id = new.id
      and submission_version = 0
      and status in ('pending', 'in_progress', 'blocked');

    update public.student_visa_tasks
    set is_archived = true
    where requirement_id = new.id
      and is_archived = false;
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.sync_university_visa_application_requirement() OWNER TO postgres;

