-- Name: FUNCTION sync_university_visa_application_requirement(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.sync_university_visa_application_requirement() IS 'Synchronizes university visa requirement changes to student tasks using tenant-scoped identity and conflict handling.';

--
-- Name: teaching_script_publish_snapshot(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.teaching_script_publish_snapshot(p_version_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'auth'
    AS $$
declare v_result jsonb;
begin
  if auth.uid() is null or not private.is_platform_owner() then raise exception '只有平台负责人可以检查教学脚本'; end if;
  select jsonb_build_object(
    'nodes', coalesce(n.nodes, '[]'::jsonb),
    'token', md5(jsonb_build_object('version', to_jsonb(v), 'nodes', n.nodes, 'answers', n.answers)::text)
  ) into v_result
  from public.learning_agent_script_versions v
  cross join lateral (
    select jsonb_agg(to_jsonb(node) order by node.id) as nodes,
      jsonb_agg(to_jsonb(secret) order by node.id) as answers
    from public.learning_agent_script_nodes node
    left join public.learning_agent_node_interaction_secrets secret on secret.node_id = node.id
    where node.script_version_id = v.id
  ) n where v.id = p_version_id and v.status = 'draft';
  if v_result is null then raise exception '只有草稿版本可以发布'; end if;
  return v_result;
end;
$$;


ALTER FUNCTION public.teaching_script_publish_snapshot(p_version_id uuid) OWNER TO postgres;

--
-- Name: toggle_library_favorite(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.toggle_library_favorite(p_resource_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_added boolean;
  v_tenant_id uuid := private.current_tenant_id();
begin
  if v_tenant_id is null
    or not public.is_active_account()
    or not exists (
      select 1
      from public.library_resources as resource
      join public.courses as course on course.id = resource.course_id
      where resource.id = p_resource_id
        and resource.tenant_id is null
        and resource.content_scope = 'platform'
        and resource.status = 'published'
        and private.current_user_can_read_student_app(course.student_app_id)
    )
  then
    raise exception '无权收藏该资料';
  end if;

  if exists (
    select 1
    from public.library_favorites
    where tenant_id = v_tenant_id
      and user_id = auth.uid()
      and resource_id = p_resource_id
  ) then
    delete from public.library_favorites
    where tenant_id = v_tenant_id
      and user_id = auth.uid()
      and resource_id = p_resource_id;
    v_added := false;
  else
    insert into public.library_favorites (
      tenant_id,
      user_id,
      resource_id
    )
    values (
      v_tenant_id,
      auth.uid(),
      p_resource_id
    );
    v_added := true;
  end if;

  return v_added;
end;
$$;


ALTER FUNCTION public.toggle_library_favorite(p_resource_id uuid) OWNER TO postgres;

--
-- Name: university_deadline_for_stage(jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.university_deadline_for_stage(p_deadlines jsonb, p_admission_stage text) RETURNS date
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  v_deadline text;
begin
  if p_admission_stage not in (
    'language',
    'bachelor_fresh',
    'bachelor_transfer',
    'master',
    'doctor'
  ) then
    return null;
  end if;

  v_deadline := p_deadlines ->> p_admission_stage;
  if not public.is_valid_university_deadline(v_deadline) then
    return null;
  end if;

  return v_deadline::date;
end;
$$;


ALTER FUNCTION public.university_deadline_for_stage(p_deadlines jsonb, p_admission_stage text) OWNER TO postgres;

--
-- Name: update_guide_agent_behavior(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_guide_agent_behavior(p_agent_profile_id uuid, p_system_prompt text, p_max_output_characters integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
begin
  if not private.is_platform_owner() then
    raise insufficient_privilege using message = 'platform owner required';
  end if;
  if char_length(btrim(p_system_prompt)) not between 40 and 6000 then
    raise exception 'invalid system prompt';
  end if;
  if p_max_output_characters not between 120 and 1000 then
    raise exception 'invalid output character limit';
  end if;
  update public.learning_agent_profile_secrets as secret
  set system_prompt = btrim(p_system_prompt),
      reply_policy = coalesce(secret.reply_policy, '{}'::jsonb) || jsonb_build_object('maxOutputCharacters', p_max_output_characters),
      updated_at = now()
  from public.learning_agent_profiles as profile
  where secret.agent_profile_id = p_agent_profile_id
    and profile.id = secret.agent_profile_id
    and profile.agent_code = 'uply-guide-agent'
    and profile.status = 'published';
  if not found then raise exception 'guide agent profile not found'; end if;
  insert into public.guide_agent_operation_logs (actor_id, action, target_type, target_id, summary, details)
  values (
    v_actor_id,
    '更新 Agent 配置',
    'agent_profile',
    p_agent_profile_id,
    '更新系统提示词与回复长度上限（' || p_max_output_characters || ' 字）',
    jsonb_build_object('maxOutputCharacters', p_max_output_characters)
  );
end;
$$;


ALTER FUNCTION public.update_guide_agent_behavior(p_agent_profile_id uuid, p_system_prompt text, p_max_output_characters integer) OWNER TO postgres;

--
-- Name: update_help_ticket(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_help_ticket(p_ticket_id uuid, p_status text, p_priority text, p_resolution text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not public.current_user_can_handle_help_tickets() then
    raise exception '当前账号没有工单处理权限';
  end if;
  if p_status not in ('open', 'in_progress', 'waiting_student', 'resolved', 'closed')
     or p_priority not in ('normal', 'urgent')
     or char_length(coalesce(p_resolution, '')) > 3000 then
    raise exception '求助状态、紧急程度或处理结果不正确';
  end if;

  update public.help_tickets
  set status = p_status,
      priority = p_priority,
      resolution = trim(coalesce(p_resolution, '')),
      assigned_to = coalesce(assigned_to, auth.uid()),
      resolved_at = case
        when p_status in ('resolved', 'closed') then coalesce(resolved_at, now())
        else null
      end,
      updated_at = now()
  where id = p_ticket_id
    and tenant_id = private.current_tenant_id();

  if not found then raise exception '求助记录不存在'; end if;
end;
$$;


ALTER FUNCTION public.update_help_ticket(p_ticket_id uuid, p_status text, p_priority text, p_resolution text) OWNER TO postgres;

--
-- Name: update_learning_assignment_deadline(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_learning_assignment_deadline(p_assignment_id uuid, p_due_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_due_at is null or p_due_at <= now() then
    raise exception '新的截止时间必须晚于当前时间';
  end if;
  if not exists (
    select 1
    from public.learning_assignments as assignment
    where assignment.id = p_assignment_id
      and assignment.tenant_id = private.current_tenant_id()
      and private.current_staff_has_app_capability(
        assignment.tenant_id,
        assignment.student_app_id,
        'manage_assessments'
      )
  ) then
    raise exception '任务不存在或当前账号没有该应用的教学管理权限';
  end if;

  update public.learning_assignments
  set due_at = p_due_at,
      updated_by = auth.uid(),
      updated_at = now()
  where id = p_assignment_id
    and tenant_id = private.current_tenant_id();
end;
$$;


