--
-- Name: update_learning_grading_comment(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_learning_grading_comment(p_comment_id uuid, p_content text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tenant_id uuid := private.current_tenant_id();
  v_content text := btrim(coalesce(p_content, ''));
begin
  if v_tenant_id is null or not public.current_user_is_assignment_manager() then
    raise exception '当前账号没有维护常用评语的权限';
  end if;
  if char_length(v_content) not between 1 and 500 then
    raise exception '常用评语必须为 1 到 500 个字';
  end if;
  update public.learning_grading_comments
  set content = v_content, updated_by = auth.uid(), updated_at = now()
  where id = p_comment_id and tenant_id = v_tenant_id;
  if not found then raise exception '常用评语不存在'; end if;
exception when unique_violation then
  raise exception '这条常用评语已经存在';
end;
$$;


ALTER FUNCTION public.update_learning_grading_comment(p_comment_id uuid, p_content text) OWNER TO postgres;

--
-- Name: validate_live_class_member(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.validate_live_class_member() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_session_tenant uuid;
  v_session_teacher uuid;
  v_session_mode text;
  v_student_role text;
  v_is_assigned boolean;
begin
  select s.tenant_id, s.teacher_id, s.mode
  into v_session_tenant, v_session_teacher, v_session_mode
  from public.live_class_sessions as s
  where s.id = new.session_id;

  if v_session_tenant is null then
    raise exception '课堂不存在。';
  end if;

  if v_session_mode <> 'group' then
    raise exception '只有公共课堂可以写入成员表。';
  end if;

  select membership.role into v_student_role
  from public.tenant_memberships as membership
  where membership.tenant_id = v_session_tenant
    and membership.user_id = new.student_id
    and membership.status = 'active';

  if v_student_role is null or v_student_role <> 'student' then
    raise exception '目标学生不在本机构或不是有效学生角色。';
  end if;

  -- 已有成员仅更新 joined_at/left_at 时允许正常离场，即使负责关系后来被解除。
  if tg_op = 'INSERT'
     or old.session_id is distinct from new.session_id
     or old.student_id is distinct from new.student_id then
    select exists (
      select 1
      from public.tenant_student_assignments as assignment
      where assignment.tenant_id = v_session_tenant
        and assignment.teacher_id = v_session_teacher
        and assignment.student_id = new.student_id
    ) into v_is_assigned;

    if not v_is_assigned then
      raise exception '该学生不在课堂老师的负责名单中。';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.validate_live_class_member() OWNER TO postgres;

--
-- Name: validate_live_class_session(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.validate_live_class_session() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_teacher_role text;
  v_student_role text;
  v_is_assigned boolean;
begin
  select membership.role into v_teacher_role
  from public.tenant_memberships as membership
  where membership.tenant_id = new.tenant_id
    and membership.user_id = new.teacher_id;

  if v_teacher_role is null or v_teacher_role <> 'teacher' then
    raise exception '发起老师不在本机构或不是老师角色。';
  end if;

  if new.mode = 'group' then
    -- 公共课堂：学生成员关系全部走 live_class_members（由 validate_live_class_member 校验）
    if new.student_id is not null then
      raise exception '公共课堂不应指定单一 student_id。';
    end if;
    return new;
  end if;

  -- one_on_one：沿用原逻辑（学生必须是被该老师负责的机构学生）
  select membership.role into v_student_role
  from public.tenant_memberships as membership
  where membership.tenant_id = new.tenant_id
    and membership.user_id = new.student_id;

  if v_student_role is null or v_student_role <> 'student' then
    raise exception '目标学生不在本机构或不是学生角色。';
  end if;

  select exists (
    select 1 from public.tenant_student_assignments as assignment
    where assignment.tenant_id = new.tenant_id
      and assignment.teacher_id = new.teacher_id
      and assignment.student_id = new.student_id
  ) into v_is_assigned;

  if not v_is_assigned then
    raise exception '该学生不是这位老师负责的学生。';
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.validate_live_class_session() OWNER TO postgres;

--
-- Name: validate_student_teacher_assignment(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.validate_student_teacher_assignment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.student_id = new.teacher_id then
    raise exception '学生与负责老师不能是同一账号。';
  end if;

  if tg_op = 'UPDATE'
    and old.student_app_id is distinct from new.student_app_id then
    raise exception '师生关系的应用归属不可修改，请先解除后重新分配。';
  end if;

  if not exists (
    select 1
    from public.student_app_enrollments as enrollment
    where enrollment.tenant_id = new.tenant_id
      and enrollment.student_id = new.student_id
      and enrollment.app_id = new.student_app_id
      and enrollment.status = 'active'
      and enrollment.starts_at <= now()
      and (enrollment.ends_at is null or enrollment.ends_at > now())
  ) then
    raise exception '目标学生当前未开通该应用。';
  end if;

  if not exists (
    select 1
    from public.staff_app_assignments as staff_access
    where staff_access.tenant_id = new.tenant_id
      and staff_access.staff_id = new.teacher_id
      and staff_access.app_id = new.student_app_id
      and staff_access.status = 'active'
      and staff_access.access_role in ('teacher', 'operator', 'administrator')
      and staff_access.can_view_analytics
  ) then
    raise exception '目标老师没有该应用的有效教学权限。';
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.validate_student_teacher_assignment() OWNER TO postgres;

--
-- Name: canonical(jsonb); Type: FUNCTION; Schema: recording_private; Owner: postgres
--

CREATE FUNCTION recording_private.canonical(v jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare result text;
begin
  case jsonb_typeof(v)
    when 'object' then
      select '{' || coalesce(string_agg(to_jsonb(key)::text || ':' || recording_private.canonical(value), ',' order by key collate "C"), '') || '}'
      into result from jsonb_each(v);
    when 'array' then
      select '[' || coalesce(string_agg(recording_private.canonical(value), ',' order by ord), '') || ']'
      into result from jsonb_array_elements(v) with ordinality a(value, ord);
    when 'number' then result := trim_scale((v::text)::numeric)::text;
    else result := v::text;
  end case;
  return result;
end $$;


ALTER FUNCTION recording_private.canonical(v jsonb) OWNER TO postgres;

