CREATE TABLE public.digital_textbook_speaking_evidence (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    student_id uuid NOT NULL,
    activity_id uuid NOT NULL,
    object_key text NOT NULL,
    byte_size bigint NOT NULL,
    mime_type text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    consumed_at timestamp with time zone,
    consumed_attempt_number integer,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT digital_textbook_speaking_evidenc_consumed_attempt_number_check CHECK (((consumed_attempt_number IS NULL) OR (consumed_attempt_number > 0))),
    CONSTRAINT digital_textbook_speaking_evidence_byte_size_check CHECK (((byte_size >= 2048) AND (byte_size <= 10485760))),
    CONSTRAINT digital_textbook_speaking_evidence_check CHECK ((((consumed_at IS NULL) AND (consumed_attempt_number IS NULL)) OR ((consumed_at IS NOT NULL) AND (consumed_attempt_number IS NOT NULL)))),
    CONSTRAINT digital_textbook_speaking_evidence_mime_type_check CHECK ((mime_type = ANY (ARRAY['audio/webm'::text, 'audio/ogg'::text, 'audio/mp4'::text, 'audio/mpeg'::text])))
);


