--
-- Name: transition_domain(text, bigint, boolean, jsonb); Type: FUNCTION; Schema: recording_private; Owner: postgres
--

CREATE FUNCTION recording_private.transition_domain(p_operation text, p_epoch bigint, p_enabled boolean DEFAULT false, p_cohort jsonb DEFAULT '[]'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare c recording_private.domain_control%rowtype; entry jsonb;
begin
  select * into strict c from recording_private.domain_control where singleton for update;
  if p_operation='drain' and c.state='open' and p_epoch=c.epoch then
    update recording_private.domain_control set state='draining';
  elsif p_operation='fence' and c.state='draining' and p_epoch=c.epoch then
    if exists(select 1 from recording_private.domain_requests) then raise exception 'RECORDING_NOT_DRAINED'; end if;
    update recording_private.domain_control set state='fenced';
  elsif p_operation='switch' and c.state='fenced' and p_epoch=c.epoch+1 then
    if exists(select 1 from recording_private.domain_requests) then raise exception 'RECORDING_NOT_DRAINED'; end if;
    if not exists(select 1 from recording_private.domain_instances) or exists(
      select 1 from recording_private.domain_instances where acknowledged_epoch<>p_epoch)
      then raise exception 'RECORDING_INSTANCES_NOT_ACKNOWLEDGED'; end if;
    if p_enabled is null or jsonb_typeof(p_cohort) is distinct from 'array' then raise exception 'RECORDING_COHORT_INVALID'; end if;
    for entry in select value from jsonb_array_elements(p_cohort) loop
      if jsonb_typeof(entry) <> 'object' or (select count(*) from jsonb_object_keys(entry))<>2
        or not(entry ?& array['tenantId','studentId']) then raise exception 'RECORDING_COHORT_INVALID'; end if;
      perform (entry->>'tenantId')::uuid,(entry->>'studentId')::uuid;
      if entry->>'tenantId' is null or entry->>'studentId' is null then raise exception 'RECORDING_COHORT_INVALID'; end if;
    end loop;
    if (select count(*) from jsonb_array_elements(p_cohort)) <> (select count(distinct value) from jsonb_array_elements(p_cohort))
      then raise exception 'RECORDING_COHORT_INVALID'; end if;
    update recording_private.domain_control set epoch=p_epoch,enabled=p_enabled,cohort=p_cohort;
  elsif p_operation='open' and c.state='fenced' and p_epoch=c.epoch then
    if not exists(select 1 from recording_private.domain_instances) or exists(select 1 from recording_private.domain_instances where acknowledged_epoch<>p_epoch)
      then raise exception 'RECORDING_INSTANCES_NOT_ACKNOWLEDGED'; end if;
    update recording_private.domain_control set state='open';
  else raise exception 'RECORDING_TRANSITION_INVALID'; end if;
end $$;


ALTER FUNCTION recording_private.transition_domain(p_operation text, p_epoch bigint, p_enabled boolean, p_cohort jsonb) OWNER TO postgres;

--
-- Name: verify(public.digital_textbook_speaking_evidence, uuid, jsonb, text, jsonb, jsonb); Type: FUNCTION; Schema: recording_private; Owner: postgres
--

CREATE FUNCTION recording_private.verify(e public.digital_textbook_speaking_evidence, version uuid, binding jsonb, purpose text, response jsonb, proof jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare claims jsonb; identity jsonb; expected jsonb; key bytea; now_epoch bigint;
begin
  identity := recording_private.identity(e);
  if e.consumed_at is not null or e.consumed_attempt_number is not null
    or coalesce(e.metadata->>'lifecycle','active') <> 'active'
    or e.created_at < clock_timestamp() - interval '24 hours' or e.created_at > clock_timestamp() then
    raise exception 'RECORDING_NOT_CONSUMABLE';
  end if;
  if jsonb_typeof(proof) is distinct from 'object' or (proof - array['keyId','payload','signature']) <> '{}'
    or coalesce(proof->>'signature','') !~ '^[0-9a-f]{64}$' then raise exception 'RECORDING_PROOF_INVALID'; end if;
  select secret into key from recording_private.proof_keys where id=proof->>'keyId' and enabled;
  if key is null or encode(recording_private.mac(convert_to(proof->>'payload','UTF8'),key),'hex') is distinct from proof->>'signature' then
    raise exception 'RECORDING_PROOF_SIGNATURE';
  end if;
  claims := (proof->>'payload')::jsonb;
  now_epoch := floor(extract(epoch from clock_timestamp()));
  if coalesce(claims->>'issuedAt','') !~ '^[0-9]{10}$' or coalesce(claims->>'expiresAt','') !~ '^[0-9]{10}$'
    or coalesce(claims->>'nonce','') !~ '^[0-9a-f]{64}$' then raise exception 'RECORDING_PROOF_TIME'; end if;
  if (claims->>'issuedAt')::bigint > now_epoch or (claims->>'expiresAt')::bigint <= now_epoch
    or (claims->>'expiresAt')::bigint - (claims->>'issuedAt')::bigint not between 1 and 60 then raise exception 'RECORDING_PROOF_EXPIRED'; end if;
  expected := jsonb_build_object('protocol','recording-object-proof.v2','purpose',purpose,
    'evidenceId',e.id,'tenantId',e.tenant_id,'studentId',e.student_id,'activityId',e.activity_id,
    'versionId',version,'runtimeBinding',binding,'backend',identity->>'backend','recordingKind',identity->>'kind',
    'objectDigest',identity->>'objectDigest','metadataDigest',recording_private.hash(e.metadata),
    'byteSize',e.byte_size,'mimeType',e.mime_type,'responseDigest',recording_private.hash(response),
    'issuedAt',claims->'issuedAt','expiresAt',claims->'expiresAt','nonce',claims->'nonce');
  if claims is distinct from expected then raise exception 'RECORDING_PROOF_BINDING_MISMATCH'; end if;
  if identity->>'backend' = 'legacy-supabase' and not exists (
    select 1 from storage.objects o where o.bucket_id='digital-textbook-student-recordings' and o.name=e.object_key
      and o.metadata->>'size'=e.byte_size::text
      and split_part(coalesce(o.metadata->>'mimetype',o.metadata->>'contentType',''),';',1)=e.mime_type
  ) then raise exception 'RECORDING_LEGACY_OBJECT_INVALID'; end if;
end $_$;


ALTER FUNCTION recording_private.verify(e public.digital_textbook_speaking_evidence, version uuid, binding jsonb, purpose text, response jsonb, proof jsonb) OWNER TO postgres;

