    CONSTRAINT conversation_practice_scenarios_description_check CHECK ((char_length(description) <= 500)),
    CONSTRAINT conversation_practice_scenarios_difficulty_check CHECK ((difficulty = ANY (ARRAY['beginner'::text, 'intermediate'::text, 'advanced'::text]))),
    CONSTRAINT conversation_practice_scenarios_duration_minutes_check CHECK (((duration_minutes >= 1) AND (duration_minutes <= 120))),
    CONSTRAINT conversation_practice_scenarios_key_expressions_check CHECK ((jsonb_typeof(key_expressions) = 'array'::text)),
    CONSTRAINT conversation_practice_scenarios_learning_objectives_check CHECK ((jsonb_typeof(learning_objectives) = 'array'::text)),
    CONSTRAINT conversation_practice_scenarios_practice_tips_check CHECK ((char_length(practice_tips) <= 1500)),
    CONSTRAINT conversation_practice_scenarios_sample_dialogue_check CHECK ((jsonb_typeof(sample_dialogue) = 'array'::text)),
    CONSTRAINT conversation_practice_scenarios_situation_check CHECK ((char_length(situation) <= 1500)),
    CONSTRAINT conversation_practice_scenarios_sort_order_check CHECK (((sort_order >= 0) AND (sort_order <= 100000))),
    CONSTRAINT conversation_practice_scenarios_starter_prompt_check CHECK ((char_length(starter_prompt) <= 1000)),
    CONSTRAINT conversation_practice_scenarios_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'published'::text, 'archived'::text]))),
    CONSTRAINT conversation_practice_scenarios_title_check CHECK (((char_length(title) >= 2) AND (char_length(title) <= 100)))
);


