    CONSTRAINT course_completion_certificate_events_metadata_check CHECK ((jsonb_typeof(metadata) = 'object'::text)),
    CONSTRAINT course_completion_certificate_events_reason_check CHECK (((event_type <> ALL (ARRAY['revoked'::text, 'reissued'::text])) OR ((reason IS NOT NULL) AND ((char_length(btrim(reason)) >= 2) AND (char_length(btrim(reason)) <= 1000))))),
    CONSTRAINT course_completion_certificate_events_type_check CHECK ((event_type = ANY (ARRAY['issued'::text, 'revoked'::text, 'reissued'::text, 'downloaded'::text, 'verification_viewed'::text])))
);

