--

CREATE TABLE public.course_completion_policies (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    student_app_id uuid NOT NULL,
    course_id uuid NOT NULL,
    policy_code text NOT NULL,
    version integer NOT NULL,
    title text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    is_default boolean DEFAULT true NOT NULL,
    effective_from timestamp with time zone,
    effective_until timestamp with time zone,
    requirements jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_by uuid NOT NULL,
    published_by uuid,
    published_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT course_completion_policies_code_check CHECK ((policy_code ~ '^[A-Z0-9][A-Z0-9_-]{2,79}$'::text)),
    CONSTRAINT course_completion_policies_publication_metadata_check CHECK ((((status = 'draft'::text) AND (published_by IS NULL) AND (published_at IS NULL)) OR ((status = ANY (ARRAY['published'::text, 'retired'::text])) AND (published_by IS NOT NULL) AND (published_at IS NOT NULL)))),
    CONSTRAINT course_completion_policies_requirements_object_check CHECK ((jsonb_typeof(requirements) = 'object'::text)),
    CONSTRAINT course_completion_policies_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'published'::text, 'retired'::text]))),
    CONSTRAINT course_completion_policies_time_check CHECK (((effective_until IS NULL) OR (effective_until > effective_from))),
    CONSTRAINT course_completion_policies_title_check CHECK (((char_length(btrim(title)) >= 2) AND (char_length(btrim(title)) <= 160))),
    CONSTRAINT course_completion_policies_version_check CHECK ((version > 0))
);

ALTER TABLE ONLY public.course_completion_policies FORCE ROW LEVEL SECURITY;


ALTER TABLE public.course_completion_policies OWNER TO postgres;

