--
-- Name: course_completion_refresh_tasks; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.course_completion_refresh_tasks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    task_kind text NOT NULL,
    tenant_id uuid,
    student_id uuid,
    student_app_id uuid NOT NULL,
    course_id uuid NOT NULL,
    policy_id uuid,
    source_kind text,
    source_id text,
    reason text NOT NULL,
    dedupe_key text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    requested_by uuid,
    available_at timestamp with time zone DEFAULT now() NOT NULL,
    worker_token uuid,
    attempt_count integer DEFAULT 0 NOT NULL,
    target_count integer DEFAULT 0 NOT NULL,
    succeeded_count integer DEFAULT 0 NOT NULL,
    failed_count integer DEFAULT 0 NOT NULL,
    last_error text,
    started_at timestamp with time zone,
    finished_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT course_completion_refresh_tasks_attempt_count_check CHECK ((attempt_count >= 0)),
    CONSTRAINT course_completion_refresh_tasks_dedupe_key_check CHECK (((char_length(dedupe_key) >= 8) AND (char_length(dedupe_key) <= 500))),
    CONSTRAINT course_completion_refresh_tasks_failed_count_check CHECK ((failed_count >= 0)),
    CONSTRAINT course_completion_refresh_tasks_reason_check CHECK (((char_length(btrim(reason)) >= 2) AND (char_length(btrim(reason)) <= 300))),
    CONSTRAINT course_completion_refresh_tasks_scope_check CHECK ((((task_kind = 'policy_publish'::text) AND (tenant_id IS NULL) AND (student_id IS NULL) AND (policy_id IS NOT NULL)) OR ((task_kind = 'grade_item_publish'::text) AND (tenant_id IS NOT NULL) AND (student_id IS NULL)) OR ((task_kind = 'institution_manual'::text) AND (tenant_id IS NOT NULL)) OR ((task_kind = 'event_retry'::text) AND (tenant_id IS NOT NULL) AND (student_id IS NOT NULL)))),
    CONSTRAINT course_completion_refresh_tasks_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'processing'::text, 'succeeded'::text, 'partial_failed'::text, 'failed'::text]))),
    CONSTRAINT course_completion_refresh_tasks_succeeded_count_check CHECK ((succeeded_count >= 0)),
    CONSTRAINT course_completion_refresh_tasks_target_count_check CHECK ((target_count >= 0)),
    CONSTRAINT course_completion_refresh_tasks_task_kind_check CHECK ((task_kind = ANY (ARRAY['event_retry'::text, 'policy_publish'::text, 'institution_manual'::text, 'grade_item_publish'::text])))
);

ALTER TABLE ONLY public.course_completion_refresh_tasks FORCE ROW LEVEL SECURITY;


