-- Name: curriculum_plan_templates; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.curriculum_plan_templates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    student_app_id uuid NOT NULL,
    course_id uuid,
    title text NOT NULL,
    description text,
    duration_days integer NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    created_by uuid NOT NULL,
    published_by uuid,
    published_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT curriculum_plan_templates_duration_days_check CHECK (((duration_days >= 1) AND (duration_days <= 366))),
    CONSTRAINT curriculum_plan_templates_publish_check CHECK ((((status = 'draft'::text) AND (published_at IS NULL) AND (published_by IS NULL)) OR ((status = ANY (ARRAY['published'::text, 'retired'::text])) AND (published_at IS NOT NULL) AND (published_by IS NOT NULL)))),
    CONSTRAINT curriculum_plan_templates_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'published'::text, 'retired'::text]))),
    CONSTRAINT curriculum_plan_templates_title_check CHECK (((char_length(btrim(title)) >= 1) AND (char_length(btrim(title)) <= 160))),
    CONSTRAINT curriculum_plan_templates_version_check CHECK ((version > 0))
);


ALTER TABLE public.curriculum_plan_templates OWNER TO postgres;

--
-- Name: TABLE curriculum_plan_templates; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.curriculum_plan_templates IS '平台负责人维护并版本化发布的课程标准学习流程模板';

--
-- Name: digital_textbook_activities; Type: TABLE; Schema: public; Owner: postgres
