    prompt jsonb NOT NULL,
    instruction jsonb DEFAULT '{}'::jsonb NOT NULL,
    options jsonb DEFAULT '[]'::jsonb NOT NULL,
    public_config jsonb DEFAULT '{}'::jsonb NOT NULL,
    max_attempts integer DEFAULT 3 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    counts_toward_completion boolean DEFAULT true NOT NULL,
    CONSTRAINT digital_textbook_activities_activity_type_check CHECK ((activity_type = ANY (ARRAY['single_choice'::text, 'multiple_choice'::text, 'fill_blank'::text, 'ordering'::text, 'listening'::text, 'speaking'::text, 'writing'::text, 'self_check'::text]))),
    CONSTRAINT digital_textbook_activities_instruction_check CHECK ((jsonb_typeof(instruction) = 'object'::text)),
    CONSTRAINT digital_textbook_activities_max_attempts_check CHECK (((max_attempts >= 1) AND (max_attempts <= 20))),
    CONSTRAINT digital_textbook_activities_options_check CHECK ((jsonb_typeof(options) = 'array'::text)),
    CONSTRAINT digital_textbook_activities_prompt_check CHECK ((jsonb_typeof(prompt) = 'object'::text)),
    CONSTRAINT digital_textbook_activities_public_config_check CHECK ((jsonb_typeof(public_config) = 'object'::text)),
    CONSTRAINT digital_textbook_activities_sort_order_check CHECK ((sort_order > 0))
);


ALTER TABLE public.digital_textbook_activities OWNER TO postgres;

