--
-- Name: exam_bank_materials; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.exam_bank_materials (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    chapter_test_id uuid,
    language_skill text NOT NULL,
    difficulty text NOT NULL,
    material_length text NOT NULL,
    title_ko text NOT NULL,
    content_ko text DEFAULT ''::text NOT NULL,
    audio_path text,
    audio_duration_seconds integer,
    status text DEFAULT 'draft'::text NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    tags jsonb DEFAULT '[]'::jsonb NOT NULL,
    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    ebook_section_step text DEFAULT 'STEP 06'::text NOT NULL,
    ebook_page_reference text DEFAULT ''::text NOT NULL,
    CONSTRAINT exam_bank_material_payload_check CHECK ((((language_skill = 'listening'::text) AND (NULLIF(TRIM(BOTH FROM audio_path), ''::text) IS NOT NULL) AND (char_length(TRIM(BOTH FROM content_ko)) = 0)) OR ((language_skill = 'reading'::text) AND private.korean_bank_text_is_valid(content_ko) AND (audio_path IS NULL)))),
    CONSTRAINT exam_bank_materials_audio_duration_seconds_check CHECK (((audio_duration_seconds IS NULL) OR (audio_duration_seconds > 0))),
    CONSTRAINT exam_bank_materials_difficulty_check CHECK ((difficulty = ANY (ARRAY['beginner'::text, 'intermediate'::text, 'advanced'::text]))),
    CONSTRAINT exam_bank_materials_ebook_section_check CHECK ((ebook_section_step = ANY (ARRAY['STEP 01'::text, 'STEP 02'::text, 'STEP 03'::text, 'STEP 04'::text, 'STEP 05'::text, 'STEP 06'::text, 'STEP 07'::text, 'STEP 08'::text]))),
