    CONSTRAINT exam_bank_materials_material_length_check CHECK ((material_length = ANY (ARRAY['short'::text, 'medium'::text, 'long'::text]))),
    CONSTRAINT exam_bank_materials_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'review'::text, 'published'::text, 'retired'::text]))),
    CONSTRAINT exam_bank_materials_tags_check CHECK ((jsonb_typeof(tags) = 'array'::text)),
    CONSTRAINT exam_bank_materials_title_ko_check CHECK (private.korean_bank_text_is_valid(title_ko)),
    CONSTRAINT exam_bank_materials_version_check CHECK ((version > 0))
);


