--
-- Name: exam_bank_questions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.exam_bank_questions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    chapter_test_id uuid,
    material_id uuid,
    language_skill text NOT NULL,
    assessment_category text NOT NULL,
    question_type text NOT NULL,
    difficulty text NOT NULL,
    prompt_ko text NOT NULL,
    options_ko jsonb DEFAULT '[]'::jsonb NOT NULL,
    min_response_characters integer,
    max_response_characters integer,
    preparation_seconds integer,
    min_recording_seconds integer,
    max_recording_seconds integer,
    default_points numeric(8,2) DEFAULT 1 NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    tags jsonb DEFAULT '[]'::jsonb NOT NULL,
    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    ebook_section_step text DEFAULT 'STEP 08'::text NOT NULL,
    ebook_page_reference text DEFAULT ''::text NOT NULL,
    CONSTRAINT exam_bank_question_options_check CHECK (
CASE
    WHEN (question_type = ANY (ARRAY['single_choice'::text, 'multiple_choice'::text, 'ordering'::text])) THEN private.korean_bank_options_are_valid(options_ko, 4)
    ELSE ((jsonb_typeof(options_ko) = 'array'::text) AND (jsonb_array_length(options_ko) = 0))
END),
    CONSTRAINT exam_bank_question_skill_type_check CHECK ((((language_skill = 'listening'::text) AND (question_type = 'single_choice'::text) AND (material_id IS NOT NULL)) OR ((language_skill = 'speaking'::text) AND (question_type = 'audio_response'::text) AND (material_id IS NULL)) OR ((language_skill = 'reading'::text) AND (question_type = ANY (ARRAY['single_choice'::text, 'multiple_choice'::text, 'fill_blank'::text, 'ordering'::text])) AND (material_id IS NOT NULL)) OR ((language_skill = 'writing'::text) AND (question_type = 'long_text'::text) AND (material_id IS NULL)))),
    CONSTRAINT exam_bank_questions_assessment_category_check CHECK (((char_length(TRIM(BOTH FROM assessment_category)) >= 1) AND (char_length(TRIM(BOTH FROM assessment_category)) <= 80))),
    CONSTRAINT exam_bank_questions_default_points_check CHECK (((default_points > (0)::numeric) AND (default_points <= (1000)::numeric))),
    CONSTRAINT exam_bank_questions_difficulty_check CHECK ((difficulty = ANY (ARRAY['beginner'::text, 'intermediate'::text, 'advanced'::text]))),
    CONSTRAINT exam_bank_questions_ebook_section_check CHECK ((ebook_section_step = ANY (ARRAY['STEP 01'::text, 'STEP 02'::text, 'STEP 03'::text, 'STEP 04'::text, 'STEP 05'::text, 'STEP 06'::text, 'STEP 07'::text, 'STEP 08'::text]))),
    CONSTRAINT exam_bank_questions_language_skill_check CHECK ((language_skill = ANY (ARRAY['listening'::text, 'speaking'::text, 'reading'::text, 'writing'::text]))),
    CONSTRAINT exam_bank_questions_max_recording_seconds_check CHECK (((max_recording_seconds IS NULL) OR (max_recording_seconds > 0))),
    CONSTRAINT exam_bank_questions_max_response_characters_check CHECK (((max_response_characters IS NULL) OR (max_response_characters > 0))),
    CONSTRAINT exam_bank_questions_min_recording_seconds_check CHECK (((min_recording_seconds IS NULL) OR (min_recording_seconds > 0))),
    CONSTRAINT exam_bank_questions_min_response_characters_check CHECK (((min_response_characters IS NULL) OR (min_response_characters > 0))),
    CONSTRAINT exam_bank_questions_preparation_seconds_check CHECK (((preparation_seconds IS NULL) OR (preparation_seconds >= 0))),
    CONSTRAINT exam_bank_questions_prompt_ko_check CHECK (private.korean_bank_text_is_valid(prompt_ko)),
    CONSTRAINT exam_bank_questions_question_type_check CHECK ((question_type = ANY (ARRAY['single_choice'::text, 'multiple_choice'::text, 'fill_blank'::text, 'ordering'::text, 'audio_response'::text, 'long_text'::text]))),
    CONSTRAINT exam_bank_questions_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'review'::text, 'published'::text, 'retired'::text]))),
    CONSTRAINT exam_bank_questions_tags_check CHECK ((jsonb_typeof(tags) = 'array'::text)),
    CONSTRAINT exam_bank_questions_version_check CHECK ((version > 0)),
    CONSTRAINT exam_bank_speaking_duration_check CHECK ((((question_type <> 'audio_response'::text) AND (min_recording_seconds IS NULL) AND (max_recording_seconds IS NULL)) OR ((question_type = 'audio_response'::text) AND (min_recording_seconds IS NOT NULL) AND (max_recording_seconds IS NOT NULL) AND (min_recording_seconds <= max_recording_seconds)))),
    CONSTRAINT exam_bank_writing_length_check CHECK ((((question_type <> 'long_text'::text) AND (min_response_characters IS NULL) AND (max_response_characters IS NULL)) OR ((question_type = 'long_text'::text) AND (min_response_characters IS NOT NULL) AND (max_response_characters IS NOT NULL) AND (min_response_characters <= max_response_characters))))
);


