    CONSTRAINT guide_agent_navigation_rules_action_type_check CHECK ((action_type = ANY (ARRAY['navigate'::text, 'highlight'::text]))),
    CONSTRAINT guide_agent_navigation_rules_check CHECK (((action_type = 'navigate'::text) OR (target_element_id IS NOT NULL))),
    CONSTRAINT guide_agent_navigation_rules_name_check CHECK (((char_length(btrim(name)) >= 2) AND (char_length(btrim(name)) <= 80))),
    CONSTRAINT guide_agent_navigation_rules_priority_check CHECK (((priority >= 0) AND (priority <= 1000))),
    CONSTRAINT guide_agent_navigation_rules_response_text_check CHECK (((char_length(btrim(response_text)) >= 2) AND (char_length(btrim(response_text)) <= 200))),
    CONSTRAINT guide_agent_navigation_rules_status_check CHECK ((status = ANY (ARRAY['enabled'::text, 'disabled'::text]))),
    CONSTRAINT guide_agent_navigation_rules_target_element_id_check CHECK (((target_element_id IS NULL) OR (target_element_id ~ '^[A-Za-z][A-Za-z0-9:._-]{0,99}$'::text))),
    CONSTRAINT guide_agent_navigation_rules_target_path_allowed CHECK ((target_path = ANY (ARRAY['/dashboard'::text, '/dashboard/courses'::text, '/dashboard/courses/korean/korean-basic/korean-beginner'::text, '/dashboard/practice/course'::text, '/dashboard/practice/skills'::text, '/dashboard/practice/review#guide-target-review-questions'::text, '/dashboard/assignments'::text, '/dashboard/assignments/korean'::text, '/dashboard/universities'::text, '/dashboard/universities/targets'::text, '/dashboard/universities/library'::text, '/dashboard#reminders'::text]))),
    CONSTRAINT guide_agent_navigation_rules_target_path_check CHECK ((target_path ~ '^/dashboard(?:[/?#]|$)'::text)),
    CONSTRAINT guide_agent_navigation_rules_trigger_phrases_check CHECK (((cardinality(trigger_phrases) >= 1) AND (cardinality(trigger_phrases) <= 20))),
    CONSTRAINT guide_agent_navigation_rules_trigger_phrases_valid CHECK (private.valid_guide_agent_trigger_phrases(trigger_phrases))
);


