    ebook_section_step text DEFAULT 'STEP 06'::text NOT NULL,
    ebook_page_reference text DEFAULT ''::text NOT NULL,
    CONSTRAINT homework_bank_material_payload_check CHECK ((((language_skill = 'listening'::text) AND (NULLIF(TRIM(BOTH FROM audio_path), ''::text) IS NOT NULL) AND (char_length(TRIM(BOTH FROM content_ko)) = 0)) OR ((language_skill = 'reading'::text) AND private.korean_bank_text_is_valid(content_ko) AND (audio_path IS NULL)))),
    CONSTRAINT homework_bank_materials_audio_duration_seconds_check CHECK (((audio_duration_seconds IS NULL) OR (audio_duration_seconds > 0))),
    CONSTRAINT homework_bank_materials_difficulty_check CHECK ((difficulty = ANY (ARRAY['beginner'::text, 'intermediate'::text, 'advanced'::text]))),
    CONSTRAINT homework_bank_materials_ebook_section_check CHECK ((ebook_section_step = ANY (ARRAY['STEP 01'::text, 'STEP 02'::text, 'STEP 03'::text, 'STEP 04'::text, 'STEP 05'::text, 'STEP 06'::text, 'STEP 07'::text, 'STEP 08'::text]))),
    CONSTRAINT homework_bank_materials_language_skill_check CHECK ((language_skill = ANY (ARRAY['listening'::text, 'reading'::text]))),
    CONSTRAINT homework_bank_materials_material_length_check CHECK ((material_length = ANY (ARRAY['short'::text, 'medium'::text, 'long'::text]))),
    CONSTRAINT homework_bank_materials_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'review'::text, 'published'::text, 'retired'::text]))),
    CONSTRAINT homework_bank_materials_tags_check CHECK ((jsonb_typeof(tags) = 'array'::text)),
    CONSTRAINT homework_bank_materials_title_ko_check CHECK (private.korean_bank_text_is_valid(title_ko)),
    CONSTRAINT homework_bank_materials_version_check CHECK ((version > 0))
);


