    id uuid DEFAULT gen_random_uuid() NOT NULL,
    slug text NOT NULL,
    name_zh text NOT NULL,
    name_ko text NOT NULL,
    name_en text NOT NULL,
    ownership text NOT NULL,
    province text NOT NULL,
    city text NOT NULL,
    admission_stages text[] DEFAULT '{}'::text[] NOT NULL,
    discipline_groups text[] DEFAULT '{}'::text[] NOT NULL,
    tuition_min_krw integer NOT NULL,
    tuition_max_krw integer NOT NULL,
    tuition_min_cny integer NOT NULL,
    tuition_max_cny integer NOT NULL,
    tuition_reference_year smallint DEFAULT 2025 NOT NULL,
    qs_rank_display text,
    qs_rank_sort integer,
    qs_ranking_year smallint,
    joongang_rank_display text,
    joongang_rank_sort integer,
    joongang_ranking_year smallint,
    summary text NOT NULL,
    highlights text[] DEFAULT '{}'::text[] NOT NULL,
    official_website text,
    ranking_source_url text,
    is_featured boolean DEFAULT false NOT NULL,
    is_published boolean DEFAULT true NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    logo_url text,
    detailed_introduction text,
    application_deadlines jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT korean_universities_application_deadlines_check CHECK (((jsonb_typeof(application_deadlines) = 'object'::text) AND ((application_deadlines - ARRAY['language'::text, 'bachelor_fresh'::text, 'bachelor_transfer'::text, 'master'::text, 'doctor'::text]) = '{}'::jsonb) AND public.is_valid_university_deadline((application_deadlines ->> 'language'::text)) AND public.is_valid_university_deadline((application_deadlines ->> 'bachelor_fresh'::text)) AND public.is_valid_university_deadline((application_deadlines ->> 'bachelor_transfer'::text)) AND public.is_valid_university_deadline((application_deadlines ->> 'master'::text)) AND public.is_valid_university_deadline((application_deadlines ->> 'doctor'::text)))),
    CONSTRAINT korean_universities_check CHECK ((tuition_max_krw >= tuition_min_krw)),
    CONSTRAINT korean_universities_check1 CHECK ((tuition_max_cny >= tuition_min_cny)),
    CONSTRAINT korean_universities_discipline_check CHECK ((discipline_groups <@ ARRAY['humanities_social'::text, 'science'::text, 'natural_sciences'::text, 'medicine'::text])),
    CONSTRAINT korean_universities_ownership_check CHECK ((ownership = ANY (ARRAY['national'::text, 'public'::text, 'private'::text]))),
    CONSTRAINT korean_universities_stage_check CHECK ((admission_stages <@ ARRAY['language'::text, 'bachelor_fresh'::text, 'bachelor_transfer'::text, 'master'::text, 'doctor'::text])),
    CONSTRAINT korean_universities_tuition_min_cny_check CHECK ((tuition_min_cny >= 0)),
    CONSTRAINT korean_universities_tuition_min_krw_check CHECK ((tuition_min_krw >= 0))
);


