--
-- Name: learning_assignments; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.learning_assignments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    title text NOT NULL,
    description text DEFAULT ''::text NOT NULL,
    assignment_type text NOT NULL,
    course_id uuid,
    target_scope text DEFAULT 'all_students'::text NOT NULL,
    total_points numeric(8,2) DEFAULT 0 NOT NULL,
    due_at timestamp with time zone NOT NULL,
    duration_minutes integer,
    allow_resubmission boolean DEFAULT true NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    published_at timestamp with time zone,
    created_by uuid NOT NULL,
    updated_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    tenant_id uuid NOT NULL,
    source_paper_id uuid,
    source_paper_code text,
    source_paper_version integer,
    starts_at timestamp with time zone DEFAULT now() NOT NULL,
    institution_note text DEFAULT ''::text NOT NULL,
    student_app_id uuid NOT NULL,
    unlock_after_chapter_completion boolean DEFAULT false NOT NULL,
    unlock_test_slug text,
    due_days_after_unlock integer,
    allow_late_submission boolean DEFAULT false NOT NULL,
    max_attempts integer DEFAULT 1 NOT NULL,
    shuffle_questions boolean DEFAULT false NOT NULL,
    shuffle_options boolean DEFAULT false NOT NULL,
    grade_release_at timestamp with time zone,
    retake_paper_id uuid,
    retake_starts_at timestamp with time zone,
    retake_due_at timestamp with time zone,
    retake_score_policy text,
    retake_original_weight_percent integer,
    CONSTRAINT learning_assignments_assignment_type_check CHECK ((assignment_type = ANY (ARRAY['homework'::text, 'quiz'::text, 'exam'::text]))),
    CONSTRAINT learning_assignments_description_check CHECK ((char_length(description) <= 5000)),
    CONSTRAINT learning_assignments_due_days_after_unlock_check CHECK (((due_days_after_unlock IS NULL) OR ((due_days_after_unlock >= 1) AND (due_days_after_unlock <= 30)))),
    CONSTRAINT learning_assignments_duration_minutes_check CHECK (((duration_minutes IS NULL) OR ((duration_minutes >= 1) AND (duration_minutes <= 600)))),
    CONSTRAINT learning_assignments_grade_release_check CHECK (((grade_release_at IS NULL) OR (grade_release_at >= due_at))),
    CONSTRAINT learning_assignments_institution_note_check CHECK ((char_length(institution_note) <= 2000)),
    CONSTRAINT learning_assignments_max_attempts_check CHECK (((max_attempts >= 1) AND (max_attempts <= 100))),
    CONSTRAINT learning_assignments_retake_settings_check CHECK ((((retake_paper_id IS NULL) AND (retake_starts_at IS NULL) AND (retake_due_at IS NULL) AND (retake_score_policy IS NULL) AND (retake_original_weight_percent IS NULL)) OR ((retake_paper_id IS NOT NULL) AND (retake_starts_at IS NOT NULL) AND (retake_due_at > retake_starts_at) AND (retake_starts_at >= due_at) AND (retake_score_policy = ANY (ARRAY['highest'::text, 'latest'::text, 'weighted'::text])) AND (((retake_score_policy = 'weighted'::text) AND ((retake_original_weight_percent >= 1) AND (retake_original_weight_percent <= 99))) OR ((retake_score_policy <> 'weighted'::text) AND (retake_original_weight_percent IS NULL)))))),
    CONSTRAINT learning_assignments_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'published'::text, 'closed'::text]))),
    CONSTRAINT learning_assignments_target_scope_check CHECK ((target_scope = ANY (ARRAY['all_students'::text, 'selected_students'::text]))),
    CONSTRAINT learning_assignments_title_check CHECK (((char_length(title) >= 2) AND (char_length(title) <= 120))),
    CONSTRAINT learning_assignments_total_points_check CHECK ((total_points >= (0)::numeric)),
    CONSTRAINT learning_assignments_unlock_test_slug_check CHECK (((NOT unlock_after_chapter_completion) OR ((char_length(COALESCE(unlock_test_slug, ''::text)) >= 2) AND (char_length(COALESCE(unlock_test_slug, ''::text)) <= 120))))
);


ALTER TABLE public.learning_assignments OWNER TO postgres;

--
-- Name: TABLE learning_assignments; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.learning_assignments IS '作业、测验与考试主表';

--
-- Name: COLUMN learning_assignments.unlock_after_chapter_completion; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.learning_assignments.unlock_after_chapter_completion IS '为 true 时，学生必须完成来源章节教材后才能查看题目和提交。';

--
-- Name: COLUMN learning_assignments.due_days_after_unlock; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.learning_assignments.due_days_after_unlock IS '完成对应章节后，每位学生独立拥有的提交天数；为空时沿用统一截止时间。';

--
-- Name: COLUMN learning_assignments.allow_late_submission; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.learning_assignments.allow_late_submission IS '任务实例是否在截止时间后继续接受提交；任务关闭后仍不可提交。';

--
-- Name: COLUMN learning_assignments.max_attempts; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.learning_assignments.max_attempts IS '任务实例允许的提交次数上限；旧的无限重复提交任务迁移为 100 次。';

--
-- Name: COLUMN learning_assignments.shuffle_questions; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.learning_assignments.shuffle_questions IS '任务实例是否为每名学生随机排列题目。';

--
-- Name: COLUMN learning_assignments.shuffle_options; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.learning_assignments.shuffle_options IS '任务实例是否为每名学生随机排列选择题选项。';

--
-- Name: COLUMN learning_assignments.grade_release_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.learning_assignments.grade_release_at IS '成绩最早公开时间，与提交截止时间独立。';

--
-- Name: COLUMN learning_assignments.retake_paper_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.learning_assignments.retake_paper_id IS '补考使用的已发布标准卷；可与首次考试母卷相同。';

--
