    id uuid DEFAULT gen_random_uuid() NOT NULL,
    assignment_id uuid NOT NULL,
    student_id uuid NOT NULL,
    attempt_number integer NOT NULL,
    status text DEFAULT 'submitted'::text NOT NULL,
    score numeric(8,2),
    overall_feedback text,
    submitted_at timestamp with time zone DEFAULT now() NOT NULL,
    graded_at timestamp with time zone,
    graded_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    tenant_id uuid NOT NULL,
    request_id uuid NOT NULL,
    request_payload_hash text NOT NULL,
    submission_state text DEFAULT 'submitted_pending_grading'::text NOT NULL,
    computed_score numeric(8,2),
    objective_graded_at timestamp with time zone,
    grading_completed_at timestamp with time zone,
    grade_released_at timestamp with time zone,
    attempt_started_at timestamp with time zone,
    submission_intent text DEFAULT 'complete'::text NOT NULL,
    unanswered_count integer DEFAULT 0 NOT NULL,
    grade_release_confirmed_at timestamp with time zone,
    grade_release_confirmed_by uuid,
    CONSTRAINT learning_submissions_attempt_number_check CHECK ((attempt_number > 0)),
    CONSTRAINT learning_submissions_computed_score_check CHECK (((computed_score IS NULL) OR (computed_score >= (0)::numeric))),
    CONSTRAINT learning_submissions_overall_feedback_check CHECK ((char_length(overall_feedback) <= 3000)),
    CONSTRAINT learning_submissions_score_check CHECK (((score IS NULL) OR (score >= (0)::numeric))),
    CONSTRAINT learning_submissions_state_timestamps_check CHECK ((((submission_state <> 'objective_graded_pending_manual'::text) OR (objective_graded_at IS NOT NULL)) AND ((submission_state <> ALL (ARRAY['grading_completed'::text, 'grade_released'::text])) OR (grading_completed_at IS NOT NULL)) AND ((submission_state <> 'grade_released'::text) OR (grade_released_at IS NOT NULL)))),
    CONSTRAINT learning_submissions_status_check CHECK ((status = ANY (ARRAY['submitted'::text, 'graded'::text, 'revision_required'::text]))),
    CONSTRAINT learning_submissions_submission_intent_check CHECK ((submission_intent = ANY (ARRAY['complete'::text, 'confirmed_incomplete'::text, 'time_expired'::text]))),
    CONSTRAINT learning_submissions_submission_state_check CHECK ((submission_state = ANY (ARRAY['submitted_pending_grading'::text, 'objective_graded_pending_manual'::text, 'grading_completed'::text, 'grade_released'::text, 'revision_required'::text]))),
    CONSTRAINT learning_submissions_unanswered_count_check CHECK ((unanswered_count >= 0))
);


