COMMENT ON TABLE public.permission_grants IS '统一账号例外授权；角色继承权限由应用权限目录定义。';

--
-- Name: permission_grants_id_seq; Type: SEQUENCE; Schema: public; Owner: postgres
--

ALTER TABLE public.permission_grants ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.permission_grants_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

--
-- Name: profiles; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.profiles (
    id uuid NOT NULL,
    full_name text,
    role text DEFAULT 'student'::text NOT NULL,
    avatar_url text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    deactivated_at timestamp with time zone,
    deactivated_by uuid,
    deactivate_reason text,
    email text,
    registered_at timestamp with time zone,
    registration_source text DEFAULT 'email'::text NOT NULL,
    last_active_at timestamp with time zone,
    profile_completed_at timestamp with time zone,
    gender text,
    birth_date date,
    avatar_path text,
    address_province text,
    address_city text,
    education_level text,
    education_status text,
    education_completion_month date,
    academic_average numeric(5,2),
    gaokao_has_score boolean,
    gaokao_score numeric(6,2),
    english_level text,
    math_level text,
    has_korean boolean,
    topik_level smallint,
    has_work_experience boolean,
    profile_data_version text DEFAULT '2026-07'::text NOT NULL,
    membership_tier text DEFAULT 'normal'::text NOT NULL,
    membership_updated_at timestamp with time zone,
    membership_updated_by uuid,
    login_id text,
    global_role text DEFAULT 'member'::text NOT NULL,
    motto text,
    interest_tags text[] DEFAULT '{}'::text[] NOT NULL,
    CONSTRAINT profiles_academic_average_check CHECK (((academic_average IS NULL) OR ((academic_average >= (0)::numeric) AND (academic_average <= (100)::numeric)))),
    CONSTRAINT profiles_address_pair_check CHECK ((((address_province IS NULL) AND (address_city IS NULL)) OR ((NULLIF(btrim(address_province), ''::text) IS NOT NULL) AND (NULLIF(btrim(address_city), ''::text) IS NOT NULL)))),
    CONSTRAINT profiles_education_completion_check CHECK ((((education_level IS NULL) AND (education_status IS NULL) AND (education_completion_month IS NULL)) OR ((education_level IS NOT NULL) AND (education_status IS NOT NULL) AND (education_completion_month IS NOT NULL)))),
    CONSTRAINT profiles_education_level_check CHECK (((education_level IS NULL) OR (education_level = ANY (ARRAY['bachelor'::text, 'associate'::text, 'high_school'::text, 'secondary_vocational'::text, 'technical_school'::text])))),
    CONSTRAINT profiles_education_status_check CHECK (((education_status IS NULL) OR (education_status = ANY (ARRAY['graduated'::text, 'studying'::text])))),
    CONSTRAINT profiles_english_level_check CHECK (((english_level IS NULL) OR (english_level = ANY (ARRAY['A1'::text, 'A2'::text, 'B1'::text, 'B2'::text, 'C1'::text, 'C2'::text])))),
    CONSTRAINT profiles_gaokao_score_check CHECK (((gaokao_has_score IS NULL) OR ((gaokao_has_score = false) AND (gaokao_score IS NULL)) OR ((gaokao_has_score = true) AND ((gaokao_score >= (0)::numeric) AND (gaokao_score <= (750)::numeric))))),
    CONSTRAINT profiles_gender_check CHECK (((gender IS NULL) OR (gender = ANY (ARRAY['male'::text, 'female'::text])))),
    CONSTRAINT profiles_global_role_check CHECK ((global_role = ANY (ARRAY['platform_owner'::text, 'platform_deputy'::text, 'platform_admin'::text, 'platform_course_inspector'::text, 'tenant_super_admin'::text, 'member'::text]))),
    CONSTRAINT profiles_interest_tags_count_check CHECK (((array_length(interest_tags, 1) IS NULL) OR (array_length(interest_tags, 1) <= 8))),
    CONSTRAINT profiles_login_id_check CHECK (((login_id IS NULL) OR ((login_id = lower(login_id)) AND (login_id ~ '^[a-z0-9][a-z0-9_-]{2,31}$'::text)))),
    CONSTRAINT profiles_math_level_check CHECK (((math_level IS NULL) OR (math_level = ANY (ARRAY['A1'::text, 'A2'::text, 'B1'::text, 'B2'::text, 'C1'::text, 'C2'::text])))),
    CONSTRAINT profiles_membership_tier_check CHECK ((membership_tier = ANY (ARRAY['normal'::text, 'vip1'::text, 'vip2'::text, 'vip3'::text]))),
    CONSTRAINT profiles_motto_length_check CHECK (((motto IS NULL) OR (char_length(motto) <= 60))),
    CONSTRAINT profiles_role_check CHECK ((role = ANY (ARRAY['student'::text, 'teacher'::text, 'admin'::text, 'ceo'::text, 'platform_super_admin'::text, 'platform_course_inspector'::text, 'tenant_super_admin'::text, 'tenant_operator'::text]))),
    CONSTRAINT profiles_role_global_consistency_check CHECK ((((role = 'platform_super_admin'::text) AND (global_role = 'platform_owner'::text)) OR ((role = 'tenant_operator'::text) AND (global_role = 'platform_deputy'::text)) OR ((role = 'admin'::text) AND (global_role = 'platform_admin'::text)) OR ((role = 'platform_course_inspector'::text) AND (global_role = 'platform_course_inspector'::text)) OR ((role = 'tenant_super_admin'::text) AND (global_role = 'tenant_super_admin'::text)) OR ((role = ANY (ARRAY['student'::text, 'teacher'::text, 'admin'::text, 'ceo'::text])) AND (global_role = 'member'::text)))),
    CONSTRAINT profiles_status_check CHECK ((status = ANY (ARRAY['active'::text, 'inactive'::text, 'suspended'::text]))),
    CONSTRAINT profiles_topik_level_check CHECK (((has_korean IS NULL) OR ((has_korean = false) AND (topik_level IS NULL)) OR ((has_korean = true) AND ((topik_level >= 1) AND (topik_level <= 6)))))
);


ALTER TABLE public.profiles OWNER TO postgres;

--
-- Name: COLUMN profiles.role; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.profiles.role IS '账号权限角色：platform_super_admin 与 tenant_super_admin 互斥，不再使用历史 super_admin';

--
-- Name: COLUMN profiles.avatar_path; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.profiles.avatar_path IS '私有 profile-photos 存储桶中的头像对象路径';

--
-- Name: COLUMN profiles.education_completion_month; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.profiles.education_completion_month IS '毕业日期或预计毕业日期；页面以 YYYY.MM.DD 输入，数据库以 date 类型保存';

--
-- Name: COLUMN profiles.academic_average; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.profiles.academic_average IS '当前教育阶段的百分制平均成绩';

--
-- Name: COLUMN profiles.gaokao_score; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.profiles.gaokao_score IS '高中、中专或技工学校学生的高考成绩，可为空表示无成绩';

--
-- Name: COLUMN profiles.membership_tier; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.profiles.membership_tier IS '学生会员档位：普通、VIP1、VIP2、VIP3';

--
-- Name: COLUMN profiles.global_role; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.profiles.global_role IS '账号空间身份：platform_owner/platform_deputy/platform_admin/platform_course_inspector 进入平台空间，tenant_super_admin/member 进入机构空间';

--
-- Name: COLUMN profiles.motto; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.profiles.motto IS '个人空间展示的一句话个性签名，最长 60 字。';

--
-- Name: COLUMN profiles.interest_tags; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.profiles.interest_tags IS '个人空间展示的兴趣标签，取自预设列表，最多 8 个。';

