    CONSTRAINT student_chapter_practice_progress_mastery_percent_check CHECK (((mastery_percent >= (0)::numeric) AND (mastery_percent <= (100)::numeric))),
    CONSTRAINT student_chapter_practice_progress_progress_percent_check CHECK (((progress_percent >= (0)::numeric) AND (progress_percent <= (100)::numeric))),
    CONSTRAINT student_chapter_practice_progress_status_check CHECK ((status = ANY (ARRAY['not_started'::text, 'in_progress'::text, 'needs_reinforcement'::text, 'mastered'::text, 'locked'::text, 'content_preparing'::text])))
);


