--
-- Name: student_learning_submission_answers; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.student_learning_submission_answers WITH (security_barrier='true') AS
 SELECT answer.id,
    answer.tenant_id,
    answer.submission_id,
    answer.question_id,
    answer.answer_text,
        CASE
            WHEN (question.auto_graded OR (submission.submission_state = 'grade_released'::text)) THEN answer.awarded_points
            ELSE NULL::numeric
        END AS awarded_points,
        CASE
            WHEN (submission.submission_state = 'grade_released'::text) THEN answer.rubric_scores
            ELSE NULL::jsonb
        END AS rubric_scores,
        CASE
            WHEN (submission.submission_state = 'grade_released'::text) THEN answer.grader_feedback
            ELSE NULL::text
        END AS grader_feedback,
    answer.created_at,
    answer.updated_at
   FROM (((public.learning_submission_answers answer
     JOIN public.learning_submissions submission ON (((submission.id = answer.submission_id) AND (submission.tenant_id = answer.tenant_id))))
     JOIN public.learning_assignments assignment ON (((assignment.id = submission.assignment_id) AND (assignment.tenant_id = submission.tenant_id))))
     JOIN public.learning_assignment_questions question ON (((question.id = answer.question_id) AND (question.assignment_id = assignment.id) AND (question.tenant_id = answer.tenant_id))))
  WHERE ((submission.student_id = ( SELECT auth.uid() AS uid)) AND private.current_student_has_app_access(assignment.tenant_id, submission.student_id, assignment.student_app_id));


ALTER VIEW public.student_learning_submission_answers OWNER TO postgres;

