    CONSTRAINT toolbox_practice_sessions_answered_count_check CHECK (((answered_count >= 0) AND (answered_count <= 500))),
    CONSTRAINT toolbox_practice_sessions_correct_count_check CHECK (((correct_count >= 0) AND (correct_count <= 500))),
    CONSTRAINT toolbox_practice_sessions_earned_score_check CHECK ((earned_score >= (0)::numeric)),
    CONSTRAINT toolbox_practice_sessions_item_count_check CHECK (((item_count >= 0) AND (item_count <= 500))),
    CONSTRAINT toolbox_practice_sessions_max_score_check CHECK ((max_score >= (0)::numeric)),
    CONSTRAINT toolbox_practice_sessions_skill_check CHECK ((skill = ANY (ARRAY['listening'::text, 'speaking'::text, 'reading'::text, 'writing'::text, 'grammar'::text, 'vocabulary'::text]))),
    CONSTRAINT toolbox_practice_sessions_status_check CHECK ((status = ANY (ARRAY['started'::text, 'completed'::text, 'abandoned'::text])))
);


ALTER TABLE public.toolbox_practice_sessions OWNER TO postgres;

--
-- Name: student_toolbox_skill_profiles; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.student_toolbox_skill_profiles WITH (security_invoker='true', security_barrier='true') AS
 WITH valid_session AS (
         SELECT session.tenant_id,
            session.student_id,
            session.student_app_id,
            session.skill,
            session.id,
            session.completed_at,
            session.active_seconds,
            session.answered_count,
            session.item_count,
            session.earned_score,
            session.max_score,
                CASE
                    WHEN (session.completed_at >= (now() - '7 days'::interval)) THEN 1.0
                    WHEN (session.completed_at >= (now() - '14 days'::interval)) THEN 0.8
                    ELSE 0.6
                END AS recency_weight
           FROM public.toolbox_practice_sessions session
          WHERE ((session.status = 'completed'::text) AND (session.completed_at >= (now() - '30 days'::interval)) AND (session.answered_count > 0) AND (session.max_score > (0)::numeric))
        ), aggregate_profile AS (
         SELECT valid_session.tenant_id,
            valid_session.student_id,
            valid_session.student_app_id,
            valid_session.skill,
            round((sum((((valid_session.earned_score / valid_session.max_score) * (100)::numeric) * valid_session.recency_weight)) / NULLIF(sum(valid_session.recency_weight), (0)::numeric)), 1) AS accuracy_score,
            round((sum(((((valid_session.answered_count)::numeric / (GREATEST(valid_session.item_count, 1))::numeric) * (100)::numeric) * valid_session.recency_weight)) / NULLIF(sum(valid_session.recency_weight), (0)::numeric)), 1) AS completion_score,
            LEAST((100)::numeric, (((count(DISTINCT (valid_session.completed_at)::date))::numeric / (8)::numeric) * (100)::numeric)) AS consistency_score,
            sum(valid_session.answered_count) AS valid_attempts,
            count(*) AS valid_sessions,
            count(DISTINCT (valid_session.completed_at)::date) AS active_days,
            sum(valid_session.active_seconds) AS active_seconds,
            max(valid_session.completed_at) AS last_practiced_at
           FROM valid_session
          GROUP BY valid_session.tenant_id, valid_session.student_id, valid_session.student_app_id, valid_session.skill
        )
 SELECT tenant_id,
    student_id,
    student_app_id,
    skill,
    (
        CASE
            WHEN (valid_attempts >= 5) THEN round(LEAST((100)::numeric, GREATEST((0)::numeric, (((accuracy_score * 0.75) + (completion_score * 0.15)) + (consistency_score * 0.10)))), 1)
            ELSE NULL::numeric
        END)::numeric(5,1) AS ability_score,
    (accuracy_score)::numeric(5,1) AS accuracy_score,
    (completion_score)::numeric(5,1) AS completion_score,
    (round(consistency_score, 1))::numeric(5,1) AS consistency_score,
    valid_sessions,
    valid_attempts,
    active_days,
    active_seconds,
    last_practiced_at
   FROM aggregate_profile;


ALTER VIEW public.student_toolbox_skill_profiles OWNER TO postgres;

--
-- Name: student_university_assessments; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.student_university_assessments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    university_id uuid NOT NULL,
    admission_stage text NOT NULL,
    discipline_group text NOT NULL,
    academic_score numeric(5,2) NOT NULL,
    topik_level smallint NOT NULL,
    annual_budget_cny integer NOT NULL,
    match_score smallint NOT NULL,
    result_label text NOT NULL,
    score_breakdown jsonb DEFAULT '{}'::jsonb NOT NULL,
    disclaimer_version text DEFAULT '2026-07'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    tenant_id uuid NOT NULL,
    CONSTRAINT student_university_assessments_academic_score_check CHECK (((academic_score >= (0)::numeric) AND (academic_score <= (100)::numeric))),
    CONSTRAINT student_university_assessments_admission_stage_check CHECK ((admission_stage = ANY (ARRAY['language'::text, 'bachelor_fresh'::text, 'bachelor_transfer'::text, 'master'::text, 'doctor'::text]))),
