    CONSTRAINT student_university_assessments_discipline_group_check CHECK ((discipline_group = ANY (ARRAY['humanities_social'::text, 'science'::text, 'natural_sciences'::text, 'medicine'::text]))),
    CONSTRAINT student_university_assessments_match_score_check CHECK (((match_score >= 0) AND (match_score <= 100))),
    CONSTRAINT student_university_assessments_result_label_check CHECK ((result_label = ANY (ARRAY['匹配度较高'::text, '可以冲刺'::text, '建议先提升'::text]))),
    CONSTRAINT student_university_assessments_topik_level_check CHECK (((topik_level >= 0) AND (topik_level <= 6)))
);


