--

CREATE TABLE public.student_university_targets (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    university_name text NOT NULL,
    program_name text,
    degree_level text DEFAULT 'language'::text NOT NULL,
    priority smallint DEFAULT 3 NOT NULL,
    status text DEFAULT 'researching'::text NOT NULL,
    application_deadline date,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    university_id uuid,
    admission_track text,
    documents_locked_at timestamp with time zone,
    courier_mailed_at date,
    courier_estimated_arrival_at date,
    application_stage smallint DEFAULT 0 NOT NULL,
    visa_application_channel text,
    tenant_id uuid NOT NULL,
    document_review_status text DEFAULT 'preparing'::text NOT NULL,
    document_review_submitted_at timestamp with time zone,
    document_reviewed_at timestamp with time zone,
    document_reviewed_by uuid,
    document_review_note text DEFAULT ''::text NOT NULL,
    CONSTRAINT student_university_targets_admission_track_check CHECK (((admission_track IS NULL) OR (admission_track = ANY (ARRAY['language'::text, 'bachelor_fresh'::text, 'bachelor_transfer'::text, 'master'::text, 'doctor'::text])))),
    CONSTRAINT student_university_targets_application_stage_check CHECK (((application_stage >= 0) AND (application_stage <= 9))),
    CONSTRAINT student_university_targets_courier_dates_check CHECK (((courier_mailed_at IS NULL) OR (courier_estimated_arrival_at IS NULL) OR (courier_estimated_arrival_at >= courier_mailed_at))),
    CONSTRAINT student_university_targets_degree_level_check CHECK ((degree_level = ANY (ARRAY['language'::text, 'bachelor'::text, 'master'::text, 'doctor'::text, 'exchange'::text, 'other'::text]))),
    CONSTRAINT student_university_targets_document_review_note_check CHECK ((char_length(document_review_note) <= 2000)),
    CONSTRAINT student_university_targets_document_review_status_check CHECK ((document_review_status = ANY (ARRAY['preparing'::text, 'pending_review'::text, 'revision_required'::text, 'approved'::text]))),
    CONSTRAINT student_university_targets_priority_check CHECK (((priority >= 1) AND (priority <= 5))),
    CONSTRAINT student_university_targets_status_check CHECK ((status = ANY (ARRAY['researching'::text, 'preparing'::text, 'applied'::text, 'interview'::text, 'offer'::text, 'rejected'::text, 'paused'::text]))),
    CONSTRAINT student_university_targets_university_name_check CHECK (((char_length(TRIM(BOTH FROM university_name)) >= 2) AND (char_length(TRIM(BOTH FROM university_name)) <= 120))),
    CONSTRAINT student_university_targets_visa_application_channel_check CHECK (((visa_application_channel IS NULL) OR (visa_application_channel = ANY (ARRAY['china_consulate'::text, 'korea_immigration'::text]))))
);


