    CONSTRAINT student_weekly_learning_plans_preferred_days_check CHECK (((cardinality(preferred_days) <= 7) AND (preferred_days <@ ARRAY[(1)::smallint, (2)::smallint, (3)::smallint, (4)::smallint, (5)::smallint, (6)::smallint, (7)::smallint]))),
    CONSTRAINT student_weekly_learning_plans_target_days_check CHECK (((target_days >= 1) AND (target_days <= 7))),
    CONSTRAINT student_weekly_learning_plans_target_minutes_check CHECK (((target_minutes >= 1) AND (target_minutes <= 10080))),
    CONSTRAINT student_weekly_learning_plans_week_starts_monday_check CHECK ((EXTRACT(isodow FROM week_start_date) = (1)::numeric))
);


