    CONSTRAINT teacher_learning_recommendations_source_type_check CHECK ((source_type = ANY (ARRAY['course'::text, 'chapter_practice'::text, 'specialized_practice'::text, 'review'::text]))),
    CONSTRAINT teacher_learning_recommendations_status_check CHECK ((status = ANY (ARRAY['active'::text, 'withdrawn'::text]))),
