    CONSTRAINT teacher_learning_recommendations_target_scope_check CHECK ((target_scope = ANY (ARRAY['class'::text, 'student'::text]))),
    CONSTRAINT teacher_learning_recommendations_time_check CHECK ((due_at > starts_at)),
    CONSTRAINT teacher_learning_recommendations_title_check CHECK (((char_length(btrim(title)) >= 1) AND (char_length(btrim(title)) <= 200)))
);


