--
-- Name: profiles Executives manage subordinate tenant member profiles; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Executives manage subordinate tenant member profiles" ON public.profiles FOR UPDATE TO authenticated USING ((((EXISTS ( SELECT 1
   FROM public.tenant_memberships membership
  WHERE ((membership.user_id = profiles.id) AND (membership.tenant_id = ( SELECT private.current_tenant_id() AS current_tenant_id))))) AND (role <> 'tenant_operator'::text) AND (( SELECT public.is_owner_account() AS is_owner_account) OR (( SELECT public.is_executive_account() AS is_executive_account) AND (role <> ALL (ARRAY['tenant_super_admin'::text, 'ceo'::text]))))) OR ( SELECT private.is_platform_owner() AS is_platform_owner))) WITH CHECK ((((EXISTS ( SELECT 1
   FROM public.tenant_memberships membership
  WHERE ((membership.user_id = profiles.id) AND (membership.tenant_id = ( SELECT private.current_tenant_id() AS current_tenant_id))))) AND (role <> 'tenant_operator'::text) AND (( SELECT public.is_owner_account() AS is_owner_account) OR (( SELECT public.is_executive_account() AS is_executive_account) AND (role <> ALL (ARRAY['tenant_super_admin'::text, 'ceo'::text]))))) OR ( SELECT private.is_platform_owner() AS is_platform_owner)));

--
-- Name: profiles Executives read profiles of their tenant members; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Executives read profiles of their tenant members" ON public.profiles FOR SELECT TO authenticated USING (((( SELECT public.is_executive_account() AS is_executive_account) AND (EXISTS ( SELECT 1
   FROM public.tenant_memberships membership
  WHERE ((membership.user_id = profiles.id) AND (membership.tenant_id = ( SELECT private.current_tenant_id() AS current_tenant_id)))))) OR ( SELECT private.is_platform_owner() AS is_platform_owner)));

--
-- Name: profiles Users can update own profile; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Users can update own profile" ON public.profiles FOR UPDATE TO authenticated USING (((( SELECT auth.uid() AS uid) = id) OR ( SELECT private.is_platform_owner() AS is_platform_owner))) WITH CHECK (((( SELECT auth.uid() AS uid) = id) OR ( SELECT private.is_platform_owner() AS is_platform_owner)));

--
-- Name: profiles Users can view own profile; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Users can view own profile" ON public.profiles FOR SELECT TO authenticated USING (((( SELECT auth.uid() AS uid) = id) OR ( SELECT private.is_platform_owner() AS is_platform_owner)));

