   FROM (public.lessons lesson
     JOIN public.courses course ON ((course.id = lesson.course_id)))
  WHERE ((lesson.id = course_chapters.lesson_id) AND private.current_staff_has_app_capability(course_chapters.tenant_id, course.student_app_id, 'manage_content'::text))))) OR ( SELECT private.is_platform_owner() AS is_platform_owner)));

