-- Name: institution_curriculum_plans teachers manage own curriculum plans; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "teachers manage own curriculum plans" ON public.institution_curriculum_plans TO authenticated USING (((tenant_id = ( SELECT private.current_tenant_id() AS current_tenant_id)) AND (( SELECT public.current_profile_role() AS current_profile_role) = 'teacher'::text) AND (created_by = ( SELECT auth.uid() AS uid)) AND (EXISTS ( SELECT 1
   FROM public.staff_app_assignments access
  WHERE ((access.tenant_id = institution_curriculum_plans.tenant_id) AND (access.staff_id = ( SELECT auth.uid() AS uid)) AND (access.app_id = institution_curriculum_plans.student_app_id) AND (access.status = 'active'::text) AND access.can_manage_assessments))))) WITH CHECK (((tenant_id = ( SELECT private.current_tenant_id() AS current_tenant_id)) AND (( SELECT public.current_profile_role() AS current_profile_role) = 'teacher'::text) AND (created_by = ( SELECT auth.uid() AS uid)) AND (published_by = ( SELECT auth.uid() AS uid)) AND (EXISTS ( SELECT 1
   FROM public.staff_app_assignments access
  WHERE ((access.tenant_id = institution_curriculum_plans.tenant_id) AND (access.staff_id = ( SELECT auth.uid() AS uid)) AND (access.app_id = institution_curriculum_plans.student_app_id) AND (access.status = 'active'::text) AND access.can_manage_assessments)))));

