--
-- Name: grade_review_requests teachers read grade reviews of their assigned students; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "teachers read grade reviews of their assigned students" ON public.grade_review_requests FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.tenant_student_assignments app_assignment
  WHERE ((app_assignment.tenant_id = grade_review_requests.tenant_id) AND (app_assignment.student_id = grade_review_requests.student_id) AND (app_assignment.teacher_id = ( SELECT auth.uid() AS uid)) AND private.current_teacher_has_student_app_access(app_assignment.tenant_id, app_assignment.student_id, app_assignment.student_app_id) AND (((grade_review_requests.source_type = 'assignment_submission'::text) AND (EXISTS ( SELECT 1
           FROM (public.learning_submissions submission
             JOIN public.learning_assignments assignment ON (((assignment.tenant_id = submission.tenant_id) AND (assignment.id = submission.assignment_id))))
          WHERE ((submission.tenant_id = grade_review_requests.tenant_id) AND (submission.id = grade_review_requests.source_result_id) AND (assignment.student_app_id = app_assignment.student_app_id))))) OR ((grade_review_requests.source_type = 'chapter_test_attempt'::text) AND (EXISTS ( SELECT 1
           FROM (public.chapter_test_attempts attempt
             JOIN public.chapter_tests test ON ((test.id = attempt.test_id)))
          WHERE ((attempt.tenant_id = grade_review_requests.tenant_id) AND (attempt.id = grade_review_requests.source_result_id) AND (test.student_app_id = app_assignment.student_app_id))))) OR ((grade_review_requests.source_type = 'manual_grade_record'::text) AND (EXISTS ( SELECT 1
           FROM (((public.grade_records grade_record
             JOIN public.grade_items grade_item ON (((grade_item.tenant_id = grade_record.tenant_id) AND (grade_item.id = grade_record.item_id))))
             LEFT JOIN public.courses course ON ((course.id = grade_item.course_id)))
             LEFT JOIN public.learning_assignments assignment ON ((assignment.id = grade_item.source_assignment_id)))
          WHERE ((grade_record.tenant_id = grade_review_requests.tenant_id) AND (grade_record.id = grade_review_requests.record_id) AND (COALESCE(course.student_app_id, assignment.student_app_id) = app_assignment.student_app_id))))))))));

